window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["JHN"]={"book":"JHN","editions":{"dan-1819":[[1,1,"I Begyndelsen var Ordet, og Ordet var hos Gud, og Ordet var Gud.","I Begyndelsen var Ordet, og Ordet var hos Gud, og Ordet var Gud."],[1,2,"Det var i Begyndelsen hos Gud.","Det var i Begyndelsen hos Gud."],[1,3,"Alle Ting ere blevne ved det, og uden det er ikke een Ting bleven til af det, som er.","Alle Ting ere blevne ved det, og uden det er ikke een Ting bleven til af det, som er."],[1,4,"I det var Livet, og Livet var Menneskenes Lys.","I det var Livet, og Livet var Menneskenes Lys."],[1,5,"Og Lyset skinnede i Mørket, og Mørket begreb det ikke.","Og Lyset skinnede i Mørket, og Mørket begreb det ikke."],[1,6,"Der blev et Menneske udsendt af Gud, han hedte Johannes.","Der blev et Menneske udsendt af Gud, han hedte Johannes."],[1,7,"Denne kom til et Vidnesbyrd, at han skulde vidne om Lyset, at alle skulde troe ved ham.","Denne kom til et Vidnesbyrd, at han skulde vidne om Lyset, at alle skulde troe ved ham."],[1,8,"Han var ikke Lyset, men at han skulde vidne om Lyset.","Han var ikke Lyset, men at han skulde vidne om Lyset."],[1,9,"Det var det sande Lys, som oplyser hvert Menneske, der kom til Verden.","Det var det sande Lys, som oplyser hvert Menneske, der kom til Verden."],[1,10,"Han var i Verden, og Verden er gjort ved ham, og Verden Kjendte ham ikke.","Han var i Verden, og Verden er gjort ved ham, og Verden Kjendte ham ikke."],[1,11,"Han kom til sit Eget, og hans Egne annammede ham ikke.","Han kom til sit Eget, og hans Egne annammede ham ikke."],[1,12,"Men saa Mange, som ham annammede, dem haver han givet Magt at vorde Guds Børn, dem, som troe paa hans Navn;","Men saa Mange, som ham annammede, dem haver han givet Magt at vorde Guds Børn, dem, som troe paa hans Navn;"],[1,13,"hvilke ikke ere fødte af Blod; ei heller af Kjøds Villie, ei heller af Mands Villie, men af Gud.","hvilke ikke ere fødte af Blod; ei heller af Kjøds Villie, ei heller af Mands Villie, men af Gud."],[1,14,"Og Ordet blev Kjød og boede iblandt os, (og vi saae hans Herlighed, en Herlighed, som den Eenbaarnes af Faderen), fuld af Naade og Sandhed.","Og Ordet blev Kjød og boede iblandt os, (og vi saae hans Herlighed, en Herlighed, som den Eenbaarnes af Faderen), fuld af Naade og Sandhed."],[1,15,"Johannes vidnede om ham og raabte, sigende: denne er det, om hvem jeg sagde: den, som kommer efter mig, haver været for mig; thi han var førend jeg.","Johannes vidnede om ham og raabte, sigende: denne er det, om hvem jeg sagde: den, som kommer efter mig, haver været for mig; thi han var førend jeg."],[1,16,"Og af hans Fylde have vi annammet, ja, Naade over Naade.","Og af hans Fylde have vi annammet, ja, Naade over Naade."],[1,17,"Thi Loven er given ved Moses; Naaden og Sandheden er vorden ved Jesus Christus.","Thi Loven er given ved Moses; Naaden og Sandheden er vorden ved Jesus Christus."],[1,18,"Ingen har nogen Tid seet Gud; den eenbaarne Søn, som er i Faderens Skjød, han haver kundgjort det.","Ingen har nogen Tid seet Gud; den eenbaarne Søn, som er i Faderens Skjød, han haver kundgjort det."],[1,19,"Og dette er Johannes’ Vidnesbyrd, der Jøderne sendte fra Jerusalem Præster og Leviter, at de skulde spørge ham: hvo er du?","Og dette er Johannes’ Vidnesbyrd, der Jøderne sendte fra Jerusalem Præster og Leviter, at de skulde spørge ham: hvo er du?"],[1,20,"Han bekjendte og negtede ikke, og bekjendte: jeg er ikke den Christus.","Han bekjendte og negtede ikke, og bekjendte: jeg er ikke den Christus."],[1,21,"Og de spurgte ham: hvad da? er du Elias? og han sagde: jeg er det ikke; er du den Prophet? og han svarede: nei.","Og de spurgte ham: hvad da? er du Elias? og han sagde: jeg er det ikke; er du den Prophet? og han svarede: nei."],[1,22,"Da sagde de til ham: hvo er du? at vi kunne give dem Svar, som have udsendt os; hvad siger du om dig selv?","Da sagde de til ham: hvo er du? at vi kunne give dem Svar, som have udsendt os; hvad siger du om dig selv?"],[1,23,"Han sagde: jeg er hans Røst, som raaber i Ørken: jævner Herrens Vei, som Propheten Esaias haver sagt.","Han sagde: jeg er hans Røst, som raaber i Ørken: jævner Herrens Vei, som Propheten Esaias haver sagt."],[1,24,"Og de, som vare udsendte, vare af Pharisæerne.","Og de, som vare udsendte, vare af Pharisæerne."],[1,25,"Og de spurgte ham og sagde til ham: hvi døber du da, dersom du ikke er Christus, ei heller Elias, ei heller den Prophet?","Og de spurgte ham og sagde til ham: hvi døber du da, dersom du ikke er Christus, ei heller Elias, ei heller den Prophet?"],[1,26,"Johannes svarede dem og sagde: jeg døber med Vand; men han staaer midt iblandt Eder, den I ikke kjende.","Johannes svarede dem og sagde: jeg døber med Vand; men han staaer midt iblandt Eder, den I ikke kjende."],[1,27,"Han er den, som kommer efter mig, hvilken haver været for mig, hvis Skotvinge jeg ikke er værdig at opløse.","Han er den, som kommer efter mig, hvilken haver været for mig, hvis Skotvinge jeg ikke er værdig at opløse."],[1,28,"Dette skete i Bethabara paa hiin Side Jordan, hvor Johannes døbte.","Dette skete i Bethabara paa hiin Side Jordan, hvor Johannes døbte."],[1,29,"Den anden Dag seer Johannes Jesus komme til sig, og siger: see det Guds Lam, som bærer Verdens Synd!","Den anden Dag seer Johannes Jesus komme til sig, og siger: see det Guds Lam, som bærer Verdens Synd!"],[1,30,"Han er den, om hvilken jeg sagde: efter mig kommer en Mand, hvilken har været for mig; thi han var førend jeg.","Han er den, om hvilken jeg sagde: efter mig kommer en Mand, hvilken har været for mig; thi han var førend jeg."],[1,31,"Og jeg kjendte ham ikke; men paa det han skulde aabenbares for Israel, derfor er jeg kommen, og døber med Vand.","Og jeg kjendte ham ikke; men paa det han skulde aabenbares for Israel, derfor er jeg kommen, og døber med Vand."],[1,32,"Og Johannes vidnede og sagde: jeg saae, at Aanden foer ned som en Due fra Himmelen, og den blev over ham.","Og Johannes vidnede og sagde: jeg saae, at Aanden foer ned som en Due fra Himmelen, og den blev over ham."],[1,33,"Og jeg kjendte ham ikke; men den, som sendte mig at døbe med Vand, han sagde til mig: paa hvem du seer Aanden fare ned og blive over ham, han er den, som døber med den Hellig Aand.","Og jeg kjendte ham ikke; men den, som sendte mig at døbe med Vand, han sagde til mig: paa hvem du seer Aanden fare ned og blive over ham, han er den, som døber med den Hellig Aand."],[1,34,"Og jeg haver seet det og vidnet, at denne er Guds Søn.","Og jeg haver seet det og vidnet, at denne er Guds Søn."],[1,35,"Den anden Dag stod atter Johannes der og to af hans Disciple.","Den anden Dag stod atter Johannes der og to af hans Disciple."],[1,36,"Og der han saae paa Jesus, som gik der, sagde han: see, det Guds Lam!","Og der han saae paa Jesus, som gik der, sagde han: see, det Guds Lam!"],[1,37,"Og de to Disciple hørte ham tale, og de fulgte Jesus.","Og de to Disciple hørte ham tale, og de fulgte Jesus."],[1,38,"Men Jesus vendte sig om, og saae dem følge, og sagde til dem:","Men Jesus vendte sig om, og saae dem følge, og sagde til dem:"],[1,39,"hvad søge I efter? Men de sagde til ham: Rabbi! (hvilket udlagt betyder: Mester), hvor opholder du dig?","hvad søge I efter? Men de sagde til ham: Rabbi! (hvilket udlagt betyder: Mester), hvor opholder du dig?"],[1,40,"Han sagde til dem: kommer og seer. De kom og saae, hvor han opholdt sig, og bleve samme Dag hos ham; thi det var ved den tiende Time .","Han sagde til dem: kommer og seer. De kom og saae, hvor han opholdt sig, og bleve samme Dag hos ham; thi det var ved den tiende Time ."],[1,41,"Een af de To, som havde hørt dette af Johannes, og havde fulgt ham, var Andreas, Simon Peters Broder.","Een af de To, som havde hørt dette af Johannes, og havde fulgt ham, var Andreas, Simon Peters Broder."],[1,42,"Denne fandt først sin Broder Simon, og sagde til ham: vi have fundet Messias, (hvilket er udlagt: Christus).","Denne fandt først sin Broder Simon, og sagde til ham: vi have fundet Messias, (hvilket er udlagt: Christus)."],[1,43,"Og han førte ham til Jesus. Men der Jesus saae paa ham, sagde han: du er Simon, Jonas’ Søn; du skal hedde Kephas, (det er udlagt Petrus ).","Og han førte ham til Jesus. Men der Jesus saae paa ham, sagde han: du er Simon, Jonas’ Søn; du skal hedde Kephas, (det er udlagt Petrus )."],[1,44,"Den anden Dag vilde Jesus drage hen til Galilæa; og han fandt Philippus og sagde til ham: følg mig.","Den anden Dag vilde Jesus drage hen til Galilæa; og han fandt Philippus og sagde til ham: følg mig."],[1,45,"Men Philippus var fra Bethsaida, fra Andreas’ og Peters Stad.","Men Philippus var fra Bethsaida, fra Andreas’ og Peters Stad."],[1,46,"Philippus fandt Nathanael og sagde til ham: vi have fundet den, om hvem Moses i Loven og Propheterne have skrevet, Jesus, den Josephs Søn, af Nazareth.","Philippus fandt Nathanael og sagde til ham: vi have fundet den, om hvem Moses i Loven og Propheterne have skrevet, Jesus, den Josephs Søn, af Nazareth."],[1,47,"Og Nathanael sagde til ham: kan noget Godt være fra Nazareth? Philippus sagde til ham: kom og see.","Og Nathanael sagde til ham: kan noget Godt være fra Nazareth? Philippus sagde til ham: kom og see."],[1,48,"Jesus saae Nathanael komme til sig, og sagde om ham: see, det er sandelig en Israelit, i hvem der ikke er Svig.","Jesus saae Nathanael komme til sig, og sagde om ham: see, det er sandelig en Israelit, i hvem der ikke er Svig."],[1,49,"Nathanael sagde til ham: hvorfra kjender du mig? Jesus svarede og sagde til ham: førend Philippus kaldte dig, der du var under Figentræet, saae jeg dig.","Nathanael sagde til ham: hvorfra kjender du mig? Jesus svarede og sagde til ham: førend Philippus kaldte dig, der du var under Figentræet, saae jeg dig."],[1,50,"Nathanael svarede og sagde til ham: Rabbi! du er den Guds Søn, du er den Israels Konge.","Nathanael svarede og sagde til ham: Rabbi! du er den Guds Søn, du er den Israels Konge."],[1,51,"Jesus svarede og sagde til ham: troer du, fordi jeg sagde dig: jeg saae dig under Figentræet? du skal see større Ting end disse.","Jesus svarede og sagde til ham: troer du, fordi jeg sagde dig: jeg saae dig under Figentræet? du skal see større Ting end disse."],[1,52,"Og han sagde til ham: sandelig, sandelig siger jeg Eder: fra nu af skulle I see Himmelen aabnet, og Guds Engle fare op og fare ned over Menneskens Søn.","Og han sagde til ham: sandelig, sandelig siger jeg Eder: fra nu af skulle I see Himmelen aabnet, og Guds Engle fare op og fare ned over Menneskens Søn."],[2,1,"Og paa den tredie Dag var et Bryllup i Cana i Galilæa; og Jesu Moder var der.","Og paa den tredie Dag var et Bryllup i Cana i Galilæa; og Jesu Moder var der."],[2,2,"Men ogsaa Jesus og hans Disciple vare budne til Brylluppet.","Men ogsaa Jesus og hans Disciple vare budne til Brylluppet."],[2,3,"Og der de fattedes Viin, sagde Jesu Moder til ham: de have ikke Viin.","Og der de fattedes Viin, sagde Jesu Moder til ham: de have ikke Viin."],[2,4,"Jesus sagde til hende: Kvinde! hvad vil du mig? min Time er endnu ikke kommen.","Jesus sagde til hende: Kvinde! hvad vil du mig? min Time er endnu ikke kommen."],[2,5,"Hans Moder sagde til Tjenerne: hvad som han siger Eder, det gjører.","Hans Moder sagde til Tjenerne: hvad som han siger Eder, det gjører."],[2,6,"Men der vare sex Vandkar af Steen, satte efter Jødernes Renselsesskik, som holdt hver to eller tre Maader.","Men der vare sex Vandkar af Steen, satte efter Jødernes Renselsesskik, som holdt hver to eller tre Maader."],[2,7,"Jesus sagde til dem: fylder Vandkarrene med Vand; og de fyldte dem indtil det Øverste.","Jesus sagde til dem: fylder Vandkarrene med Vand; og de fyldte dem indtil det Øverste."],[2,8,"Og han sagde til dem: øser nu og bærer til Køgemesteren; og de bare det til ham.","Og han sagde til dem: øser nu og bærer til Køgemesteren; og de bare det til ham."],[2,9,"Men der Køgemesteren smagede Vandet, som var blevet Viin, (og vidste ikke, hvorfra det kom, men Tjenerne, som havde øst Vandet, vidste det), kaldte Køgemesteren Brudgommen og sagde til ham:","Men der Køgemesteren smagede Vandet, som var blevet Viin, (og vidste ikke, hvorfra det kom, men Tjenerne, som havde øst Vandet, vidste det), kaldte Køgemesteren Brudgommen og sagde til ham:"],[2,10,"hvert Menneske sætter først den gode Viin frem, og naar de ere blevne drukne, da den ringere; du haver forvaret den gode Viin indtil nu.","hvert Menneske sætter først den gode Viin frem, og naar de ere blevne drukne, da den ringere; du haver forvaret den gode Viin indtil nu."],[2,11,"Denne Begyndelse paa sine Tegn gjorde Jesus i Cana udi Galilæa og aabenbarede sin Herlighed; og hans Disciple troede paa ham.","Denne Begyndelse paa sine Tegn gjorde Jesus i Cana udi Galilæa og aabenbarede sin Herlighed; og hans Disciple troede paa ham."],[2,12,"Derefter drog han ned til Capernaum, han og hans Moder og hans Brødre og hans Disciple, og de bleve der ikke mange Dage.","Derefter drog han ned til Capernaum, han og hans Moder og hans Brødre og hans Disciple, og de bleve der ikke mange Dage."],[2,13,"Og Jødernes Paaske var nær, og Jesus drog op til Jerusalem.","Og Jødernes Paaske var nær, og Jesus drog op til Jerusalem."],[2,14,"Og han fandt til Templet dem, som solgte Øxen og Faar og Duer, og Vexelererne siddende.","Og han fandt til Templet dem, som solgte Øxen og Faar og Duer, og Vexelererne siddende."],[2,15,"Og han gjorde en Svøbe af Snorer og drev dem alle ud af Templet, tilligemed Faarene og Øxnene, og spredte Vexelerernes Penninge og omstødte Bordene.","Og han gjorde en Svøbe af Snorer og drev dem alle ud af Templet, tilligemed Faarene og Øxnene, og spredte Vexelerernes Penninge og omstødte Bordene."],[2,16,"Og han sagde til dem, som solgte Duer: tager dette herfra; gjører ikke min Faders Huus til et Kjøbehuus.","Og han sagde til dem, som solgte Duer: tager dette herfra; gjører ikke min Faders Huus til et Kjøbehuus."],[2,17,"Men hans Disciple kom ihu, at der er skrevet: Nidkjærhed for dit Huus haver fortæret mig.","Men hans Disciple kom ihu, at der er skrevet: Nidkjærhed for dit Huus haver fortæret mig."],[2,18,"Da svarede Jøderne og sagde til ham: hvad viser du os for et Tegn, efterdi du gjør dette?","Da svarede Jøderne og sagde til ham: hvad viser du os for et Tegn, efterdi du gjør dette?"],[2,19,"Jesus svarede og sagde til dem: nedbryder dette Tempel, og i tre Dage vil jeg opreise det.","Jesus svarede og sagde til dem: nedbryder dette Tempel, og i tre Dage vil jeg opreise det."],[2,20,"Derfor sagde Jøderne: paa dette Tempel er bygt i sex og fyrretyve Aar, og du vil opreise det i tre Dage?","Derfor sagde Jøderne: paa dette Tempel er bygt i sex og fyrretyve Aar, og du vil opreise det i tre Dage?"],[2,21,"Men han talede om sit Legems Tempel.","Men han talede om sit Legems Tempel."],[2,22,"Derfor, der han var opstanden fra de Døde, kom hans Disciple ihu, at han havde sagt dette til dem; og de troede Skriften og de Ord, som Jesus havde sagt.","Derfor, der han var opstanden fra de Døde, kom hans Disciple ihu, at han havde sagt dette til dem; og de troede Skriften og de Ord, som Jesus havde sagt."],[2,23,"Men der han var i Jerusalem om Paasken paa Høitiden, troede Mange paa hans Navn, der de saae hans Tegn, som han gjorde.","Men der han var i Jerusalem om Paasken paa Høitiden, troede Mange paa hans Navn, der de saae hans Tegn, som han gjorde."],[2,24,"Men Jesus selv betroede sig ikke til dem, fordi han kjendte Alle,","Men Jesus selv betroede sig ikke til dem, fordi han kjendte Alle,"],[2,25,"og fordi han havde ikke behov, at Nogen skulde vidne om et Menneske; thi han vidste selv, hvad der var i Mennesket.","og fordi han havde ikke behov, at Nogen skulde vidne om et Menneske; thi han vidste selv, hvad der var i Mennesket."],[3,1,"Men der var en Mand af Pharisæerne, han hedte Nicodemus, en Øverste iblandt Jøderne.","Men der var en Mand af Pharisæerne, han hedte Nicodemus, en Øverste iblandt Jøderne."],[3,2,"Han kom til Jesus om Natten og sagde til ham: Mester! vi vide, at du er en Lærer, kommen fra Gud; thi Ingen kan gjøre de Tegn, som du gjør, uden Gud er med ham.","Han kom til Jesus om Natten og sagde til ham: Mester! vi vide, at du er en Lærer, kommen fra Gud; thi Ingen kan gjøre de Tegn, som du gjør, uden Gud er med ham."],[3,3,"Jesus svarede og sagde til ham: sandelig, sandelig siger jeg dig: uden Nogen bliver født paa ny, kan han ikke see Guds Rige.","Jesus svarede og sagde til ham: sandelig, sandelig siger jeg dig: uden Nogen bliver født paa ny, kan han ikke see Guds Rige."],[3,4,"Nicodemus siger til ham: hvorledes kan et Menneske fødes, naar han er gammel? Mon han kan anden Gang komme ind i sin Moders Liv, og fødes?","Nicodemus siger til ham: hvorledes kan et Menneske fødes, naar han er gammel? Mon han kan anden Gang komme ind i sin Moders Liv, og fødes?"],[3,5,"Jesus svarede: sandelig, sandelig siger jeg dig: uden Nogen bliver født af Vand og Aand, kan han ikke indkomme i Guds Rige.","Jesus svarede: sandelig, sandelig siger jeg dig: uden Nogen bliver født af Vand og Aand, kan han ikke indkomme i Guds Rige."],[3,6,"Hvad som født er af Kjødet, er Kjød; og hvad som er født af Aanden, er Aand.","Hvad som født er af Kjødet, er Kjød; og hvad som er født af Aanden, er Aand."],[3,7,"Forundre dig ikke, at jeg sagde til dig: det bør Eder at fødes paa ny.","Forundre dig ikke, at jeg sagde til dig: det bør Eder at fødes paa ny."],[3,8,"Veiret blæser, hvorhen det vil, og du hører dets Susen, men du veed ikke hvorfra det kommer, og hvor det farer hen; saaledes er det med hver, som er født af Aanden.","Veiret blæser, hvorhen det vil, og du hører dets Susen, men du veed ikke hvorfra det kommer, og hvor det farer hen; saaledes er det med hver, som er født af Aanden."],[3,9,"Nicodemus svarede og sagde til ham: hvorledes kan dette skee?","Nicodemus svarede og sagde til ham: hvorledes kan dette skee?"],[3,10,"Jesus svarede og sagde til ham: er du en Israels Lærer, og veed ikke dette?","Jesus svarede og sagde til ham: er du en Israels Lærer, og veed ikke dette?"],[3,11,"Sandelig, sandelig siger jeg dig: vi tale det, vi vide, og vidne det, vi have seet; og I annamme ikke vort Vidnesbyrd.","Sandelig, sandelig siger jeg dig: vi tale det, vi vide, og vidne det, vi have seet; og I annamme ikke vort Vidnesbyrd."],[3,12,"Dersom jeg siger Eder de jordiske Ting, og I ikke troe, hvorledes skulde I troe, om jeg sagde Eder de himmelske?","Dersom jeg siger Eder de jordiske Ting, og I ikke troe, hvorledes skulde I troe, om jeg sagde Eder de himmelske?"],[3,13,"Og Ingen farer op til Himmelen, uden den, som foer ned af Himmelen, Menneskens Søn, som er i Himmelen.","Og Ingen farer op til Himmelen, uden den, som foer ned af Himmelen, Menneskens Søn, som er i Himmelen."],[3,14,"Og ligesom Moses ophøiede Slangen i Ørken, saa bør det Menneskens Søn at ophøies,","Og ligesom Moses ophøiede Slangen i Ørken, saa bør det Menneskens Søn at ophøies,"],[3,15,"paa det at hver den, som troer paa ham, ikke skal fortabes, men have et evigt Liv.","paa det at hver den, som troer paa ham, ikke skal fortabes, men have et evigt Liv."],[3,16,"Thi saa haver Gud elsket Verden, at han haver givet sin Søn den eenbaarne, at hver den, som troer paa ham, ikke skal fortabes, men have et evigt Liv.","Thi saa haver Gud elsket Verden, at han haver givet sin Søn den eenbaarne, at hver den, som troer paa ham, ikke skal fortabes, men have et evigt Liv."],[3,17,"Thi Gud haver ikke sendt sin Søn til Verden, at han skal dømme Verden, men at Verden skal blive salig ved ham.","Thi Gud haver ikke sendt sin Søn til Verden, at han skal dømme Verden, men at Verden skal blive salig ved ham."],[3,18,"Hvo som troer paa ham, dømmes ikke; men hvo som ikke troer, er allerede dømt, fordi han ikke troet paa Guds eenbaarne Søns Navn.","Hvo som troer paa ham, dømmes ikke; men hvo som ikke troer, er allerede dømt, fordi han ikke troet paa Guds eenbaarne Søns Navn."],[3,19,"Men denne er Dommen, at Lyset er kommet til Verden, og Menneskene elskede mere Mørket end Lyset; thi deres Gjerninger vare onde.","Men denne er Dommen, at Lyset er kommet til Verden, og Menneskene elskede mere Mørket end Lyset; thi deres Gjerninger vare onde."],[3,20,"Thi hver, som gjør Ondt, hader Lyset og kommer ikke til Lyset, at hans Gjerninger ikke skulle overbevises ham.","Thi hver, som gjør Ondt, hader Lyset og kommer ikke til Lyset, at hans Gjerninger ikke skulle overbevises ham."],[3,21,"Men hvo som øver Sandhed, kommer til Lyset, at hans Gjerninger maae blive aabenbarede; thi de ere gjorte i Gud.","Men hvo som øver Sandhed, kommer til Lyset, at hans Gjerninger maae blive aabenbarede; thi de ere gjorte i Gud."],[3,22,"Derefter kom Jesus og hans Disciple til Judæas Land, og han opholdt sig der med dem, og døbte.","Derefter kom Jesus og hans Disciple til Judæas Land, og han opholdt sig der med dem, og døbte."],[3,23,"Men ogsaa Johannes døbte i Ænon, nær ved Salem, fordi der var meget Vand; og de kom derhen og bleve døbte.","Men ogsaa Johannes døbte i Ænon, nær ved Salem, fordi der var meget Vand; og de kom derhen og bleve døbte."],[3,24,"Thi Johannes var ikke endnu kastet i Fængsel.","Thi Johannes var ikke endnu kastet i Fængsel."],[3,25,"Da opkom der en Tvist imellem Johannes’ Disciple og Jøderne om Renselsen.","Da opkom der en Tvist imellem Johannes’ Disciple og Jøderne om Renselsen."],[3,26,"Og de kom til Johannes og sagde til ham: Mester! den, som var hos dig paa hiin Side Jorden, hvilken du gav Vidnesbyrd, see, han døber, og Alle komme til ham.","Og de kom til Johannes og sagde til ham: Mester! den, som var hos dig paa hiin Side Jorden, hvilken du gav Vidnesbyrd, see, han døber, og Alle komme til ham."],[3,27,"Johannes svarede og sagde: et Menneske kan slet intet tage, uden det bliver givet ham af Himmelen.","Johannes svarede og sagde: et Menneske kan slet intet tage, uden det bliver givet ham af Himmelen."],[3,28,"I ere selv mine Vidner, at jeg sagde: jeg er ikke den Christus, men at jeg er udsendt for ham.","I ere selv mine Vidner, at jeg sagde: jeg er ikke den Christus, men at jeg er udsendt for ham."],[3,29,"Den, som haver Bruden, er Brudgommen; men Brudgommens Ven, som staaer og hører ham, glæder sig meget over Brudgommens Røst. Denne min Glæde er fuldkommen.","Den, som haver Bruden, er Brudgommen; men Brudgommens Ven, som staaer og hører ham, glæder sig meget over Brudgommens Røst. Denne min Glæde er fuldkommen."],[3,30,"Ham bør at voxe, men mig at forringes.","Ham bør at voxe, men mig at forringes."],[3,31,"Den, som kommer ovenfra, er over Alle; den, som er af Jorden, er af Jorden, og taler af Jorden; den, som kommer af Himmelen, er over Alle.","Den, som kommer ovenfra, er over Alle; den, som er af Jorden, er af Jorden, og taler af Jorden; den, som kommer af Himmelen, er over Alle."],[3,32,"Og det, som han haver seet og hørt, vidner han; og Ingen annammer hans Vidnesbyrd.","Og det, som han haver seet og hørt, vidner han; og Ingen annammer hans Vidnesbyrd."],[3,33,"Den, som annammer hans Vidnesbyrd, besegler, at Gud er sanddru.","Den, som annammer hans Vidnesbyrd, besegler, at Gud er sanddru."],[3,34,"Thi den, som Gud udsendte, taler Guds Ord; thi Gud giver ham Aanden over al Maade.","Thi den, som Gud udsendte, taler Guds Ord; thi Gud giver ham Aanden over al Maade."],[3,35,"Faderen elsker Sønnen, og haver givet alle Ting i hans Haand.","Faderen elsker Sønnen, og haver givet alle Ting i hans Haand."],[3,36,"Hvo som troer paa Sønnen, haver et evigt Liv; men hvo som ikke troer Sønnen, skal ikke see Livet, men Guds Vrede bliver over ham.","Hvo som troer paa Sønnen, haver et evigt Liv; men hvo som ikke troer Sønnen, skal ikke see Livet, men Guds Vrede bliver over ham."],[4,1,"Der Herren nu erfarede, at Pharisæerne havde hørt, at Jesus gjorde flere Disciple og døbte flere end Johannes,","Der Herren nu erfarede, at Pharisæerne havde hørt, at Jesus gjorde flere Disciple og døbte flere end Johannes,"],[4,2,"(enddog Jesus ikke døbte selv, men hans Disciple):","(enddog Jesus ikke døbte selv, men hans Disciple):"],[4,3,"da forlod han Judæa og drog atter hen til Galilæa.","da forlod han Judæa og drog atter hen til Galilæa."],[4,4,"Men han maatte reise igjennem Samaria.","Men han maatte reise igjennem Samaria."],[4,5,"Da kom han til en Stad i Samaria, som kaldes Sichar, nær ved det Stykke Land, som Jakob gav Joseph sin Søn.","Da kom han til en Stad i Samaria, som kaldes Sichar, nær ved det Stykke Land, som Jakob gav Joseph sin Søn."],[4,6,"Men der var Jakobs Brønd. Der Jesus da var træt af Reisen, satte han sig ved Brønden; det var ved den sjette Time.","Men der var Jakobs Brønd. Der Jesus da var træt af Reisen, satte han sig ved Brønden; det var ved den sjette Time."],[4,7,"Da kom en samaritansk Kvinde, at drage Vand op. Jesus sagde til hende: giv mig at drikke.","Da kom en samaritansk Kvinde, at drage Vand op. Jesus sagde til hende: giv mig at drikke."],[4,8,"Thi hans Disciple vare gangne til Staden for at kjøbe Mad.","Thi hans Disciple vare gangne til Staden for at kjøbe Mad."],[4,9,"Da sagde den samaritanske Kvinde til ham: hvorledes beder du, som er en Jøde, mig, som er en samaritansk Kvinde, om Drikke? Thi Jøder holde ikke Samkvem med Samaritaner.","Da sagde den samaritanske Kvinde til ham: hvorledes beder du, som er en Jøde, mig, som er en samaritansk Kvinde, om Drikke? Thi Jøder holde ikke Samkvem med Samaritaner."],[4,10,"Jesus svarede og sagde til hende: dersom du kjendte Guds Gave, og hvo den er, som siger til dig: giv mig at drikke, da bad du ham, og han gav dig levende Vand.","Jesus svarede og sagde til hende: dersom du kjendte Guds Gave, og hvo den er, som siger til dig: giv mig at drikke, da bad du ham, og han gav dig levende Vand."],[4,11,"Kvinden sagde til ham: Herre! du haver jo Intet at drage op med, og Brønden er dyb; hvorfra haver du da det levende Vand?","Kvinden sagde til ham: Herre! du haver jo Intet at drage op med, og Brønden er dyb; hvorfra haver du da det levende Vand?"],[4,12,"Mon du være mere end vor Fader Jakob, som haver givet os Brønden, og han haver selv drukket deraf, og hans Børn og hans Kvæg?","Mon du være mere end vor Fader Jakob, som haver givet os Brønden, og han haver selv drukket deraf, og hans Børn og hans Kvæg?"],[4,13,"Jesus svarede og sagde til hende: hver den, som drikker af dette Vand, skal tørste igjen,","Jesus svarede og sagde til hende: hver den, som drikker af dette Vand, skal tørste igjen,"],[4,14,"men hvo som drikker af det Vand, som jeg vil give ham, skal til evig Tid ikke tørste; men det Vand, som jeg vil give ham, skal blive i ham en Kilde af Vand, som opvælder til et evigt Liv.","men hvo som drikker af det Vand, som jeg vil give ham, skal til evig Tid ikke tørste; men det Vand, som jeg vil give ham, skal blive i ham en Kilde af Vand, som opvælder til et evigt Liv."],[4,15,"Kvinden siger til ham: Herre! giv mig det Vand, at jeg ikke skal tørste, og ikke komme hid for at drage op.","Kvinden siger til ham: Herre! giv mig det Vand, at jeg ikke skal tørste, og ikke komme hid for at drage op."],[4,16,"Jesus siger til hende: gak bort, kald din Mand og kom hid.","Jesus siger til hende: gak bort, kald din Mand og kom hid."],[4,17,"Kvinden svarede og sagde: jeg haver ingen Mand. Jesus siger til hende: du talede ret: jeg haver ingen Mand.","Kvinden svarede og sagde: jeg haver ingen Mand. Jesus siger til hende: du talede ret: jeg haver ingen Mand."],[4,18,"Thi du haver havt fem Mænd; og den, som du nu haver, er ikke din Mand. Det sagde du sandt.","Thi du haver havt fem Mænd; og den, som du nu haver, er ikke din Mand. Det sagde du sandt."],[4,19,"Kvinden siger til ham: Herre! jeg seer, at du er en Prophet.","Kvinden siger til ham: Herre! jeg seer, at du er en Prophet."],[4,20,"Vore Fædre have tilbedet paa dette Bjerg, og I sige, at i Jerusalem er Stedet, hvor man bør tilbede.","Vore Fædre have tilbedet paa dette Bjerg, og I sige, at i Jerusalem er Stedet, hvor man bør tilbede."],[4,21,"Jesus siger til hende: Kvinde! tro mig, at den Time kommer, da I hverken paa dette Bjerg, ei heller i Jerusalem, skulle tilbede Faderen.","Jesus siger til hende: Kvinde! tro mig, at den Time kommer, da I hverken paa dette Bjerg, ei heller i Jerusalem, skulle tilbede Faderen."],[4,22,"I tilbede det, som I ikke kjende; vi tilbede det, som vi kjende; thi Saliggjørelsen kommer fra Jøderne.","I tilbede det, som I ikke kjende; vi tilbede det, som vi kjende; thi Saliggjørelsen kommer fra Jøderne."],[4,23,"Men den Time kommer, ja er nu, da de sande Tilbedere skulle tilbede Faderen i Aand og Sandhed; thi Faderen søger saadanne, som ham saaledes tilbede.","Men den Time kommer, ja er nu, da de sande Tilbedere skulle tilbede Faderen i Aand og Sandhed; thi Faderen søger saadanne, som ham saaledes tilbede."],[4,24,"Gud er en Aand; og de, som han tilbede, bør det at tilbede i Aand og Sandhed.","Gud er en Aand; og de, som han tilbede, bør det at tilbede i Aand og Sandhed."],[4,25,"Kvinden siger til ham: jeg veed, at Messias kommer, (hvilket betyder Christus); naar han kommer, skal hen kundgjøre os alle Ting.","Kvinden siger til ham: jeg veed, at Messias kommer, (hvilket betyder Christus); naar han kommer, skal hen kundgjøre os alle Ting."],[4,26,"Jesus siger til hende: ham er jeg, som taler med dig.","Jesus siger til hende: ham er jeg, som taler med dig."],[4,27,"Og i det samme kom hans Disciple, og forundrede sig, at han talede med Kvinden; dog sagde Ingen: hvad spørger du? eller, hvad taler du med hende?","Og i det samme kom hans Disciple, og forundrede sig, at han talede med Kvinden; dog sagde Ingen: hvad spørger du? eller, hvad taler du med hende?"],[4,28,"Da lod Kvinden sit Vandkar staae, og gik ind i Staden og sagde til Menneskene der:","Da lod Kvinden sit Vandkar staae, og gik ind i Staden og sagde til Menneskene der:"],[4,29,"kommer, seer et Menneske, som haver sagt mig alt det, jeg haver gjort; mon denne ikke være den Christus?","kommer, seer et Menneske, som haver sagt mig alt det, jeg haver gjort; mon denne ikke være den Christus?"],[4,30,"Da gik de ud af Staden og kom til ham.","Da gik de ud af Staden og kom til ham."],[4,31,"Imidlertid bade Disciplene ham og sagde: Mester, æd!","Imidlertid bade Disciplene ham og sagde: Mester, æd!"],[4,32,"Men han sagde til dem: jeg haver Mad at æde, den I ikke kjende.","Men han sagde til dem: jeg haver Mad at æde, den I ikke kjende."],[4,33,"Da sagde Disciplene til hverandre: mon Nogen haver bragt ham Noget at æde?","Da sagde Disciplene til hverandre: mon Nogen haver bragt ham Noget at æde?"],[4,34,"Jesus sagde til dem: min Mad er, at jeg gjør hans Villie, som mig udsendte, og fuldkommer hans Gjerning.","Jesus sagde til dem: min Mad er, at jeg gjør hans Villie, som mig udsendte, og fuldkommer hans Gjerning."],[4,35,"Sige I ikke: der er endnu fire Maaneder, saa kommer Høsten? See, jeg siger Eder: opløfter Eders Øine, og seer Markerne: de ere allerede hvide til Høsten.","Sige I ikke: der er endnu fire Maaneder, saa kommer Høsten? See, jeg siger Eder: opløfter Eders Øine, og seer Markerne: de ere allerede hvide til Høsten."],[4,36,"Og hvo som høster, faaer Løn, og samler Frugt til et evigt Liv; paa det de skulle glæde sig tilhobe, baade den, som saaer, og den, som høster.","Og hvo som høster, faaer Løn, og samler Frugt til et evigt Liv; paa det de skulle glæde sig tilhobe, baade den, som saaer, og den, som høster."],[4,37,"Thi herudi er hiint Ord sandt: En saaer, og en Anden høster.","Thi herudi er hiint Ord sandt: En saaer, og en Anden høster."],[4,38,"Jeg haver udsendt Eder, at høste det, som I ikke arbeidede; Andre have arbeidet, og I ere indkomne i deres Arbeide.","Jeg haver udsendt Eder, at høste det, som I ikke arbeidede; Andre have arbeidet, og I ere indkomne i deres Arbeide."],[4,39,"Men mange Samaritaner af den samme Stad troede paa ham for Kvindens tales Skyld, som vidnede: han haver sagt mig alt det, jeg haver gjort.","Men mange Samaritaner af den samme Stad troede paa ham for Kvindens tales Skyld, som vidnede: han haver sagt mig alt det, jeg haver gjort."],[4,40,"Da nu Samaritanerne kom til ham, bade de ham, at han vilde blive hos dem; og han blev der to Dage.","Da nu Samaritanerne kom til ham, bade de ham, at han vilde blive hos dem; og han blev der to Dage."],[4,41,"Og mange Flere troede for hans Tales Skyld.","Og mange Flere troede for hans Tales Skyld."],[4,42,"Og de sagde til Kvinden: vi troe nu ikke længere for din Tales Skyld; thi vi have selv hørt, og vide, at denne er sandelig den Verdens Frelser, den Christus.","Og de sagde til Kvinden: vi troe nu ikke længere for din Tales Skyld; thi vi have selv hørt, og vide, at denne er sandelig den Verdens Frelser, den Christus."],[4,43,"Men efter to Dage gik han derfra og drog til Galilæa.","Men efter to Dage gik han derfra og drog til Galilæa."],[4,44,"Thi Jesus vidnede selv, at en Prophet bliver ikke æret i sit Fædreneland.","Thi Jesus vidnede selv, at en Prophet bliver ikke æret i sit Fædreneland."],[4,45,"Der han da kom til Galilæa, annammede de Galilæer ham, som havde seet alt det, som han gjorde i Jerusalem paa Høitiden; thi de vare og komne til Høitiden.","Der han da kom til Galilæa, annammede de Galilæer ham, som havde seet alt det, som han gjorde i Jerusalem paa Høitiden; thi de vare og komne til Høitiden."],[4,46,"Da kom Jesus atter til Cana i Galilæa, hvor han havde gjort Vand til Viin. Og der var en kongelig Tjener, hvis Søn laae syg i Capernaum.","Da kom Jesus atter til Cana i Galilæa, hvor han havde gjort Vand til Viin. Og der var en kongelig Tjener, hvis Søn laae syg i Capernaum."],[4,47,"Der denne hørte, at Jesus var kommen fra Judæa til Galilæa, gik han til ham og bad ham, at han vilde komme og helbrede hans Søn; thi han var nær Døden.","Der denne hørte, at Jesus var kommen fra Judæa til Galilæa, gik han til ham og bad ham, at han vilde komme og helbrede hans Søn; thi han var nær Døden."],[4,48,"Da sagde Jesus til ham: dersom I ikke see Tegn og Undergjerninger, ville I ikke troe.","Da sagde Jesus til ham: dersom I ikke see Tegn og Undergjerninger, ville I ikke troe."],[4,49,"Manden sagde til ham: Herre! kom, før mit Barn døer.","Manden sagde til ham: Herre! kom, før mit Barn døer."],[4,50,"Jesus siger til ham: gak bort, din Søn lever. Og Manden troede det Ord, som Jesus sagde til ham, og gik bort.","Jesus siger til ham: gak bort, din Søn lever. Og Manden troede det Ord, som Jesus sagde til ham, og gik bort."],[4,51,"Men idet han nu drog bort, mødte hans Tjenere ham, og forkyndte og sagde: dit Barn lever.","Men idet han nu drog bort, mødte hans Tjenere ham, og forkyndte og sagde: dit Barn lever."],[4,52,"Da udspurgte han af dem den Time, paa hvilken det var blevet bedre med ham; og de sagde til ham: igaar ved den syvende Time forlod Feberen ham.","Da udspurgte han af dem den Time, paa hvilken det var blevet bedre med ham; og de sagde til ham: igaar ved den syvende Time forlod Feberen ham."],[4,53,"Da mærkede Faderen, at det var skeet paa den samme Time, paa hvilken Jesus havde sagt til ham: din Søn lever! og han troede selv og hans ganske Huus.","Da mærkede Faderen, at det var skeet paa den samme Time, paa hvilken Jesus havde sagt til ham: din Søn lever! og han troede selv og hans ganske Huus."],[4,54,"Dette fik andet Tegn gjorde Jesus, der han var kommen fra Judæa til Galilæa.","Dette fik andet Tegn gjorde Jesus, der han var kommen fra Judæa til Galilæa."],[5,1,"Derefter var det Jødernes Høitid, og Jesus gik op til Jerusalem.","Derefter var det Jødernes Høitid, og Jesus gik op til Jerusalem."],[5,2,"Men der var en Dam i Jerusalem ved Faareporten, den kaldes paa Hebraisk Bethesda, og haver fem Buegange.","Men der var en Dam i Jerusalem ved Faareporten, den kaldes paa Hebraisk Bethesda, og haver fem Buegange."],[5,3,"I dem laae en stor Mængde af Syge, Blinde, Halte, Visne, som ventede paa, at Vandet skulde røres.","I dem laae en stor Mængde af Syge, Blinde, Halte, Visne, som ventede paa, at Vandet skulde røres."],[5,4,"Thi paa visse Tider foer en Engel ned udi Dammen og oprørte Vandet. Hvo som da først, efter Vandets Oprør, steg ned, blev sund, hvadsomhelst Syge han var beheftet med.","Thi paa visse Tider foer en Engel ned udi Dammen og oprørte Vandet. Hvo som da først, efter Vandets Oprør, steg ned, blev sund, hvadsomhelst Syge han var beheftet med."],[5,5,"Men der var et Menneske, som havde ligget otte og tredive Aar i Sygdom.","Men der var et Menneske, som havde ligget otte og tredive Aar i Sygdom."],[5,6,"Der Jesus saae ham ligge, og vidste, at han allerede havde ligget lang Tid, sagde han til ham: vil du vorde sund?","Der Jesus saae ham ligge, og vidste, at han allerede havde ligget lang Tid, sagde han til ham: vil du vorde sund?"],[5,7,"Den Syge svarede ham: Herre! jeg haver Ingen, som kan bringe mig i Dammen, naar Vandet bliver oprørt; men naar jeg kommer, nedstiger en Anden før jeg.","Den Syge svarede ham: Herre! jeg haver Ingen, som kan bringe mig i Dammen, naar Vandet bliver oprørt; men naar jeg kommer, nedstiger en Anden før jeg."],[5,8,"Jesus sagde til ham: staa op, tag din Seng og gak.","Jesus sagde til ham: staa op, tag din Seng og gak."],[5,9,"Og strax blev Mennesket sundt, og tog sin Seng og gik; men det var Sabbat paa den samme Dag.","Og strax blev Mennesket sundt, og tog sin Seng og gik; men det var Sabbat paa den samme Dag."],[5,10,"Derfor sagde Jøderne til den, som var bleven helbredet: det er Sabbat, det er dig ei tilladt at bære Sengen.","Derfor sagde Jøderne til den, som var bleven helbredet: det er Sabbat, det er dig ei tilladt at bære Sengen."],[5,11,"Han svarede dem: den, som gjorde mig sund, han sagde til mig: tag din Seng og gak.","Han svarede dem: den, som gjorde mig sund, han sagde til mig: tag din Seng og gak."],[5,12,"Da spurgte de ham: hvo er det Menneske, som sagde til dig: tag din Seng og gak?","Da spurgte de ham: hvo er det Menneske, som sagde til dig: tag din Seng og gak?"],[5,13,"Men den, som var bleven helbredet, vidste ikke, hvo han var; thi Jesus havde unddraget sig, da der var meget Folk paa Stedet.","Men den, som var bleven helbredet, vidste ikke, hvo han var; thi Jesus havde unddraget sig, da der var meget Folk paa Stedet."],[5,14,"Derefter fandt Jesus ham i Templet og sagde til ham: see, du er bleven sund; synd ikke mere, at dig ikke noget værre skal vederfares.","Derefter fandt Jesus ham i Templet og sagde til ham: see, du er bleven sund; synd ikke mere, at dig ikke noget værre skal vederfares."],[5,15,"Mennesket gik bort og kundgjorde Jøderne, at det var Jesus, som havde gjort ham sund.","Mennesket gik bort og kundgjorde Jøderne, at det var Jesus, som havde gjort ham sund."],[5,16,"Og derfor forfulgte Jøderne Jesus, og søgte at slaae ham ihjel, efterdi han havde gjort dette paa en Sabbat.","Og derfor forfulgte Jøderne Jesus, og søgte at slaae ham ihjel, efterdi han havde gjort dette paa en Sabbat."],[5,17,"Men Jesus svarede dem: min Fader arbeider indtil nu, og jeg arbeider.","Men Jesus svarede dem: min Fader arbeider indtil nu, og jeg arbeider."],[5,18,"Derfor søgte da Jøderne end mere at slaae ham ihjel, fordi han ikke aleneste brød Sabbaten, men og kaldte Gud sin egen Fader, og gjorde sig selv Gud lig.","Derfor søgte da Jøderne end mere at slaae ham ihjel, fordi han ikke aleneste brød Sabbaten, men og kaldte Gud sin egen Fader, og gjorde sig selv Gud lig."],[5,19,"Derfor svarede Jesus og sagde til dem: sandelig, sandelig siger jeg Eder: Sønnen kan slet intet gjøre af sig selv, uden hvad han seer Faderen gjøre; thi hvilke Ting, som han gjør, de samme gjør og Sønnen ligesaa.","Derfor svarede Jesus og sagde til dem: sandelig, sandelig siger jeg Eder: Sønnen kan slet intet gjøre af sig selv, uden hvad han seer Faderen gjøre; thi hvilke Ting, som han gjør, de samme gjør og Sønnen ligesaa."],[5,20,"Thi Faderen elsker Sønnen, og viser ham alt det, han selv gjør, og han skal vise ham større Gjerninger end disse, at I skulle forundre Eder.","Thi Faderen elsker Sønnen, og viser ham alt det, han selv gjør, og han skal vise ham større Gjerninger end disse, at I skulle forundre Eder."],[5,21,"Thi ligesom Faderen opvækker Døde og gjør levende, ligesaa gjør og Sønnen levende, hvilke han vil.","Thi ligesom Faderen opvækker Døde og gjør levende, ligesaa gjør og Sønnen levende, hvilke han vil."],[5,22,"Ogsaa dømmer Faderen Ingen, men haver givet Sønnen al Dom,","Ogsaa dømmer Faderen Ingen, men haver givet Sønnen al Dom,"],[5,23,"at Alle skulle ære Sønnen, ligesom de ære Faderen. Hvo som ikke ærer Sønnen, ærer ikke Faderen, som ham udsendte.","at Alle skulle ære Sønnen, ligesom de ære Faderen. Hvo som ikke ærer Sønnen, ærer ikke Faderen, som ham udsendte."],[5,24,"Sandelig, sandelig siger jeg Eder: hvo som hører mit Ord, og troer den, som mig udsendte, haver et evigt Liv, og kommer ikke til Dommen, men er gaaet over fra Døden til Livet.","Sandelig, sandelig siger jeg Eder: hvo som hører mit Ord, og troer den, som mig udsendte, haver et evigt Liv, og kommer ikke til Dommen, men er gaaet over fra Døden til Livet."],[5,25,"Sandelig, sandelig siger jeg Eder: den Time kommer, ja, er nu, da de Døde skulle høre Guds Søns Røst, og de, som den høre, skulle leve.","Sandelig, sandelig siger jeg Eder: den Time kommer, ja, er nu, da de Døde skulle høre Guds Søns Røst, og de, som den høre, skulle leve."],[5,26,"Thi ligesom Faderen haver Livet i sig selv, saaledes haver han og givet Sønnen at have Livet i sig selv;","Thi ligesom Faderen haver Livet i sig selv, saaledes haver han og givet Sønnen at have Livet i sig selv;"],[5,27,"og haver givet ham Magt, ogsaa at holde Dom, efterdi han er Menneskens Søn.","og haver givet ham Magt, ogsaa at holde Dom, efterdi han er Menneskens Søn."],[5,28,"Forundrer Eder ikke herover; thi den Time kommer, paa hvilken alle de i Gravene skulle høre hans Røst,","Forundrer Eder ikke herover; thi den Time kommer, paa hvilken alle de i Gravene skulle høre hans Røst,"],[5,29,"og de skulle gaae frem, de, som have gjort Godt, til Livsens Opstandelse, men de, som have gjort Ondt, til Dommens Opstandelse.","og de skulle gaae frem, de, som have gjort Godt, til Livsens Opstandelse, men de, som have gjort Ondt, til Dommens Opstandelse."],[5,30,"Jeg kan slet intet gjøre af mig selv; ligesom jeg hører, dømmer jeg, og min Dom er retfærdig; thi jeg søger ikke min Villie, men Faderens Villie, som haver udsendt mig.","Jeg kan slet intet gjøre af mig selv; ligesom jeg hører, dømmer jeg, og min Dom er retfærdig; thi jeg søger ikke min Villie, men Faderens Villie, som haver udsendt mig."],[5,31,"Dersom jeg vidner om mig selv, er mit Vidnesbyrd ikke sandt.","Dersom jeg vidner om mig selv, er mit Vidnesbyrd ikke sandt."],[5,32,"Der er en Anden, som vidner om mig, og jeg veed, at det Vidnesbyrd er sandt, som han vidner om mig.","Der er en Anden, som vidner om mig, og jeg veed, at det Vidnesbyrd er sandt, som han vidner om mig."],[5,33,"I have sendt til Johannes, og han haver vidnet for Sandheden.","I have sendt til Johannes, og han haver vidnet for Sandheden."],[5,34,"Men ikke fra et Menneske henter jeg Vidnesbyrd; dog dette siger jeg, paa det I skulle frelses.","Men ikke fra et Menneske henter jeg Vidnesbyrd; dog dette siger jeg, paa det I skulle frelses."],[5,35,"Han var et brændende og skinnende Lys; men I have til en Tid villet fryde Eder ved hans Lys.","Han var et brændende og skinnende Lys; men I have til en Tid villet fryde Eder ved hans Lys."],[5,36,"Men jeg haver et større Vidnesbyrd end Johannes’; thi de Gjerninger, som Faderen haver givet mig at fuldkomme, disse Gjerninger, som jeg gjør, vidne om mig, at Faderen haver udsendt mig.","Men jeg haver et større Vidnesbyrd end Johannes’; thi de Gjerninger, som Faderen haver givet mig at fuldkomme, disse Gjerninger, som jeg gjør, vidne om mig, at Faderen haver udsendt mig."],[5,37,"Og Faderen, som haver udsendt mig, haver selv vidnet om mig; I have aldrig hverken hørt hans Røst eller seet hans Skikkelse.","Og Faderen, som haver udsendt mig, haver selv vidnet om mig; I have aldrig hverken hørt hans Røst eller seet hans Skikkelse."],[5,38,"Og I have ikke hans Ord blivende i Eder; thi den, som han haver udsendt, ham troe I ikke.","Og I have ikke hans Ord blivende i Eder; thi den, som han haver udsendt, ham troe I ikke."],[5,39,"I ransage Skrifterne, fordi I mene i dem at have et evigt Liv; og disse er det, som vidne om mig.","I ransage Skrifterne, fordi I mene i dem at have et evigt Liv; og disse er det, som vidne om mig."],[5,40,"Og I ville ikke komme til mig, at I kunne have Livet.","Og I ville ikke komme til mig, at I kunne have Livet."],[5,41,"Jeg tager ikke Ære af Mennesker;","Jeg tager ikke Ære af Mennesker;"],[5,42,"men jeg kjender Eder, at I have ikke Guds Kjærlighed i Eder.","men jeg kjender Eder, at I have ikke Guds Kjærlighed i Eder."],[5,43,"Jeg er kommen i min Faders Navn, og I annamme mig ikke; dersom en Anden kommer i sit eget Navn, ham skulle I annamme.","Jeg er kommen i min Faders Navn, og I annamme mig ikke; dersom en Anden kommer i sit eget Navn, ham skulle I annamme."],[5,44,"Hvorledes kunne I troe, I, som tage Ære af hverandre, og den Ære, som er af den eneste Gud, søge I ikke?","Hvorledes kunne I troe, I, som tage Ære af hverandre, og den Ære, som er af den eneste Gud, søge I ikke?"],[5,45,"Tænker ikke, at jeg vil anklage Eder for Faderen; der er den, som Eder anklager, Moses, paa hvem I haabe.","Tænker ikke, at jeg vil anklage Eder for Faderen; der er den, som Eder anklager, Moses, paa hvem I haabe."],[5,46,"Dersom I troede Moses, troede I vel mig; thi han haver skrevet om mig.","Dersom I troede Moses, troede I vel mig; thi han haver skrevet om mig."],[5,47,"Men troe I ikke hans Skrifter, hvorledes skulle I troe mine Ord?","Men troe I ikke hans Skrifter, hvorledes skulle I troe mine Ord?"],[6,1,"Derefter foer Jesus hen over Galilæas Sø, ved Tiberias.","Derefter foer Jesus hen over Galilæas Sø, ved Tiberias."],[6,2,"Og meget Folk fulgte ham, fordi de saae hans Tegn, som han gjorde paa de Syge.","Og meget Folk fulgte ham, fordi de saae hans Tegn, som han gjorde paa de Syge."],[6,3,"Men Jesus gik op paa et Bjerg og satte sig der med sine Disciple.","Men Jesus gik op paa et Bjerg og satte sig der med sine Disciple."],[6,4,"Men det var nær Paaske, Jødernes Høitid.","Men det var nær Paaske, Jødernes Høitid."],[6,5,"Da Jesus nu opløftede sine Øine og saae, at meget Folk kom til ham, sagde han til Philippus: hvor skulle vi kjøbe Brød, at disse kunne æde?","Da Jesus nu opløftede sine Øine og saae, at meget Folk kom til ham, sagde han til Philippus: hvor skulle vi kjøbe Brød, at disse kunne æde?"],[6,6,"(Men han sagde dette for at forsøge ham; thi han vidste selv, hvad han vilde gjøre.)","(Men han sagde dette for at forsøge ham; thi han vidste selv, hvad han vilde gjøre.)"],[6,7,"Philippus svarede ham: Brød for to hundrede Penninge er ikke nok for dem, at hver af dem kan faae noget Lidet.","Philippus svarede ham: Brød for to hundrede Penninge er ikke nok for dem, at hver af dem kan faae noget Lidet."],[6,8,"Een af hans Disciple, Andreas, Simon Peters Broder, siger til ham:","Een af hans Disciple, Andreas, Simon Peters Broder, siger til ham:"],[6,9,"her er en liden Dreng, som haver fem Bygbrød og to smaa Fiske; men hvad er dette til saa Mange?","her er en liden Dreng, som haver fem Bygbrød og to smaa Fiske; men hvad er dette til saa Mange?"],[6,10,"Men Jesus sagde: kommer Folket til at sidde; og der var meget Græs paa Stedet. Da satte Mændene sig ned, ved frem tusinde i Tallet.","Men Jesus sagde: kommer Folket til at sidde; og der var meget Græs paa Stedet. Da satte Mændene sig ned, ved frem tusinde i Tallet."],[6,11,"Men Jesus tog Brødene, gjorde Taksigelse og uddelede dem til Disciplene, men Disciplene til dem, som havde sat sig ned; desligeste ogsaa af de smaa Fiske, saa meget de vilde.","Men Jesus tog Brødene, gjorde Taksigelse og uddelede dem til Disciplene, men Disciplene til dem, som havde sat sig ned; desligeste ogsaa af de smaa Fiske, saa meget de vilde."],[6,12,"Men der de vare mætte, sagde han til sine Disciple: sanker tilsammen de overblevne Stykker, at Intet forkommes.","Men der de vare mætte, sagde han til sine Disciple: sanker tilsammen de overblevne Stykker, at Intet forkommes."],[6,13,"Da samlede de og fyldte tolv Kurve med Stykker, som bleve tilovers af de fem Bygbrød fra dem, som havde faaet Mad.","Da samlede de og fyldte tolv Kurve med Stykker, som bleve tilovers af de fem Bygbrød fra dem, som havde faaet Mad."],[6,14,"Da nu Folket saae det Tegn, som Jesus havde gjort, sagde de: denne er i Sandhed den Prophet, som kommer til Verden.","Da nu Folket saae det Tegn, som Jesus havde gjort, sagde de: denne er i Sandhed den Prophet, som kommer til Verden."],[6,15,"Der Jesus da vidste, at de vilde komme og tage ham med Magt for at gjøre ham til Konge, veg han atter op paa Bjerget, ganske alene.","Der Jesus da vidste, at de vilde komme og tage ham med Magt for at gjøre ham til Konge, veg han atter op paa Bjerget, ganske alene."],[6,16,"Men der det var blevet Aften, gik hans Disciple ned til Søen.","Men der det var blevet Aften, gik hans Disciple ned til Søen."],[6,17,"Og de traadte i Skibet, og kom paa hiin Side Søen til Capernaum. Og det var allerede blevet mørkt, og Jesus var ikke kommen til dem.","Og de traadte i Skibet, og kom paa hiin Side Søen til Capernaum. Og det var allerede blevet mørkt, og Jesus var ikke kommen til dem."],[6,18,"Og Søen reiste sig, da der blæste et stærkt Veir.","Og Søen reiste sig, da der blæste et stærkt Veir."],[6,19,"Der de nu havde roet ved fem og tyve eller tredive Stadier, saae de Jesus vandre paa Søen og komme nær til Skibet; og de forfærdedes.","Der de nu havde roet ved fem og tyve eller tredive Stadier, saae de Jesus vandre paa Søen og komme nær til Skibet; og de forfærdedes."],[6,20,"Men han sagde til dem: det er mig; frygter ikke.","Men han sagde til dem: det er mig; frygter ikke."],[6,21,"Da vilde de tage ham ind i Skibet; og strax var Skibet ved Landet, som de føre til.","Da vilde de tage ham ind i Skibet; og strax var Skibet ved Landet, som de føre til."],[6,22,"Den anden Dag, da Folket, som stod paa hiin Side Søen, saae, at intet andet Skib var der, uden det ene, som hans Disciple vare traadte ind i, og at Jesus ikke var gaaet i Skibet med sine Disciple, men at hans Disciple alene vare farne bort;","Den anden Dag, da Folket, som stod paa hiin Side Søen, saae, at intet andet Skib var der, uden det ene, som hans Disciple vare traadte ind i, og at Jesus ikke var gaaet i Skibet med sine Disciple, men at hans Disciple alene vare farne bort;"],[6,23,"(men der kom andre Skibe fra Tiberias nær til det Sted, hvor de aade Brødet, efter at Herren havde gjort Taksigelse);","(men der kom andre Skibe fra Tiberias nær til det Sted, hvor de aade Brødet, efter at Herren havde gjort Taksigelse);"],[6,24,"og da Folket nu saae, at Jesus var der ikke, ei heller hans Disciple, traadte ogsaa de i Skibene, og kom til Capernaum for at søge Jesus.","og da Folket nu saae, at Jesus var der ikke, ei heller hans Disciple, traadte ogsaa de i Skibene, og kom til Capernaum for at søge Jesus."],[6,25,"Og der de fandt ham paa hiin Side Søen, sagde de til ham: Rabbi! naar er du kommen hid?","Og der de fandt ham paa hiin Side Søen, sagde de til ham: Rabbi! naar er du kommen hid?"],[6,26,"Jesus svarede dem og sagde: sandelig, sandelig siger jeg Eder: I søge mig, ikke fordi I saae Tegn, men fordi I aade af Brødene og bleve mætte.","Jesus svarede dem og sagde: sandelig, sandelig siger jeg Eder: I søge mig, ikke fordi I saae Tegn, men fordi I aade af Brødene og bleve mætte."],[6,27,"Arbeider ikke for den Mad, som er forgængelig, men for den Mad, som varer til et evigt Liv, hvilken Menneskens Søn skal give Eder; thi ham haver Faderen, Gud selv, beseglet.","Arbeider ikke for den Mad, som er forgængelig, men for den Mad, som varer til et evigt Liv, hvilken Menneskens Søn skal give Eder; thi ham haver Faderen, Gud selv, beseglet."],[6,28,"Da sagde de til ham: hvad skulle vi gjøre, at vi kunne arbeide Guds Gjerning?","Da sagde de til ham: hvad skulle vi gjøre, at vi kunne arbeide Guds Gjerning?"],[6,29,"Jesus svarede og sagde til dem: dette er Guds Gjerning, at I skulle troe paa den, som han udsendte.","Jesus svarede og sagde til dem: dette er Guds Gjerning, at I skulle troe paa den, som han udsendte."],[6,30,"Da sagde de til ham: hvad gjør du da for et Tegn, at vi kunne see det og troe dig? hvad Arbeide gjør du?","Da sagde de til ham: hvad gjør du da for et Tegn, at vi kunne see det og troe dig? hvad Arbeide gjør du?"],[6,31,"Vore Fædre aade Manna i Ørken, som skrevet er: han gav dem Brød af Himmelen at æde.","Vore Fædre aade Manna i Ørken, som skrevet er: han gav dem Brød af Himmelen at æde."],[6,32,"Da sagde Jesus til dem: sandelig, sandelig siger jeg Eder: ikke Moses gav Eder det Brød af Himmelen; men min Fader giver Eder det Brød af Himmelen, som er det sande.","Da sagde Jesus til dem: sandelig, sandelig siger jeg Eder: ikke Moses gav Eder det Brød af Himmelen; men min Fader giver Eder det Brød af Himmelen, som er det sande."],[6,33,"Thi Guds Brød er det, som kommer ned af Himmelen, og giver Verden Liv.","Thi Guds Brød er det, som kommer ned af Himmelen, og giver Verden Liv."],[6,34,"Da sagde de til ham: Herre! giv os altid dette Brød.","Da sagde de til ham: Herre! giv os altid dette Brød."],[6,35,"Men Jesus sagde til dem: jeg er det Livsens Brød, Hvo som kommer til mig, skal ikke hungre; og hvo som troer paa mig, skal aldrig tørste.","Men Jesus sagde til dem: jeg er det Livsens Brød, Hvo som kommer til mig, skal ikke hungre; og hvo som troer paa mig, skal aldrig tørste."],[6,36,"Men jeg haver sagt Eder, at I have seet mig, og troe dog ikke.","Men jeg haver sagt Eder, at I have seet mig, og troe dog ikke."],[6,37,"Alt, hvad min Fader giver mig, skal komme til mig; og den, som kommer til mig, skal jeg ingenlunde kaste hen ud.","Alt, hvad min Fader giver mig, skal komme til mig; og den, som kommer til mig, skal jeg ingenlunde kaste hen ud."],[6,38,"Thi jeg er kommen ned af Himmelen, ikke at jeg skal gjøre min Villie, men hans Villie, som mig udsendte.","Thi jeg er kommen ned af Himmelen, ikke at jeg skal gjøre min Villie, men hans Villie, som mig udsendte."],[6,39,"Men dette er Faderens Villie, som mig udsendte, at jeg skal Intet miste af alt det, som han haver givet mig; men jeg skal opreise det paa den yderste Dag.","Men dette er Faderens Villie, som mig udsendte, at jeg skal Intet miste af alt det, som han haver givet mig; men jeg skal opreise det paa den yderste Dag."],[6,40,"Men det er hans Villie, som mig udsendte, at hver den, som seer Sønnen og troer paa ham, skal have et evigt Liv, og jeg skal opreise ham paa den yderste Dag.","Men det er hans Villie, som mig udsendte, at hver den, som seer Sønnen og troer paa ham, skal have et evigt Liv, og jeg skal opreise ham paa den yderste Dag."],[6,41,"Da knurrede Jøderne imod ham, fordi han sagde: jeg er det Brød, som kom ned af Himmelen.","Da knurrede Jøderne imod ham, fordi han sagde: jeg er det Brød, som kom ned af Himmelen."],[6,42,"Og de sagde: er ikke denne Jesus, Josephs Søn, hvis Fader og Moder vi kjende? hvorledes siger da denne: jeg er kommen ned af Himmelen?","Og de sagde: er ikke denne Jesus, Josephs Søn, hvis Fader og Moder vi kjende? hvorledes siger da denne: jeg er kommen ned af Himmelen?"],[6,43,"Derfor svarede Jesus og sagde til dem: knurrer ikke indbyrdes.","Derfor svarede Jesus og sagde til dem: knurrer ikke indbyrdes."],[6,44,"Ingen kan komme til mig uden Faderen, som mig udsendte, drager ham; og jeg skal opreise ham paa den yderste Dag.","Ingen kan komme til mig uden Faderen, som mig udsendte, drager ham; og jeg skal opreise ham paa den yderste Dag."],[6,45,"Der er skrevet i Propheterne: og de skulle alle være oplærte af Gud. Hver da, som hører af Faderen og lærer, kommer til mig.","Der er skrevet i Propheterne: og de skulle alle være oplærte af Gud. Hver da, som hører af Faderen og lærer, kommer til mig."],[6,46,"Ikke at Nogen haver seet Faderen, uden den, som er fra Gud, han haver seet Faderen.","Ikke at Nogen haver seet Faderen, uden den, som er fra Gud, han haver seet Faderen."],[6,47,"Sandelig, sandelig siger jeg Eder: hvo, som troer paa mig, haver et evigt Liv.","Sandelig, sandelig siger jeg Eder: hvo, som troer paa mig, haver et evigt Liv."],[6,48,"Jeg er det Livsens Brød.","Jeg er det Livsens Brød."],[6,49,"Eders Fædre aade Manna i Ørken og døde.","Eders Fædre aade Manna i Ørken og døde."],[6,50,"Dette er det Brød, som kommer ned af Himmelen, at man skal æde af det og ikke døe.","Dette er det Brød, som kommer ned af Himmelen, at man skal æde af det og ikke døe."],[6,51,"Jeg er det levende Brød, som kom ned af Himmelen; om Nogen æder af dette Brød, han skal leve til evig Tid; og det Brød, som jeg vil give, er mit Kjød hvilket jeg vil give for Verdens Liv.","Jeg er det levende Brød, som kom ned af Himmelen; om Nogen æder af dette Brød, han skal leve til evig Tid; og det Brød, som jeg vil give, er mit Kjød hvilket jeg vil give for Verdens Liv."],[6,52,"Da kivedes Jøderne indbyrdes og sagde: hvorledes kan denne give os sit Kjød at æde?","Da kivedes Jøderne indbyrdes og sagde: hvorledes kan denne give os sit Kjød at æde?"],[6,53,"Derfor sagde Jesus til dem: sandelig, sandelig siger jeg Eder: dersom I ikke æde Menneskens Søns Kjød og drikke hans Blod, have I ikke Livet i Eder.","Derfor sagde Jesus til dem: sandelig, sandelig siger jeg Eder: dersom I ikke æde Menneskens Søns Kjød og drikke hans Blod, have I ikke Livet i Eder."],[6,54,"Hvo som æder mit Kjød og drikker mit Blod, haver et evigt Liv, og jeg skal opreise ham paa den yderste Dag.","Hvo som æder mit Kjød og drikker mit Blod, haver et evigt Liv, og jeg skal opreise ham paa den yderste Dag."],[6,55,"Thi mit Kjød er sandelig Mad, og mit Blod er sandelig Drikke.","Thi mit Kjød er sandelig Mad, og mit Blod er sandelig Drikke."],[6,56,"Hvo som æder mit Kjød og drikker mit Blod, han bliver i mig, og jeg i ham.","Hvo som æder mit Kjød og drikker mit Blod, han bliver i mig, og jeg i ham."],[6,57,"Ligesom den levende Fader udsendte mig, og jeg lever ved Faderen, ligesaa skal og den, som mig æder, leve ved mig.","Ligesom den levende Fader udsendte mig, og jeg lever ved Faderen, ligesaa skal og den, som mig æder, leve ved mig."],[6,58,"Dette er det Brød, som er kommet ned af Himmelen; ikke som Eders Fædre aade Manna og døde. Hvo som æder dette Brød, skal leve evindeligen.","Dette er det Brød, som er kommet ned af Himmelen; ikke som Eders Fædre aade Manna og døde. Hvo som æder dette Brød, skal leve evindeligen."],[6,59,"Dette sagde han i en Synagoge, der han lærte i Capernaum.","Dette sagde han i en Synagoge, der han lærte i Capernaum."],[6,60,"Hvorfor mange af hans Disciple, der de det hørte, sagde: denne er en haard Tale, hvo kan høre ham?","Hvorfor mange af hans Disciple, der de det hørte, sagde: denne er en haard Tale, hvo kan høre ham?"],[6,61,"Men der Jesus vidste ved sig selv, at hans Disciple knurrede over dette, sagde han til dem: forarger dette Eder?","Men der Jesus vidste ved sig selv, at hans Disciple knurrede over dette, sagde han til dem: forarger dette Eder?"],[6,62,"Hvad om I da faae at see, at Menneskens Søn farer op, hvor han var før?","Hvad om I da faae at see, at Menneskens Søn farer op, hvor han var før?"],[6,63,"Det er Aanden, som levendegjør, Kjødet gavner intet; de Ord, som jeg taler til Eder, ere Aand og ere Liv.","Det er Aanden, som levendegjør, Kjødet gavner intet; de Ord, som jeg taler til Eder, ere Aand og ere Liv."],[6,64,"Men der ere nogle af Eder, som ikke troe. Thi Jesus vidste fra Begyndelsen, hvilke de vare, som ikke troede, og hvo den var, som ham vilde forraade.","Men der ere nogle af Eder, som ikke troe. Thi Jesus vidste fra Begyndelsen, hvilke de vare, som ikke troede, og hvo den var, som ham vilde forraade."],[6,65,"Og han sagde: derfor sagde jeg Eder, at Ingen kan komme til mig, uden det er givet ham af min Fader.","Og han sagde: derfor sagde jeg Eder, at Ingen kan komme til mig, uden det er givet ham af min Fader."],[6,66,"Fra den Tid traadte mange af hans Disciple tilbage, og vandrede ikke mere med ham.","Fra den Tid traadte mange af hans Disciple tilbage, og vandrede ikke mere med ham."],[6,67,"Derfor sagde Jesus til de Tolv: monne og I ville gaae bort?","Derfor sagde Jesus til de Tolv: monne og I ville gaae bort?"],[6,68,"Da svarede Simon Peter ham: Herre! til hvem skulle vi gaae hen? Du haver det evige Livs Ord;","Da svarede Simon Peter ham: Herre! til hvem skulle vi gaae hen? Du haver det evige Livs Ord;"],[6,69,"og vi have troet og erkjendt, at du er den Christus, den levende Guds Søn.","og vi have troet og erkjendt, at du er den Christus, den levende Guds Søn."],[6,70,"Jesus svarede dem: har jeg ikke udvalgt Eder tolv, og een af Eder er en Djævel.","Jesus svarede dem: har jeg ikke udvalgt Eder tolv, og een af Eder er en Djævel."],[6,71,"Men han talede om Judas, Simons Søn, Ischariotes; thi han blev siden hans Forræder og var een af de Tolv.","Men han talede om Judas, Simons Søn, Ischariotes; thi han blev siden hans Forræder og var een af de Tolv."],[7,1,"Derefter drog Jesus omkring i Galilæa; thi han vilde ikke vandre i Judæa, fordi Jøderne søgte at slaae ham ihjel.","Derefter drog Jesus omkring i Galilæa; thi han vilde ikke vandre i Judæa, fordi Jøderne søgte at slaae ham ihjel."],[7,2,"Men Jødernes Fest, Løvsalernes Høitid var nær.","Men Jødernes Fest, Løvsalernes Høitid var nær."],[7,3,"Da sagde hans Brødre til ham: drag bort herfra, og gak til Judæa, at og dine Disciple der kunne see dine Gjerninger, som du gjør.","Da sagde hans Brødre til ham: drag bort herfra, og gak til Judæa, at og dine Disciple der kunne see dine Gjerninger, som du gjør."],[7,4,"Thi Ingen gjør Noget i Løndom, naar han selv søger at blive navnkundig; dersom du gjør Saadant, da viis dig for Verden.","Thi Ingen gjør Noget i Løndom, naar han selv søger at blive navnkundig; dersom du gjør Saadant, da viis dig for Verden."],[7,5,"Thi hans Brødre troede ei heller paa ham.","Thi hans Brødre troede ei heller paa ham."],[7,6,"Da sagde Jesus til dem: min Tid er endnu ikke kommen; men Eders Tid er stedse forhaanden.","Da sagde Jesus til dem: min Tid er endnu ikke kommen; men Eders Tid er stedse forhaanden."],[7,7,"Verden kan ikke hade Eder; men den hader mig, fordi jeg vidner om den, at dens Gjerninger ere onde.","Verden kan ikke hade Eder; men den hader mig, fordi jeg vidner om den, at dens Gjerninger ere onde."],[7,8,"Drager I op til denne Høitid; jeg drager ikke endnu op til denne Høitid, thi min Tid er ikke endnu fuldkommet.","Drager I op til denne Høitid; jeg drager ikke endnu op til denne Høitid, thi min Tid er ikke endnu fuldkommet."],[7,9,"Der han havde sagt dette til dem, blev han i Galilæa.","Der han havde sagt dette til dem, blev han i Galilæa."],[7,10,"Men der hans Brødre vare dragne op, da drog han og selv op til Høitiden, ikke aabenbare, men lønligen.","Men der hans Brødre vare dragne op, da drog han og selv op til Høitiden, ikke aabenbare, men lønligen."],[7,11,"Da ledte Jøderne efter ham paa Høitiden og sagde: hvor er han?","Da ledte Jøderne efter ham paa Høitiden og sagde: hvor er han?"],[7,12,"Og der blev meget mumlet om ham iblandt Folket; Nogle sagde: han er en god Mand; men Andre sagde: nei, han forfører Folket.","Og der blev meget mumlet om ham iblandt Folket; Nogle sagde: han er en god Mand; men Andre sagde: nei, han forfører Folket."],[7,13,"Dog talede Ingen frit om ham, af Frygt for Jøderne.","Dog talede Ingen frit om ham, af Frygt for Jøderne."],[7,14,"Men der det nu var midt i Høitiden, gik Jesus op i Templet og lærte.","Men der det nu var midt i Høitiden, gik Jesus op i Templet og lærte."],[7,15,"Og Jøderne forundrede sig og sagde: hvorledes veed denne Skrifterne, da han ikke er lært?","Og Jøderne forundrede sig og sagde: hvorledes veed denne Skrifterne, da han ikke er lært?"],[7,16,"Jesus svarede dem og sagde: min Lærdom er ikke min, men hans, som mig udsendte.","Jesus svarede dem og sagde: min Lærdom er ikke min, men hans, som mig udsendte."],[7,17,"Dersom Nogen vil gjøre hans Villie, han skal kjende, om Lærdommen er af Gud, eller jeg taler af mig selv.","Dersom Nogen vil gjøre hans Villie, han skal kjende, om Lærdommen er af Gud, eller jeg taler af mig selv."],[7,18,"Hvo som taler af sig selv, søger sin egen Ære; men hvo som søger hans Ære, som ham udsendte, han er sanddru, og Svig er ikke i ham.","Hvo som taler af sig selv, søger sin egen Ære; men hvo som søger hans Ære, som ham udsendte, han er sanddru, og Svig er ikke i ham."],[7,19,"Haver ikke Moses givet Eder Loven? Og ingen af Eder holder Loven. Hvi søge I at slaae mig ihjel?","Haver ikke Moses givet Eder Loven? Og ingen af Eder holder Loven. Hvi søge I at slaae mig ihjel?"],[7,20,"Folket svarede og sagde: du haver Djævelen; hvo søger at slaae dig ihjel?","Folket svarede og sagde: du haver Djævelen; hvo søger at slaae dig ihjel?"],[7,21,"Jesus svarede og sagde til dem: een Gjerning gjorde jeg, og I forundrede Eder alle derover.","Jesus svarede og sagde til dem: een Gjerning gjorde jeg, og I forundrede Eder alle derover."],[7,22,"Moses gav Eder Omskærelsen, (ikke at den er fra Moses, men fra Fædrene), og I omskære et Menneske paa Sabbaten.","Moses gav Eder Omskærelsen, (ikke at den er fra Moses, men fra Fædrene), og I omskære et Menneske paa Sabbaten."],[7,23,"Dersom et Menneske annammer Omskærelsen paa Sabbaten, paa det Moses’ Lov skal ikke brydes, ere I da vrede paa mig, at jeg haver gjort et heelt Menneske sundt paa Sabbaten?","Dersom et Menneske annammer Omskærelsen paa Sabbaten, paa det Moses’ Lov skal ikke brydes, ere I da vrede paa mig, at jeg haver gjort et heelt Menneske sundt paa Sabbaten?"],[7,24,"Dømmer ikke efter Anseelse, men dømmer en retfærdig Dom.","Dømmer ikke efter Anseelse, men dømmer en retfærdig Dom."],[7,25,"Da sagde Nogle af dem fra Jerusalem: er det ikke ham, som de søge at slaae ihjel?","Da sagde Nogle af dem fra Jerusalem: er det ikke ham, som de søge at slaae ihjel?"],[7,26,"Og see, han taler frit, og de sige Intet til ham; mon ikke de Øverste i Sandhed have kjendt, at denne er i Sandhed den Christus?","Og see, han taler frit, og de sige Intet til ham; mon ikke de Øverste i Sandhed have kjendt, at denne er i Sandhed den Christus?"],[7,27,"Dog vide vi, hvorfra denne er; men naar Christus kommer, veed Ingen, hvorfra han er.","Dog vide vi, hvorfra denne er; men naar Christus kommer, veed Ingen, hvorfra han er."],[7,28,"Derfor raabte Jesus, idet han lærte i Templet, og sagde: baade kjende I mig og vide, hvorfra jeg er; og af mig selv er jeg ikke kommen, men han er sanddru, som mig udsendte, hvilken I ikke kjende.","Derfor raabte Jesus, idet han lærte i Templet, og sagde: baade kjende I mig og vide, hvorfra jeg er; og af mig selv er jeg ikke kommen, men han er sanddru, som mig udsendte, hvilken I ikke kjende."],[7,29,"Men jeg kjender ham, thi jeg er af ham, og han udsendte mig.","Men jeg kjender ham, thi jeg er af ham, og han udsendte mig."],[7,30,"Derfor søgte de at gribe ham; dog lagde Ingen Haand paa ham, thi hans Time var ikke endnu kommen.","Derfor søgte de at gribe ham; dog lagde Ingen Haand paa ham, thi hans Time var ikke endnu kommen."],[7,31,"Men Mange af Folket troede paa ham og sagde: naar Christus kommer, monne han skal gjøre flere Tegn, end denne haver gjort?","Men Mange af Folket troede paa ham og sagde: naar Christus kommer, monne han skal gjøre flere Tegn, end denne haver gjort?"],[7,32,"Pharisæerne hørte, at Folket mumlede saadant om ham; og Pharisæerne og de Ypperstepræster sendte Tjenere ud for at gribe ham.","Pharisæerne hørte, at Folket mumlede saadant om ham; og Pharisæerne og de Ypperstepræster sendte Tjenere ud for at gribe ham."],[7,33,"Derfor sagde Jesus til dem: endnu en liden Tid er jeg hos Eder, saa gaaer jeg bort til den, som mig udsendte.","Derfor sagde Jesus til dem: endnu en liden Tid er jeg hos Eder, saa gaaer jeg bort til den, som mig udsendte."],[7,34,"I skulle lede efter mig og ikke finde mig, og der, hvor jeg er, kunne I ikke komme.","I skulle lede efter mig og ikke finde mig, og der, hvor jeg er, kunne I ikke komme."],[7,35,"Da sagde Jøderne til hverandre: hvor vil denne gaae hen, at vi ikke skulle finde ham? Mon han vil gaae til dem, som ere adspredte iblandt Grækerne, og lære Grækerne?","Da sagde Jøderne til hverandre: hvor vil denne gaae hen, at vi ikke skulle finde ham? Mon han vil gaae til dem, som ere adspredte iblandt Grækerne, og lære Grækerne?"],[7,36,"Hvad er det for en Tale, at han siger: I skulle lede efter mig, og ikke finde mig, og der, hvor jeg er, kunne I ikke komme?","Hvad er det for en Tale, at han siger: I skulle lede efter mig, og ikke finde mig, og der, hvor jeg er, kunne I ikke komme?"],[7,37,"Men paa den sidste og store Høitidsdag stod Jesus frem, og raabte og sagde: om Nogen tørster, han komme til mig og drikke.","Men paa den sidste og store Høitidsdag stod Jesus frem, og raabte og sagde: om Nogen tørster, han komme til mig og drikke."],[7,38,"Hvo som troer paa mig, af hans Liv skal, som Skriften siger, flyde levende Vandstrømme.","Hvo som troer paa mig, af hans Liv skal, som Skriften siger, flyde levende Vandstrømme."],[7,39,"(Men dette sagde han om den Aand, som de skulde annamme, der troe paa ham; thi den Hellig Aand var ikke endnu, fordi Jesus var ikke endnu herliggjort.)","(Men dette sagde han om den Aand, som de skulde annamme, der troe paa ham; thi den Hellig Aand var ikke endnu, fordi Jesus var ikke endnu herliggjort.)"],[7,40,"Derfor sagde Mange af Folket, som hørte den Tale: denne er sandelig den Prophet.","Derfor sagde Mange af Folket, som hørte den Tale: denne er sandelig den Prophet."],[7,41,"Andre sagde: han er Christus; men Andre sagde: mon da Christus komme af Galilæa?","Andre sagde: han er Christus; men Andre sagde: mon da Christus komme af Galilæa?"],[7,42,"Siger ikke Skriften, at Christus kommer af Davids Sæd og af Bethlehem, den By, hvorfra David var?","Siger ikke Skriften, at Christus kommer af Davids Sæd og af Bethlehem, den By, hvorfra David var?"],[7,43,"Saaledes blev der Splid iblandt Folket om ham.","Saaledes blev der Splid iblandt Folket om ham."],[7,44,"Men Nogle af dem vilde grebet ham; dog lagde Ingen Haand paa ham.","Men Nogle af dem vilde grebet ham; dog lagde Ingen Haand paa ham."],[7,45,"Da kom Tjenerne til de Ypperstepræster og Pharisæerne, og disse sagde til dem: hvi førte I ham ikke hid?","Da kom Tjenerne til de Ypperstepræster og Pharisæerne, og disse sagde til dem: hvi førte I ham ikke hid?"],[7,46,"Tjenerne svarede: aldrig haver et Menneske talet saaledes som dette Menneske.","Tjenerne svarede: aldrig haver et Menneske talet saaledes som dette Menneske."],[7,47,"Da svarede Pharisæerne dem: monne I og være forførte?","Da svarede Pharisæerne dem: monne I og være forførte?"],[7,48,"Mon Nogen af de Øverste haver troet paa ham, eller af Pharisæerne?","Mon Nogen af de Øverste haver troet paa ham, eller af Pharisæerne?"],[7,49,"Men denne Hob, som ikke kjender til Loven, er forbandet.","Men denne Hob, som ikke kjender til Loven, er forbandet."],[7,50,"Nicodemus, (den, som var kommen til ham om Natten, og var een af dem) sagde til dem:","Nicodemus, (den, som var kommen til ham om Natten, og var een af dem) sagde til dem:"],[7,51,"mon vor Lov dømme et Menneske, uden at man først forhører ham og faaer at vide, hvad han gjør?","mon vor Lov dømme et Menneske, uden at man først forhører ham og faaer at vide, hvad han gjør?"],[7,52,"De svarede og sagde til ham: mon du og være af Galilæa? Ransag og see, at der er ingen Prophet opstanden af Galilæa.","De svarede og sagde til ham: mon du og være af Galilæa? Ransag og see, at der er ingen Prophet opstanden af Galilæa."],[7,53,"Og hver gik til sit Huus.","Og hver gik til sit Huus."],[8,1,"Men Jesus gik til Oliebjerget.","Men Jesus gik til Oliebjerget."],[8,2,"Og aarle om Morgenen kom han igjen i Templet, og alt Folket kom til ham; og han satte sig og lærte dem.","Og aarle om Morgenen kom han igjen i Templet, og alt Folket kom til ham; og han satte sig og lærte dem."],[8,3,"Men de Skriftkloge og Pharisæerne førte en Kvinde til ham, greben i Hoer, og stillede hende frem i Midten.","Men de Skriftkloge og Pharisæerne førte en Kvinde til ham, greben i Hoer, og stillede hende frem i Midten."],[8,4,"Og de sagde til ham: Mester! denne Kvinde er greben i Hoer paa frisk Gjerning.","Og de sagde til ham: Mester! denne Kvinde er greben i Hoer paa frisk Gjerning."],[8,5,"Men Moses bød os i Loven, at saadanne skulle stenes; hvad siger nu du?","Men Moses bød os i Loven, at saadanne skulle stenes; hvad siger nu du?"],[8,6,"Men dette sagde de, for at forsøge ham, at de kunde have Noget at anklage ham for. Men Jesus bukkede sig ned og skrev med Fingeren paa Jorden.","Men dette sagde de, for at forsøge ham, at de kunde have Noget at anklage ham for. Men Jesus bukkede sig ned og skrev med Fingeren paa Jorden."],[8,7,"Men der de bleve ved at spørge ham, reiste han sig op og sagde til dem: den, som er syndeløs iblandt Eder, kaste først Stenen paa hende.","Men der de bleve ved at spørge ham, reiste han sig op og sagde til dem: den, som er syndeløs iblandt Eder, kaste først Stenen paa hende."],[8,8,"Og han bukkede sig atter ned og skrev paa Jorden.","Og han bukkede sig atter ned og skrev paa Jorden."],[8,9,"Men der de hørte det, og bleve slagne af deres Samvittighed, gik de bort, En efter den Anden, fra de Ældste af til de Yngste, og Jesus blev efterladt alene, og Kvinden staaende i Midten.","Men der de hørte det, og bleve slagne af deres Samvittighed, gik de bort, En efter den Anden, fra de Ældste af til de Yngste, og Jesus blev efterladt alene, og Kvinden staaende i Midten."],[8,10,"Men da Jesus reiste sig op og saae Ingen uden Kvinden, sagde han til hende: Kvinde! hvor ere hine dine Anklagere? fordømte Ingen dig?","Men da Jesus reiste sig op og saae Ingen uden Kvinden, sagde han til hende: Kvinde! hvor ere hine dine Anklagere? fordømte Ingen dig?"],[8,11,"Men hun sagde: Herre! Ingen. Men Jesus sagde til hende: jeg fordømmer dig ikke heller; gak bort, og synd ikke mere.","Men hun sagde: Herre! Ingen. Men Jesus sagde til hende: jeg fordømmer dig ikke heller; gak bort, og synd ikke mere."],[8,12,"Da talede Jesus atter til dem og sagde: jeg er det Verdens Lys; hvo som følger mig, skal ikke vandre i Mørket, men have det Livsens Lys.","Da talede Jesus atter til dem og sagde: jeg er det Verdens Lys; hvo som følger mig, skal ikke vandre i Mørket, men have det Livsens Lys."],[8,13,"Da sagde Pharisæerne til ham: du vidner om dig selv; dit Vidnesbyrd er ikke sandt.","Da sagde Pharisæerne til ham: du vidner om dig selv; dit Vidnesbyrd er ikke sandt."],[8,14,"Jesus svarede og sagde til dem: om jeg end vidner om mig selv, er mit Vidnesbyrd sandt; thi jeg veed, hvorfra jeg kom, og hvor jeg gaaer hen; men I vide ikke, hvorfra jeg kommer, og hvor jeg gaaer hen.","Jesus svarede og sagde til dem: om jeg end vidner om mig selv, er mit Vidnesbyrd sandt; thi jeg veed, hvorfra jeg kom, og hvor jeg gaaer hen; men I vide ikke, hvorfra jeg kommer, og hvor jeg gaaer hen."],[8,15,"I dømmer efter Kjødet , jeg dømmer Ingen.","I dømmer efter Kjødet , jeg dømmer Ingen."],[8,16,"Men dersom jeg og dømmer, er min Dom sand; thi jeg er ikke alene, men baade jeg og Faderen, som udsendte mig.","Men dersom jeg og dømmer, er min Dom sand; thi jeg er ikke alene, men baade jeg og Faderen, som udsendte mig."],[8,17,"Men der er og skrevet i Eders Lov, at to Menneskers Vidnesbyrd er sandt.","Men der er og skrevet i Eders Lov, at to Menneskers Vidnesbyrd er sandt."],[8,18,"Jeg er den, som vidner om mig selv, og Faderen, som udsendte mig, vidner om mig.","Jeg er den, som vidner om mig selv, og Faderen, som udsendte mig, vidner om mig."],[8,19,"Derfor sagde de til ham: hvor er din Fader? Jesus svarede: hverken kjende I mig, ei heller min Fader; dersom I kjendte mig, kjendte I og min Fader.","Derfor sagde de til ham: hvor er din Fader? Jesus svarede: hverken kjende I mig, ei heller min Fader; dersom I kjendte mig, kjendte I og min Fader."],[8,20,"Disse Ord talede Jesus ved Templets Kiste, der han lærte i Templet; dog greb Ingen ham, fordi hans Time var ikke endnu kommen.","Disse Ord talede Jesus ved Templets Kiste, der han lærte i Templet; dog greb Ingen ham, fordi hans Time var ikke endnu kommen."],[8,21,"Da sagde Jesus atter til dem: jeg gaaer bort, og I skulle lede efter mig, og døe i Eders Synd; hvor jeg gaaer hen, kunne I ikke komme.","Da sagde Jesus atter til dem: jeg gaaer bort, og I skulle lede efter mig, og døe i Eders Synd; hvor jeg gaaer hen, kunne I ikke komme."],[8,22,"Da sagde Jøderne: mon han vil slaae sig selv ihjel, fordi han siger: hvor jeg gaaer hen, kunne I ikke komme?","Da sagde Jøderne: mon han vil slaae sig selv ihjel, fordi han siger: hvor jeg gaaer hen, kunne I ikke komme?"],[8,23,"Og han sagde til dem: I ere nedenfra, jeg er ovenfra; I ere af denne Verden, jeg er ikke af denne Verden.","Og han sagde til dem: I ere nedenfra, jeg er ovenfra; I ere af denne Verden, jeg er ikke af denne Verden."],[8,24,"Derfor haver jeg sagt Eder, at I skulle døe i Eders Synder; thi dersom I ikke ville troe, at det er mig, skulle I døde i Eders Synder.","Derfor haver jeg sagt Eder, at I skulle døe i Eders Synder; thi dersom I ikke ville troe, at det er mig, skulle I døde i Eders Synder."],[8,25,"Derfor sagde de til ham: hvo er du? Og Jesus sagde til dem: just det, som jeg siger Eder.","Derfor sagde de til ham: hvo er du? Og Jesus sagde til dem: just det, som jeg siger Eder."],[8,26,"Jeg haver Meget at tale og dømme om Eder; men den, som mig udsendte, er sanddru, og hvad jeg haver hørt af ham, det siger jeg for Verden.","Jeg haver Meget at tale og dømme om Eder; men den, som mig udsendte, er sanddru, og hvad jeg haver hørt af ham, det siger jeg for Verden."],[8,27,"Men de forstode ikke, at han talede til dem om Faderen.","Men de forstode ikke, at han talede til dem om Faderen."],[8,28,"Derfor sagde Jesus til dem: naar I faae ophøiet Menneskens Søn, da skulle I kjende, at det er mig, og at jeg gjør Intet af mig selv; men som min Fader haver lært mig, saaledes taler jeg.","Derfor sagde Jesus til dem: naar I faae ophøiet Menneskens Søn, da skulle I kjende, at det er mig, og at jeg gjør Intet af mig selv; men som min Fader haver lært mig, saaledes taler jeg."],[8,29,"Og den, som udsendte mig, er med mig; Faderen haver ikke ladet mig alene, fordi jeg gjør altid det, som er ham behageligt.","Og den, som udsendte mig, er med mig; Faderen haver ikke ladet mig alene, fordi jeg gjør altid det, som er ham behageligt."],[8,30,"Der han talede dette, troede Mange paa ham.","Der han talede dette, troede Mange paa ham."],[8,31,"Derfor sagde Jesus til Jøderne, som havde troet paa ham: dersom I blive i mit Ord, ere I sandelig mine Disciple,","Derfor sagde Jesus til Jøderne, som havde troet paa ham: dersom I blive i mit Ord, ere I sandelig mine Disciple,"],[8,32,"og I skulle forstaae Sandheden, og Sandheden skal frigjøre Eder.","og I skulle forstaae Sandheden, og Sandheden skal frigjøre Eder."],[8,33,"De svarede ham: vi ere Abrahams Sæd, og have aldrig været Nogens Trælle; hvorledes siger du da: I skulle vorde frie?","De svarede ham: vi ere Abrahams Sæd, og have aldrig været Nogens Trælle; hvorledes siger du da: I skulle vorde frie?"],[8,34,"Jesus svarede dem: sandelig, sandelig siger jeg Eder: hver den, som gjør Synd, er Syndens Træl.","Jesus svarede dem: sandelig, sandelig siger jeg Eder: hver den, som gjør Synd, er Syndens Træl."],[8,35,"Men Trællen bliver ikke altid i Huset, Sønnen bliver der altid.","Men Trællen bliver ikke altid i Huset, Sønnen bliver der altid."],[8,36,"Dersom da Sønnen faaer frigjort Eder, skulle I være virkeligen frie.","Dersom da Sønnen faaer frigjort Eder, skulle I være virkeligen frie."],[8,37,"Jeg veed, at I ere Abrahams Sæd; men I søge at slaae mig ihjel, fordi min Tale ikke finder Rum hos Eder.","Jeg veed, at I ere Abrahams Sæd; men I søge at slaae mig ihjel, fordi min Tale ikke finder Rum hos Eder."],[8,38,"Jeg taler det, som jeg haver seet hos min Fader, saa gjøre I og det, som I have seet hos Eders Fader.","Jeg taler det, som jeg haver seet hos min Fader, saa gjøre I og det, som I have seet hos Eders Fader."],[8,39,"De svarede og sagde til ham: Abraham er vor Fader. Jesus sagde til dem: dersom I vare Abrahams Børn, gjorde I Abrahams Gjerninger.","De svarede og sagde til ham: Abraham er vor Fader. Jesus sagde til dem: dersom I vare Abrahams Børn, gjorde I Abrahams Gjerninger."],[8,40,"Men nu søge I at slaae mig ihjel, et Menneske, der haver sagt Eder Sandheden, som jeg haver hørt af Gud; dette havde Abraham ikke gjort.","Men nu søge I at slaae mig ihjel, et Menneske, der haver sagt Eder Sandheden, som jeg haver hørt af Gud; dette havde Abraham ikke gjort."],[8,41,"I gjøre Eders Faders Gjerninger. Derfor sagde de til ham: vi ere ikke avlede i Hoer; vi have en Fader, Gud.","I gjøre Eders Faders Gjerninger. Derfor sagde de til ham: vi ere ikke avlede i Hoer; vi have en Fader, Gud."],[8,42,"Da sagde Jesus til dem: dersom Gud var Eders Fader, da elskede I mig; thi jeg er ingenlunde kommen af mig selv, men han haver udsendt mig.","Da sagde Jesus til dem: dersom Gud var Eders Fader, da elskede I mig; thi jeg er ingenlunde kommen af mig selv, men han haver udsendt mig."],[8,43,"Hvi forstaae I ikke min Tale? efterdi I ikke kunne fordrage mit Ord.","Hvi forstaae I ikke min Tale? efterdi I ikke kunne fordrage mit Ord."],[8,44,"I ere af en Fader Djævelen, og ville gjøre Eders Faders Begjerninger. Han var en Manddraber fra Begyndelsen af, og blev ikke bestaaende i Sandheden; thi Sandhed er ikke i ham. Naar han taler Løgn, taler han af sit eget; thi han er en Løgner og Løgnens Fader.","I ere af en Fader Djævelen, og ville gjøre Eders Faders Begjerninger. Han var en Manddraber fra Begyndelsen af, og blev ikke bestaaende i Sandheden; thi Sandhed er ikke i ham. Naar han taler Løgn, taler han af sit eget; thi han er en Løgner og Løgnens Fader."],[8,45,"Men mig troe I ikke, fordi jeg taler Sandhed.","Men mig troe I ikke, fordi jeg taler Sandhed."],[8,46,"Hvo af Eder kan overbevise mig om nogen Synd? men siger jeg Sandhed, hvorfor troe I mig ikke?","Hvo af Eder kan overbevise mig om nogen Synd? men siger jeg Sandhed, hvorfor troe I mig ikke?"],[8,47,"Hvo som er af Gud, hører Guds Ord; derfor høre I ikke, fordi I ere ikke af Gud.","Hvo som er af Gud, hører Guds Ord; derfor høre I ikke, fordi I ere ikke af Gud."],[8,48,"Da svarede Jøderne og sagde til ham: sige vi ikke med Rette, at du er en Samaritan og haver Djævelen?","Da svarede Jøderne og sagde til ham: sige vi ikke med Rette, at du er en Samaritan og haver Djævelen?"],[8,49,"Jesus svarede: jeg haver ikke Djævelen, men jeg ærer min Fader, og I vanære mig.","Jesus svarede: jeg haver ikke Djævelen, men jeg ærer min Fader, og I vanære mig."],[8,50,"Men jeg søger ikke min Ære; der er den, som søger den, og dømmer.","Men jeg søger ikke min Ære; der er den, som søger den, og dømmer."],[8,51,"Sandelig, sandelig siger jeg Eder: dersom Nogen holder mit Ord, skal han ikke see Døden evindeligen.","Sandelig, sandelig siger jeg Eder: dersom Nogen holder mit Ord, skal han ikke see Døden evindeligen."],[8,52,"Da sagde Jøderne til ham: nu kjende vi, at du haver Djævelen; Abraham er død, og Propheterne, og du siger: dersom Nogen holder mit Ord, han skal ikke smage Døden evindeligen.","Da sagde Jøderne til ham: nu kjende vi, at du haver Djævelen; Abraham er død, og Propheterne, og du siger: dersom Nogen holder mit Ord, han skal ikke smage Døden evindeligen."],[8,53,"Mon du er større end vor Fader Abraham, hvilken er død? og Propheterne ere døde; hvem gjør du dig selv til?","Mon du er større end vor Fader Abraham, hvilken er død? og Propheterne ere døde; hvem gjør du dig selv til?"],[8,54,"Jesus svarede: dersom jeg ærer mig selv, er min Ære Intet; det er min Fader, som mig ærer, og hvem I sige, at han er Eders Gud.","Jesus svarede: dersom jeg ærer mig selv, er min Ære Intet; det er min Fader, som mig ærer, og hvem I sige, at han er Eders Gud."],[8,55,"Og I have ikke kjendt ham, men jeg kjender ham; og dersom jeg sagde: jeg kjender ham ikke, da blev jeg en Løgner ligesom I. Men jeg kjender ham og holder hans Ord.","Og I have ikke kjendt ham, men jeg kjender ham; og dersom jeg sagde: jeg kjender ham ikke, da blev jeg en Løgner ligesom I. Men jeg kjender ham og holder hans Ord."],[8,56,"Abraham, Eders Fader, frydede sig, at han skulde see min Dag, og han saae den og glædede sig.","Abraham, Eders Fader, frydede sig, at han skulde see min Dag, og han saae den og glædede sig."],[8,57,"Da sagde Jøderne til ham: du er ikke endnu halvtredsindstyve Aar gammel, og du haver seet Abraham?","Da sagde Jøderne til ham: du er ikke endnu halvtredsindstyve Aar gammel, og du haver seet Abraham?"],[8,58,"Jesus sagde til dem: sandelig, sandelig siger jeg Eder: førend Abraham blev, er jeg.","Jesus sagde til dem: sandelig, sandelig siger jeg Eder: førend Abraham blev, er jeg."],[8,59,"Derfor optoge de Stene, for at kaste paa ham: men Jesus skjulte sig, og gik ud af Templet og gik midt igjennem Mængden, og han undkom saaledes.","Derfor optoge de Stene, for at kaste paa ham: men Jesus skjulte sig, og gik ud af Templet og gik midt igjennem Mængden, og han undkom saaledes."],[9,1,"Og da han gik frem, saae han et Menneske, som var blind født.","Og da han gik frem, saae han et Menneske, som var blind født."],[9,2,"Og hans Disciple spurgte ham og sagde: Mester! hvo haver syndet? denne eller hans Forældre, at han er blind født?","Og hans Disciple spurgte ham og sagde: Mester! hvo haver syndet? denne eller hans Forældre, at han er blind født?"],[9,3,"Jesus svarede: hverken denne syndede, ei heller hans Forældre; men paa det at Guds Gjerninger skulle blive aabenbarede paa ham.","Jesus svarede: hverken denne syndede, ei heller hans Forældre; men paa det at Guds Gjerninger skulle blive aabenbarede paa ham."],[9,4,"Mig bør at gjøre hans Gjerninger, som mig haver udsendt, saalænge det er Dag; Natten kommer, da Ingen kan arbeide.","Mig bør at gjøre hans Gjerninger, som mig haver udsendt, saalænge det er Dag; Natten kommer, da Ingen kan arbeide."],[9,5,"Medens jeg er i Verden, er jeg Verdens Lys.","Medens jeg er i Verden, er jeg Verdens Lys."],[9,6,"Der han det havde sagt, spyttede han paa Jorden, og gjorde Dynd af Spyttet, og smurte Dyndet paa den Blindes Øine.","Der han det havde sagt, spyttede han paa Jorden, og gjorde Dynd af Spyttet, og smurte Dyndet paa den Blindes Øine."],[9,7,"Og han sagde til ham: gak bort, to dig i Dammen Siloam, (hvilket er udlagt: udsendt). Da gik han bort og toede sig og kom seende tilbage.","Og han sagde til ham: gak bort, to dig i Dammen Siloam, (hvilket er udlagt: udsendt). Da gik han bort og toede sig og kom seende tilbage."],[9,8,"Da sagde Naboerne og de, som før havde seet, at han var blind: er det ikke den, som sad og tiggede?","Da sagde Naboerne og de, som før havde seet, at han var blind: er det ikke den, som sad og tiggede?"],[9,9,"Andre sagde: det er denne; men Andre: han er ham lig. Han selv sagde: det er mig.","Andre sagde: det er denne; men Andre: han er ham lig. Han selv sagde: det er mig."],[9,10,"Da sagde de til ham: hvorledes bleve dine Øine aabnede?","Da sagde de til ham: hvorledes bleve dine Øine aabnede?"],[9,11,"Han svarede og sagde: et Menneske, som kaldes Jesus, gjorde Dynd, og smurte paa mine Øine, og sagde til mig: gak bort til Dammen Siloam og to dig. Men da jeg gik hen og toede mig, blev jeg seende.","Han svarede og sagde: et Menneske, som kaldes Jesus, gjorde Dynd, og smurte paa mine Øine, og sagde til mig: gak bort til Dammen Siloam og to dig. Men da jeg gik hen og toede mig, blev jeg seende."],[9,12,"Da sagde de til ham: hvor er han? Han sagde: jeg veed ikke.","Da sagde de til ham: hvor er han? Han sagde: jeg veed ikke."],[9,13,"Da førte de ham, som før var blind, til Pharisæerne.","Da førte de ham, som før var blind, til Pharisæerne."],[9,14,"(Men det var en Sabbat, da Jesus gjorde Dynd og aabnede hans Øine.)","(Men det var en Sabbat, da Jesus gjorde Dynd og aabnede hans Øine.)"],[9,15,"Da spurgte og Pharisæerne ham atter, hvorledes han var bleven seende. Men han sagde til dem: Dynd lagde ham paa mine Øine, og jeg toede mig, og seer.","Da spurgte og Pharisæerne ham atter, hvorledes han var bleven seende. Men han sagde til dem: Dynd lagde ham paa mine Øine, og jeg toede mig, og seer."],[9,16,"Derfor sagde nogle af Pharisæerne: dette Menneske er ikke af Gud, efterdi han holder ikke Sabbaten. Andre sagde: hvorledes kan et syndigt Menneske gjøre saadanne Tegn? Og der var Splid imellem dem.","Derfor sagde nogle af Pharisæerne: dette Menneske er ikke af Gud, efterdi han holder ikke Sabbaten. Andre sagde: hvorledes kan et syndigt Menneske gjøre saadanne Tegn? Og der var Splid imellem dem."],[9,17,"Da sagde atter til den Blinde: hvad siger du om ham, efterdi han aabnede dine Øine? Men han sagde: han er en Prophet.","Da sagde atter til den Blinde: hvad siger du om ham, efterdi han aabnede dine Øine? Men han sagde: han er en Prophet."],[9,18,"Men Jøderne troede ikke om ham, at han havde været blind og var bleven seende, førend de kaldte hans Forældre, som havde faaet sit Syn.","Men Jøderne troede ikke om ham, at han havde været blind og var bleven seende, førend de kaldte hans Forældre, som havde faaet sit Syn."],[9,19,"Og de spurgte dem og sagde: er denne Eders Søn, om hvem I sige, at han var blind født? hvorledes er han da nu seende?","Og de spurgte dem og sagde: er denne Eders Søn, om hvem I sige, at han var blind født? hvorledes er han da nu seende?"],[9,20,"Hans Forældre svarede dem og sagde: vi vide, at dette er vor Søn, og at han var blind født.","Hans Forældre svarede dem og sagde: vi vide, at dette er vor Søn, og at han var blind født."],[9,21,"Men hvorledes han nu er bleven seende, vide vi ikke, og hvo der haver aabnet hans Øine, vide vi ikke heller; han er selv gammel nok, spørger ham, han maa selv svare for sig.","Men hvorledes han nu er bleven seende, vide vi ikke, og hvo der haver aabnet hans Øine, vide vi ikke heller; han er selv gammel nok, spørger ham, han maa selv svare for sig."],[9,22,"Dette sagde hans Forældre, fordi de frygtede for Jøderne; thi Jøderne vare allerede komne overeens om, at dersom Nogen bekjendte ham at være Christus, skulle denne blive udelukt af Synagogen.","Dette sagde hans Forældre, fordi de frygtede for Jøderne; thi Jøderne vare allerede komne overeens om, at dersom Nogen bekjendte ham at være Christus, skulle denne blive udelukt af Synagogen."],[9,23,"Derfor sagde hans Forældre: han er gammel nok, spørger ham selv.","Derfor sagde hans Forældre: han er gammel nok, spørger ham selv."],[9,24,"Da kaldte de anden Gang til sig det Menneske, som havde været blind, og sagde til ham: giv Gud Æren; vi vide, at hiint Menneske er en Synder.","Da kaldte de anden Gang til sig det Menneske, som havde været blind, og sagde til ham: giv Gud Æren; vi vide, at hiint Menneske er en Synder."],[9,25,"Da svarede han og sagde: om han er en Synder, veed jeg ikke; een Ting veed jeg, at jeg, som var blind, nu seer.","Da svarede han og sagde: om han er en Synder, veed jeg ikke; een Ting veed jeg, at jeg, som var blind, nu seer."],[9,26,"Men de sagde til ham igjen: hvad gjorde han ved dig? hvorledes aabnede han dine Øine?","Men de sagde til ham igjen: hvad gjorde han ved dig? hvorledes aabnede han dine Øine?"],[9,27,"Han svarede dem: jeg haver allerede sagt Eder det, og I hørte ikke derefter. Hvorfor ville I høre det igjen? ville I og vorde hans Disciple?","Han svarede dem: jeg haver allerede sagt Eder det, og I hørte ikke derefter. Hvorfor ville I høre det igjen? ville I og vorde hans Disciple?"],[9,28,"Da skjældte de paa ham og sagde: du er hans Discipel, men vi ere Moses’ Disciple.","Da skjældte de paa ham og sagde: du er hans Discipel, men vi ere Moses’ Disciple."],[9,29,"Vi vide, at Gud haver talet til Moses; men om denne vide vi ikke, hvorfra han er.","Vi vide, at Gud haver talet til Moses; men om denne vide vi ikke, hvorfra han er."],[9,30,"Mennesket svarede og sagde til dem: det er dog underligt, at I ikke vide, hvorfra han er, og han haver aabnet mine Øine.","Mennesket svarede og sagde til dem: det er dog underligt, at I ikke vide, hvorfra han er, og han haver aabnet mine Øine."],[9,31,"Vi vide dog, at Gud hører ikke Syndere; men dersom Nogen er gudfrygtig og gjør hans Villie, den hører han.","Vi vide dog, at Gud hører ikke Syndere; men dersom Nogen er gudfrygtig og gjør hans Villie, den hører han."],[9,32,"Aldrig er det hørt, at Nogen haver aabnet Øinene paa en Blindfødt.","Aldrig er det hørt, at Nogen haver aabnet Øinene paa en Blindfødt."],[9,33,"Var denne ikke fra Gud, da kunde han slet intet gjøre.","Var denne ikke fra Gud, da kunde han slet intet gjøre."],[9,34,"De svarede og sagde til ham: du er ganske født i Synd, og du vil lære os? Og de stødte ham ud.","De svarede og sagde til ham: du er ganske født i Synd, og du vil lære os? Og de stødte ham ud."],[9,35,"Jesus hørte, at de havde udstødt ham, og da han traf ham, sagde ham til ham: troer du paa Guds Søn?","Jesus hørte, at de havde udstødt ham, og da han traf ham, sagde ham til ham: troer du paa Guds Søn?"],[9,36,"Han svarede og sagde: hvo er han, Herre! at jeg kan troe paa ham?","Han svarede og sagde: hvo er han, Herre! at jeg kan troe paa ham?"],[9,37,"Men Jesus sagde til ham: baade haver du seet ham, og den, som taler med dig, ham er det.","Men Jesus sagde til ham: baade haver du seet ham, og den, som taler med dig, ham er det."],[9,38,"Men han sagde: jeg troer, Herre! og han kastede sig ned for ham.","Men han sagde: jeg troer, Herre! og han kastede sig ned for ham."],[9,39,"Og Jesus sagde: jeg er kommen til Dom i denne Verden, at de, som ikke see, skulle vorde seende, og de, som see, skulle vorde blinde.","Og Jesus sagde: jeg er kommen til Dom i denne Verden, at de, som ikke see, skulle vorde seende, og de, som see, skulle vorde blinde."],[9,40,"Dette hørte de af Pharisæerne, som vare hos ham, og de sagde til ham: monne og vi ere blinde?","Dette hørte de af Pharisæerne, som vare hos ham, og de sagde til ham: monne og vi ere blinde?"],[9,41,"Jesus sagde til dem: vare I blinde, da havde I ikke Synd; men nu sige I: vi see; derfor bliver Eders Synd.","Jesus sagde til dem: vare I blinde, da havde I ikke Synd; men nu sige I: vi see; derfor bliver Eders Synd."],[10,1,"Sandelig, sandelig siger jeg Eder: hvo som ikke gaaer ind ad Døren i Faarestien, men stiger andensteds over, han er en Tyv og en Røver.","Sandelig, sandelig siger jeg Eder: hvo som ikke gaaer ind ad Døren i Faarestien, men stiger andensteds over, han er en Tyv og en Røver."],[10,2,"Men den, som gaaer ind ad Døren, er Faarenes Hyrde.","Men den, som gaaer ind ad Døren, er Faarenes Hyrde."],[10,3,"For denne lader Dørvogteren op, og Faarene høre hans Røst; og han kalder sine egne Faar ved Navn og fører dem ud.","For denne lader Dørvogteren op, og Faarene høre hans Røst; og han kalder sine egne Faar ved Navn og fører dem ud."],[10,4,"Og naar han haver udladt sine egne Faar, gaaer han foran dem; og Faarene følge ham, fordi de kjende hans Røst.","Og naar han haver udladt sine egne Faar, gaaer han foran dem; og Faarene følge ham, fordi de kjende hans Røst."],[10,5,"Men en Fremmed følge de ikke, men flye fra ham, fordi de kjende ikke den Fremmedes Røst.","Men en Fremmed følge de ikke, men flye fra ham, fordi de kjende ikke den Fremmedes Røst."],[10,6,"Denne Lignelse sagde Jesus til dem; men de forstode ikke, hvad det var, som han talede til dem.","Denne Lignelse sagde Jesus til dem; men de forstode ikke, hvad det var, som han talede til dem."],[10,7,"Derfor sagde Jesus atter til dem: sandelig, sandelig siger jeg Eder: jeg er Faarenes Dør.","Derfor sagde Jesus atter til dem: sandelig, sandelig siger jeg Eder: jeg er Faarenes Dør."],[10,8,"Alle de, som ere komne før mig, ere Tyve og Røvere; men Faarene hørte dem ikke.","Alle de, som ere komne før mig, ere Tyve og Røvere; men Faarene hørte dem ikke."],[10,9,"Jeg er Døren; dersom Nogen gaaer ind ved mig, han skal frelses; og han skal gaae ind og gaae ud og finde Føde.","Jeg er Døren; dersom Nogen gaaer ind ved mig, han skal frelses; og han skal gaae ind og gaae ud og finde Føde."],[10,10,"Tyven kommer ikke, uden for at stjæle og myrde og fordærve; jeg er kommen, at de skulle have Liv og have overflødigt.","Tyven kommer ikke, uden for at stjæle og myrde og fordærve; jeg er kommen, at de skulle have Liv og have overflødigt."],[10,11,"Jeg er den gode Hyrde; den gode Hyrde sætter sit Liv til for Faarene.","Jeg er den gode Hyrde; den gode Hyrde sætter sit Liv til for Faarene."],[10,12,"Men Leiesvenden og den, som ikke er Hyrde, hvilken Faarene ikke høre til, seer Ulven komme og forlader Faarene og flyer; og Ulven røver dem og adspreder Faarene.","Men Leiesvenden og den, som ikke er Hyrde, hvilken Faarene ikke høre til, seer Ulven komme og forlader Faarene og flyer; og Ulven røver dem og adspreder Faarene."],[10,13,"Men Leiesvenden flyer, fordi han er en Leiesvend og haver ikke Omsorg for Faarene.","Men Leiesvenden flyer, fordi han er en Leiesvend og haver ikke Omsorg for Faarene."],[10,14,"Jeg er den gode Hyrde, og jeg kjender Mine, og kjendes af Mine,","Jeg er den gode Hyrde, og jeg kjender Mine, og kjendes af Mine,"],[10,15,"(ligesom Faderen kjender mig, kjender jeg og Faderen); og jeg sætter mit Liv til for Faarene.","(ligesom Faderen kjender mig, kjender jeg og Faderen); og jeg sætter mit Liv til for Faarene."],[10,16,"Og jeg haver andre Faar, som ikke ere af denne Sti, dem bør det mig og at føre did, og de skulle høre min Røst; og der skal blive een Hjord, een Hyrde.","Og jeg haver andre Faar, som ikke ere af denne Sti, dem bør det mig og at føre did, og de skulle høre min Røst; og der skal blive een Hjord, een Hyrde."],[10,17,"Derfor elsker Faderen mig, fordi jeg sætter mit Liv til, at jeg skal tage det igjen.","Derfor elsker Faderen mig, fordi jeg sætter mit Liv til, at jeg skal tage det igjen."],[10,18,"Ingen tager det fra mig, men jeg sætter det til af mig selv. Jeg haver Magt at sætte det til, og haver Magt at tage det igjen. Dette Bud annammede jeg af min Fader.","Ingen tager det fra mig, men jeg sætter det til af mig selv. Jeg haver Magt at sætte det til, og haver Magt at tage det igjen. Dette Bud annammede jeg af min Fader."],[10,19,"Da blev der atter Splid iblandt Jøderne over disse Ord.","Da blev der atter Splid iblandt Jøderne over disse Ord."],[10,20,"Mange af dem sagde: han haver Djævelen og raser, hvi høre I ham?","Mange af dem sagde: han haver Djævelen og raser, hvi høre I ham?"],[10,21,"Andre sagde: disse ere ikke Ord af en Besat; mon en Djævel kan aabne de Blindes Øine?","Andre sagde: disse ere ikke Ord af en Besat; mon en Djævel kan aabne de Blindes Øine?"],[10,22,"Men Indvielsens Fest indtraf i Jerusalem, og det var Vinter.","Men Indvielsens Fest indtraf i Jerusalem, og det var Vinter."],[10,23,"Og Jesus gik omkring i Templet, udi Salomons Buegang.","Og Jesus gik omkring i Templet, udi Salomons Buegang."],[10,24,"Da omringede Jøderne ham og sagde til ham: hvor længe holder du vor Sjæl i Forventning? dersom du er Christus, da siig os det frit!","Da omringede Jøderne ham og sagde til ham: hvor længe holder du vor Sjæl i Forventning? dersom du er Christus, da siig os det frit!"],[10,25,"Jesus svarede dem: jeg haver sagt Eder det, og I troe ikke; de Gjerninger, som jeg gjør i min Faders Navn, disse vidne om mig.","Jesus svarede dem: jeg haver sagt Eder det, og I troe ikke; de Gjerninger, som jeg gjør i min Faders Navn, disse vidne om mig."],[10,26,"Men I troe ikke; thi I ere ikke af mine Faar, som jeg sagde Eder.","Men I troe ikke; thi I ere ikke af mine Faar, som jeg sagde Eder."],[10,27,"Mine Faar høre min Røst, og jeg kjender dem, og de følge mig.","Mine Faar høre min Røst, og jeg kjender dem, og de følge mig."],[10,28,"Og jeg giver dem et evigt Liv, og de skulle ingenlunde fortabes, og Ingen skal rive dem af min Haand.","Og jeg giver dem et evigt Liv, og de skulle ingenlunde fortabes, og Ingen skal rive dem af min Haand."],[10,29,"Min Fader, som haver givet mig dem, er større end Alle; og Ingen kan rive dem af min Faders Haand.","Min Fader, som haver givet mig dem, er større end Alle; og Ingen kan rive dem af min Faders Haand."],[10,30,"Jeg og Faderen, vi ere eet.","Jeg og Faderen, vi ere eet."],[10,31,"Da toge Jøderne atter Stene op for at stene ham.","Da toge Jøderne atter Stene op for at stene ham."],[10,32,"Jesus svarede dem: mange gode Gjerninger viste jeg Eder fra min Fader; for hvilken af disse Gjerninger stene I mig?","Jesus svarede dem: mange gode Gjerninger viste jeg Eder fra min Fader; for hvilken af disse Gjerninger stene I mig?"],[10,33,"Jøderne svarede ham og sagde: for en god Gjerning stene vi dig ikke, men for Gudsbespottelse, og fordi du, som er et Menneske, gjør dig selv til Gud.","Jøderne svarede ham og sagde: for en god Gjerning stene vi dig ikke, men for Gudsbespottelse, og fordi du, som er et Menneske, gjør dig selv til Gud."],[10,34,"Jesus svarede dem: er der ikke skrevet i Eders Lov: jeg haver sagt: I ere Guder?","Jesus svarede dem: er der ikke skrevet i Eders Lov: jeg haver sagt: I ere Guder?"],[10,35,"Dersom han kalder dem Guder, til hvilke Guds Ord skete, (og Skriften kan ikke rokkes);","Dersom han kalder dem Guder, til hvilke Guds Ord skete, (og Skriften kan ikke rokkes);"],[10,36,"sige I da til den, hvem Faderen haver helliget og sendt til Verden: du bespotter Gud, fordi jeg sagde: jeg er Guds Søn?","sige I da til den, hvem Faderen haver helliget og sendt til Verden: du bespotter Gud, fordi jeg sagde: jeg er Guds Søn?"],[10,37,"Dersom jeg ikke gjør min Faders Gjerninger, troer mig ikke.","Dersom jeg ikke gjør min Faders Gjerninger, troer mig ikke."],[10,38,"Men dersom jeg gjør dem, om I end ikke ville troe mig, da troer Gjerningerne, paa det I kunne kjende og troe, at Faderen er i mig, og jeg i ham.","Men dersom jeg gjør dem, om I end ikke ville troe mig, da troer Gjerningerne, paa det I kunne kjende og troe, at Faderen er i mig, og jeg i ham."],[10,39,"Derfor søgte de atter at gribe ham; men han undkom af deres Haand.","Derfor søgte de atter at gribe ham; men han undkom af deres Haand."],[10,40,"Og han drog atter bort paa hiin Side Jordan til det Sted, hvor Johannes først døbte, og blev der.","Og han drog atter bort paa hiin Side Jordan til det Sted, hvor Johannes først døbte, og blev der."],[10,41,"Og Mange kom til ham og sagde: Johannes gjorde vel intet Tegn: men Alt, hvad Johannes sagde om denne, var sandt.","Og Mange kom til ham og sagde: Johannes gjorde vel intet Tegn: men Alt, hvad Johannes sagde om denne, var sandt."],[10,42,"Og Mange der troede paa ham.","Og Mange der troede paa ham."],[11,1,"Men der laae En syg, Lazarus af Bethania, af den By, hvor Maria og Martha, hendes Søstre, vare.","Men der laae En syg, Lazarus af Bethania, af den By, hvor Maria og Martha, hendes Søstre, vare."],[11,2,"(Men Maria var den, som salvede Herren med Salve og tørrede hans Fødder med sit Haar; hendes Broder Lazarus var syg).","(Men Maria var den, som salvede Herren med Salve og tørrede hans Fødder med sit Haar; hendes Broder Lazarus var syg)."],[11,3,"Da sendte de Søstre til ham og lode ham sige: Herre! see, den, du elsker, er syg.","Da sendte de Søstre til ham og lode ham sige: Herre! see, den, du elsker, er syg."],[11,4,"Men der Jesus det hørte, sagde han: denne Sygdom er ikke til Døden, men til Guds Ære, at Guds Søn skal æres ved den.","Men der Jesus det hørte, sagde han: denne Sygdom er ikke til Døden, men til Guds Ære, at Guds Søn skal æres ved den."],[11,5,"Men Jesus elskede Martha og hendes Søster og Lazarus.","Men Jesus elskede Martha og hendes Søster og Lazarus."],[11,6,"Der han nu hørte, at han var syg, blev han dog to Dage paa det Sted, hvor han var.","Der han nu hørte, at han var syg, blev han dog to Dage paa det Sted, hvor han var."],[11,7,"Siden efter sagde han til Disciplene: lader os drage til Judæa igjen.","Siden efter sagde han til Disciplene: lader os drage til Judæa igjen."],[11,8,"Disciplene sagde til ham: Mester! nyligen søgte Jøderne at stene dig, og du drager atter derhen?","Disciplene sagde til ham: Mester! nyligen søgte Jøderne at stene dig, og du drager atter derhen?"],[11,9,"Jesus svarede: ere der ikke tolv Timer om Dagen? Vandrer Nogen om Dagen, da støder han ikke an; thi han seer denne Verdens Lys.","Jesus svarede: ere der ikke tolv Timer om Dagen? Vandrer Nogen om Dagen, da støder han ikke an; thi han seer denne Verdens Lys."],[11,10,"Men vandrer Nogen om Natten, da støder han an; thi Lyset er ikke i ham.","Men vandrer Nogen om Natten, da støder han an; thi Lyset er ikke i ham."],[11,11,"Dette talede han, og derefter siger han til dem: Lazarus, vor Ven, er sovet ind; men jeg gaaer hen for at opvække ham af Søvne.","Dette talede han, og derefter siger han til dem: Lazarus, vor Ven, er sovet ind; men jeg gaaer hen for at opvække ham af Søvne."],[11,12,"Da sagde hans Disciple: Herre! sover han, da bliver han karsk.","Da sagde hans Disciple: Herre! sover han, da bliver han karsk."],[11,13,"Men Jesus talede om hans Død; de derimod meente, at han talede om den naturlige Søvn.","Men Jesus talede om hans Død; de derimod meente, at han talede om den naturlige Søvn."],[11,14,"Derefter sagde da Jesus dem reent ud: Lazarus er død!","Derefter sagde da Jesus dem reent ud: Lazarus er død!"],[11,15,"Og jeg er glad for Eders Skyld, at jeg ikke var der, paa det I skulle troe: men lader os gaae til ham!","Og jeg er glad for Eders Skyld, at jeg ikke var der, paa det I skulle troe: men lader os gaae til ham!"],[11,16,"Da sagde Thomas, (hvilket betyder Tvilling), til sine Meddisciple: lader os ogsaa gaae, at vi kunne døe med ham.","Da sagde Thomas, (hvilket betyder Tvilling), til sine Meddisciple: lader os ogsaa gaae, at vi kunne døe med ham."],[11,17,"Da Jesus kom, fandt han ham liggende i Graven allerede fire Dage.","Da Jesus kom, fandt han ham liggende i Graven allerede fire Dage."],[11,18,"(Men Bethania var nær ved Jerusalem, omtrent femten Stadier derfra).","(Men Bethania var nær ved Jerusalem, omtrent femten Stadier derfra)."],[11,19,"Og mange Jøder vare komne til Martha og Maria, for at trøste dem over deres Broder.","Og mange Jøder vare komne til Martha og Maria, for at trøste dem over deres Broder."],[11,20,"Da Martha nu hørte, at Jesus kom, gik hun ud ham imøde; men Maria blev siddende i Huset.","Da Martha nu hørte, at Jesus kom, gik hun ud ham imøde; men Maria blev siddende i Huset."],[11,21,"Da sagde Martha til Jesus: Herre! havde du været her, da var min Broder ikke død.","Da sagde Martha til Jesus: Herre! havde du været her, da var min Broder ikke død."],[11,22,"Men ogsaa nu veed jeg, at hvadsomhelst du beder af Gud, vil Gud give dig.","Men ogsaa nu veed jeg, at hvadsomhelst du beder af Gud, vil Gud give dig."],[11,23,"Jesus sagde til hende: din Broder skal opstaae.","Jesus sagde til hende: din Broder skal opstaae."],[11,24,"Martha siger til ham: jeg veed, at han skal opstaae i Opstandelsen paa den yderste Dag.","Martha siger til ham: jeg veed, at han skal opstaae i Opstandelsen paa den yderste Dag."],[11,25,"Jesus sagde til hende: jeg er Opstandelsen og Livet; hvo som troer paa mig, om han end døer, skal han dog leve.","Jesus sagde til hende: jeg er Opstandelsen og Livet; hvo som troer paa mig, om han end døer, skal han dog leve."],[11,26,"Og hver den, som lever og troer paa mig, skal ikke døde evindeligen. Troer du dette?","Og hver den, som lever og troer paa mig, skal ikke døde evindeligen. Troer du dette?"],[11,27,"Hun siger til ham: ja Herre! jeg haver troet, at du er Christus, den Guds Søn, den, som kommer til Verden.","Hun siger til ham: ja Herre! jeg haver troet, at du er Christus, den Guds Søn, den, som kommer til Verden."],[11,28,"Og der hun dette havde sagt, gik hun bort og kaldte hemmeligen sin Søster Maria og sagde: Mesteren er her og kalder ad dig.","Og der hun dette havde sagt, gik hun bort og kaldte hemmeligen sin Søster Maria og sagde: Mesteren er her og kalder ad dig."],[11,29,"Der hun det hørte, reiste hun sig strax og kom til ham.","Der hun det hørte, reiste hun sig strax og kom til ham."],[11,30,"(Men Jesus var ikke endnu kommen til Byen, men var paa det Sted, hvor Martha mødte ham.)","(Men Jesus var ikke endnu kommen til Byen, men var paa det Sted, hvor Martha mødte ham.)"],[11,31,"Da nu Jøderne, som var hos hende i Huset og trøstede hende, saae, at Maria stod hastelig op og gik ud, fulgte de hende og sagde: hun gaaer bort til Graven for at græde der.","Da nu Jøderne, som var hos hende i Huset og trøstede hende, saae, at Maria stod hastelig op og gik ud, fulgte de hende og sagde: hun gaaer bort til Graven for at græde der."],[11,32,"Der Maria da kom derhen, hvor Jesus var, og saae ham, faldt hun ned for hans Fødder og sagde til ham: Herre! havde du været her, da var min Broder ikke død.","Der Maria da kom derhen, hvor Jesus var, og saae ham, faldt hun ned for hans Fødder og sagde til ham: Herre! havde du været her, da var min Broder ikke død."],[11,33,"Der Jesus da saae hende græde, og saae Jøderne græde, som kom med hende, rørtes han i Aanden, og blev heftig bevæget og sagde:","Der Jesus da saae hende græde, og saae Jøderne græde, som kom med hende, rørtes han i Aanden, og blev heftig bevæget og sagde:"],[11,34,"hvor have I lagt ham? De sagde til ham: Herre! kom og see.","hvor have I lagt ham? De sagde til ham: Herre! kom og see."],[11,35,"Jesus græd.","Jesus græd."],[11,36,"Da sagde Jøderne: see, hvor han elskede ham!","Da sagde Jøderne: see, hvor han elskede ham!"],[11,37,"Men nogle af dem sagde: kunde ikke han, som aabnede den Blindes Øine, have gjort, at og denne ikke var død?","Men nogle af dem sagde: kunde ikke han, som aabnede den Blindes Øine, have gjort, at og denne ikke var død?"],[11,38,"Da rørtes Jesus atter inderlig, og kom til Graven. Men det var en Hule, og en Steen laae derfor.","Da rørtes Jesus atter inderlig, og kom til Graven. Men det var en Hule, og en Steen laae derfor."],[11,39,"Jesus sagde: tager Stenen bort. Martha, den Dødes Søster, siger til ham: Herre! han stinker allerede; thi han haver ligget fire Dage.","Jesus sagde: tager Stenen bort. Martha, den Dødes Søster, siger til ham: Herre! han stinker allerede; thi han haver ligget fire Dage."],[11,40,"Jesus sagde til hende: sagde jeg ikke, at dersom du kunde troe, skulde du see Guds Herlighed?","Jesus sagde til hende: sagde jeg ikke, at dersom du kunde troe, skulde du see Guds Herlighed?"],[11,41,"Da toge de Stenen bort, hvor den Døde var lagt. Men Jesus opløftede sine Øine og sagde: Fader! jeg takker dig, at du haver hørt mig.","Da toge de Stenen bort, hvor den Døde var lagt. Men Jesus opløftede sine Øine og sagde: Fader! jeg takker dig, at du haver hørt mig."],[11,42,"Dog, jeg vidste, at du altid hører mig; men for Folkets Skyld, som staaer omkring, sagde jeg det, at de skulle troe, at du haver udsendt mig.","Dog, jeg vidste, at du altid hører mig; men for Folkets Skyld, som staaer omkring, sagde jeg det, at de skulle troe, at du haver udsendt mig."],[11,43,"Og der han havde sagt dette, raabte han med høi Røst: Lazarus, kom hid ud!","Og der han havde sagt dette, raabte han med høi Røst: Lazarus, kom hid ud!"],[11,44,"Og den Døde kom ud, bunden med Jordeklæder om Fødder og Hænder, og hans Ansigt var ombundet med en Svededug. Jesus sagde til dem: løser ham og lader ham gaae.","Og den Døde kom ud, bunden med Jordeklæder om Fødder og Hænder, og hans Ansigt var ombundet med en Svededug. Jesus sagde til dem: løser ham og lader ham gaae."],[11,45,"Derfor troede mange paa ham af de Jøder, som vare komne til Maria, og havde seet de Ting, som Jesus havde gjort.","Derfor troede mange paa ham af de Jøder, som vare komne til Maria, og havde seet de Ting, som Jesus havde gjort."],[11,46,"Men nogle af dem gik hen til Pharisæerne og sagde dem, hvad Jesus havde gjort.","Men nogle af dem gik hen til Pharisæerne og sagde dem, hvad Jesus havde gjort."],[11,47,"Derfor forsamlede de Ypperstepræster og Pharisæerne Raadet og sagde: hvad gjøre vi? thi dette Menneske gjør mange Tegn.","Derfor forsamlede de Ypperstepræster og Pharisæerne Raadet og sagde: hvad gjøre vi? thi dette Menneske gjør mange Tegn."],[11,48,"Dersom vi lade ham saaledes blive ved, ville Alle troe paa ham; og Romerne skulle komme og tage baade vort land og Folk.","Dersom vi lade ham saaledes blive ved, ville Alle troe paa ham; og Romerne skulle komme og tage baade vort land og Folk."],[11,49,"Men een af dem, Caiphas, som var dette Aars Ypperstepræst, sagde til dem:","Men een af dem, Caiphas, som var dette Aars Ypperstepræst, sagde til dem:"],[11,50,"I forstaae slet Intet; ei heller betænke I, at det er os gavnligt, at eet Menneske døer for Folket, og at ikke det ganske Folk skal fordærves.","I forstaae slet Intet; ei heller betænke I, at det er os gavnligt, at eet Menneske døer for Folket, og at ikke det ganske Folk skal fordærves."],[11,51,"Men dette sagde han ikke af sig selv; men da han var samme Aars Ypperstepræst, spaaede han, at Jesus skulde døde for Folket.","Men dette sagde han ikke af sig selv; men da han var samme Aars Ypperstepræst, spaaede han, at Jesus skulde døde for Folket."],[11,52,"Og ikke for Folket alene; men paa det han og skulde samle de adspredte Guds Børn til een Hob.","Og ikke for Folket alene; men paa det han og skulde samle de adspredte Guds Børn til een Hob."],[11,53,"Fra den Dag af raadsloge de derfor om at ihjelslaae ham.","Fra den Dag af raadsloge de derfor om at ihjelslaae ham."],[11,54,"Da vandrede Jesus ikke mere frit iblandt Jøderne, men gik derfra til en Egn nær ved Ørken, til en Stad, som kaldes Ephraim; og han blev der nogen Tid med sine Disciple.","Da vandrede Jesus ikke mere frit iblandt Jøderne, men gik derfra til en Egn nær ved Ørken, til en Stad, som kaldes Ephraim; og han blev der nogen Tid med sine Disciple."],[11,55,"Men Jødernes Paaske var nær; og Mange fra Landet gik op til Jerusalem før Paasken, for at rense sig.","Men Jødernes Paaske var nær; og Mange fra Landet gik op til Jerusalem før Paasken, for at rense sig."],[11,56,"Da ledte de efter Jesus og talede med hverandre, der de stode i Templet: hvad tykkes Eder, at han kommer ikke til Høitiden?","Da ledte de efter Jesus og talede med hverandre, der de stode i Templet: hvad tykkes Eder, at han kommer ikke til Høitiden?"],[11,57,"Men baade de Ypperstepræster og Pharisæerne havde givet en Befaling, at dersom Nogen vidste, hvor han var, skulde han give det tilkjende, at de kunde gribe ham.","Men baade de Ypperstepræster og Pharisæerne havde givet en Befaling, at dersom Nogen vidste, hvor han var, skulde han give det tilkjende, at de kunde gribe ham."],[12,1,"Men sex Dage før Paaske kom Jesus til Bethania, hvor Lazarus var, der havde været død, og hvem han havde opreist fra de Døde.","Men sex Dage før Paaske kom Jesus til Bethania, hvor Lazarus var, der havde været død, og hvem han havde opreist fra de Døde."],[12,2,"Da gjorde de ham der en Nadvere, og Martha opvartede; men Lazarus var een af dem, som sadde tilbords med ham.","Da gjorde de ham der en Nadvere, og Martha opvartede; men Lazarus var een af dem, som sadde tilbords med ham."],[12,3,"Da tog Maria et Pund af uforfalsket meget kostelig Nardus-Salve, og salvede Jesu Fødder, og tørrede hans Fødder med sit Haar; men Huset blev fuldt af Salvens Lugt.","Da tog Maria et Pund af uforfalsket meget kostelig Nardus-Salve, og salvede Jesu Fødder, og tørrede hans Fødder med sit Haar; men Huset blev fuldt af Salvens Lugt."],[12,4,"Da sagde een af hans Disciple, Judas, Simons Søn, Ischariotes, som siden forraadte ham:","Da sagde een af hans Disciple, Judas, Simons Søn, Ischariotes, som siden forraadte ham:"],[12,5,"hvorfor blev denne Salve ikke solgt for tre hundrede Penninge og givet til Fattige?","hvorfor blev denne Salve ikke solgt for tre hundrede Penninge og givet til Fattige?"],[12,6,"Men dette sagde han ikke, fordi han havde Omsorg for de Fattige, men fordi han var en Tyv, og havde Pungen, og bar hvad der blev lagt deri.","Men dette sagde han ikke, fordi han havde Omsorg for de Fattige, men fordi han var en Tyv, og havde Pungen, og bar hvad der blev lagt deri."],[12,7,"Da sagde Jesus: lad hende i Fred; til min Begravelsesdag haver hun bevaret den.","Da sagde Jesus: lad hende i Fred; til min Begravelsesdag haver hun bevaret den."],[12,8,"Thi Fattige have I altid hos Eder; men mig have I ikke altid.","Thi Fattige have I altid hos Eder; men mig have I ikke altid."],[12,9,"Da fik en stor Hob af Jøderne at vide, at han var der; og de kom ikke for Jesu Skyld alene, men ogsaa for at see Lazarus, hvem han havde opreist fra de Døde.","Da fik en stor Hob af Jøderne at vide, at han var der; og de kom ikke for Jesu Skyld alene, men ogsaa for at see Lazarus, hvem han havde opreist fra de Døde."],[12,10,"Men de Ypperstepræster raadsloge om, ogsaa at ihjelslaae Lazarus;","Men de Ypperstepræster raadsloge om, ogsaa at ihjelslaae Lazarus;"],[12,11,"thi for hans Skyld gik mange af Jøderne hen, og troede paa Jesus.","thi for hans Skyld gik mange af Jøderne hen, og troede paa Jesus."],[12,12,"Den anden Dag, da den store Mængde, som var kommen til Høitiden, hørte, at Jesus kom til Jerusalem,","Den anden Dag, da den store Mængde, som var kommen til Høitiden, hørte, at Jesus kom til Jerusalem,"],[12,13,"toge de Palmegrene, og gik ud imod ham og raabte: Hosanna! velsignet være den, som kommer i Herrens Navn, den Israels Konge!","toge de Palmegrene, og gik ud imod ham og raabte: Hosanna! velsignet være den, som kommer i Herrens Navn, den Israels Konge!"],[12,14,"Men Jesus fandt en Asenindes Føl og satte sig derpaa, som der er skrevet:","Men Jesus fandt en Asenindes Føl og satte sig derpaa, som der er skrevet:"],[12,15,"frygt ikke, Zions Datter! see, din Konge kommer ridende paa en Asenindes Føl.","frygt ikke, Zions Datter! see, din Konge kommer ridende paa en Asenindes Føl."],[12,16,"Men dette forstode hans Disciple ikke først; men der Jesus var herliggjort, da kom de ihu, at dette var skrevet om ham, og at de havde gjort dette for ham.","Men dette forstode hans Disciple ikke først; men der Jesus var herliggjort, da kom de ihu, at dette var skrevet om ham, og at de havde gjort dette for ham."],[12,17,"Men den Mængde, som havde været med ham, vidnede, at han havde kaldt Lazarus af Graven, og opreist ham fra de Døde.","Men den Mængde, som havde været med ham, vidnede, at han havde kaldt Lazarus af Graven, og opreist ham fra de Døde."],[12,18,"Derfor gik og Folket ham imøde, fordi det havde hørt, at han havde gjort dette Tegn.","Derfor gik og Folket ham imøde, fordi det havde hørt, at han havde gjort dette Tegn."],[12,19,"Da sagde Pharisæerne til hverandre: I see, at I udrette slet intet; see! al Verden gaaer efter ham.","Da sagde Pharisæerne til hverandre: I see, at I udrette slet intet; see! al Verden gaaer efter ham."],[12,20,"Men der var nogle Græker af dem, som vare gangne op for at tilbede paa Høitiden.","Men der var nogle Græker af dem, som vare gangne op for at tilbede paa Høitiden."],[12,21,"Disse gik nu til Philippus, som var fra Bethsaida i Galilæa, og bade ham og sagde: Herre! vi ønske at see Jesus.","Disse gik nu til Philippus, som var fra Bethsaida i Galilæa, og bade ham og sagde: Herre! vi ønske at see Jesus."],[12,22,"Philippus kommer og siger Andreas det, og Andreas og Philippus sige atter Jesus det.","Philippus kommer og siger Andreas det, og Andreas og Philippus sige atter Jesus det."],[12,23,"Men Jesus svarede dem og sagde: Timen er kommen, at Menneskens Søn skal herliggjøres.","Men Jesus svarede dem og sagde: Timen er kommen, at Menneskens Søn skal herliggjøres."],[12,24,"Sandelig, sandelig siger jeg Eder: uden Hvedekornet falder i Jorden og døer, bliver det ene; men dersom det døer, bærer det megen Frugt.","Sandelig, sandelig siger jeg Eder: uden Hvedekornet falder i Jorden og døer, bliver det ene; men dersom det døer, bærer det megen Frugt."],[12,25,"Hvo som elsker sit Liv, skal miste det; og hvo som hader sit Liv i denne Verden, skal bevare det til et evigt Liv.","Hvo som elsker sit Liv, skal miste det; og hvo som hader sit Liv i denne Verden, skal bevare det til et evigt Liv."],[12,26,"Om Nogen tjener mig, han følge mig, og hvor jeg er, der skal og min Tjener være; og om Nogen tjener mig, ham skal Faderen ære.","Om Nogen tjener mig, han følge mig, og hvor jeg er, der skal og min Tjener være; og om Nogen tjener mig, ham skal Faderen ære."],[12,27,"Nu er min Sjæl forfærdet; og hvad skal jeg sige? Fader, frels mig fra denne Time! Dog derfor er jeg kommen til denne Time.","Nu er min Sjæl forfærdet; og hvad skal jeg sige? Fader, frels mig fra denne Time! Dog derfor er jeg kommen til denne Time."],[12,28,"Fader, herliggjør dit Navn! Da kom en Røst af Himmelen: baade haver jeg herliggjort, og vil atter herliggjøre det.","Fader, herliggjør dit Navn! Da kom en Røst af Himmelen: baade haver jeg herliggjort, og vil atter herliggjøre det."],[12,29,"Da sagde Folket, som stod og hørte det, at det havde tordnet; Andre sagde: en Engel talede til ham.","Da sagde Folket, som stod og hørte det, at det havde tordnet; Andre sagde: en Engel talede til ham."],[12,30,"Jesus svarede og sagde: denne Røst skete ikke for min Skyld, men for Eders Skyld.","Jesus svarede og sagde: denne Røst skete ikke for min Skyld, men for Eders Skyld."],[12,31,"Nu gaaer der Dom over denne Verden, nu skal denne Verdens Fyrste udstødes.","Nu gaaer der Dom over denne Verden, nu skal denne Verdens Fyrste udstødes."],[12,32,"Og jeg, naar jeg bliver ophøiet fra Jorden, vil jeg drage Alle til mig.","Og jeg, naar jeg bliver ophøiet fra Jorden, vil jeg drage Alle til mig."],[12,33,"(Men han sagde dette, for at betegne, hvad Død han skulle døe.)","(Men han sagde dette, for at betegne, hvad Død han skulle døe.)"],[12,34,"Folket svarede ham: vi have hørt af Loven, at Christus bliver evindeligen, og hvorledes siger du, at det bør Menneskens Søn at ophøies? hvo er denne Menneskens Søn?","Folket svarede ham: vi have hørt af Loven, at Christus bliver evindeligen, og hvorledes siger du, at det bør Menneskens Søn at ophøies? hvo er denne Menneskens Søn?"],[12,35,"Da sagde Jesus til dem: Lyset er endnu en liden Tid hos Eder. Vandrer, den Stund I have Lyset, at Mørket ikke skal overfalde Eder! Og hvo som vandrer i Mørket, veed ikke, hvor han gaaer hen.","Da sagde Jesus til dem: Lyset er endnu en liden Tid hos Eder. Vandrer, den Stund I have Lyset, at Mørket ikke skal overfalde Eder! Og hvo som vandrer i Mørket, veed ikke, hvor han gaaer hen."],[12,36,"Medens I have Lyset, troer paa Lyset, at I kunne blive Lysets Børn. Dette talede Jesus og gik bort og skjulte sig for dem.","Medens I have Lyset, troer paa Lyset, at I kunne blive Lysets Børn. Dette talede Jesus og gik bort og skjulte sig for dem."],[12,37,"Men alligevel han have gjort saa mange Tegn for deres Øine, troede de dog ikke paa ham,","Men alligevel han have gjort saa mange Tegn for deres Øine, troede de dog ikke paa ham,"],[12,38,"at Esaias den Prophets Tale skulde fuldkommes, som han har sagt: Herre! hvo troede det, han hørte af os, og for hvem er Herrens Arm aabenbaret?","at Esaias den Prophets Tale skulde fuldkommes, som han har sagt: Herre! hvo troede det, han hørte af os, og for hvem er Herrens Arm aabenbaret?"],[12,39,"Derfor kunde de ikke troe; thi Esaias siger atter:","Derfor kunde de ikke troe; thi Esaias siger atter:"],[12,40,"han haver forblindet deres Øine, og forhærdet deres Hjerter, at de ikke skulde see med Øinene, og forstaae med Hjertet og omvende sig, og jeg maatte helbrede dem.","han haver forblindet deres Øine, og forhærdet deres Hjerter, at de ikke skulde see med Øinene, og forstaae med Hjertet og omvende sig, og jeg maatte helbrede dem."],[12,41,"Dette sagde Esaias, der han saae hans Herlighed og talede om ham.","Dette sagde Esaias, der han saae hans Herlighed og talede om ham."],[12,42,"Dog alligevel troede mange ogsaa af de Øverste paa ham; men for Pharisæernes Skyld bekjendte de det ikke, at de ikke skulde blive udelukte af Synagogen;","Dog alligevel troede mange ogsaa af de Øverste paa ham; men for Pharisæernes Skyld bekjendte de det ikke, at de ikke skulde blive udelukte af Synagogen;"],[12,43,"thi de elskede Menneskens Ære mere end Guds Ære.","thi de elskede Menneskens Ære mere end Guds Ære."],[12,44,"Men Jesus raabte og sagde: hvo som troer paa mig, troer ikke paa mig, men paa den, som mig haver udsendt.","Men Jesus raabte og sagde: hvo som troer paa mig, troer ikke paa mig, men paa den, som mig haver udsendt."],[12,45,"Og hvo som seer mig, seer den, som mig haver udsendt.","Og hvo som seer mig, seer den, som mig haver udsendt."],[12,46,"Jeg er kommen et Lys til Verden, at hver den, som troer paa mig, ikke skal blive i Mørket.","Jeg er kommen et Lys til Verden, at hver den, som troer paa mig, ikke skal blive i Mørket."],[12,47,"Og om Nogen hører mine Ord, og troer ikke, han dømmer jeg ikke; thi jeg er ikke kommen for at dømme Verden, men for at frelse Verden.","Og om Nogen hører mine Ord, og troer ikke, han dømmer jeg ikke; thi jeg er ikke kommen for at dømme Verden, men for at frelse Verden."],[12,48,"Hvo mig foragter og annammer ikke mine Ord, haver den, som ham dømmer; det Ord, som jeg haver talet, det skal dømme ham paa den yderste Dag.","Hvo mig foragter og annammer ikke mine Ord, haver den, som ham dømmer; det Ord, som jeg haver talet, det skal dømme ham paa den yderste Dag."],[12,49,"Thi jeg haver ikke talet af mig selv; men Faderen, som mig haver udsendt, han haver givet mig Befaling, hvad jeg skal sige, og hvad jeg skal tale.","Thi jeg haver ikke talet af mig selv; men Faderen, som mig haver udsendt, han haver givet mig Befaling, hvad jeg skal sige, og hvad jeg skal tale."],[12,50,"Og jeg veed, at hans Befaling er et evigt Liv. Derfor, hvad jeg taler, taler jeg saaledes, som Faderen haver sagt mig.","Og jeg veed, at hans Befaling er et evigt Liv. Derfor, hvad jeg taler, taler jeg saaledes, som Faderen haver sagt mig."],[13,1,"Men for Paaskehøitiden, der Jesus vidste, at hans Time var kommen, at han skulde gaae ud af denne Verden til Faderen, da, som han havde elsket sine Egne, som vare i Verden, saa elskede han dem indtil Enden.","Men for Paaskehøitiden, der Jesus vidste, at hans Time var kommen, at han skulde gaae ud af denne Verden til Faderen, da, som han havde elsket sine Egne, som vare i Verden, saa elskede han dem indtil Enden."],[13,2,"Da nu Nadveren holdtes, og Djævelen allerede havde indskudt i Judas, Simon Søns, Ischariotes’ Hjerte, at han skulde forraade ham;","Da nu Nadveren holdtes, og Djævelen allerede havde indskudt i Judas, Simon Søns, Ischariotes’ Hjerte, at han skulde forraade ham;"],[13,3,"da Jesus vidste, at Faderen havde givet ham alle Ting i Hænder, og at han udkom fra Gud og gik hen til Gud:","da Jesus vidste, at Faderen havde givet ham alle Ting i Hænder, og at han udkom fra Gud og gik hen til Gud:"],[13,4,"reiste han sig fra Nadveren og lagde sine Klæder fra sig, og han tog et Linklæde og bandt op om sig.","reiste han sig fra Nadveren og lagde sine Klæder fra sig, og han tog et Linklæde og bandt op om sig."],[13,5,"Derefter slog han Vand i et Bækken og begyndte at toe Disciplenes Fødder og at tørre dem med Linklædet, som han var ombunden med.","Derefter slog han Vand i et Bækken og begyndte at toe Disciplenes Fødder og at tørre dem med Linklædet, som han var ombunden med."],[13,6,"Da kom han til Simon Peter, og han sagde til ham: Herre! toer du mine Fødder?","Da kom han til Simon Peter, og han sagde til ham: Herre! toer du mine Fødder?"],[13,7,"Jesus svarede og sagde til ham: hvad jeg gjør, veed du ikke nu, men du skal forstaae det herefter.","Jesus svarede og sagde til ham: hvad jeg gjør, veed du ikke nu, men du skal forstaae det herefter."],[13,8,"Peter siger til ham: du skal i Evighed ikke toe mine Fødder. Jesus svarede ham: dersom jeg ikke toer dig, haver du ingen Deel med mig.","Peter siger til ham: du skal i Evighed ikke toe mine Fødder. Jesus svarede ham: dersom jeg ikke toer dig, haver du ingen Deel med mig."],[13,9,"Simon Peter siger til ham: Herre ikke mine Fødder alene, men ogsaa Hænderne og Hovedet.","Simon Peter siger til ham: Herre ikke mine Fødder alene, men ogsaa Hænderne og Hovedet."],[13,10,"Jesus siger til ham: hvo som er toet, haver ikke behov uden at toe Fødderne, men er ganske reen; og I ere rene, men ikke alle.","Jesus siger til ham: hvo som er toet, haver ikke behov uden at toe Fødderne, men er ganske reen; og I ere rene, men ikke alle."],[13,11,"Thi han kjendte den, som ham forraadte; derfor sagde han: I ere ikke alle rene.","Thi han kjendte den, som ham forraadte; derfor sagde han: I ere ikke alle rene."],[13,12,"Der han da havde toet deres Fødder og havde taget sine Klæder, satte han sig atter ned og sagde til dem: vide I, hvad jeg haver gjort Eder?","Der han da havde toet deres Fødder og havde taget sine Klæder, satte han sig atter ned og sagde til dem: vide I, hvad jeg haver gjort Eder?"],[13,13,"I kalde mig Mester og Herre, og I tale ret, thi jeg er det.","I kalde mig Mester og Herre, og I tale ret, thi jeg er det."],[13,14,"Dersom da jeg, Herren og Mesteren, haver toet Eders Fødder, saa ere I og skyldige at toe hverandres Fødder.","Dersom da jeg, Herren og Mesteren, haver toet Eders Fødder, saa ere I og skyldige at toe hverandres Fødder."],[13,15,"Thi jeg haver givet Eder et Exempel, at ligesom jeg gjorde Eder, skulle og I gjøre.","Thi jeg haver givet Eder et Exempel, at ligesom jeg gjorde Eder, skulle og I gjøre."],[13,16,"Sandelig, sandelig siger jeg Eder: en Tjener er ikke større end hans Herre, ikke heller et Sendebud større end den, ham haver sendt.","Sandelig, sandelig siger jeg Eder: en Tjener er ikke større end hans Herre, ikke heller et Sendebud større end den, ham haver sendt."],[13,17,"Dersom I vide dette, ere I salige, om I gjøre det.","Dersom I vide dette, ere I salige, om I gjøre det."],[13,18,"Jeg taler ikke om Eder alle, jeg veed, hvilke jeg haver udvalgt; men Skriften maa fuldkommes: den, som æder Brødet med mig, haver opløftet sin Hæl mod mig.","Jeg taler ikke om Eder alle, jeg veed, hvilke jeg haver udvalgt; men Skriften maa fuldkommes: den, som æder Brødet med mig, haver opløftet sin Hæl mod mig."],[13,19,"Fra nu af siger jeg Eder det, førend det skeer, at, naar det er skeet, I skulle troe, at det er mig.","Fra nu af siger jeg Eder det, førend det skeer, at, naar det er skeet, I skulle troe, at det er mig."],[13,20,"Sandelig, sandelig siger jeg Eder: hvo som annammer den, som jeg sender, annammer mig; men hvo mig annammer, annammer den, som haver sendt mig.","Sandelig, sandelig siger jeg Eder: hvo som annammer den, som jeg sender, annammer mig; men hvo mig annammer, annammer den, som haver sendt mig."],[13,21,"Der Jesus havde sagt dette, blev han heftig bevæget i Aanden, og vidnede og sagde: sandelig, sandelig siger jeg Eder, at een af Eder skal forraade mig.","Der Jesus havde sagt dette, blev han heftig bevæget i Aanden, og vidnede og sagde: sandelig, sandelig siger jeg Eder, at een af Eder skal forraade mig."],[13,22,"Da saae Disciplene paa hverandre, tvivlraadige, om hvem han talede.","Da saae Disciplene paa hverandre, tvivlraadige, om hvem han talede."],[13,23,"Men der var een iblandt hans Disciple, som laae op til Jesu Skjød, hvem Jesus elskede.","Men der var een iblandt hans Disciple, som laae op til Jesu Skjød, hvem Jesus elskede."],[13,24,"Til denne nikkede derfor Simon Peter, at han skulde udspørge, hvo det maatte vare, han talede om?","Til denne nikkede derfor Simon Peter, at han skulde udspørge, hvo det maatte vare, han talede om?"],[13,25,"Men denne bøiede sig op til Jesu Bryst, og sagde til ham: Herre! hvo er det?","Men denne bøiede sig op til Jesu Bryst, og sagde til ham: Herre! hvo er det?"],[13,26,"Jesus svarede: det er den, hvilken jeg giver det Stykke, som jeg dypper. Og han dyppede Stykket, og gav Judas, Simons Søn, Ischariotes det.","Jesus svarede: det er den, hvilken jeg giver det Stykke, som jeg dypper. Og han dyppede Stykket, og gav Judas, Simons Søn, Ischariotes det."],[13,27,"Og efterat han havde faaet Stykket, da gik Satan ind i ham. Da sagde Jesus til ham: hvad du gjør, det gjør snart!","Og efterat han havde faaet Stykket, da gik Satan ind i ham. Da sagde Jesus til ham: hvad du gjør, det gjør snart!"],[13,28,"Men ingen af dem, som sadde tilbords, forstod, til hvad Ende han sagde ham det.","Men ingen af dem, som sadde tilbords, forstod, til hvad Ende han sagde ham det."],[13,29,"Thi Nogle meente, efterdi Judas havde Pungen, at Jesus sagde til ham: kjøb, hvad vi havde behov til Høitiden; eller at han skulde give Noget til Fattige.","Thi Nogle meente, efterdi Judas havde Pungen, at Jesus sagde til ham: kjøb, hvad vi havde behov til Høitiden; eller at han skulde give Noget til Fattige."],[13,30,"Der han da havde taget Stykket, gik han strax ud; men det var Nat.","Der han da havde taget Stykket, gik han strax ud; men det var Nat."],[13,31,"Der han da var udgangen, sagde Jesus: nu er Menneskens Søn herliggjort, og Gud er herliggjort i ham.","Der han da var udgangen, sagde Jesus: nu er Menneskens Søn herliggjort, og Gud er herliggjort i ham."],[13,32,"Dersom Gud er herliggjort i ham, skal Gud og herliggjøre ham i sig selv, og han skal snart herliggjøre ham.","Dersom Gud er herliggjort i ham, skal Gud og herliggjøre ham i sig selv, og han skal snart herliggjøre ham."],[13,33,"Børnlille! jeg er endnu lidet hos Eder. I skulle lede efter mig, og ligesom jeg sagde til Jøderne: hvor jeg gaaer hen, kunne I ikke komme, siger jeg og Eder nu.","Børnlille! jeg er endnu lidet hos Eder. I skulle lede efter mig, og ligesom jeg sagde til Jøderne: hvor jeg gaaer hen, kunne I ikke komme, siger jeg og Eder nu."],[13,34,"Jeg giver Eder en ny Befaling, at I skulle elske hverandre; som jeg elskede Eder, at I og skulle elske hverandre.","Jeg giver Eder en ny Befaling, at I skulle elske hverandre; som jeg elskede Eder, at I og skulle elske hverandre."],[13,35,"Derpaa skulle Alle kjende, at I ere mine Disciple, dersom I have indbyrdes Kjærlighed.","Derpaa skulle Alle kjende, at I ere mine Disciple, dersom I have indbyrdes Kjærlighed."],[13,36,"Simon Peter sagde til ham: Herre! hvor gaaer du hen? Jesus svarede ham: hvor jeg gaaer hen, kan du ikke nu følge mig; men siden skal du følge mig.","Simon Peter sagde til ham: Herre! hvor gaaer du hen? Jesus svarede ham: hvor jeg gaaer hen, kan du ikke nu følge mig; men siden skal du følge mig."],[13,37,"Peter siger til ham: Herre! hvorfor kan jeg ikke følge dig nu? Jeg vil sætte mit Liv til for dig.","Peter siger til ham: Herre! hvorfor kan jeg ikke følge dig nu? Jeg vil sætte mit Liv til for dig."],[13,38,"Jesus svarede ham: vil du sætte dit Liv til for mig? Sandelig, sandelig siger jeg dig: Hanen skal ikke gale, førend du skal fornegte mig tre Gange.","Jesus svarede ham: vil du sætte dit Liv til for mig? Sandelig, sandelig siger jeg dig: Hanen skal ikke gale, førend du skal fornegte mig tre Gange."],[14,1,"Eders Hjerte forfærdes ikke; troer paa Gud, og troer paa mig!","Eders Hjerte forfærdes ikke; troer paa Gud, og troer paa mig!"],[14,2,"I min Faders Huus ere mange Boliger; men dersom det ikke saa var, havde jeg sagt Eder det. Jeg gaaer bort, at berede Eder Sted.","I min Faders Huus ere mange Boliger; men dersom det ikke saa var, havde jeg sagt Eder det. Jeg gaaer bort, at berede Eder Sted."],[14,3,"Og naar jeg er gaaet bort, og faaer beredt Eder sted, kommer jeg igjen og vil tage Eder til mig, at hvor jeg er, skulle ogsaa I være.","Og naar jeg er gaaet bort, og faaer beredt Eder sted, kommer jeg igjen og vil tage Eder til mig, at hvor jeg er, skulle ogsaa I være."],[14,4,"Og hvor jeg gaaer hen, vide I, og Veien vide I.","Og hvor jeg gaaer hen, vide I, og Veien vide I."],[14,5,"Thomas siger til ham: Herre! vi vide ikke, hvor du gaaer hen; og hvorledes kunne vi vide Veien?","Thomas siger til ham: Herre! vi vide ikke, hvor du gaaer hen; og hvorledes kunne vi vide Veien?"],[14,6,"Jesus siger til ham: jeg er Veien, og Sandheden, og Livet; der kommer Ingen til Faderen uden ved mig.","Jesus siger til ham: jeg er Veien, og Sandheden, og Livet; der kommer Ingen til Faderen uden ved mig."],[14,7,"Havde I kjendt mig, da havde I og kjendt min Fader; og fra nu af kjende I ham, og have seet ham.","Havde I kjendt mig, da havde I og kjendt min Fader; og fra nu af kjende I ham, og have seet ham."],[14,8,"Philippus siger til ham: Herre! viis os Faderen, og det er os nok.","Philippus siger til ham: Herre! viis os Faderen, og det er os nok."],[14,9,"Jesus siger til ham: saa lang en Tid er jeg hos Eder, og du haver ikke kjendt mig, Philippus? Hvo mig haver seet, haver seet Faderen; hvorledes siger du da: viis os Faderen?","Jesus siger til ham: saa lang en Tid er jeg hos Eder, og du haver ikke kjendt mig, Philippus? Hvo mig haver seet, haver seet Faderen; hvorledes siger du da: viis os Faderen?"],[14,10,"Troer du ikke, at jeg er i Faderen, og Faderen er i mig? De Ord, som jeg taler til Eder, taler jeg ikke af mig selv; men Faderen, som bliver i mig, han gjør Gjerningerne.","Troer du ikke, at jeg er i Faderen, og Faderen er i mig? De Ord, som jeg taler til Eder, taler jeg ikke af mig selv; men Faderen, som bliver i mig, han gjør Gjerningerne."],[14,11,"Troer mig, at jeg er i Faderen, og Faderen er i mig; men ville I ikke, saa troer mig dog for disse Gjerningers Skyld.","Troer mig, at jeg er i Faderen, og Faderen er i mig; men ville I ikke, saa troer mig dog for disse Gjerningers Skyld."],[14,12,"Sandelig, sandelig siger jeg Eder: hvo som troer paa mig, de Gjerninger, som jeg gjør, skal og han gjøre, og han skal gjøre større end disse; thi jeg gaaer til min Fader.","Sandelig, sandelig siger jeg Eder: hvo som troer paa mig, de Gjerninger, som jeg gjør, skal og han gjøre, og han skal gjøre større end disse; thi jeg gaaer til min Fader."],[14,13,"Og hvadsomhelst I bede om i mit Navn, det vil jeg gjøre, at Faderen maa forherliges ved Sønnen.","Og hvadsomhelst I bede om i mit Navn, det vil jeg gjøre, at Faderen maa forherliges ved Sønnen."],[14,14,"Dersom I bede om Noget i mit Navn, vil jeg gjøre det.","Dersom I bede om Noget i mit Navn, vil jeg gjøre det."],[14,15,"Dersom I elske mig, da holder mine Befalinger.","Dersom I elske mig, da holder mine Befalinger."],[14,16,"Og jeg vil bede Faderen, og han skal give Eder en anden Talsmand, at han skal blive hos Eder evindeligen,","Og jeg vil bede Faderen, og han skal give Eder en anden Talsmand, at han skal blive hos Eder evindeligen,"],[14,17,"den Sandheds Aand, hvilken Verden ikke kan annamme, thi den seer han ikke, kjender ham ei heller; men I kjende ham, thi han bliver hos Eder, og skal være i Eder.","den Sandheds Aand, hvilken Verden ikke kan annamme, thi den seer han ikke, kjender ham ei heller; men I kjende ham, thi han bliver hos Eder, og skal være i Eder."],[14,18,"Jeg vil ikke forlade Eder faderløse; jeg kommer til Eder.","Jeg vil ikke forlade Eder faderløse; jeg kommer til Eder."],[14,19,"Endnu et Lidet, og Verden seer mig ikke mere, men I see mig; thi jeg lever, og I skulle leve.","Endnu et Lidet, og Verden seer mig ikke mere, men I see mig; thi jeg lever, og I skulle leve."],[14,20,"Paa den Dag skulle I kjende, at jeg er i min Fader, og I udi mig, og jeg i Eder.","Paa den Dag skulle I kjende, at jeg er i min Fader, og I udi mig, og jeg i Eder."],[14,21,"Hvo som haver mine Befalinger, og holder dem, han er den, som mig elsker; men hvo mig elsker, skal elskes af min Fader; og jeg skal elske ham og aabenbare mig for ham.","Hvo som haver mine Befalinger, og holder dem, han er den, som mig elsker; men hvo mig elsker, skal elskes af min Fader; og jeg skal elske ham og aabenbare mig for ham."],[14,22,"Judas (ikke Ischariotes) siger til ham: Herre! hvor kommer det, at du vil aabenbare dig for os, og ikke for Verden?","Judas (ikke Ischariotes) siger til ham: Herre! hvor kommer det, at du vil aabenbare dig for os, og ikke for Verden?"],[14,23,"Jesus svarede og sagde til ham: om Nogen elsker mig, skal han holde mit Ord; og min Fader skal elske ham, og vi skulle komme til ham, og tage Bolig hos ham.","Jesus svarede og sagde til ham: om Nogen elsker mig, skal han holde mit Ord; og min Fader skal elske ham, og vi skulle komme til ham, og tage Bolig hos ham."],[14,24,"Hvo mig ikke elsker, holder ikke mine Ord; og det Ord, som I høre, er ikke mit, men Faderens, som mig haver udsendt.","Hvo mig ikke elsker, holder ikke mine Ord; og det Ord, som I høre, er ikke mit, men Faderens, som mig haver udsendt."],[14,25,"Dette haver jeg talet til Eder, medens jeg blev hos Eder.","Dette haver jeg talet til Eder, medens jeg blev hos Eder."],[14,26,"Men Talsmanden, den Hellig Aand, hvilken Faderen skal sende i mit Navn, skal lære Eder alle Ting, og minde Eder paa alle Ting, som jeg haver sagt Eder.","Men Talsmanden, den Hellig Aand, hvilken Faderen skal sende i mit Navn, skal lære Eder alle Ting, og minde Eder paa alle Ting, som jeg haver sagt Eder."],[14,27,"Fred lader jeg Eder, min Fred giver jeg Eder; jeg giver Eder ikke, som Verden giver. Eders Hjerte forfærdes ikke og forsage ikke.","Fred lader jeg Eder, min Fred giver jeg Eder; jeg giver Eder ikke, som Verden giver. Eders Hjerte forfærdes ikke og forsage ikke."],[14,28,"I have hørt, at jeg sagde til Eder: jeg gaaer bort og kommer til Eder igjen; dersom I havde mig kjær, da glædede I Eder, at jeg sagde: jeg gaaer til Faderen; thi min Fader er større end jeg.","I have hørt, at jeg sagde til Eder: jeg gaaer bort og kommer til Eder igjen; dersom I havde mig kjær, da glædede I Eder, at jeg sagde: jeg gaaer til Faderen; thi min Fader er større end jeg."],[14,29,"Og nu haver jeg sagt Eder det, før det skeer, at, naar det er skeet, I da skulle troe.","Og nu haver jeg sagt Eder det, før det skeer, at, naar det er skeet, I da skulle troe."],[14,30,"Jeg skal herefter ikke tale Meget med Eder; thi denne Verdens Fyrste kommer, og haver slet intet i mig.","Jeg skal herefter ikke tale Meget med Eder; thi denne Verdens Fyrste kommer, og haver slet intet i mig."],[14,31,"Men paa det Verden skal kjende, at jeg elsker Faderen, og ligesom Faderen haver befalet mig, saa gjør jeg; staaer op, lader os gaae herfra.","Men paa det Verden skal kjende, at jeg elsker Faderen, og ligesom Faderen haver befalet mig, saa gjør jeg; staaer op, lader os gaae herfra."],[15,1,"Jeg er det sande Viintræ, og min Fader er Viingaardsmanden.","Jeg er det sande Viintræ, og min Fader er Viingaardsmanden."],[15,2,"Hver Green paa mig, som ikke bærer Frugt, den borttager han, og hver den, som bærer Frugt, renser han, at den skal bære mere Frugt.","Hver Green paa mig, som ikke bærer Frugt, den borttager han, og hver den, som bærer Frugt, renser han, at den skal bære mere Frugt."],[15,3,"I ere allerede rene formedelst det Ord, som jeg haver talet til Eder.","I ere allerede rene formedelst det Ord, som jeg haver talet til Eder."],[15,4,"Bliver i mig, da bliver og jeg i Eder. Ligesom Grenen ikke kan bære Frugt af sig selv, uden den bliver i Træet, saa kunne I ikke heller, uden I blive i mig.","Bliver i mig, da bliver og jeg i Eder. Ligesom Grenen ikke kan bære Frugt af sig selv, uden den bliver i Træet, saa kunne I ikke heller, uden I blive i mig."],[15,5,"Jeg er Viintræet, I ere Grenene. Hvo som bliver i mig, og jeg i ham, han bærer megen Frugt; thi uden mig kunne I slet Intet gjøre.","Jeg er Viintræet, I ere Grenene. Hvo som bliver i mig, og jeg i ham, han bærer megen Frugt; thi uden mig kunne I slet Intet gjøre."],[15,6,"Om Nogen ikke bliver i mig, han bliver udkastet som en Green, og visner; man sanker dem, og kaster dem i Ilden, og de brænde.","Om Nogen ikke bliver i mig, han bliver udkastet som en Green, og visner; man sanker dem, og kaster dem i Ilden, og de brænde."],[15,7,"Dersom I blive i mig og mine Ord blive i Eder, da beder om hvadsomhelst I ville, og det skal vederfares Eder.","Dersom I blive i mig og mine Ord blive i Eder, da beder om hvadsomhelst I ville, og det skal vederfares Eder."],[15,8,"Derudi forherliges min Fader, at I bære megen Frugt, og I skulle vorde mine Disciple.","Derudi forherliges min Fader, at I bære megen Frugt, og I skulle vorde mine Disciple."],[15,9,"Ligesom Faderen haver elsket mig, saa haver jeg og elsket Eder; bliver i min Kjærlighed!","Ligesom Faderen haver elsket mig, saa haver jeg og elsket Eder; bliver i min Kjærlighed!"],[15,10,"Dersom I holde mine Befalinger, skulle I blive i min Kjærlighed, ligesom jeg haver holdt min Faders Befalinger, og bliver i hans Kjærlighed.","Dersom I holde mine Befalinger, skulle I blive i min Kjærlighed, ligesom jeg haver holdt min Faders Befalinger, og bliver i hans Kjærlighed."],[15,11,"Dette haver jeg talet til Eder, paa det min Glæde kan blive i Eder, og Eders Glæde kan blive fuldkommen.","Dette haver jeg talet til Eder, paa det min Glæde kan blive i Eder, og Eders Glæde kan blive fuldkommen."],[15,12,"Denne er min Befaling, at I skulle elske hverandre, ligesom jeg haver elsket Eder.","Denne er min Befaling, at I skulle elske hverandre, ligesom jeg haver elsket Eder."],[15,13,"Ingen haver større Kjærlighed end denne, at En sætter sit Liv til for sine Venner.","Ingen haver større Kjærlighed end denne, at En sætter sit Liv til for sine Venner."],[15,14,"I ere mine Venner, dersom I gjøre, hvad jeg befaler Eder.","I ere mine Venner, dersom I gjøre, hvad jeg befaler Eder."],[15,15,"Jeg kalder Eder ikke længere Tjenere; thi Tjeneren veed ikke, hvad hans Herre gjør; men Eder haver jeg kaldet Venner; thi alt det, som jeg haver hørt af min Fader, haver jeg kundgjort Eder.","Jeg kalder Eder ikke længere Tjenere; thi Tjeneren veed ikke, hvad hans Herre gjør; men Eder haver jeg kaldet Venner; thi alt det, som jeg haver hørt af min Fader, haver jeg kundgjort Eder."],[15,16,"I have ikke udvalgt mig, men jeg haver udvalgt Eder og sat Eder, at I skulle gaae hen og bære Frugt, og Eders Frugt skal blive ved; at hvadsomhelst I bede Faderen i mit Navn, skal han give Eder.","I have ikke udvalgt mig, men jeg haver udvalgt Eder og sat Eder, at I skulle gaae hen og bære Frugt, og Eders Frugt skal blive ved; at hvadsomhelst I bede Faderen i mit Navn, skal han give Eder."],[15,17,"Dette befaler jeg Eder, at I skulle elske hverandre.","Dette befaler jeg Eder, at I skulle elske hverandre."],[15,18,"Dersom Verden hader Eder, da vider, at den haver hadet mig førend Eder.","Dersom Verden hader Eder, da vider, at den haver hadet mig førend Eder."],[15,19,"Vare I af Verden, da vilde Verden elske sit Eget; men efterdi I ikke ere af Verden, men jeg haver udvalgt Eder af Verden, derfor hader Verden Eder.","Vare I af Verden, da vilde Verden elske sit Eget; men efterdi I ikke ere af Verden, men jeg haver udvalgt Eder af Verden, derfor hader Verden Eder."],[15,20,"Kommer det Ord ihu, som jeg sagde Eder: en Tjener er ikke større end hans Herre. Have de forfulgt mig, skulle de og forfølge Eder; have de holdt mit Ord, skulle de og holde Eders.","Kommer det Ord ihu, som jeg sagde Eder: en Tjener er ikke større end hans Herre. Have de forfulgt mig, skulle de og forfølge Eder; have de holdt mit Ord, skulle de og holde Eders."],[15,21,"Men alt dette skulle de gjøre Eder for mit Navns Skyld, fordi de ikke kjende den, som mig haver udsendt.","Men alt dette skulle de gjøre Eder for mit Navns Skyld, fordi de ikke kjende den, som mig haver udsendt."],[15,22,"Dersom jeg ikke var kommen og havde talet til dem, havde de ikke Synd; men nu have de end ikke et Paaskud for deres Synd.","Dersom jeg ikke var kommen og havde talet til dem, havde de ikke Synd; men nu have de end ikke et Paaskud for deres Synd."],[15,23,"Hvo mig hader, hader og min Fader.","Hvo mig hader, hader og min Fader."],[15,24,"Havde jeg ikke gjort de Gjerninger iblandt dem, som ingen Anden haver gjort, havde de ikke Synd; men nu have de seet dem, og dog hadet baade mig og min Fader.","Havde jeg ikke gjort de Gjerninger iblandt dem, som ingen Anden haver gjort, havde de ikke Synd; men nu have de seet dem, og dog hadet baade mig og min Fader."],[15,25,"Dog, de Ord, som ere skrevne i deres Lov, maa fuldkommes: de hadede mig uforskyldt.","Dog, de Ord, som ere skrevne i deres Lov, maa fuldkommes: de hadede mig uforskyldt."],[15,26,"Men naar Talsmanden kommer, hvilken jeg skal sende Eder fra Faderen, (den Sandheds Aand, som udgaaer fra Faderen), han skal vidne om mig.","Men naar Talsmanden kommer, hvilken jeg skal sende Eder fra Faderen, (den Sandheds Aand, som udgaaer fra Faderen), han skal vidne om mig."],[15,27,"Men ogsaa I skulle vidne; thi I vare med mig fra Begyndelsen.","Men ogsaa I skulle vidne; thi I vare med mig fra Begyndelsen."],[16,1,"Dette haver jeg talet til Eder, at I skulle ikke forarges.","Dette haver jeg talet til Eder, at I skulle ikke forarges."],[16,2,"De skulle udelukke Eder af Synagogerne, ja den Tid skal komme, at hver den, som ihjelslaaer Eder, skal mene, han viser Gud en Dyrkelse.","De skulle udelukke Eder af Synagogerne, ja den Tid skal komme, at hver den, som ihjelslaaer Eder, skal mene, han viser Gud en Dyrkelse."],[16,3,"Og dette skulle de gjøre Eder, fordi de hverken kjende Faderen, ei heller mig.","Og dette skulle de gjøre Eder, fordi de hverken kjende Faderen, ei heller mig."],[16,4,"Men dette haver jeg talet til Eder, paa det naar Timen kommer, I skulle komme ihu, at jeg sagde Eder det; men dette sagde jeg Eder ikke fra Begyndelsen, fordi jeg var hos Eder.","Men dette haver jeg talet til Eder, paa det naar Timen kommer, I skulle komme ihu, at jeg sagde Eder det; men dette sagde jeg Eder ikke fra Begyndelsen, fordi jeg var hos Eder."],[16,5,"Men nu gaaer jeg hen til den, som mig udsendte, og ingen af Eder spørger mig: hvor gaaer du hen?","Men nu gaaer jeg hen til den, som mig udsendte, og ingen af Eder spørger mig: hvor gaaer du hen?"],[16,6,"Men fordi jeg haver talet dette til Eder, haver Bedrøvelse opfyldt Eders Hjerte.","Men fordi jeg haver talet dette til Eder, haver Bedrøvelse opfyldt Eders Hjerte."],[16,7,"Men jeg siger Eder Sandhed: det er Eder gavnligt, at jeg gaaer bort, thi gaaer jeg ikke bort, skal Talsmanden ikke komme til Eder; men gaaer jeg bort saa vil jeg sende ham til Eder.","Men jeg siger Eder Sandhed: det er Eder gavnligt, at jeg gaaer bort, thi gaaer jeg ikke bort, skal Talsmanden ikke komme til Eder; men gaaer jeg bort saa vil jeg sende ham til Eder."],[16,8,"Og naar han kommer, skal han overbevise Verden og Synd og om Retfærdighed og om Dom.","Og naar han kommer, skal han overbevise Verden og Synd og om Retfærdighed og om Dom."],[16,9,"Om Synd, fordi de troe ikke paa mig;","Om Synd, fordi de troe ikke paa mig;"],[16,10,"men om Retfærdighed, fordi jeg gaaer hen til min Fader, og I see mig ikke længere;","men om Retfærdighed, fordi jeg gaaer hen til min Fader, og I see mig ikke længere;"],[16,11,"men om Dom, fordi denne Verdens Fyrste er dømt.","men om Dom, fordi denne Verdens Fyrste er dømt."],[16,12,"Jeg haver endnu Meget at sige Eder; men nu kunne I ikke bære det.","Jeg haver endnu Meget at sige Eder; men nu kunne I ikke bære det."],[16,13,"Men naar han, den Sandheds Aand, kommer, skal han veilede Eder til al Sandhed; thi han skal ikke tale af sig selv, men hvadsomhelst han hører, skal han tale, og de tilkommende Ting skal han forkynde Eder.","Men naar han, den Sandheds Aand, kommer, skal han veilede Eder til al Sandhed; thi han skal ikke tale af sig selv, men hvadsomhelst han hører, skal han tale, og de tilkommende Ting skal han forkynde Eder."],[16,14,"Han skal herliggjøre mig; thi han skal tage af Mit og forkynde Eder.","Han skal herliggjøre mig; thi han skal tage af Mit og forkynde Eder."],[16,15,"Alt hvad Faderen haver, er Mit; derfor sagde jeg, at han skal tage af Mit og forkynde Eder.","Alt hvad Faderen haver, er Mit; derfor sagde jeg, at han skal tage af Mit og forkynde Eder."],[16,16,"Om en liden Stund skulle I ikke see mig, og atter om en liden Stund skulle I see mig; thi jeg gaaer hen til Faderen.","Om en liden Stund skulle I ikke see mig, og atter om en liden Stund skulle I see mig; thi jeg gaaer hen til Faderen."],[16,17,"Da sagde nogle af hans Disciple til hverandre: hvad er dette, som han siger os: om en liden Stund skulle I ikke see mig, og atter om en liden Stund skulle I see mig, og: thi jeg gaaer hen til Faderen?","Da sagde nogle af hans Disciple til hverandre: hvad er dette, som han siger os: om en liden Stund skulle I ikke see mig, og atter om en liden Stund skulle I see mig, og: thi jeg gaaer hen til Faderen?"],[16,18,"Da sagde de: hvad er det, som han siger: om en liden Stund? Vi forstaae ikke, hvad han taler.","Da sagde de: hvad er det, som han siger: om en liden Stund? Vi forstaae ikke, hvad han taler."],[16,19,"Da vidste Jesus, at de vilde spørge ham, og han sagde til dem: derom bespørge I Eder indbyrdes, at jeg sagde: om en liden Stund skulle I ikke see mig, og atter om en liden Stund skulle I see mig.","Da vidste Jesus, at de vilde spørge ham, og han sagde til dem: derom bespørge I Eder indbyrdes, at jeg sagde: om en liden Stund skulle I ikke see mig, og atter om en liden Stund skulle I see mig."],[16,20,"Sandelig, sandelig siger jeg Eder: I skulle græde og hyle, men Verden skal glæde sig; I skulle være bedrøvede, men Eders Bedrøvelse skal vorde til Glæde.","Sandelig, sandelig siger jeg Eder: I skulle græde og hyle, men Verden skal glæde sig; I skulle være bedrøvede, men Eders Bedrøvelse skal vorde til Glæde."],[16,21,"Kvinden, naar hun føder, haver Bedrøvelse, fordi hendes Time er kommen; men naar hun haver født Barnet, kommer hun ikke mere den Trængsel ihu for Glæde, at et Menneske er født til Verden.","Kvinden, naar hun føder, haver Bedrøvelse, fordi hendes Time er kommen; men naar hun haver født Barnet, kommer hun ikke mere den Trængsel ihu for Glæde, at et Menneske er født til Verden."],[16,22,"Ogsaa I have da vel nu Bedrøvelse; men jeg vil see Eder igjen, og Eders Hjerte skal glædes, og Ingen tager Eders Glæde fra Eder.","Ogsaa I have da vel nu Bedrøvelse; men jeg vil see Eder igjen, og Eders Hjerte skal glædes, og Ingen tager Eders Glæde fra Eder."],[16,23,"Og paa den samme Dag skulle I ikke spørge mig om Noget. Sandelig, sandelig siger jeg Eder, at hvadsomhelst I bede Faderen om i mit Navn, skal han give Eder.","Og paa den samme Dag skulle I ikke spørge mig om Noget. Sandelig, sandelig siger jeg Eder, at hvadsomhelst I bede Faderen om i mit Navn, skal han give Eder."],[16,24,"Hidindtil have I ikke bedet om Noget i mit Navn; beder, og I skulle faae, at Eders Glæde maa blive fuldkommen.","Hidindtil have I ikke bedet om Noget i mit Navn; beder, og I skulle faae, at Eders Glæde maa blive fuldkommen."],[16,25,"Dette haver jeg talet til Eder ved Lignelser; men den Time kommer, da jeg ikke mere skal tale med Eder ved Lignelser; men den Time kommer, da jeg ikke mere skal tale med Eder ved Lignelser, men frit ud forkynde Eder om min Fader.","Dette haver jeg talet til Eder ved Lignelser; men den Time kommer, da jeg ikke mere skal tale med Eder ved Lignelser; men den Time kommer, da jeg ikke mere skal tale med Eder ved Lignelser, men frit ud forkynde Eder om min Fader."],[16,26,"Paa den samme Dag skulle I bede i mit Navn, og jeg siger Eder ikke, at jeg vil bede Faderen for Eder;","Paa den samme Dag skulle I bede i mit Navn, og jeg siger Eder ikke, at jeg vil bede Faderen for Eder;"],[16,27,"thi Faderen selv elsker Eder, efterdi I have elsket mig og troet, at jeg er udgangen fra Gud.","thi Faderen selv elsker Eder, efterdi I have elsket mig og troet, at jeg er udgangen fra Gud."],[16,28,"Jeg udgik fra Faderen og kom til Verden; jeg forlader Verden igjen og gaaer til Faderen.","Jeg udgik fra Faderen og kom til Verden; jeg forlader Verden igjen og gaaer til Faderen."],[16,29,"Hans Disciple sige til ham: see, nu taler du frit ud og siger ingen Lignelse.","Hans Disciple sige til ham: see, nu taler du frit ud og siger ingen Lignelse."],[16,30,"Nu vide vi, at du veed alle Ting og haver ikke behov, at Nogen spørger dig; desaarsag troe vi, at du udgik fra Gud.","Nu vide vi, at du veed alle Ting og haver ikke behov, at Nogen spørger dig; desaarsag troe vi, at du udgik fra Gud."],[16,31,"Jesus svarede dem: nu troe I!","Jesus svarede dem: nu troe I!"],[16,32,"See, den Time kommer og er allerede kommen, at I skulle adspredes hver til Sit, og forlade mig alene; dog jeg er ikke alene, thi Faderen er med mig.","See, den Time kommer og er allerede kommen, at I skulle adspredes hver til Sit, og forlade mig alene; dog jeg er ikke alene, thi Faderen er med mig."],[16,33,"Dette haver jeg talet til Eder, paa det I skulle have Fred i mig. I Verden skulle I have Trængsel; men værer frimodige, jeg haver overvundet Verden.","Dette haver jeg talet til Eder, paa det I skulle have Fred i mig. I Verden skulle I have Trængsel; men værer frimodige, jeg haver overvundet Verden."],[17,1,"Dette talede Jesus, og opløftede sine Øine til Himmelen og sagde: Fader! Timen er kommen; herliggjør din Søn, at ogsaa din Søn maa herliggjøre dig.","Dette talede Jesus, og opløftede sine Øine til Himmelen og sagde: Fader! Timen er kommen; herliggjør din Søn, at ogsaa din Søn maa herliggjøre dig."],[17,2,"Ligesom du haver givet ham Magt over alt Kjød, paa det han maa give alle dem, som du haver givet ham, et evigt Liv.","Ligesom du haver givet ham Magt over alt Kjød, paa det han maa give alle dem, som du haver givet ham, et evigt Liv."],[17,3,"Men dette er det evige Liv, at de kjende dig, den eneste sande Gud, og den, du udsendte, Jesus Christus.","Men dette er det evige Liv, at de kjende dig, den eneste sande Gud, og den, du udsendte, Jesus Christus."],[17,4,"Jeg haver herliggjort dig paa Jorden; jeg haver fuldkommet den Gjerning, som du haver givet mig at gjøre.","Jeg haver herliggjort dig paa Jorden; jeg haver fuldkommet den Gjerning, som du haver givet mig at gjøre."],[17,5,"Herliggjør du mig og nu, Fader! hos dig selv med den Herlighed, som jeg havde hos dig, før Verden var.","Herliggjør du mig og nu, Fader! hos dig selv med den Herlighed, som jeg havde hos dig, før Verden var."],[17,6,"Jeg haver aabenbaret dit Navn for de Mennesker, hvilke du haver givet mig af Verden; de vare dine, og du haver givet mig dem, og de have bevaret dit Ord.","Jeg haver aabenbaret dit Navn for de Mennesker, hvilke du haver givet mig af Verden; de vare dine, og du haver givet mig dem, og de have bevaret dit Ord."],[17,7,"Nu vide de, at alt det, som du haver givet mig, er af dig.","Nu vide de, at alt det, som du haver givet mig, er af dig."],[17,8,"Thi de Ord, som du haver givet mig, haver jeg givet dem; og de have annammet dem og kjendt i Sandhed, at jeg udgik fra dig, og de have troet, at du haver udsendt mig.","Thi de Ord, som du haver givet mig, haver jeg givet dem; og de have annammet dem og kjendt i Sandhed, at jeg udgik fra dig, og de have troet, at du haver udsendt mig."],[17,9,"Jeg beder for dem; jeg beder ikke for Verden, men for dem, som du haver givet mig; thi de ere dine.","Jeg beder for dem; jeg beder ikke for Verden, men for dem, som du haver givet mig; thi de ere dine."],[17,10,"Og alt det, som mit er, det er dit, og det, som dit er, det er mit; og jeg er herliggjort i dem.","Og alt det, som mit er, det er dit, og det, som dit er, det er mit; og jeg er herliggjort i dem."],[17,11,"Og jeg er ikke mere i Verden, men disse ere i Verden, og jeg kommer til dig. Hellige Fader! bevar dem i dit Navn, hvilke du haver givet mig, at de maa vare eet ligesom vi.","Og jeg er ikke mere i Verden, men disse ere i Verden, og jeg kommer til dig. Hellige Fader! bevar dem i dit Navn, hvilke du haver givet mig, at de maa vare eet ligesom vi."],[17,12,"Da jeg var hos dem i Verden, bevarede jeg dem i dit Navn; dem, som du haver givet mig, vogtede jeg, og ingen af dem blev fortabt, uden det Fortabelsens Barn, at Skriften skulde fuldkommes.","Da jeg var hos dem i Verden, bevarede jeg dem i dit Navn; dem, som du haver givet mig, vogtede jeg, og ingen af dem blev fortabt, uden det Fortabelsens Barn, at Skriften skulde fuldkommes."],[17,13,"Men nu kommer jeg til dig, og dette taler jeg i Verden, at de maa have min Glæde fuldeligen i sig.","Men nu kommer jeg til dig, og dette taler jeg i Verden, at de maa have min Glæde fuldeligen i sig."],[17,14,"Jeg haver givet dem dit Ord; og Verden haver hadet dem, fordi de ere ikke af Verden, ligesom jeg er ikke af Verden.","Jeg haver givet dem dit Ord; og Verden haver hadet dem, fordi de ere ikke af Verden, ligesom jeg er ikke af Verden."],[17,15,"Jeg beder ikke, at du skal borttage dem af Verden, men at du skal bevare dem fra det Onde.","Jeg beder ikke, at du skal borttage dem af Verden, men at du skal bevare dem fra det Onde."],[17,16,"De ere ikke af Verden ligesom jeg ikke af Verden.","De ere ikke af Verden ligesom jeg ikke af Verden."],[17,17,"Hellige dem i din Sandhed; dit Ord er Sandhed.","Hellige dem i din Sandhed; dit Ord er Sandhed."],[17,18,"Ligesom du haver sendt mig til Verden, saa haver og jeg sendt dem til Verden.","Ligesom du haver sendt mig til Verden, saa haver og jeg sendt dem til Verden."],[17,19,"Og jeg helliger mig selv for dem, paa det de skulle ogsaa være helligede i Sandheden.","Og jeg helliger mig selv for dem, paa det de skulle ogsaa være helligede i Sandheden."],[17,20,"Men jeg beder ikke alene for disse, men ogsaa for dem, som formedelst deres Ord skulle troe paa mig,","Men jeg beder ikke alene for disse, men ogsaa for dem, som formedelst deres Ord skulle troe paa mig,"],[17,21,"paa det de maa alle være eet; ligesom du, Fader! i mig, og jeg i dig, at de og skulle være eet i os, at Verden kan troe, at du haver udsendt mig.","paa det de maa alle være eet; ligesom du, Fader! i mig, og jeg i dig, at de og skulle være eet i os, at Verden kan troe, at du haver udsendt mig."],[17,22,"Og jeg haver givet dem den Herlighed, som du haver givet mig, paa det de skulle være eet, ligesom vi ere eet;","Og jeg haver givet dem den Herlighed, som du haver givet mig, paa det de skulle være eet, ligesom vi ere eet;"],[17,23,"jeg i dem, og du i mig, paa det de skulle være fuldkommede til eet, og at Verden kan kjende, at du haver udsendt mig og haver elsket dem, ligesom du haver elsket mig.","jeg i dem, og du i mig, paa det de skulle være fuldkommede til eet, og at Verden kan kjende, at du haver udsendt mig og haver elsket dem, ligesom du haver elsket mig."],[17,24,"Fader! jeg vil, at de, som du haver givet mig, skulle og være hos mig, hvor jeg er, at de maa skue min Herlighed, som du haver givet mig; thi du haver elsket mig, førend Verdens Grundvold blev lagt.","Fader! jeg vil, at de, som du haver givet mig, skulle og være hos mig, hvor jeg er, at de maa skue min Herlighed, som du haver givet mig; thi du haver elsket mig, førend Verdens Grundvold blev lagt."],[17,25,"Retfærdige Fader! og Verden kjendte dig ikke, men jeg kjender dig, og disse have kjendt, at du haver udsendt mig.","Retfærdige Fader! og Verden kjendte dig ikke, men jeg kjender dig, og disse have kjendt, at du haver udsendt mig."],[17,26,"Og jeg kundgjorde dem dit Navn, og vil kundgjøre dem det, paa det den Kjærlighed, hvormed du elsker mig, skal være i dem, og jeg i dem.","Og jeg kundgjorde dem dit Navn, og vil kundgjøre dem det, paa det den Kjærlighed, hvormed du elsker mig, skal være i dem, og jeg i dem."],[18,1,"Der Jesus havde talet dette, gik han ud med sine Disciple over den Bæk Kedron, hvor en Urtegaard var, i hvilken han gik ind med sine Disciple.","Der Jesus havde talet dette, gik han ud med sine Disciple over den Bæk Kedron, hvor en Urtegaard var, i hvilken han gik ind med sine Disciple."],[18,2,"Men og Judas, som ham forraadte vidste Stedet; thi Jesus forsamledes ofte der med sine Disciple.","Men og Judas, som ham forraadte vidste Stedet; thi Jesus forsamledes ofte der med sine Disciple."],[18,3,"Da tog Judas Roden og de Ypperstepræsters og Pharisæernes Svende med sig, og kom derhen med Blus og Lamper og Vaaben.","Da tog Judas Roden og de Ypperstepræsters og Pharisæernes Svende med sig, og kom derhen med Blus og Lamper og Vaaben."],[18,4,"Men som Jesus vidste Alt, hvad der skulde komme over ham, gik han frem og sagde til dem: hvem lede I efter?","Men som Jesus vidste Alt, hvad der skulde komme over ham, gik han frem og sagde til dem: hvem lede I efter?"],[18,5,"De svarede ham: Jesus af Nazareth. Jesus siger til dem: det er mig. Men Judas, som ham forraadte, stod og hos dem.","De svarede ham: Jesus af Nazareth. Jesus siger til dem: det er mig. Men Judas, som ham forraadte, stod og hos dem."],[18,6,"Der han da sagde til dem: det er mig, vege de tilbage og faldt til Jorden.","Der han da sagde til dem: det er mig, vege de tilbage og faldt til Jorden."],[18,7,"Da spurgte han dem atter: hvem lede I efter? Men de sagde: Jesus af Nazareth.","Da spurgte han dem atter: hvem lede I efter? Men de sagde: Jesus af Nazareth."],[18,8,"Jesus svarede: jeg haver sagt Eder, at det er mig; dersom I da lede efter mig, saa lader disse gaae.","Jesus svarede: jeg haver sagt Eder, at det er mig; dersom I da lede efter mig, saa lader disse gaae."],[18,9,"Paa det de Ord skulde fuldkommes, hvilke han havde sagt: jeg mistede end ikke een af dem, som du haver givet mig.","Paa det de Ord skulde fuldkommes, hvilke han havde sagt: jeg mistede end ikke een af dem, som du haver givet mig."],[18,10,"Men Simon Peter, som havde et Sværd, drog det ud og slog den Ypperstepræsts Tjener og afhuggede hans høire Øre. Men den Tjener hedte Malchus.","Men Simon Peter, som havde et Sværd, drog det ud og slog den Ypperstepræsts Tjener og afhuggede hans høire Øre. Men den Tjener hedte Malchus."],[18,11,"Da sagde Jesus til Peter: stik dit Sværd i Balgen. Skal jeg ikke drikke den Kalk, som min Fader haver givet mig?","Da sagde Jesus til Peter: stik dit Sværd i Balgen. Skal jeg ikke drikke den Kalk, som min Fader haver givet mig?"],[18,12,"Da toge Roden og Krigsøversten og Jødernes Svende samtligen Jesus og bandt ham.","Da toge Roden og Krigsøversten og Jødernes Svende samtligen Jesus og bandt ham."],[18,13,"Og de førte ham først til Annas; thi han var Svigerfader til Caiphas, som var det Aars Ypperstepræst.","Og de førte ham først til Annas; thi han var Svigerfader til Caiphas, som var det Aars Ypperstepræst."],[18,14,"Men det var Caiphas, som havde givet Jøderne det Raad, at det var gavnligt, at eet Menneske skulde omkommes for Folket.","Men det var Caiphas, som havde givet Jøderne det Raad, at det var gavnligt, at eet Menneske skulde omkommes for Folket."],[18,15,"Men Simon Peter og en anden Discipel fulgte Jesus; samme Discipel var kjendt af den Ypperstepræst, og gik ind med Jesus i den Ypperstepræstes Pallads.","Men Simon Peter og en anden Discipel fulgte Jesus; samme Discipel var kjendt af den Ypperstepræst, og gik ind med Jesus i den Ypperstepræstes Pallads."],[18,16,"Men Peter stod udenfor Døren. Da gik den anden Discipel, som var kjendt med den Ypperstepræst, ud og talede med Dørvogtersken og førte Peter ind.","Men Peter stod udenfor Døren. Da gik den anden Discipel, som var kjendt med den Ypperstepræst, ud og talede med Dørvogtersken og førte Peter ind."],[18,17,"Da siger Pigen, som var Dørvogterske, til Peter: mon ikke og du være af dette Menneskes Disciple? Han sagde: jeg er ikke.","Da siger Pigen, som var Dørvogterske, til Peter: mon ikke og du være af dette Menneskes Disciple? Han sagde: jeg er ikke."],[18,18,"Men Tjenerne og Svendene stode og havde gjort Kulild, (thi det var koldt), og varmede sig; men Peter stod hos dem og varmede sig.","Men Tjenerne og Svendene stode og havde gjort Kulild, (thi det var koldt), og varmede sig; men Peter stod hos dem og varmede sig."],[18,19,"Da spurgte den Ypperstepræst Jesus om hans Disciple og om hans Lærdom.","Da spurgte den Ypperstepræst Jesus om hans Disciple og om hans Lærdom."],[18,20,"Jesus svarede ham: jeg haver talet frit for Verden; jeg haver altid lært i Synagogen og i Templet, der hvor Jøderne komme tilsammen fra alle Steder, og jeg haver Intet talet i Løndom.","Jesus svarede ham: jeg haver talet frit for Verden; jeg haver altid lært i Synagogen og i Templet, der hvor Jøderne komme tilsammen fra alle Steder, og jeg haver Intet talet i Løndom."],[18,21,"Hvi spørger du mig? spørg dem, som have hørt, hvad jeg talede til dem; see, de vide, hvad jeg haver sagt.","Hvi spørger du mig? spørg dem, som have hørt, hvad jeg talede til dem; see, de vide, hvad jeg haver sagt."],[18,22,"Men som han det talede, gav een af Svendene, som stod derhos, Jesus et Slag paa Munden og sagde: svarer du saaledes den Ypperstepræst?","Men som han det talede, gav een af Svendene, som stod derhos, Jesus et Slag paa Munden og sagde: svarer du saaledes den Ypperstepræst?"],[18,23,"Jesus svarede ham: haver jeg talet ilde, da beviis, at det er ondt; men haver jeg talet vel, hvi slaaer du mig?","Jesus svarede ham: haver jeg talet ilde, da beviis, at det er ondt; men haver jeg talet vel, hvi slaaer du mig?"],[18,24,"Men Annas havde sendt ham bunden til den Ypperstepræst Caiphas.","Men Annas havde sendt ham bunden til den Ypperstepræst Caiphas."],[18,25,"Men Simon Peter stod og varmede sig. Da sagde de til ham: mon ikke og du være af hans Disciple? Han negtede det og sagde: jeg er ikke.","Men Simon Peter stod og varmede sig. Da sagde de til ham: mon ikke og du være af hans Disciple? Han negtede det og sagde: jeg er ikke."],[18,26,"En af den Ypperstepræstes Tjenere, som var hans Frænde, hvis Øre Peter havde afhugget, siger: saae jeg dig ikke i Urtegaarden med ham?","En af den Ypperstepræstes Tjenere, som var hans Frænde, hvis Øre Peter havde afhugget, siger: saae jeg dig ikke i Urtegaarden med ham?"],[18,27,"Da negtede Peter atter, og strax goel Hanen.","Da negtede Peter atter, og strax goel Hanen."],[18,28,"Da førte de Jesus fra Caiphas til Domhuset; men det var aarle. Og de gik ikke ind i Domhuset, at de ikke skulde besmittes, men at de maatte æde Paaske.","Da førte de Jesus fra Caiphas til Domhuset; men det var aarle. Og de gik ikke ind i Domhuset, at de ikke skulde besmittes, men at de maatte æde Paaske."],[18,29,"Derfor gik Pilatus ud til dem og sagde: hvad Klagemaal føre I imod dette Menneske?","Derfor gik Pilatus ud til dem og sagde: hvad Klagemaal føre I imod dette Menneske?"],[18,30,"De svarede og sagde til ham: var denne ikke en Misdæder, da havde vi ikke overantvordet dig ham.","De svarede og sagde til ham: var denne ikke en Misdæder, da havde vi ikke overantvordet dig ham."],[18,31,"Da sagde Pilatus til dem: tager I ham og dømmer ham efter Eders Lov. Da sagde Jøderne til ham: vi tør ingen aflive;","Da sagde Pilatus til dem: tager I ham og dømmer ham efter Eders Lov. Da sagde Jøderne til ham: vi tør ingen aflive;"],[18,32,"at Jesu Ord skulde fuldkommes, hvilke han sagde, der han gav tilkjende, hvilken Død han skulde døe.","at Jesu Ord skulde fuldkommes, hvilke han sagde, der han gav tilkjende, hvilken Død han skulde døe."],[18,33,"Da gik Pilatus igjen ind i Domhuset, og kaldte Jesus og sagde til ham: er du den Jødernes Konge?","Da gik Pilatus igjen ind i Domhuset, og kaldte Jesus og sagde til ham: er du den Jødernes Konge?"],[18,34,"Jesus svarede ham: taler du dette af dig selv, eller have Andre sagt dig det om mig?","Jesus svarede ham: taler du dette af dig selv, eller have Andre sagt dig det om mig?"],[18,35,"Pilatus svarede: mon jeg være en Jøde? dit Folk og de Ypperstepræster overantvordede mig dig; hvad haver du gjort?","Pilatus svarede: mon jeg være en Jøde? dit Folk og de Ypperstepræster overantvordede mig dig; hvad haver du gjort?"],[18,36,"Jesus svarede: mit Rige er ikke af denne Verden. Var mit Rige af denne Verden, havde vel mine Tjenere stredet derfor, at jeg ikke var bleven overantvordet Jøderne; men nu er mit Rige ikke deraf.","Jesus svarede: mit Rige er ikke af denne Verden. Var mit Rige af denne Verden, havde vel mine Tjenere stredet derfor, at jeg ikke var bleven overantvordet Jøderne; men nu er mit Rige ikke deraf."],[18,37,"Da sagde Pilatus til ham: er du ikke dog en Konge? Jesus svarede: du siger det, at jeg er en Konge. Jeg er dertil født og dertil kommen til Verden, at jeg skal vidne om Sandheden. Hver den, som er af Sandheden, hører min Røst.","Da sagde Pilatus til ham: er du ikke dog en Konge? Jesus svarede: du siger det, at jeg er en Konge. Jeg er dertil født og dertil kommen til Verden, at jeg skal vidne om Sandheden. Hver den, som er af Sandheden, hører min Røst."],[18,38,"Pilatus sagde til ham: hvad er Sandhed? Og der han dette havde sagt, gik han igjen ud til Jøderne og sagde til dem: jeg finder slet ingen Skyld hos ham.","Pilatus sagde til ham: hvad er Sandhed? Og der han dette havde sagt, gik han igjen ud til Jøderne og sagde til dem: jeg finder slet ingen Skyld hos ham."],[18,39,"Men I have en Sædvane, at jeg skal lade Eder Een løs om Paasken; ville I da, at jeg skal lade Eder den Jødernes Konge løs?","Men I have en Sædvane, at jeg skal lade Eder Een løs om Paasken; ville I da, at jeg skal lade Eder den Jødernes Konge løs?"],[18,40,"Da raabte de alle igjen og sagde: ikke denne, men Barrabas; og Barrabas var en Røver.","Da raabte de alle igjen og sagde: ikke denne, men Barrabas; og Barrabas var en Røver."],[19,1,"Nu tog da Pilatus Jesus og lod ham hudstryge.","Nu tog da Pilatus Jesus og lod ham hudstryge."],[19,2,"Og Stridsmændene flettede en Krone af Torne og satte den paa hans Hoved, og kastede et Purpurklæde om ham og sagde:","Og Stridsmændene flettede en Krone af Torne og satte den paa hans Hoved, og kastede et Purpurklæde om ham og sagde:"],[19,3,"hil være dig, du Jødernes Konge! og de sloge ham paa Munden.","hil være dig, du Jødernes Konge! og de sloge ham paa Munden."],[19,4,"Da gik Pilatus atter ud og sagde til dem: see, jeg fører ham hid ud til Eder, at I skulle vide, at jeg finder ingen Skyld hos ham.","Da gik Pilatus atter ud og sagde til dem: see, jeg fører ham hid ud til Eder, at I skulle vide, at jeg finder ingen Skyld hos ham."],[19,5,"Da gik Jesus ud og bar Tornekronen og Purpurklædet. Og han sagde til dem: see, hvilket Menneske!","Da gik Jesus ud og bar Tornekronen og Purpurklædet. Og han sagde til dem: see, hvilket Menneske!"],[19,6,"Da nu de Ypperstepræster og Svendene saae ham, raabte de og sagde: korsfæst! korsfæst! Pilatus siger til dem: tager I ham og korsfæster ham: thi jeg finder ikke Skyld hos ham.","Da nu de Ypperstepræster og Svendene saae ham, raabte de og sagde: korsfæst! korsfæst! Pilatus siger til dem: tager I ham og korsfæster ham: thi jeg finder ikke Skyld hos ham."],[19,7,"Jøderne svarede ham: vi have en Lov, og efter denne vor Lov er han skyldig at døe, fordi han haver gjort sig selv til Guds Søn.","Jøderne svarede ham: vi have en Lov, og efter denne vor Lov er han skyldig at døe, fordi han haver gjort sig selv til Guds Søn."],[19,8,"Der Pilatus da hørte den Tale, frygtede han mere.","Der Pilatus da hørte den Tale, frygtede han mere."],[19,9,"Og han gik ind igjen i Domhuset og sagde til Jesus: hvorfra er du? Men Jesus gav ham ikke Svar.","Og han gik ind igjen i Domhuset og sagde til Jesus: hvorfra er du? Men Jesus gav ham ikke Svar."],[19,10,"Da siger Pilatus til ham: taler du ikke med mig? veed du ikke, at jeg haver Magt til at korsfæste dig, og at jeg haver Magt til at lade dig løs?","Da siger Pilatus til ham: taler du ikke med mig? veed du ikke, at jeg haver Magt til at korsfæste dig, og at jeg haver Magt til at lade dig løs?"],[19,11,"Jesus svarede: du havde aldeles ingen Magt mod mig, dersom den ikke var given dig ovenfra; derfor haver den, som overantvordede mig til dig, større Synd.","Jesus svarede: du havde aldeles ingen Magt mod mig, dersom den ikke var given dig ovenfra; derfor haver den, som overantvordede mig til dig, større Synd."],[19,12,"Derefter søgte Pilatus at lade ham løs. Men Jøderne raabte og sagde: dersom du lader denne løs, er du ikke Keiserens Ven. Hver den, som gjør sig til Konge, sætter sig op imod Keiseren.","Derefter søgte Pilatus at lade ham løs. Men Jøderne raabte og sagde: dersom du lader denne løs, er du ikke Keiserens Ven. Hver den, som gjør sig til Konge, sætter sig op imod Keiseren."],[19,13,"Der Pilatus hørte disse Ord, da førte han Jesus ud og satte sig paa Domstolen paa det Sted, som kaldes Steenlagt, men paa Hebraisk Gabbatha;","Der Pilatus hørte disse Ord, da førte han Jesus ud og satte sig paa Domstolen paa det Sted, som kaldes Steenlagt, men paa Hebraisk Gabbatha;"],[19,14,"men det var Beredelsens Dag i Paasken, ved den sjette Time; og han siger til Jøderne: see, Eders Konge!","men det var Beredelsens Dag i Paasken, ved den sjette Time; og han siger til Jøderne: see, Eders Konge!"],[19,15,"Men de raabte: bort, bort med ham! korsfæst ham! Pilatus sagde til dem: skal jeg korsfæste Eders Konge? De Ypperstepræster svarede: vi have ingen Konge, uden Keiseren.","Men de raabte: bort, bort med ham! korsfæst ham! Pilatus sagde til dem: skal jeg korsfæste Eders Konge? De Ypperstepræster svarede: vi have ingen Konge, uden Keiseren."],[19,16,"Derfor overantvordede han ham da til dem, for at korsfæstes. Men de toge Jesus og førte ham bort.","Derfor overantvordede han ham da til dem, for at korsfæstes. Men de toge Jesus og førte ham bort."],[19,17,"Og han bar sit Kors, og gik ud til det Sted, som kaldes Hovedpandested, og hedder paa Hebraisk Golgatha,","Og han bar sit Kors, og gik ud til det Sted, som kaldes Hovedpandested, og hedder paa Hebraisk Golgatha,"],[19,18,"hvor de korsfæstede ham og to Andre med ham, een paa hver Side, men Jesus midt imellem.","hvor de korsfæstede ham og to Andre med ham, een paa hver Side, men Jesus midt imellem."],[19,19,"Men Pilatus havde og skrevet en Overskrift og sat den paa Korset. Men der var skrevet: Jesus Nazaræus, den Jødernes Konge.","Men Pilatus havde og skrevet en Overskrift og sat den paa Korset. Men der var skrevet: Jesus Nazaræus, den Jødernes Konge."],[19,20,"Denne Overskrift læste da mange af Jøderne; thi det Sted, hvor Jesus blev korsfæstet, var nær ved Staden; og den var skreven paa Hebraisk, Græsk og Latin.","Denne Overskrift læste da mange af Jøderne; thi det Sted, hvor Jesus blev korsfæstet, var nær ved Staden; og den var skreven paa Hebraisk, Græsk og Latin."],[19,21,"Da sagde Jødernes Ypperstepræster til Pilatus: skriv ikke: den Jødernes Konge; men: han sagde: jeg er Jødernes Konge.","Da sagde Jødernes Ypperstepræster til Pilatus: skriv ikke: den Jødernes Konge; men: han sagde: jeg er Jødernes Konge."],[19,22,"Pilatus svarede: hvad jeg skrev, det skrev jeg.","Pilatus svarede: hvad jeg skrev, det skrev jeg."],[19,23,"Der nu Stridsmændene havde korsfæstet Jesus, toge de hans Klæder og gjorde fire Parter, for hver Stridsmand en Part, ligeledes og Kjortelen; men Kjortelen var usyet, vævet fra øverst helt igjennem.","Der nu Stridsmændene havde korsfæstet Jesus, toge de hans Klæder og gjorde fire Parter, for hver Stridsmand en Part, ligeledes og Kjortelen; men Kjortelen var usyet, vævet fra øverst helt igjennem."],[19,24,"Da sagde de til hverandre: lader os ikke sønderskære den, men lodde om den, hvis den skal være; paa det Skriften skulde fuldkommes, som siger: de delede mine Klæder iblandt sig, og kastede Lod om min Kjortel. Dette gjorde da Stridsmændene.","Da sagde de til hverandre: lader os ikke sønderskære den, men lodde om den, hvis den skal være; paa det Skriften skulde fuldkommes, som siger: de delede mine Klæder iblandt sig, og kastede Lod om min Kjortel. Dette gjorde da Stridsmændene."],[19,25,"Men der stode ved Jesu Kors hans Moder og hans Moders Søster, Maria, Cleophas’ Hustru, og Maria Magdalene.","Men der stode ved Jesu Kors hans Moder og hans Moders Søster, Maria, Cleophas’ Hustru, og Maria Magdalene."],[19,26,"Der Jesus da saae sin Moder og den Discipel staae hos, som han elskede, siger han til sin Moder: Kvinde! see, det er din Søn.","Der Jesus da saae sin Moder og den Discipel staae hos, som han elskede, siger han til sin Moder: Kvinde! see, det er din Søn."],[19,27,"Derefter siger han til Disciplen: see, det er din Moder. Og fra den Time tog Disciplen hende hjem til Sit.","Derefter siger han til Disciplen: see, det er din Moder. Og fra den Time tog Disciplen hende hjem til Sit."],[19,28,"Derefter da Jesus vidste, at Alting var nu fuldbragt, paa det Skriften skulde fuldkommes, sagde han: jeg tørster.","Derefter da Jesus vidste, at Alting var nu fuldbragt, paa det Skriften skulde fuldkommes, sagde han: jeg tørster."],[19,29,"Men der stod et Kar fuldt af Eddike; og de fyldte en Svamp med Eddike, og satte den paa en Isopstengel og holdt den til hans Mund.","Men der stod et Kar fuldt af Eddike; og de fyldte en Svamp med Eddike, og satte den paa en Isopstengel og holdt den til hans Mund."],[19,30,"Der nu Jesus havde taget Eddiken, sagde han: det er fuldbragt; og bøiede Hovedet og opgav Aanden.","Der nu Jesus havde taget Eddiken, sagde han: det er fuldbragt; og bøiede Hovedet og opgav Aanden."],[19,31,"Men paa det Legemerne ikke skulde blive paa Korset Sabbaten over, (efterdi det var Beredelsens Dag, thi denne Sabbatsdag var stor), bade Jøderne Pilatus, at deres Been maatte brydes, og de nedtages.","Men paa det Legemerne ikke skulde blive paa Korset Sabbaten over, (efterdi det var Beredelsens Dag, thi denne Sabbatsdag var stor), bade Jøderne Pilatus, at deres Been maatte brydes, og de nedtages."],[19,32,"Da kom Stridsmændene og brøde Benene paa den Første og den Anden, som vare korsfæstede med ham.","Da kom Stridsmændene og brøde Benene paa den Første og den Anden, som vare korsfæstede med ham."],[19,33,"Men da de kom til Jesus, og de saae, at han var allerede død, brøde de ikke hans Been.","Men da de kom til Jesus, og de saae, at han var allerede død, brøde de ikke hans Been."],[19,34,"Men een af Stridsmændene stak ham i Siden med et Spyd, og strax udgik Blod og Vand.","Men een af Stridsmændene stak ham i Siden med et Spyd, og strax udgik Blod og Vand."],[19,35,"Og den, det haver seet, haver vidnet det, og hans Vidnesbyrd er sandt, og den Samme veed, at han siger Sanden, paa det I skulle troe.","Og den, det haver seet, haver vidnet det, og hans Vidnesbyrd er sandt, og den Samme veed, at han siger Sanden, paa det I skulle troe."],[19,36,"Thi disse Ting skete, at Skriften skulde fuldkommes: hans Been skal ikke sønderbrydes.","Thi disse Ting skete, at Skriften skulde fuldkommes: hans Been skal ikke sønderbrydes."],[19,37,"Og atter paa et andet Sted siger Skriften: de skulle see, i hvilken de have stunget.","Og atter paa et andet Sted siger Skriften: de skulle see, i hvilken de have stunget."],[19,38,"Men Joseph af Arimathæa, (som var en Jesu Discipel, dog lønligen, af Frygt for Jøderne), bad derefter Pilatus, at han maatte nedtage Jesu Legeme, og Pilatus tilstedte det. Da kom han og nedtog Jesu Legeme.","Men Joseph af Arimathæa, (som var en Jesu Discipel, dog lønligen, af Frygt for Jøderne), bad derefter Pilatus, at han maatte nedtage Jesu Legeme, og Pilatus tilstedte det. Da kom han og nedtog Jesu Legeme."],[19,39,"Men og Nicodemus, han, som tilforn var kommen til Jesus om Natten, kom og bragte Myrrha og Aloe sammenblandede, henved hundrede Pund.","Men og Nicodemus, han, som tilforn var kommen til Jesus om Natten, kom og bragte Myrrha og Aloe sammenblandede, henved hundrede Pund."],[19,40,"Da toge de Jesu Legeme og bandt det i Linklæder med dyrebare Salver, som Jødernes Skik er at flye Lig til Jorde.","Da toge de Jesu Legeme og bandt det i Linklæder med dyrebare Salver, som Jødernes Skik er at flye Lig til Jorde."],[19,41,"Men der var ved det Sted, hvor han blev korsfæstet, en Urtegaard, og i Urtegaarden en ny Grav, i hvilken endnu aldrig Nogen var lagt.","Men der var ved det Sted, hvor han blev korsfæstet, en Urtegaard, og i Urtegaarden en ny Grav, i hvilken endnu aldrig Nogen var lagt."],[19,42,"Der lagde de da Jesus for Jødernes Beredelsesdags Skyld, efterdi Graven var nær.","Der lagde de da Jesus for Jødernes Beredelsesdags Skyld, efterdi Graven var nær."],[20,1,"Men paa den første Dag i Ugen kom Maria Magdalene aarle, der det var endnu mørkt, til Graven, og saae, at Stenen var borttagen fra Graven.","Men paa den første Dag i Ugen kom Maria Magdalene aarle, der det var endnu mørkt, til Graven, og saae, at Stenen var borttagen fra Graven."],[20,2,"Da løb hun og kom til Simon Peter og til den anden Discipel, hvilken Jesus elskede, og sagde til dem: de have borttaget Herren af Graven, og vi vide ikke, hvor de have lagt ham.","Da løb hun og kom til Simon Peter og til den anden Discipel, hvilken Jesus elskede, og sagde til dem: de have borttaget Herren af Graven, og vi vide ikke, hvor de have lagt ham."],[20,3,"Da gik Peter og den anden Discipel ud, og de kom til Graven.","Da gik Peter og den anden Discipel ud, og de kom til Graven."],[20,4,"Men de Tvende løb tilsammen, og den anden Discipel løb foran, fastere end Peter, og kom først til Graven.","Men de Tvende løb tilsammen, og den anden Discipel løb foran, fastere end Peter, og kom først til Graven."],[20,5,"Og da han kigede ind, saae han Linklæderne ligge, men gik dog ikke ind.","Og da han kigede ind, saae han Linklæderne ligge, men gik dog ikke ind."],[20,6,"Da kom Simon Peter, som fulgte ham, og gik ind i Graven, og saae Linklæderne ligge,","Da kom Simon Peter, som fulgte ham, og gik ind i Graven, og saae Linklæderne ligge,"],[20,7,"og Svededugen, som havde paa sit Hoved, ikke liggende hos Linklæderne, men sammensvøbt paa et Sted for sig selv.","og Svededugen, som havde paa sit Hoved, ikke liggende hos Linklæderne, men sammensvøbt paa et Sted for sig selv."],[20,8,"Nu gik da og den anden Discipel, som var kommen først til Graven, ind, og saae og troede.","Nu gik da og den anden Discipel, som var kommen først til Graven, ind, og saae og troede."],[20,9,"Thi de forstode ikke endnu Skriften, at det burde ham at opstaae fra de Døde.","Thi de forstode ikke endnu Skriften, at det burde ham at opstaae fra de Døde."],[20,10,"Da gik Disciplene atter hen til Deres.","Da gik Disciplene atter hen til Deres."],[20,11,"Men Maria stod udenfor ved Graven og græd; og som hun græd, kigede hun ind i Graven,","Men Maria stod udenfor ved Graven og græd; og som hun græd, kigede hun ind i Graven,"],[20,12,"og hun saae to Engle sidde i hvide Klæder, een ved Hovedet og een ved Fødderne, hvor Jesu Legeme havde ligget.","og hun saae to Engle sidde i hvide Klæder, een ved Hovedet og een ved Fødderne, hvor Jesu Legeme havde ligget."],[20,13,"Og de sagde til hende: Kvinde! hvi græder du? Hun sagde til dem: fordi de have taget min Herre bort, og jeg ved ikke, hvor de have lagt ham.","Og de sagde til hende: Kvinde! hvi græder du? Hun sagde til dem: fordi de have taget min Herre bort, og jeg ved ikke, hvor de have lagt ham."],[20,14,"Og der hun det havde sagt, vendte hun sig tilbage og saae Jesus staae der, og hun vidste ikke, at det var Jesus.","Og der hun det havde sagt, vendte hun sig tilbage og saae Jesus staae der, og hun vidste ikke, at det var Jesus."],[20,15,"Jesus siger til hende: Kvinde! hvi græder du? hvem leder du efter? Hun meente, det var Urtegaardsmanden, og siger til ham: Herre! dersom du haver baaret ham bort, da siig mig, hvor du haver lagt ham, saa vil jeg tage ham.","Jesus siger til hende: Kvinde! hvi græder du? hvem leder du efter? Hun meente, det var Urtegaardsmanden, og siger til ham: Herre! dersom du haver baaret ham bort, da siig mig, hvor du haver lagt ham, saa vil jeg tage ham."],[20,16,"Jesus siger til hende: Maria! Da vendte hun sig, og siger til ham: Rabbuni! hvilket betyder: Mester.","Jesus siger til hende: Maria! Da vendte hun sig, og siger til ham: Rabbuni! hvilket betyder: Mester."],[20,17,"Jesus siger til hende: rør ikke ved mig, thi jeg er ikke endnu opfaren til min Fader; men gak til mine Brødre og siig dem: jeg farer op til min Fader og Eders Fader, og til min Gud og Eders Gud.","Jesus siger til hende: rør ikke ved mig, thi jeg er ikke endnu opfaren til min Fader; men gak til mine Brødre og siig dem: jeg farer op til min Fader og Eders Fader, og til min Gud og Eders Gud."],[20,18,"Men Maria Magdalene kommer og forkynder Disciplene, at hun havde seet Herren, og at han havde sagt hende dette.","Men Maria Magdalene kommer og forkynder Disciplene, at hun havde seet Herren, og at han havde sagt hende dette."],[20,19,"Men om Aftenen paa den samme Dag, som var den første i Ugen, da Dørene vare lukte, hvor Disciplene vare forsamlede, af Frygt for Jøderne, kom Jesus og stod midt iblandt dem og sagde til dem: Fred være med Eder!","Men om Aftenen paa den samme Dag, som var den første i Ugen, da Dørene vare lukte, hvor Disciplene vare forsamlede, af Frygt for Jøderne, kom Jesus og stod midt iblandt dem og sagde til dem: Fred være med Eder!"],[20,20,"Og der han det sagde, viste han dem sine Hænder og sin Side. Da bleve Disciplene glade, at de saae Herren.","Og der han det sagde, viste han dem sine Hænder og sin Side. Da bleve Disciplene glade, at de saae Herren."],[20,21,"Da sagde Jesus atter til dem: Fred være med Eder! ligesom Faderen haver udsendt mig, saa sender og jeg Eder.","Da sagde Jesus atter til dem: Fred være med Eder! ligesom Faderen haver udsendt mig, saa sender og jeg Eder."],[20,22,"Og der han dette sagde, aandede han paa dem og siger til dem: annammer den Hellig Aand!","Og der han dette sagde, aandede han paa dem og siger til dem: annammer den Hellig Aand!"],[20,23,"Hvem I forlade Synderne, dem ere de forladne, og hvem I beholde dem, ere de beholdne.","Hvem I forlade Synderne, dem ere de forladne, og hvem I beholde dem, ere de beholdne."],[20,24,"Men Thomas, een af de Tolv, hvilket betyder Tvilling, var ikke med dem, der Jesus kom.","Men Thomas, een af de Tolv, hvilket betyder Tvilling, var ikke med dem, der Jesus kom."],[20,25,"Derfor sagde de andre Disciple til ham: vi have seet Herren. Men han sagde til dem: uden jeg faaer seet Naglegabet i hans Hænder, og stikker min Finger i Naglegabet, og stikker min Haand i hans Side, vil jeg ingenlunde troe.","Derfor sagde de andre Disciple til ham: vi have seet Herren. Men han sagde til dem: uden jeg faaer seet Naglegabet i hans Hænder, og stikker min Finger i Naglegabet, og stikker min Haand i hans Side, vil jeg ingenlunde troe."],[20,26,"Og efter otte Dage vare atter hans Disciple inde, og Thomas med dem. Jesus kom, der Dørene vare lukte, og stod midt iblandt dem og sagde: Fred være med Eder!","Og efter otte Dage vare atter hans Disciple inde, og Thomas med dem. Jesus kom, der Dørene vare lukte, og stod midt iblandt dem og sagde: Fred være med Eder!"],[20,27,"Derefter siger han til Thomas: ræk din Finger hid, og see mine Hænder, og ræk din Haand hid, og stik den i min Side, og vær ikke vantro, men troende.","Derefter siger han til Thomas: ræk din Finger hid, og see mine Hænder, og ræk din Haand hid, og stik den i min Side, og vær ikke vantro, men troende."],[20,28,"Og Thomas svarede og sagde til ham: min Herre og min Gud!","Og Thomas svarede og sagde til ham: min Herre og min Gud!"],[20,29,"Jesus siger til ham: efterdi du haver seet mig, Thomas! haver du troet; salige ere du, som ikke have seet, og dog troet.","Jesus siger til ham: efterdi du haver seet mig, Thomas! haver du troet; salige ere du, som ikke have seet, og dog troet."],[20,30,"Desuden har Jesus og gjort mange andre Tegn for sine Disciples Aasyn, som ikke ere skrevne i denne Bog.","Desuden har Jesus og gjort mange andre Tegn for sine Disciples Aasyn, som ikke ere skrevne i denne Bog."],[20,31,"Men dette er skrevet, at I skulle troe, at Jesus er den Christus, den Guds Søn, og at I, som troe, skulle have Livet i hans Navn.","Men dette er skrevet, at I skulle troe, at Jesus er den Christus, den Guds Søn, og at I, som troe, skulle have Livet i hans Navn."],[21,1,"Derefter aabenbarede Jesus sig atter for Disciple ved Tiberias’ Sø; men han aabenbarede sig saaledes.","Derefter aabenbarede Jesus sig atter for Disciple ved Tiberias’ Sø; men han aabenbarede sig saaledes."],[21,2,"Simon Peter og Thomas, hvilket betyder Tvilling, og Nathanael fra Cana i Galilæa, og Zebedæus’ Sønner, og to andre af hans Disciple vare tilsammen.","Simon Peter og Thomas, hvilket betyder Tvilling, og Nathanael fra Cana i Galilæa, og Zebedæus’ Sønner, og to andre af hans Disciple vare tilsammen."],[21,3,"Simon Peter siger til dem: jeg gaaer hen at fiske. De sige til ham: vi komme og med dig. De gik ud og traadte strax i Skibet, og samme Nat fangede de Intet.","Simon Peter siger til dem: jeg gaaer hen at fiske. De sige til ham: vi komme og med dig. De gik ud og traadte strax i Skibet, og samme Nat fangede de Intet."],[21,4,"Men der det var bleven Morgen, stod Jesus ved Søbredden; men Disciplene vidste ikke, at det var Jesus.","Men der det var bleven Morgen, stod Jesus ved Søbredden; men Disciplene vidste ikke, at det var Jesus."],[21,5,"Jesus siger da til dem: Børnlille! have I Noget at æde? De svarede ham: nei.","Jesus siger da til dem: Børnlille! have I Noget at æde? De svarede ham: nei."],[21,6,"Men han sagde til dem: kaster Garnet til den høire Side af Skibet, saa skulle I finde. Da kastede de det ud, og de kunde ikke mere drage det for Fiskenes Mængde.","Men han sagde til dem: kaster Garnet til den høire Side af Skibet, saa skulle I finde. Da kastede de det ud, og de kunde ikke mere drage det for Fiskenes Mængde."],[21,7,"Da siger den Discipel, som Jesus elskede, til Peter: det er Herren. Der Simon Peter da hørte, at det var Herren, opbandt han sin Fiskerkjortel om sig, (thi han var nøgen), og kastede sig i Søen.","Da siger den Discipel, som Jesus elskede, til Peter: det er Herren. Der Simon Peter da hørte, at det var Herren, opbandt han sin Fiskerkjortel om sig, (thi han var nøgen), og kastede sig i Søen."],[21,8,"Men de andre Disciple kom med Skibet, (thi de vare ikke langt fra Landet, kun henved to hundrede Alen), og de droge Garnet med Fiskene.","Men de andre Disciple kom med Skibet, (thi de vare ikke langt fra Landet, kun henved to hundrede Alen), og de droge Garnet med Fiskene."],[21,9,"Der de traadte ud paa Landet, saae de der en Kulild, og Fisk ligge derpaa og Brød.","Der de traadte ud paa Landet, saae de der en Kulild, og Fisk ligge derpaa og Brød."],[21,10,"Jesus siger til dem: tager hid af Fiskene, som I nu fangede.","Jesus siger til dem: tager hid af Fiskene, som I nu fangede."],[21,11,"Simon Peter steg op og drog Garnet paa Landet, fuldt af store Fiske, hundrede, halvtredsindstyve og tre, og alligevel de vare saa mange, sønderreves Garnet ikke.","Simon Peter steg op og drog Garnet paa Landet, fuldt af store Fiske, hundrede, halvtredsindstyve og tre, og alligevel de vare saa mange, sønderreves Garnet ikke."],[21,12,"Jesus siger til dem: kommer, gjører Maaltid. Men ingen af Disciplene turde spørge ham: hvo er du? thi de vidste, at det var Herren.","Jesus siger til dem: kommer, gjører Maaltid. Men ingen af Disciplene turde spørge ham: hvo er du? thi de vidste, at det var Herren."],[21,13,"Da kom Jesus og tog Brødet og gav dem det, ligeledes og Fisken.","Da kom Jesus og tog Brødet og gav dem det, ligeledes og Fisken."],[21,14,"Dette var nu den tredie Gang, at Jesus aabenbarede sig for sine Disciple, efterat han var opstanden fra de Døde.","Dette var nu den tredie Gang, at Jesus aabenbarede sig for sine Disciple, efterat han var opstanden fra de Døde."],[21,15,"Efter at de da havde gjort Maaltid, siger Jesus til Simon Peter: Simon, Jonas’ Søn, elsker du mig mere end disse? Han siger til ham: ja, Herre! du veed, at jeg elsker dig. Jesus siger til ham: vogt mine Lam.","Efter at de da havde gjort Maaltid, siger Jesus til Simon Peter: Simon, Jonas’ Søn, elsker du mig mere end disse? Han siger til ham: ja, Herre! du veed, at jeg elsker dig. Jesus siger til ham: vogt mine Lam."],[21,16,"Han siger atter anden Gang til ham: Simon, Jonas’ Søn, elsker du mig? Han siger til ham: ja, Herre! du veed, at jeg elsker dig. Jesus siger til ham: vær Hyrde for mine Faar.","Han siger atter anden Gang til ham: Simon, Jonas’ Søn, elsker du mig? Han siger til ham: ja, Herre! du veed, at jeg elsker dig. Jesus siger til ham: vær Hyrde for mine Faar."],[21,17,"Han siger for tredie Gang til ham: Simon, Jonas’ Søn, elsker du mig? Peter blev bedrøvet, fordi han sagde den tredie Gang til ham: elsker du mig? og han sagde til ham: Herre! du veed alle Ting, du veed, at jeg elsker dig. Jesus siger til ham: vogt mine Faar.","Han siger for tredie Gang til ham: Simon, Jonas’ Søn, elsker du mig? Peter blev bedrøvet, fordi han sagde den tredie Gang til ham: elsker du mig? og han sagde til ham: Herre! du veed alle Ting, du veed, at jeg elsker dig. Jesus siger til ham: vogt mine Faar."],[21,18,"Sandelig, sandelig siger jeg dig: der du var yngre, bandt du op om dig selv, og gik, hvor du vilde; men naar du bliver gammel, skal du udrække dine Hænder, og en Anden skal binde op om dig og føre dig derhen, hvor du ikke vil.","Sandelig, sandelig siger jeg dig: der du var yngre, bandt du op om dig selv, og gik, hvor du vilde; men naar du bliver gammel, skal du udrække dine Hænder, og en Anden skal binde op om dig og føre dig derhen, hvor du ikke vil."],[21,19,"Men dette sagde han, for at betegne, med hvad Død han skulde herliggjøre Gud. Og der han havde dette sagt, siger han til ham: følg mig.","Men dette sagde han, for at betegne, med hvad Død han skulde herliggjøre Gud. Og der han havde dette sagt, siger han til ham: følg mig."],[21,20,"Men Peter vendte sig og saae den Disciple følge, som Jesus elskede, som og laae op til hans Bryst i Nadveren og havde sagt: Herre! hvo er den, som forraader dig?","Men Peter vendte sig og saae den Disciple følge, som Jesus elskede, som og laae op til hans Bryst i Nadveren og havde sagt: Herre! hvo er den, som forraader dig?"],[21,21,"Der Peter saae denne, siger han til Jesus: Herre! men hvad skal denne?","Der Peter saae denne, siger han til Jesus: Herre! men hvad skal denne?"],[21,22,"Jesus siger til ham: dersom jeg vil, at han skal blive, indtil jeg kommer, hvad angaaer det dig? følg du mig.","Jesus siger til ham: dersom jeg vil, at han skal blive, indtil jeg kommer, hvad angaaer det dig? følg du mig."],[21,23,"Derover kom dette Sagn ud iblandt Brødrene: denne Discipel døer ikke; endog Jesus ikke sagde til ham: han døer ikke, men: om jeg vil, at han skal blive, indtil jeg kommer, hvad angaaer det dig?","Derover kom dette Sagn ud iblandt Brødrene: denne Discipel døer ikke; endog Jesus ikke sagde til ham: han døer ikke, men: om jeg vil, at han skal blive, indtil jeg kommer, hvad angaaer det dig?"],[21,24,"Denne er den Discipel, som vidner om disse Ting, og haver skrevet dette; og vi vide, at hans Vidnesbyrd er sandt.","Denne er den Discipel, som vidner om disse Ting, og haver skrevet dette; og vi vide, at hans Vidnesbyrd er sandt."],[21,25,"Men der er og mange andre Ting, som Jesus haver gjort, hvilke, dersom de skulde skrives stykkeviis, mener jeg, at ikke end Verden selv kunde rumme de Bøger, som skulde skrives. Amen.","Men der er og mange andre Ting, som Jesus haver gjort, hvilke, dersom de skulde skrives stykkeviis, mener jeg, at ikke end Verden selv kunde rumme de Bøger, som skulde skrives. Amen."]],"epo-londona":[[1,1,"En la komenco estis la Vorto, kaj la Vorto estis kun Dio, kaj la Vorto estis Dio.","En la komenco estis la Vorto, kaj la Vorto estis kun Dio, kaj la Vorto estis Dio."],[1,2,"Tiu estis en la komenco kun Dio.","Tiu estis en la komenco kun Dio."],[1,3,"Ĉio estiĝis per li; kaj aparte de li estiĝis nenio, kio estiĝis.","Ĉio estiĝis per li; kaj aparte de li estiĝis nenio, kio estiĝis."],[1,4,"En li estis la vivo, kaj la vivo estis la lumo de la homoj.","En li estis la vivo, kaj la vivo estis la lumo de la homoj."],[1,5,"Kaj la lumo brilas en la mallumo, kaj la mallumo ĝin ne venkis.","Kaj la lumo brilas en la mallumo, kaj la mallumo ĝin ne venkis."],[1,6,"De Dio estis sendita viro, kies nomo estis Johano.","De Dio estis sendita viro, kies nomo estis Johano."],[1,7,"Tiu venis kiel atestanto, por atesti pri la lumo, por ke ĉiuj per li kredu.","Tiu venis kiel atestanto, por atesti pri la lumo, por ke ĉiuj per li kredu."],[1,8,"Li ne estis la lumo, sed li venis, por atesti pri la lumo.","Li ne estis la lumo, sed li venis, por atesti pri la lumo."],[1,9,"Tio estis la vera lumo, kiu lumas al ĉiu homo, venanta en la mondon.","Tio estis la vera lumo, kiu lumas al ĉiu homo, venanta en la mondon."],[1,10,"Tiu estis en la mondo, kaj la mondo per li estiĝis, kaj la mondo lin ne konis.","Tiu estis en la mondo, kaj la mondo per li estiĝis, kaj la mondo lin ne konis."],[1,11,"Li venis al siaj propraĵoj, kaj liaj propruloj lin ne akceptis.","Li venis al siaj propraĵoj, kaj liaj propruloj lin ne akceptis."],[1,12,"Sed al ĉiuj, kiuj lin akceptis, li donis la rajton fariĝi filoj de Dio, al la kredantoj al lia nomo,","Sed al ĉiuj, kiuj lin akceptis, li donis la rajton fariĝi filoj de Dio, al la kredantoj al lia nomo,"],[1,13,"kiuj naskiĝis nek el sango, nek el volo de karno, nek el volo de homo, sed el Dio.","kiuj naskiĝis nek el sango, nek el volo de karno, nek el volo de homo, sed el Dio."],[1,14,"Kaj la Vorto fariĝis karno kaj loĝis inter ni, kaj ni vidis lian gloron, gloron kvazaŭ de la solenaskita de la Patro, plena de graco kaj vero.","Kaj la Vorto fariĝis karno kaj loĝis inter ni, kaj ni vidis lian gloron, gloron kvazaŭ de la solenaskita de la Patro, plena de graco kaj vero."],[1,15,"Johano atestis pri li, kaj kriis, dirante: Ĉi tiu estas li, pri kiu mi diris: Kiu venas post mi, tiu estas metita super mi, ĉar li ekzistis pli frue ol mi.","Johano atestis pri li, kaj kriis, dirante: Ĉi tiu estas li, pri kiu mi diris: Kiu venas post mi, tiu estas metita super mi, ĉar li ekzistis pli frue ol mi."],[1,16,"Ĉar el lia pleneco ni ĉiuj ricevis, kaj gracon post graco.","Ĉar el lia pleneco ni ĉiuj ricevis, kaj gracon post graco."],[1,17,"Ĉar la leĝo estis donita per Moseo; la graco kaj la vero estiĝis per Jesuo Kristo.","Ĉar la leĝo estis donita per Moseo; la graco kaj la vero estiĝis per Jesuo Kristo."],[1,18,"Neniu iam vidis Dion; la solenaskita Filo, kiu estas en la sino de la Patro, Lin deklaris.","Neniu iam vidis Dion; la solenaskita Filo, kiu estas en la sino de la Patro, Lin deklaris."],[1,19,"Kaj jen estas la atesto de Johano, kiam la Judoj sendis al li pastrojn kaj Levidojn el Jerusalem, por demandi lin: Kiu vi estas?","Kaj jen estas la atesto de Johano, kiam la Judoj sendis al li pastrojn kaj Levidojn el Jerusalem, por demandi lin: Kiu vi estas?"],[1,20,"Kaj li konfesis kaj ne kaŝis; kaj li konfesis: Mi ne estas la Kristo.","Kaj li konfesis kaj ne kaŝis; kaj li konfesis: Mi ne estas la Kristo."],[1,21,"Kaj ili demandis lin: Kio do? Ĉu vi estas Elija? Kaj li diris: Mi ne estas. Ĉu vi estas la profeto? Kaj li respondis: Ne.","Kaj ili demandis lin: Kio do? Ĉu vi estas Elija? Kaj li diris: Mi ne estas. Ĉu vi estas la profeto? Kaj li respondis: Ne."],[1,22,"Ili do diris al li: Kiu vi estas? por ke ni donu respondon al niaj sendintoj. Kion vi diras pri vi mem?","Ili do diris al li: Kiu vi estas? por ke ni donu respondon al niaj sendintoj. Kion vi diras pri vi mem?"],[1,23,"Li diris: Mi estas voĉo de krianto en la dezerto: Rektigu la vojon de la Eternulo, kiel diris la profeto Jesaja.","Li diris: Mi estas voĉo de krianto en la dezerto: Rektigu la vojon de la Eternulo, kiel diris la profeto Jesaja."],[1,24,"Kaj tiuj estis senditaj de la Fariseoj.","Kaj tiuj estis senditaj de la Fariseoj."],[1,25,"Kaj ili demandis lin, kaj diris al li: Kial do vi baptas, se vi ne estas la Kristo, nek Elija, nek la profeto?","Kaj ili demandis lin, kaj diris al li: Kial do vi baptas, se vi ne estas la Kristo, nek Elija, nek la profeto?"],[1,26,"Johano respondis al ili, dirante: Mi baptas per akvo; meze de vi staras tiu, kiun vi ne konas,","Johano respondis al ili, dirante: Mi baptas per akvo; meze de vi staras tiu, kiun vi ne konas,"],[1,27,"kiu venas post mi; la rimenon de lia ŝuo mi ne estas inda malligi.","kiu venas post mi; la rimenon de lia ŝuo mi ne estas inda malligi."],[1,28,"Tio okazis en Betania transe de Jordan, kie Johano baptadis.","Tio okazis en Betania transe de Jordan, kie Johano baptadis."],[1,29,"La sekvantan tagon li vidis Jesuon venanta al li, kaj diris: Jen la Ŝafido de Dio, kiu forportas la pekon de la mondo!","La sekvantan tagon li vidis Jesuon venanta al li, kaj diris: Jen la Ŝafido de Dio, kiu forportas la pekon de la mondo!"],[1,30,"Li estas tiu, pri kiu mi diris: Post mi venas viro, kiu estas metita super mi, ĉar li ekzistis pli frue ol mi.","Li estas tiu, pri kiu mi diris: Post mi venas viro, kiu estas metita super mi, ĉar li ekzistis pli frue ol mi."],[1,31,"Kaj mi lin ne konis; sed por ke li estu montrita al Izrael, tial mi venis, baptante per akvo.","Kaj mi lin ne konis; sed por ke li estu montrita al Izrael, tial mi venis, baptante per akvo."],[1,32,"Kaj Johano atestis, dirante: Mi vidis la Spiriton malsupreniranta de la ĉielo kiel kolombo, kaj ĝi restis sur li.","Kaj Johano atestis, dirante: Mi vidis la Spiriton malsupreniranta de la ĉielo kiel kolombo, kaj ĝi restis sur li."],[1,33,"Kaj mi lin ne konis; sed kiu sendis min por bapti per akvo, Tiu diris al mi: Sur kiun vi vidos la Spiriton malsupreniranta kaj restanta sur li, tiu estas la baptanto per la Sankta Spirito.","Kaj mi lin ne konis; sed kiu sendis min por bapti per akvo, Tiu diris al mi: Sur kiun vi vidos la Spiriton malsupreniranta kaj restanta sur li, tiu estas la baptanto per la Sankta Spirito."],[1,34,"Kaj mi vidis, kaj atestis, ke ĉi tiu estas la Filo de Dio.","Kaj mi vidis, kaj atestis, ke ĉi tiu estas la Filo de Dio."],[1,35,"Denove la sekvantan tagon staris Johano, kaj du el liaj disĉiploj;","Denove la sekvantan tagon staris Johano, kaj du el liaj disĉiploj;"],[1,36,"kaj rigardante Jesuon promenantan, li diris: Jen la Ŝafido de Dio!","kaj rigardante Jesuon promenantan, li diris: Jen la Ŝafido de Dio!"],[1,37,"Kaj la du disĉiploj aŭdis lin paroli, kaj sekvis Jesuon.","Kaj la du disĉiploj aŭdis lin paroli, kaj sekvis Jesuon."],[1,38,"Kaj Jesuo sin turnis, kaj vidis ilin sekvantajn, kaj diris al ili: Kion vi serĉas? Kaj ili diris al li: Rabeno (tio estas, Majstro), kie vi loĝas?","Kaj Jesuo sin turnis, kaj vidis ilin sekvantajn, kaj diris al ili: Kion vi serĉas? Kaj ili diris al li: Rabeno (tio estas, Majstro), kie vi loĝas?"],[1,39,"Li diris al ili: Venu, kaj vi vidos. Ili do venis, kaj vidis, kie li loĝas, kaj ili restis ĉe li tiun tagon; estis ĉirkaŭ la deka horo.","Li diris al ili: Venu, kaj vi vidos. Ili do venis, kaj vidis, kie li loĝas, kaj ili restis ĉe li tiun tagon; estis ĉirkaŭ la deka horo."],[1,40,"Unu el la du, kiuj aŭdis Johanon kaj lin sekvis, estis Andreo, la frato de Simon Petro.","Unu el la du, kiuj aŭdis Johanon kaj lin sekvis, estis Andreo, la frato de Simon Petro."],[1,41,"Tiu unue trovis sian propran fraton Simon, kaj diris al li: Ni trovis la Mesion (tio estas, Kriston).","Tiu unue trovis sian propran fraton Simon, kaj diris al li: Ni trovis la Mesion (tio estas, Kriston)."],[1,42,"Li kondukis lin al Jesuo. Jesuo lin rigardis, kaj diris: Vi estas Simon, filo de Jona; vi estos nomata Kefas (tio estas, Petro).","Li kondukis lin al Jesuo. Jesuo lin rigardis, kaj diris: Vi estas Simon, filo de Jona; vi estos nomata Kefas (tio estas, Petro)."],[1,43,"La sekvantan tagon li volis foriri en Galileon, kaj trovis Filipon; kaj Jesuo diris al li: Sekvu min.","La sekvantan tagon li volis foriri en Galileon, kaj trovis Filipon; kaj Jesuo diris al li: Sekvu min."],[1,44,"Filipo estis el Betsaida, la urbo de Andreo kaj Petro.","Filipo estis el Betsaida, la urbo de Andreo kaj Petro."],[1,45,"Filipo trovis Natanaelon, kaj diris al li: Ni trovis tiun, pri kiu skribis Moseo en la leĝo, kaj la profetoj, Jesuon el Nazaret, filon de Jozef.","Filipo trovis Natanaelon, kaj diris al li: Ni trovis tiun, pri kiu skribis Moseo en la leĝo, kaj la profetoj, Jesuon el Nazaret, filon de Jozef."],[1,46,"Kaj Natanael diris al li: Ĉu io bona povas esti el Nazaret? Filipo diris al li: Venu kaj vidu.","Kaj Natanael diris al li: Ĉu io bona povas esti el Nazaret? Filipo diris al li: Venu kaj vidu."],[1,47,"Jesuo vidis Natanaelon venanta al li, kaj diris pri li: Jen vera Izraelido, en kiu ne estas ruzeco!","Jesuo vidis Natanaelon venanta al li, kaj diris pri li: Jen vera Izraelido, en kiu ne estas ruzeco!"],[1,48,"Natanael diris al li: Per kio vi min konas? Jesuo respondis kaj diris al li: Antaŭ ol Filipo vin vokis, kiam vi estis sub la figarbo, mi vin vidis.","Natanael diris al li: Per kio vi min konas? Jesuo respondis kaj diris al li: Antaŭ ol Filipo vin vokis, kiam vi estis sub la figarbo, mi vin vidis."],[1,49,"Natanael respondis kaj diris al li: Rabeno, vi estas la Filo de Dio; vi estas Reĝo de Izrael!","Natanael respondis kaj diris al li: Rabeno, vi estas la Filo de Dio; vi estas Reĝo de Izrael!"],[1,50,"Jesuo respondis kaj diris al li: Ĉu vi kredas pro tio, ke mi diris al vi: Mi vin vidis sub la figarbo? vi vidos pli grandajn aferojn ol ĉi tio.","Jesuo respondis kaj diris al li: Ĉu vi kredas pro tio, ke mi diris al vi: Mi vin vidis sub la figarbo? vi vidos pli grandajn aferojn ol ĉi tio."],[1,51,"Kaj li diris al li: Vere, vere, mi diras al vi, vi vidos la ĉielon malfermita kaj la anĝelojn de Dio suprenirantaj kaj malsuprenirantaj sur la Filon de homo.","Kaj li diris al li: Vere, vere, mi diras al vi, vi vidos la ĉielon malfermita kaj la anĝelojn de Dio suprenirantaj kaj malsuprenirantaj sur la Filon de homo."],[2,1,"La trian tagon okazis edziĝo en Kana Galilea, kaj la patrino de Jesuo ĉeestis tie;","La trian tagon okazis edziĝo en Kana Galilea, kaj la patrino de Jesuo ĉeestis tie;"],[2,2,"ankaŭ Jesuo kaj liaj disĉiploj estis invititaj al la edziĝo.","ankaŭ Jesuo kaj liaj disĉiploj estis invititaj al la edziĝo."],[2,3,"Kaj kiam mankis vino, la patrino de Jesuo diris al li: Ili ne havas vinon.","Kaj kiam mankis vino, la patrino de Jesuo diris al li: Ili ne havas vinon."],[2,4,"Kaj Jesuo diris al ŝi: Kio estas inter mi kaj vi, virino? mia horo ankoraŭ ne venis.","Kaj Jesuo diris al ŝi: Kio estas inter mi kaj vi, virino? mia horo ankoraŭ ne venis."],[2,5,"Lia patrino diris al la servantoj: Kion ajn li diros al vi, tion faru.","Lia patrino diris al la servantoj: Kion ajn li diros al vi, tion faru."],[2,6,"Kaj estis tie ses akvokuvoj ŝtonaj, metitaj laŭ la purigo de la Judoj, enhavantaj po du ĝis tri metretoj.","Kaj estis tie ses akvokuvoj ŝtonaj, metitaj laŭ la purigo de la Judoj, enhavantaj po du ĝis tri metretoj."],[2,7,"Jesuo diris al ili: Plenigu la akvokuvojn per akvo. Kaj oni plenigis ilin ĝis la rando.","Jesuo diris al ili: Plenigu la akvokuvojn per akvo. Kaj oni plenigis ilin ĝis la rando."],[2,8,"Kaj li diris al ili: Ĉerpu nun, kaj alportu al la festenestro. Kaj oni alportis.","Kaj li diris al ili: Ĉerpu nun, kaj alportu al la festenestro. Kaj oni alportis."],[2,9,"Kiam la festenestro gustumis la akvon, nun fariĝintan vino, kaj ne sciis, de kie ĝi estas (sciis tamen la servantoj, kiuj ĉerpis la akvon), la festenestro alvokis la fianĉon,","Kiam la festenestro gustumis la akvon, nun fariĝintan vino, kaj ne sciis, de kie ĝi estas (sciis tamen la servantoj, kiuj ĉerpis la akvon), la festenestro alvokis la fianĉon,"],[2,10,"kaj diris al li: Ĉiu homo prezentas unue la bonan vinon, kaj kiam oni jam drinkis, tiam la malpli bonan; sed vi rezervis la bonan vinon ĝis nun.","kaj diris al li: Ĉiu homo prezentas unue la bonan vinon, kaj kiam oni jam drinkis, tiam la malpli bonan; sed vi rezervis la bonan vinon ĝis nun."],[2,11,"Ĉi tiun komencon de signoj Jesuo faris en Kana Galilea, kaj elmontris sian gloron, kaj liaj disĉiploj kredis al li.","Ĉi tiun komencon de signoj Jesuo faris en Kana Galilea, kaj elmontris sian gloron, kaj liaj disĉiploj kredis al li."],[2,12,"Post tio li malsupreniris al Kapernaum, kaj kun li lia patrino kaj liaj fratoj kaj liaj disĉiploj; kaj tie ili restis ne multajn tagojn.","Post tio li malsupreniris al Kapernaum, kaj kun li lia patrino kaj liaj fratoj kaj liaj disĉiploj; kaj tie ili restis ne multajn tagojn."],[2,13,"Kaj la Pasko de la Judoj alproksimiĝis, kaj Jesuo supreniris al Jerusalem.","Kaj la Pasko de la Judoj alproksimiĝis, kaj Jesuo supreniris al Jerusalem."],[2,14,"Kaj li trovis en la templo vendistojn de bovoj kaj ŝafoj kaj kolomboj, kaj la monŝanĝistojn sidantajn;","Kaj li trovis en la templo vendistojn de bovoj kaj ŝafoj kaj kolomboj, kaj la monŝanĝistojn sidantajn;"],[2,15,"kaj farinte skurĝon el ŝnuretoj, li elpelis ĉiujn el la templo, ŝafojn kaj bovojn; kaj elŝutis la monerojn de la monŝanĝistoj kaj renversis la tablojn;","kaj farinte skurĝon el ŝnuretoj, li elpelis ĉiujn el la templo, ŝafojn kaj bovojn; kaj elŝutis la monerojn de la monŝanĝistoj kaj renversis la tablojn;"],[2,16,"kaj al la vendistoj de la kolomboj li diris: Forportu tion de ĉi tie; ne faru la domon de mia Patro domo de komerco.","kaj al la vendistoj de la kolomboj li diris: Forportu tion de ĉi tie; ne faru la domon de mia Patro domo de komerco."],[2,17,"La disĉiploj rememoris, ke estis skribite: Fervoro pri Via domo min konsumis.","La disĉiploj rememoris, ke estis skribite: Fervoro pri Via domo min konsumis."],[2,18,"La Judoj do respondis kaj diris al li: Kian signon vi montras al ni, ĉar vi faras tion?","La Judoj do respondis kaj diris al li: Kian signon vi montras al ni, ĉar vi faras tion?"],[2,19,"Respondis Jesuo kaj diris al ili: Detruu ĉi tiun sanktejon, kaj mi levos ĝin en la daŭro de tri tagoj.","Respondis Jesuo kaj diris al ili: Detruu ĉi tiun sanktejon, kaj mi levos ĝin en la daŭro de tri tagoj."],[2,20,"La Judoj diris: Kvardek ses jarojn ĉi tiu sanktejo estis konstruata; ĉu vi levos ĝin en la daŭro de tri tagoj?","La Judoj diris: Kvardek ses jarojn ĉi tiu sanktejo estis konstruata; ĉu vi levos ĝin en la daŭro de tri tagoj?"],[2,21,"Sed li parolis pri la sanktejo de sia korpo.","Sed li parolis pri la sanktejo de sia korpo."],[2,22,"Kiam do li leviĝis el la mortintoj, la disĉiploj rememoris, ke li diris tion; kaj ili kredis la Skribon, kaj la vorton, kiun Jesuo diris.","Kiam do li leviĝis el la mortintoj, la disĉiploj rememoris, ke li diris tion; kaj ili kredis la Skribon, kaj la vorton, kiun Jesuo diris."],[2,23,"Kaj kiam li estis en Jerusalem ĉe la Pasko, dum la festo, multaj fidis al lia nomo, vidante la signojn, kiujn li faris.","Kaj kiam li estis en Jerusalem ĉe la Pasko, dum la festo, multaj fidis al lia nomo, vidante la signojn, kiujn li faris."],[2,24,"Sed Jesuo ne konfidis sin al ili, ĉar li konis ĉiujn,","Sed Jesuo ne konfidis sin al ili, ĉar li konis ĉiujn,"],[2,25,"kaj ne bezonis, ke iu atestu pri la homo, ĉar li mem sciis, kio estas en la homo.","kaj ne bezonis, ke iu atestu pri la homo, ĉar li mem sciis, kio estas en la homo."],[3,1,"Estis viro el la Fariseoj, nomata Nikodemo, ĉefo inter la Judoj;","Estis viro el la Fariseoj, nomata Nikodemo, ĉefo inter la Judoj;"],[3,2,"tiu venis al li nokte, kaj diris al li: Rabeno, ni scias, ke vi estas instruisto, veninta de Dio; ĉar neniu povas fari tiujn signojn, kiujn vi faras, se Dio ne estas kun li.","tiu venis al li nokte, kaj diris al li: Rabeno, ni scias, ke vi estas instruisto, veninta de Dio; ĉar neniu povas fari tiujn signojn, kiujn vi faras, se Dio ne estas kun li."],[3,3,"Jesuo respondis kaj diris al li: Vere, vere, mi diras al vi: Se homo ne estas denove naskita, li ne povas vidi la regnon de Dio.","Jesuo respondis kaj diris al li: Vere, vere, mi diras al vi: Se homo ne estas denove naskita, li ne povas vidi la regnon de Dio."],[3,4,"Nikodemo diris al li: Kiel povas homo naskiĝi, kiam li estas maljuna? ĉu li povas eniri denove en la ventron de sia patrino kaj naskiĝi?","Nikodemo diris al li: Kiel povas homo naskiĝi, kiam li estas maljuna? ĉu li povas eniri denove en la ventron de sia patrino kaj naskiĝi?"],[3,5,"Jesuo respondis: Vere, vere, mi diras al vi: Se homo ne estas naskita el akvo kaj la Spirito, li ne povas eniri en la regnon de Dio.","Jesuo respondis: Vere, vere, mi diras al vi: Se homo ne estas naskita el akvo kaj la Spirito, li ne povas eniri en la regnon de Dio."],[3,6,"Tio, kio naskiĝas el la karno, estas karno; kaj tio, kio naskiĝas de la Spirito, estas spirito.","Tio, kio naskiĝas el la karno, estas karno; kaj tio, kio naskiĝas de la Spirito, estas spirito."],[3,7,"Ne miru, ke mi diris al vi: Vi devas esti denove naskitaj.","Ne miru, ke mi diris al vi: Vi devas esti denove naskitaj."],[3,8,"La vento blovas, kie ĝi volas, kaj ĝian voĉon vi aŭdas, sed vi ne scias, de kie ĝi venas kaj kien ĝi iras; tia estas ĉiu, kiu estas naskita de la Spirito.","La vento blovas, kie ĝi volas, kaj ĝian voĉon vi aŭdas, sed vi ne scias, de kie ĝi venas kaj kien ĝi iras; tia estas ĉiu, kiu estas naskita de la Spirito."],[3,9,"Nikodemo respondis kaj diris al li: Kiel povas tio fariĝi?","Nikodemo respondis kaj diris al li: Kiel povas tio fariĝi?"],[3,10,"Jesuo respondis kaj diris al li: Vi estas la instruisto de Izrael, kaj ĉu vi ne scias tion?","Jesuo respondis kaj diris al li: Vi estas la instruisto de Izrael, kaj ĉu vi ne scias tion?"],[3,11,"Vere, vere, mi diras al vi: Kion ni scias, tion ni parolas, kaj kion ni vidis, tion ni atestas; kaj vi homoj ne akceptas nian ateston.","Vere, vere, mi diras al vi: Kion ni scias, tion ni parolas, kaj kion ni vidis, tion ni atestas; kaj vi homoj ne akceptas nian ateston."],[3,12,"Se mi aferojn surterajn diris al vi, kaj vi ne kredas, kiel vi kredos, se mi diros enĉielajn?","Se mi aferojn surterajn diris al vi, kaj vi ne kredas, kiel vi kredos, se mi diros enĉielajn?"],[3,13,"Kaj neniu supreniris en la ĉielon, krom tiu, kiu malsupreniris de la ĉielo, la Filo de homo, kiu estas en la ĉielo.","Kaj neniu supreniris en la ĉielon, krom tiu, kiu malsupreniris de la ĉielo, la Filo de homo, kiu estas en la ĉielo."],[3,14,"Kaj kiel Moseo levis la serpenton en la dezerto, tiel devas la Filo de homo esti levita;","Kaj kiel Moseo levis la serpenton en la dezerto, tiel devas la Filo de homo esti levita;"],[3,15,"por ke ĉiu, fidanta al li, havu eternan vivon.","por ke ĉiu, fidanta al li, havu eternan vivon."],[3,16,"Ĉar Dio tiel amis la mondon, ke Li donis Sian solenaskitan Filon, por ke ĉiu, kiu fidas al li, ne pereu, sed havu eternan vivon.","Ĉar Dio tiel amis la mondon, ke Li donis Sian solenaskitan Filon, por ke ĉiu, kiu fidas al li, ne pereu, sed havu eternan vivon."],[3,17,"Ĉar Dio sendis Sian Filon en la mondon, ne por juĝi la mondon, sed por ke la mondo per li estu savita.","Ĉar Dio sendis Sian Filon en la mondon, ne por juĝi la mondon, sed por ke la mondo per li estu savita."],[3,18,"Kiu fidas al li, tiu ne estas juĝata; sed la nekredanto jam estas juĝita, ĉar li ne fidas al la nomo de la solenaskita Filo de Dio.","Kiu fidas al li, tiu ne estas juĝata; sed la nekredanto jam estas juĝita, ĉar li ne fidas al la nomo de la solenaskita Filo de Dio."],[3,19,"Kaj jen estas la juĝo: ke la lumo venis en la mondon, kaj la homoj amis la mallumon pli ol la lumon, ĉar iliaj faroj estis malbonaj.","Kaj jen estas la juĝo: ke la lumo venis en la mondon, kaj la homoj amis la mallumon pli ol la lumon, ĉar iliaj faroj estis malbonaj."],[3,20,"Ĉar ĉiu, kiu faradas malbonon, malamas la lumon, kaj ne venas al la lumo, por ke liaj faroj ne estu malaprobitaj.","Ĉar ĉiu, kiu faradas malbonon, malamas la lumon, kaj ne venas al la lumo, por ke liaj faroj ne estu malaprobitaj."],[3,21,"Sed tiu, kiu faras la veron, venas al la lumo, por ke liaj faroj estu montrataj, ke ili estas faritaj en Dio.","Sed tiu, kiu faras la veron, venas al la lumo, por ke liaj faroj estu montrataj, ke ili estas faritaj en Dio."],[3,22,"Post tio venis Jesuo kun siaj disĉiploj en la landon Judujo, kaj restis tie kun ili kaj baptadis.","Post tio venis Jesuo kun siaj disĉiploj en la landon Judujo, kaj restis tie kun ili kaj baptadis."],[3,23,"Johano ankaŭ baptadis en Enon, proksime de Salim, ĉar estis tie multe da akvoj; kaj oni alvenis kaj estis baptitaj.","Johano ankaŭ baptadis en Enon, proksime de Salim, ĉar estis tie multe da akvoj; kaj oni alvenis kaj estis baptitaj."],[3,24,"Ĉar Johano ankoraŭ ne estis ĵetita en malliberejon.","Ĉar Johano ankoraŭ ne estis ĵetita en malliberejon."],[3,25,"Fariĝis do diskutado inter la disĉiploj de Johano kaj iu Judo pri la puriĝo.","Fariĝis do diskutado inter la disĉiploj de Johano kaj iu Judo pri la puriĝo."],[3,26,"Kaj ili venis al Johano, kaj diris al li: Rabeno, tiu, kiu estis kun vi transe de Jordan, kaj pri kiu vi atestis, jen tiu sama baptas, kaj ĉiuj venas al li.","Kaj ili venis al Johano, kaj diris al li: Rabeno, tiu, kiu estis kun vi transe de Jordan, kaj pri kiu vi atestis, jen tiu sama baptas, kaj ĉiuj venas al li."],[3,27,"Johano respondis kaj diris: Homo ne povas ion ricevi, se ĝi ne estas donita al li el la ĉielo.","Johano respondis kaj diris: Homo ne povas ion ricevi, se ĝi ne estas donita al li el la ĉielo."],[3,28,"Vi mem atestas pri mi, ke mi diris: Mi ne estas la Kristo, sed mi estas sendita antaŭ li.","Vi mem atestas pri mi, ke mi diris: Mi ne estas la Kristo, sed mi estas sendita antaŭ li."],[3,29,"Kiu havas la fianĉinon, tiu estas la fianĉo; sed la amiko de la fianĉo, kiu staras kaj lin aŭdas, tre ĝojas pro la voĉo de la fianĉo; ĉi tiu mia ĝojo do plenumiĝis.","Kiu havas la fianĉinon, tiu estas la fianĉo; sed la amiko de la fianĉo, kiu staras kaj lin aŭdas, tre ĝojas pro la voĉo de la fianĉo; ĉi tiu mia ĝojo do plenumiĝis."],[3,30,"Li devas altiĝi, sed mi devas malaltiĝi.","Li devas altiĝi, sed mi devas malaltiĝi."],[3,31,"Kiu de supre venas, tiu estas super ĉiuj; kiu estas el la tero, tiu el la tero estas, kaj el la tero parolas; kiu venas de la ĉielo, tiu estas super ĉiuj.","Kiu de supre venas, tiu estas super ĉiuj; kiu estas el la tero, tiu el la tero estas, kaj el la tero parolas; kiu venas de la ĉielo, tiu estas super ĉiuj."],[3,32,"Kion li vidis kaj aŭdis, tion li atestas; kaj neniu akceptas lian ateston.","Kion li vidis kaj aŭdis, tion li atestas; kaj neniu akceptas lian ateston."],[3,33,"Kiu akceptis lian ateston, tiu jam sigelis, ke Dio estas vera.","Kiu akceptis lian ateston, tiu jam sigelis, ke Dio estas vera."],[3,34,"Ĉar tiu, kiun Dio sendis, parolas la vortojn de Dio; ĉar ne laŭmezure Li donas la Spiriton.","Ĉar tiu, kiun Dio sendis, parolas la vortojn de Dio; ĉar ne laŭmezure Li donas la Spiriton."],[3,35,"La Patro amas la Filon, kaj donis ĉion en lian manon.","La Patro amas la Filon, kaj donis ĉion en lian manon."],[3,36,"Kiu fidas al la Filo, tiu havas eternan vivon; sed kiu ne obeas al la Filo, tiu ne vidos vivon, sed la kolero de Dio sur li restas.","Kiu fidas al la Filo, tiu havas eternan vivon; sed kiu ne obeas al la Filo, tiu ne vidos vivon, sed la kolero de Dio sur li restas."],[4,1,"Kiam do la Sinjoro sciis, ke la Fariseoj aŭdis, ke Jesuo faras kaj baptas pli multe da disĉiploj, ol Johano","Kiam do la Sinjoro sciis, ke la Fariseoj aŭdis, ke Jesuo faras kaj baptas pli multe da disĉiploj, ol Johano"],[4,2,"(kvankam baptadis ne Jesuo mem, sed liaj disĉiploj),","(kvankam baptadis ne Jesuo mem, sed liaj disĉiploj),"],[4,3,"li foriris el Judujo kaj reiris al Galileo.","li foriris el Judujo kaj reiris al Galileo."],[4,4,"Kaj li devis trairi tra Samario.","Kaj li devis trairi tra Samario."],[4,5,"Li alvenis do al unu urbo Samaria, nomata Siĥar, apud la terpeco, kiun Jakob donis al sia filo Jozef;","Li alvenis do al unu urbo Samaria, nomata Siĥar, apud la terpeco, kiun Jakob donis al sia filo Jozef;"],[4,6,"kaj la fonto de Jakob estis tie. Jesuo do, lacigita de sia vojirado, sidiĝis tiamaniere apud la fonto. Estis ĉirkaŭ la sesa horo.","kaj la fonto de Jakob estis tie. Jesuo do, lacigita de sia vojirado, sidiĝis tiamaniere apud la fonto. Estis ĉirkaŭ la sesa horo."],[4,7,"Venis virino Samaria, por ĉerpi akvon; Jesuo diris al ŝi: Donu al mi trinki.","Venis virino Samaria, por ĉerpi akvon; Jesuo diris al ŝi: Donu al mi trinki."],[4,8,"Ĉar liaj disĉiploj jam foriris en la urbon, por aĉeti nutraĵojn.","Ĉar liaj disĉiploj jam foriris en la urbon, por aĉeti nutraĵojn."],[4,9,"La Samarianino do diris al li: Kiel vi, estante Judo, petas trinki de mi, kiu estas Samarianino? (Ĉar la Judoj ne interrilatas kun la Samarianoj.)","La Samarianino do diris al li: Kiel vi, estante Judo, petas trinki de mi, kiu estas Samarianino? (Ĉar la Judoj ne interrilatas kun la Samarianoj.)"],[4,10,"Jesuo respondis kaj diris al ŝi: Se vi scius la donacon de Dio, kaj kiu estas tiu, kiu diras al vi: Donu al mi trinki, vi petus lin, kaj li donus al vi vivan akvon.","Jesuo respondis kaj diris al ŝi: Se vi scius la donacon de Dio, kaj kiu estas tiu, kiu diras al vi: Donu al mi trinki, vi petus lin, kaj li donus al vi vivan akvon."],[4,11,"La virino diris al li: Sinjoro, vi nenian ĉerpilon havas, kaj la puto estas profunda; de kie do vi havas tiun vivan akvon?","La virino diris al li: Sinjoro, vi nenian ĉerpilon havas, kaj la puto estas profunda; de kie do vi havas tiun vivan akvon?"],[4,12,"Ĉu vi estas pli granda ol nia patro Jakob, kiu donis al ni la puton, kaj trinkis mem el ĝi, kiel ankaŭ liaj filoj kaj liaj brutoj?","Ĉu vi estas pli granda ol nia patro Jakob, kiu donis al ni la puton, kaj trinkis mem el ĝi, kiel ankaŭ liaj filoj kaj liaj brutoj?"],[4,13,"Jesuo respondis kaj diris al ŝi: Ĉiu, kiu trinkas el ĉi tiu akvo, denove soifos;","Jesuo respondis kaj diris al ŝi: Ĉiu, kiu trinkas el ĉi tiu akvo, denove soifos;"],[4,14,"sed kiu trinkos el la akvo, kiun mi donos al li, tiu neniam soifos; sed la akvo, kiun mi donos al li, fariĝos en li fonto de akvo, ŝprucanta supren por eterna vivo.","sed kiu trinkos el la akvo, kiun mi donos al li, tiu neniam soifos; sed la akvo, kiun mi donos al li, fariĝos en li fonto de akvo, ŝprucanta supren por eterna vivo."],[4,15,"La virino diris al li: Sinjoro, donu al mi ĉi tiun akvon, por ke mi ne plu soifu, kaj ne devu traveni ĉi tien, por ĉerpi.","La virino diris al li: Sinjoro, donu al mi ĉi tiun akvon, por ke mi ne plu soifu, kaj ne devu traveni ĉi tien, por ĉerpi."],[4,16,"Jesuo diris al ŝi: Foriru, voku vian edzon, kaj revenu ĉi tien.","Jesuo diris al ŝi: Foriru, voku vian edzon, kaj revenu ĉi tien."],[4,17,"La virino respondis kaj diris al li: Mi ne havas edzon. Jesuo diris al ŝi: Vi prave diris: Mi ne havas edzon;","La virino respondis kaj diris al li: Mi ne havas edzon. Jesuo diris al ŝi: Vi prave diris: Mi ne havas edzon;"],[4,18,"ĉar vi havis kvin edzojn; kaj tiu, kiun vi nun havas, ne estas via edzo; ĉi tion vi diris vere.","ĉar vi havis kvin edzojn; kaj tiu, kiun vi nun havas, ne estas via edzo; ĉi tion vi diris vere."],[4,19,"La virino diris al li: Sinjoro, mi ekvidas, ke vi estas profeto.","La virino diris al li: Sinjoro, mi ekvidas, ke vi estas profeto."],[4,20,"Niaj patroj adoradis sur ĉi tiu monto; kaj vi diras, ke en Jerusalem estas la loko, kie oni devas adori.","Niaj patroj adoradis sur ĉi tiu monto; kaj vi diras, ke en Jerusalem estas la loko, kie oni devas adori."],[4,21,"Jesuo diris al ŝi: Kredu al mi, virino; venas la horo, kiam nek sur ĉi tiu monto, nek en Jerusalem, vi adoros la Patron.","Jesuo diris al ŝi: Kredu al mi, virino; venas la horo, kiam nek sur ĉi tiu monto, nek en Jerusalem, vi adoros la Patron."],[4,22,"Vi adoras tion, kion vi ne konas; ni adoras tion, kion ni konas; ĉar el la Judoj estas la savo.","Vi adoras tion, kion vi ne konas; ni adoras tion, kion ni konas; ĉar el la Judoj estas la savo."],[4,23,"Sed venas la horo, kaj jam estas, kiam la veraj adorantoj adoros la Patron laŭ spirito kaj vero; ĉar la Patro serĉas tiajn por esti Liaj adorantoj.","Sed venas la horo, kaj jam estas, kiam la veraj adorantoj adoros la Patron laŭ spirito kaj vero; ĉar la Patro serĉas tiajn por esti Liaj adorantoj."],[4,24,"Dio estas Spirito: kaj Liaj adorantoj devas adori Lin laŭ spirito kaj vero.","Dio estas Spirito: kaj Liaj adorantoj devas adori Lin laŭ spirito kaj vero."],[4,25,"La virino diris al li: Mi scias, ke venas la Mesio (kiu estas nomata Kristo); kiam tiu alestos, li anoncos al ni ĉion.","La virino diris al li: Mi scias, ke venas la Mesio (kiu estas nomata Kristo); kiam tiu alestos, li anoncos al ni ĉion."],[4,26,"Jesuo diris al ŝi: Tiu estas mi, kiu parolas kun vi.","Jesuo diris al ŝi: Tiu estas mi, kiu parolas kun vi."],[4,27,"Kaj ĉe tio venis liaj disĉiploj, kaj ili miris, ke li parolas kun virino; tamen neniu diris: Kion vi volas? aŭ: Kial vi parolas kun ŝi?","Kaj ĉe tio venis liaj disĉiploj, kaj ili miris, ke li parolas kun virino; tamen neniu diris: Kion vi volas? aŭ: Kial vi parolas kun ŝi?"],[4,28,"La virino do lasis sian akvokruĉon, kaj foriris en la urbon, kaj diris al la homoj:","La virino do lasis sian akvokruĉon, kaj foriris en la urbon, kaj diris al la homoj:"],[4,29,"Venu, vidu homon, kiu rakontis al mi ĉion, kion mi faris; ĉu eble ĉi tiu estas la Kristo?","Venu, vidu homon, kiu rakontis al mi ĉion, kion mi faris; ĉu eble ĉi tiu estas la Kristo?"],[4,30,"Ili eliris el la urbo, kaj venis al li.","Ili eliris el la urbo, kaj venis al li."],[4,31,"Dume la disĉiploj petis lin, dirante: Rabeno, manĝu.","Dume la disĉiploj petis lin, dirante: Rabeno, manĝu."],[4,32,"Sed li diris al ili: Por manĝi mi havas nutraĵon, pri kiu vi ne scias.","Sed li diris al ili: Por manĝi mi havas nutraĵon, pri kiu vi ne scias."],[4,33,"La disĉiploj do diris inter si: Ĉu iu alportis al li ion por manĝi?","La disĉiploj do diris inter si: Ĉu iu alportis al li ion por manĝi?"],[4,34,"Jesuo diris al ili: Mia nutraĵo estas plenumi la volon de Tiu, kiu min sendis, kaj fini Lian laboron.","Jesuo diris al ili: Mia nutraĵo estas plenumi la volon de Tiu, kiu min sendis, kaj fini Lian laboron."],[4,35,"Ĉu vi ne diras: Estas ankoraŭ kvar monatoj, kaj venas la rikolto? jen mi diras al vi: Levu viajn okulojn kaj rigardu la kampojn, ke ili jam estas blankaj por la rikolto.","Ĉu vi ne diras: Estas ankoraŭ kvar monatoj, kaj venas la rikolto? jen mi diras al vi: Levu viajn okulojn kaj rigardu la kampojn, ke ili jam estas blankaj por la rikolto."],[4,36,"La rikoltanto ricevas salajron, kaj kolektas frukton por eterna vivo, por ke ĝoju kune la semanto kaj la rikoltanto.","La rikoltanto ricevas salajron, kaj kolektas frukton por eterna vivo, por ke ĝoju kune la semanto kaj la rikoltanto."],[4,37,"Ĉar en ĉi tio estas vera la proverbo: Unu semas, alia rikoltas.","Ĉar en ĉi tio estas vera la proverbo: Unu semas, alia rikoltas."],[4,38,"Mi vin sendis, por rikolti tion, kion vi ne prilaboris; aliaj laboris, kaj vi eniris en ilian laboron.","Mi vin sendis, por rikolti tion, kion vi ne prilaboris; aliaj laboris, kaj vi eniris en ilian laboron."],[4,39,"Kaj el tiu urbo multaj el la Samarianoj kredis al li pro la diro de la virino, kiu atestis: Li rakontis al mi ĉion, kion mi faris.","Kaj el tiu urbo multaj el la Samarianoj kredis al li pro la diro de la virino, kiu atestis: Li rakontis al mi ĉion, kion mi faris."],[4,40,"Kiam do la Samarianoj venis al li, ili petis, ke li restu ĉe ili; kaj li restis tie du tagojn.","Kiam do la Samarianoj venis al li, ili petis, ke li restu ĉe ili; kaj li restis tie du tagojn."],[4,41,"Kaj multe pli multaj kredis pro lia vorto,","Kaj multe pli multaj kredis pro lia vorto,"],[4,42,"kaj diris al la virino: Jam ne pro via diro ni kredas, ĉar ni mem aŭdis lin; kaj ni scias, ke ĉi tiu estas vere la Savanto de la mondo.","kaj diris al la virino: Jam ne pro via diro ni kredas, ĉar ni mem aŭdis lin; kaj ni scias, ke ĉi tiu estas vere la Savanto de la mondo."],[4,43,"Kaj post la du tagoj li foriris de tie en Galileon.","Kaj post la du tagoj li foriris de tie en Galileon."],[4,44,"Ĉar Jesuo mem atestis, ke profeto ne havas honoron en sia propra lando.","Ĉar Jesuo mem atestis, ke profeto ne havas honoron en sia propra lando."],[4,45,"Kiam do li venis en Galileon, la Galileanoj akceptis lin, ĉar ili jam vidis ĉion, kion li faris en Jerusalem dum la festo; ĉar ili ankaŭ iris al la festo.","Kiam do li venis en Galileon, la Galileanoj akceptis lin, ĉar ili jam vidis ĉion, kion li faris en Jerusalem dum la festo; ĉar ili ankaŭ iris al la festo."],[4,46,"Li revenis en Kanan Galilean, kie li faris la akvon vino. Kaj estis unu kortegano, kies filo estis malsana en Kapernaum.","Li revenis en Kanan Galilean, kie li faris la akvon vino. Kaj estis unu kortegano, kies filo estis malsana en Kapernaum."],[4,47,"Kiam li aŭdis, ke Jesuo alvenis el Judujo en Galileon, li iris al li, kaj petis lin malsupreniri kaj resanigi lian filon; ĉar li preskaŭ mortis.","Kiam li aŭdis, ke Jesuo alvenis el Judujo en Galileon, li iris al li, kaj petis lin malsupreniri kaj resanigi lian filon; ĉar li preskaŭ mortis."],[4,48,"Jesuo do diris al li: Se vi ne vidas signojn kaj mirindaĵojn, vi tute ne kredos.","Jesuo do diris al li: Se vi ne vidas signojn kaj mirindaĵojn, vi tute ne kredos."],[4,49,"La kortegano diris al li: Sinjoro, malsupreniru, antaŭ ol mia fileto mortos.","La kortegano diris al li: Sinjoro, malsupreniru, antaŭ ol mia fileto mortos."],[4,50,"Jesuo diris al li: Foriru, via filo vivas. La viro kredis la vorton, kiun Jesuo parolis al li, kaj li foriris.","Jesuo diris al li: Foriru, via filo vivas. La viro kredis la vorton, kiun Jesuo parolis al li, kaj li foriris."],[4,51,"Dum li ankoraŭ malsupreniris, liaj sklavoj lin renkontis, dirante: Via filo vivas.","Dum li ankoraŭ malsupreniris, liaj sklavoj lin renkontis, dirante: Via filo vivas."],[4,52,"Li demandis al ili pri la horo, kiam li ekresaniĝis. Ili respondis al li: Hieraŭ je la sepa horo la febro lin forlasis.","Li demandis al ili pri la horo, kiam li ekresaniĝis. Ili respondis al li: Hieraŭ je la sepa horo la febro lin forlasis."],[4,53,"Tial la patro sciis, ke tio estis en tiu sama horo, en kiu Jesuo diris al li: Via filo vivas; kaj kredis li mem kaj lia tuta domo.","Tial la patro sciis, ke tio estis en tiu sama horo, en kiu Jesuo diris al li: Via filo vivas; kaj kredis li mem kaj lia tuta domo."],[4,54,"Ĉi tiun jam la duan signon faris Jesuo, veninte el Judujo en Galileon.","Ĉi tiun jam la duan signon faris Jesuo, veninte el Judujo en Galileon."],[5,1,"Post tio estis festo de la Judoj, kaj Jesuo supreniris al Jerusalem.","Post tio estis festo de la Judoj, kaj Jesuo supreniris al Jerusalem."],[5,2,"En Jerusalem apud la Pordego de Ŝafoj estas lageto, nomata en la Hebrea lingvo Betesda, havanta kvin portikojn.","En Jerusalem apud la Pordego de Ŝafoj estas lageto, nomata en la Hebrea lingvo Betesda, havanta kvin portikojn."],[5,3,"En tiuj kuŝis amaso da malsanuloj, blinduloj, lamuloj, velkintoj, kiuj atendis la ekmovon de la akvo;","En tiuj kuŝis amaso da malsanuloj, blinduloj, lamuloj, velkintoj, kiuj atendis la ekmovon de la akvo;"],[5,4,"ĉar anĝelo de la Eternulo malsupreniris iafoje en la lageton kaj movis la akvon; kiu ajn do unua post la movado de la akvo enpaŝis, tiu resaniĝis, tute egale, de kia malsano li suferis.","ĉar anĝelo de la Eternulo malsupreniris iafoje en la lageton kaj movis la akvon; kiu ajn do unua post la movado de la akvo enpaŝis, tiu resaniĝis, tute egale, de kia malsano li suferis."],[5,5,"Kaj tie estis unu viro, kiu estis tridek ok jarojn en sia malforteco.","Kaj tie estis unu viro, kiu estis tridek ok jarojn en sia malforteco."],[5,6,"Kiam Jesuo vidis lin kuŝantan, kaj sciis, ke li jam de longe malsanas, li diris al li: Ĉu vi volas fariĝi sana?","Kiam Jesuo vidis lin kuŝantan, kaj sciis, ke li jam de longe malsanas, li diris al li: Ĉu vi volas fariĝi sana?"],[5,7,"La malsanulo respondis: Sinjoro, mi ne havas iun por enĵeti min en la lageton, kiam la akvo moviĝis; sed dum mi venas, alia paŝas malsupren antaŭ mi.","La malsanulo respondis: Sinjoro, mi ne havas iun por enĵeti min en la lageton, kiam la akvo moviĝis; sed dum mi venas, alia paŝas malsupren antaŭ mi."],[5,8,"Jesuo diris al li: Leviĝu, prenu vian liton, kaj iru.","Jesuo diris al li: Leviĝu, prenu vian liton, kaj iru."],[5,9,"Kaj la viro tuj fariĝis sana, kaj prenis sian liton, kaj iris. Kaj estis la sabato en tiu tago.","Kaj la viro tuj fariĝis sana, kaj prenis sian liton, kaj iris. Kaj estis la sabato en tiu tago."],[5,10,"La Judoj do diris al la resanigito: Estas la sabato, kaj al vi ne konvenas porti vian liton.","La Judoj do diris al la resanigito: Estas la sabato, kaj al vi ne konvenas porti vian liton."],[5,11,"Li respondis: Tiu, kiu min sanigis, diris al mi: Prenu vian liton, kaj iru.","Li respondis: Tiu, kiu min sanigis, diris al mi: Prenu vian liton, kaj iru."],[5,12,"Ili demandis lin: Kiu estas tiu homo, kiu diris al vi: Prenu kaj iru?","Ili demandis lin: Kiu estas tiu homo, kiu diris al vi: Prenu kaj iru?"],[5,13,"Sed la resanigito ne sciis, kiu tiu estas; ĉar Jesuo jam formoviĝis pro la tiea homamaso.","Sed la resanigito ne sciis, kiu tiu estas; ĉar Jesuo jam formoviĝis pro la tiea homamaso."],[5,14,"Poste Jesuo trovis lin en la templo, kaj diris al li: Jen vi fariĝis sana; ne plu peku, por ke io pli malbona ne okazu al vi.","Poste Jesuo trovis lin en la templo, kaj diris al li: Jen vi fariĝis sana; ne plu peku, por ke io pli malbona ne okazu al vi."],[5,15,"La viro foriris, kaj diris al la Judoj, ke Jesuo estas tiu, kiu lin sanigis.","La viro foriris, kaj diris al la Judoj, ke Jesuo estas tiu, kiu lin sanigis."],[5,16,"Kaj la Judoj persekutis Jesuon pro tio, ke li tion faris en sabato.","Kaj la Judoj persekutis Jesuon pro tio, ke li tion faris en sabato."],[5,17,"Sed Jesuo respondis al ili: Mia Patro ĝis nun laboras, kaj mi laboras.","Sed Jesuo respondis al ili: Mia Patro ĝis nun laboras, kaj mi laboras."],[5,18,"Pro tio do la Judoj des pli celis mortigi lin, pro tio, ke li ne nur malobservis la sabaton, sed ankaŭ diris, ke Dio estas lia propra Patro, kaj pretendis esti egala al Dio.","Pro tio do la Judoj des pli celis mortigi lin, pro tio, ke li ne nur malobservis la sabaton, sed ankaŭ diris, ke Dio estas lia propra Patro, kaj pretendis esti egala al Dio."],[5,19,"Jesuo do respondis kaj diris al ili: Vere, vere, mi diras al vi: La Filo ne povas per si mem fari ion, krom tio, kion li vidas la Patron faranta; ĉar kion ajn Li faras, tion la Filo tiel same ankaŭ faras.","Jesuo do respondis kaj diris al ili: Vere, vere, mi diras al vi: La Filo ne povas per si mem fari ion, krom tio, kion li vidas la Patron faranta; ĉar kion ajn Li faras, tion la Filo tiel same ankaŭ faras."],[5,20,"Ĉar la Patro amas la Filon, kaj montras al li ĉion, kion Li mem faras; kaj Li montros al li farojn pli grandajn ol ĉi tio, por ke vi miru.","Ĉar la Patro amas la Filon, kaj montras al li ĉion, kion Li mem faras; kaj Li montros al li farojn pli grandajn ol ĉi tio, por ke vi miru."],[5,21,"Ĉar kiel la Patro levas la mortintojn kaj ilin vivigas, tiel ankaŭ la Filo vivigas tiujn, kiujn li volas.","Ĉar kiel la Patro levas la mortintojn kaj ilin vivigas, tiel ankaŭ la Filo vivigas tiujn, kiujn li volas."],[5,22,"Ĉar la Patro juĝas neniun, sed Li donis ĉian juĝon al la Filo,","Ĉar la Patro juĝas neniun, sed Li donis ĉian juĝon al la Filo,"],[5,23,"por ke ĉiuj honoru la Filon tiel same, kiel ili honoras la Patron. Kiu ne honoras la Filon, tiu ne honoras la Patron, kiu lin sendis.","por ke ĉiuj honoru la Filon tiel same, kiel ili honoras la Patron. Kiu ne honoras la Filon, tiu ne honoras la Patron, kiu lin sendis."],[5,24,"Vere, vere, mi diras al vi: Kiu aŭskultas mian vorton, kaj kredas al Tiu, kiu min sendis, tiu havas eternan vivon kaj ne venas en juĝon, sed jam pasis de morto en vivon.","Vere, vere, mi diras al vi: Kiu aŭskultas mian vorton, kaj kredas al Tiu, kiu min sendis, tiu havas eternan vivon kaj ne venas en juĝon, sed jam pasis de morto en vivon."],[5,25,"Vere, vere, mi diras al vi: Venas horo kaj jam estas, kiam la mortintoj aŭdos la voĉon de la Filo de Dio; kaj la aŭdintoj vivos.","Vere, vere, mi diras al vi: Venas horo kaj jam estas, kiam la mortintoj aŭdos la voĉon de la Filo de Dio; kaj la aŭdintoj vivos."],[5,26,"Ĉar kiel la Patro havas en Si mem vivon, tiel Li donis al la Filo ankaŭ, ke ĉi tiu havu en si mem vivon;","Ĉar kiel la Patro havas en Si mem vivon, tiel Li donis al la Filo ankaŭ, ke ĉi tiu havu en si mem vivon;"],[5,27,"kaj Li donis al li la rajton fari juĝon, ĉar li estas la Filo de homo.","kaj Li donis al li la rajton fari juĝon, ĉar li estas la Filo de homo."],[5,28,"Ne miru pro tio; ĉar venas horo, en kiu ĉiuj, kiuj estas en la tomboj, aŭdos lian voĉon,","Ne miru pro tio; ĉar venas horo, en kiu ĉiuj, kiuj estas en la tomboj, aŭdos lian voĉon,"],[5,29,"kaj eliros; la farintoj de bono, al releviĝo por vivo; sed la farintoj de malbono, al releviĝo por juĝo.","kaj eliros; la farintoj de bono, al releviĝo por vivo; sed la farintoj de malbono, al releviĝo por juĝo."],[5,30,"Mi ne povas per mi mem fari ion; kiel mi aŭdas, tiel mi juĝas; kaj mia juĝo estas justa, ĉar mi celas ne mian propran volon, sed la volon de Tiu, kiu min sendis.","Mi ne povas per mi mem fari ion; kiel mi aŭdas, tiel mi juĝas; kaj mia juĝo estas justa, ĉar mi celas ne mian propran volon, sed la volon de Tiu, kiu min sendis."],[5,31,"Se mi atestus pri mi mem, mia atesto ne estus vera.","Se mi atestus pri mi mem, mia atesto ne estus vera."],[5,32,"Estas alia, kiu atestas pri mi; kaj mi scias, ke vera estas la atesto, kiun li atestas pri mi.","Estas alia, kiu atestas pri mi; kaj mi scias, ke vera estas la atesto, kiun li atestas pri mi."],[5,33,"Vi sendis al Johano, kaj li atestis pri la vero.","Vi sendis al Johano, kaj li atestis pri la vero."],[5,34,"Sed la atesto, kiun mi ricevas, ne estas el homo, tamen mi tion diras, por ke vi estu savitaj.","Sed la atesto, kiun mi ricevas, ne estas el homo, tamen mi tion diras, por ke vi estu savitaj."],[5,35,"Li estis la lampo, kiu brulas kaj lumas; kaj vi volis ĝoji kelkan tempon en lia lumo.","Li estis la lampo, kiu brulas kaj lumas; kaj vi volis ĝoji kelkan tempon en lia lumo."],[5,36,"Sed la atesto, kiun mi havas, estas pli granda ol la atesto de Johano; ĉar la laboroj, kiujn la Patro donis al mi por fini, tiuj samaj laboroj, kiujn mi faras, atestas pri mi, ke la Patro min sendis.","Sed la atesto, kiun mi havas, estas pli granda ol la atesto de Johano; ĉar la laboroj, kiujn la Patro donis al mi por fini, tiuj samaj laboroj, kiujn mi faras, atestas pri mi, ke la Patro min sendis."],[5,37,"Kaj la Patro, kiu min sendis, atestis pri mi. Vi nek aŭdis iam Lian voĉon, nek vidis Lian formon.","Kaj la Patro, kiu min sendis, atestis pri mi. Vi nek aŭdis iam Lian voĉon, nek vidis Lian formon."],[5,38,"Kaj vi ne havas Lian vorton restantan en vi, ĉar vi ne kredas al tiu, kiun Li sendis.","Kaj vi ne havas Lian vorton restantan en vi, ĉar vi ne kredas al tiu, kiun Li sendis."],[5,39,"Vi esploras la Skribojn, ĉar vi opinias, ke en ili vi havas eternan vivon; kaj ili estas tio, kio atestas pri mi;","Vi esploras la Skribojn, ĉar vi opinias, ke en ili vi havas eternan vivon; kaj ili estas tio, kio atestas pri mi;"],[5,40,"kaj vi ne volas veni al mi, por havi vivon.","kaj vi ne volas veni al mi, por havi vivon."],[5,41,"De homoj mi ne prenas gloron.","De homoj mi ne prenas gloron."],[5,42,"Sed mi vin scias, ke vi ne havas en vi la amon al Dio.","Sed mi vin scias, ke vi ne havas en vi la amon al Dio."],[5,43,"Mi venis en la nomo de mia Patro, kaj vi min ne akceptas; se alia venos en sia propra nomo, vi lin akceptos.","Mi venis en la nomo de mia Patro, kaj vi min ne akceptas; se alia venos en sia propra nomo, vi lin akceptos."],[5,44,"Kiel povas kredi vi, kiuj prenas gloron unu de alia, kaj la gloron, kiu venas de la sola Dio, vi ne serĉas?","Kiel povas kredi vi, kiuj prenas gloron unu de alia, kaj la gloron, kiu venas de la sola Dio, vi ne serĉas?"],[5,45,"Ne pensu, ke mi akuzos vin antaŭ la Patro; ekzistas unu, kiu akuzas vin, Moseo, al kiu vi esperas.","Ne pensu, ke mi akuzos vin antaŭ la Patro; ekzistas unu, kiu akuzas vin, Moseo, al kiu vi esperas."],[5,46,"Ĉar se vi kredus al Moseo, vi ankaŭ kredus al mi, ĉar li skribis pri mi.","Ĉar se vi kredus al Moseo, vi ankaŭ kredus al mi, ĉar li skribis pri mi."],[5,47,"Sed se vi ne kredas liajn skribojn, kiel vi kredos miajn vortojn?","Sed se vi ne kredas liajn skribojn, kiel vi kredos miajn vortojn?"],[6,1,"Poste Jesuo foriris trans la maron de Galileo, tio estas de Tiberias.","Poste Jesuo foriris trans la maron de Galileo, tio estas de Tiberias."],[6,2,"Kaj granda homamaso lin sekvis, ĉar ili vidis la signojn, kiujn li faris por la malsanuloj.","Kaj granda homamaso lin sekvis, ĉar ili vidis la signojn, kiujn li faris por la malsanuloj."],[6,3,"Kaj Jesuo supreniris sur la monton, kaj tie li sidis kun siaj disĉiploj.","Kaj Jesuo supreniris sur la monton, kaj tie li sidis kun siaj disĉiploj."],[6,4,"Kaj la Pasko, la festo de la Judoj, estis proksima.","Kaj la Pasko, la festo de la Judoj, estis proksima."],[6,5,"Jesuo do, levinte siajn okulojn, kaj ekvidinte, ke granda homamaso venas al li, diris al Filipo: De kie ni aĉetu panojn, por ke ĉi tiuj manĝu?","Jesuo do, levinte siajn okulojn, kaj ekvidinte, ke granda homamaso venas al li, diris al Filipo: De kie ni aĉetu panojn, por ke ĉi tiuj manĝu?"],[6,6,"Tion li diris, por provi lin; ĉar li mem sciis, kion li faros.","Tion li diris, por provi lin; ĉar li mem sciis, kion li faros."],[6,7,"Filipo respondis al li: Panoj por ducent denaroj ne sufiĉus por ili, por ke ĉiu iometon ricevu.","Filipo respondis al li: Panoj por ducent denaroj ne sufiĉus por ili, por ke ĉiu iometon ricevu."],[6,8,"Unu el liaj disĉiploj, Andreo, frato de Simon Petro, diris al li:","Unu el liaj disĉiploj, Andreo, frato de Simon Petro, diris al li:"],[6,9,"Ĉi tie estas knabo, kiu havas kvin hordeajn panojn kaj du malgrandajn fiŝojn; sed kio estas tio por tiom da homoj?","Ĉi tie estas knabo, kiu havas kvin hordeajn panojn kaj du malgrandajn fiŝojn; sed kio estas tio por tiom da homoj?"],[6,10,"Jesuo diris: Sidigu la homojn. Kaj estis tie multe da herbo. La viroj do sidiĝis, nombre ĉirkaŭ kvin mil.","Jesuo diris: Sidigu la homojn. Kaj estis tie multe da herbo. La viroj do sidiĝis, nombre ĉirkaŭ kvin mil."],[6,11,"Kaj Jesuo prenis la panojn, kaj doninte dankon, disdonis al la sidiĝintoj; kaj tiel same el la fiŝoj tiom, kiom oni deziris.","Kaj Jesuo prenis la panojn, kaj doninte dankon, disdonis al la sidiĝintoj; kaj tiel same el la fiŝoj tiom, kiom oni deziris."],[6,12,"Kaj kiam ili satiĝis, li diris al siaj disĉiploj: Kolektu la postrestantajn fragmentojn, por ke nenio perdiĝu.","Kaj kiam ili satiĝis, li diris al siaj disĉiploj: Kolektu la postrestantajn fragmentojn, por ke nenio perdiĝu."],[6,13,"Ili do kolektis ilin, kaj plenigis dek du korbojn per la fragmentoj de la kvin hordeaj panoj, kiuj postrestis al la manĝintoj.","Ili do kolektis ilin, kaj plenigis dek du korbojn per la fragmentoj de la kvin hordeaj panoj, kiuj postrestis al la manĝintoj."],[6,14,"Kiam do la homoj vidis la signon, kiun Jesuo faris, ili diris: Ĉi tiu estas vere la profeto, kiu devis veni en la mondon.","Kiam do la homoj vidis la signon, kiun Jesuo faris, ili diris: Ĉi tiu estas vere la profeto, kiu devis veni en la mondon."],[6,15,"Tial Jesuo, eksciante, ke oni celas veni kaj kapti lin, por fari lin reĝo, denove fortiris sin sola al la monto.","Tial Jesuo, eksciante, ke oni celas veni kaj kapti lin, por fari lin reĝo, denove fortiris sin sola al la monto."],[6,16,"Kaj kiam vesperiĝis, liaj disĉiploj malsupreniris al la maro;","Kaj kiam vesperiĝis, liaj disĉiploj malsupreniris al la maro;"],[6,17,"kaj enŝipiĝinte, ili veturis trans la maron al Kapernaum. Kaj jam estis mallume, kaj Jesuo ankoraŭ ne venis al ili.","kaj enŝipiĝinte, ili veturis trans la maron al Kapernaum. Kaj jam estis mallume, kaj Jesuo ankoraŭ ne venis al ili."],[6,18,"Kaj la maro malsereniĝis de forta vento, kiu blovis.","Kaj la maro malsereniĝis de forta vento, kiu blovis."],[6,19,"Kiam do ili remis proksimume dudek kvin ĝis tridek stadiojn, ili ekvidis Jesuon iranta sur la akvo, kaj proksimiĝanta al la ŝipo; kaj ili timis.","Kiam do ili remis proksimume dudek kvin ĝis tridek stadiojn, ili ekvidis Jesuon iranta sur la akvo, kaj proksimiĝanta al la ŝipo; kaj ili timis."],[6,20,"Sed li diris al ili: Ĝi estas mi; ne timu.","Sed li diris al ili: Ĝi estas mi; ne timu."],[6,21,"Tiam ili volonte ricevis lin en la ŝipon, kaj tuj la ŝipo albordiĝis tien, kien ili veturis.","Tiam ili volonte ricevis lin en la ŝipon, kaj tuj la ŝipo albordiĝis tien, kien ili veturis."],[6,22,"La sekvantan tagon, kiam la homamaso, kiu restis trans la maro, vidis, ke nenia ŝipeto estas tie krom unu, kaj ke Jesuo ne eniris kun la disĉiploj en la ŝipon, sed la disĉiploj solaj veturis","La sekvantan tagon, kiam la homamaso, kiu restis trans la maro, vidis, ke nenia ŝipeto estas tie krom unu, kaj ke Jesuo ne eniris kun la disĉiploj en la ŝipon, sed la disĉiploj solaj veturis"],[6,23,"(venis tamen ŝipetoj el Tiberias proksime al la loko, kie oni manĝis la panon, post kiam la Sinjoro donis dankon) —","(venis tamen ŝipetoj el Tiberias proksime al la loko, kie oni manĝis la panon, post kiam la Sinjoro donis dankon) —"],[6,24,"kiam do la homamaso vidis, ke Jesuo ne estas tie, nek liaj disĉiploj, ili ankaŭ eniris la ŝipetojn kaj veturis al Kapernaum, serĉante Jesuon.","kiam do la homamaso vidis, ke Jesuo ne estas tie, nek liaj disĉiploj, ili ankaŭ eniris la ŝipetojn kaj veturis al Kapernaum, serĉante Jesuon."],[6,25,"Kaj trovinte lin trans la maro, ili diris al li: Rabeno, kiam vi venis ĉi tien?","Kaj trovinte lin trans la maro, ili diris al li: Rabeno, kiam vi venis ĉi tien?"],[6,26,"Jesuo respondis al ili kaj diris: Vere, vere, mi diras al vi: Vi min serĉas, ne ĉar vi vidis signojn, sed ĉar vi manĝis el la panoj kaj satiĝis.","Jesuo respondis al ili kaj diris: Vere, vere, mi diras al vi: Vi min serĉas, ne ĉar vi vidis signojn, sed ĉar vi manĝis el la panoj kaj satiĝis."],[6,27,"Laboru ne por la pereema nutraĵo, sed por la nutraĵo, kiu restas ĝis eterna vivo, kiun la Filo de homo donos al vi; ĉar lin Dio, la Patro, sigelis.","Laboru ne por la pereema nutraĵo, sed por la nutraĵo, kiu restas ĝis eterna vivo, kiun la Filo de homo donos al vi; ĉar lin Dio, la Patro, sigelis."],[6,28,"Ili do diris al li: Kiel ni agu, por ke ni faru la farojn de Dio?","Ili do diris al li: Kiel ni agu, por ke ni faru la farojn de Dio?"],[6,29,"Jesuo respondis kaj diris al ili: Jen la faro de Dio: kredi al tiu, kiun Li sendis.","Jesuo respondis kaj diris al ili: Jen la faro de Dio: kredi al tiu, kiun Li sendis."],[6,30,"Ili do diris al li: Kian signon vi montras, por ke ni vidu kaj kredu al vi? kion vi faras?","Ili do diris al li: Kian signon vi montras, por ke ni vidu kaj kredu al vi? kion vi faras?"],[6,31,"Niaj patroj manĝis la manaon en la dezerto, kiel estas skribite: Li donis al ili ĉielan panon por manĝi.","Niaj patroj manĝis la manaon en la dezerto, kiel estas skribite: Li donis al ili ĉielan panon por manĝi."],[6,32,"Jesuo do diris al ili: Vere, vere, mi diras al vi: Ne Moseo donis al vi tiun ĉielan panon; sed mia Patro donas al vi la veran ĉielan panon.","Jesuo do diris al ili: Vere, vere, mi diras al vi: Ne Moseo donis al vi tiun ĉielan panon; sed mia Patro donas al vi la veran ĉielan panon."],[6,33,"Ĉar la pano de Dio estas tiu, kiu malsupreniras de la ĉielo kaj donas vivon al la mondo.","Ĉar la pano de Dio estas tiu, kiu malsupreniras de la ĉielo kaj donas vivon al la mondo."],[6,34,"Ili do diris al li: Sinjoro, ĉiam donu al ni tiun panon.","Ili do diris al li: Sinjoro, ĉiam donu al ni tiun panon."],[6,35,"Jesuo diris al ili: Mi estas la pano de vivo; kiu venas al mi, tiu neniam malsatos, kaj kiu kredas al mi, tiu neniam soifos.","Jesuo diris al ili: Mi estas la pano de vivo; kiu venas al mi, tiu neniam malsatos, kaj kiu kredas al mi, tiu neniam soifos."],[6,36,"Sed mi diris al vi, ke vi min vidis, kaj tamen vi ne kredas.","Sed mi diris al vi, ke vi min vidis, kaj tamen vi ne kredas."],[6,37,"Ĉio, kion la Patro donas al mi, venos al mi; kaj tiun, kiu venas al mi, mi ja ne elĵetos.","Ĉio, kion la Patro donas al mi, venos al mi; kaj tiun, kiu venas al mi, mi ja ne elĵetos."],[6,38,"Ĉar mi malsupreniris de la ĉielo, por plenumi ne mian volon, sed la volon de Tiu, kiu min sendis.","Ĉar mi malsupreniris de la ĉielo, por plenumi ne mian volon, sed la volon de Tiu, kiu min sendis."],[6,39,"Kaj estas la volo de Tiu, kiu min sendis, ke el ĉio, kion Li donis al mi, mi ne perdu ion, sed relevu ĝin en la lasta tago.","Kaj estas la volo de Tiu, kiu min sendis, ke el ĉio, kion Li donis al mi, mi ne perdu ion, sed relevu ĝin en la lasta tago."],[6,40,"Ĉar estas la volo de mia Patro, ke ĉiu, kiu vidas la Filon kaj kredas al li, havu eternan vivon; kaj mi levos tiun en la lasta tago.","Ĉar estas la volo de mia Patro, ke ĉiu, kiu vidas la Filon kaj kredas al li, havu eternan vivon; kaj mi levos tiun en la lasta tago."],[6,41,"La Judoj do murmuris pri li, ĉar li diris: Mi estas la pano, kiu malsupreniris de la ĉielo.","La Judoj do murmuris pri li, ĉar li diris: Mi estas la pano, kiu malsupreniris de la ĉielo."],[6,42,"Kaj ili diris: Ĉu ĉi tiu ne estas Jesuo, filo de Jozef, kies patron kaj patrinon ni konas? kiel do li diras: Mi malsupreniris de la ĉielo?","Kaj ili diris: Ĉu ĉi tiu ne estas Jesuo, filo de Jozef, kies patron kaj patrinon ni konas? kiel do li diras: Mi malsupreniris de la ĉielo?"],[6,43,"Jesuo respondis kaj diris al ili: Ne murmuru inter vi.","Jesuo respondis kaj diris al ili: Ne murmuru inter vi."],[6,44,"Neniu povas veni al mi, se la Patro, kiu min sendis, ne tiros lin; kaj mi levos tiun en la lasta tago.","Neniu povas veni al mi, se la Patro, kiu min sendis, ne tiros lin; kaj mi levos tiun en la lasta tago."],[6,45,"Estas skribite en la profetoj: Kaj ĉiuj estos instruitaj de Dio. Ĉiu do, kiu aŭdis de la Patro kaj lernis, venas al mi.","Estas skribite en la profetoj: Kaj ĉiuj estos instruitaj de Dio. Ĉiu do, kiu aŭdis de la Patro kaj lernis, venas al mi."],[6,46,"Neniu vidis la Patron, krom tiu, kiu estas de Dio; li vidis la Patron.","Neniu vidis la Patron, krom tiu, kiu estas de Dio; li vidis la Patron."],[6,47,"Vere, vere, mi diras al vi: Kiu kredas, tiu havas vivon eternan.","Vere, vere, mi diras al vi: Kiu kredas, tiu havas vivon eternan."],[6,48,"Mi estas la pano de vivo.","Mi estas la pano de vivo."],[6,49,"Viaj patroj manĝis la manaon en la dezerto, kaj mortis.","Viaj patroj manĝis la manaon en la dezerto, kaj mortis."],[6,50,"Jen la pano, kiu malsupreniris de la ĉielo, por ke oni manĝu el ĝi kaj ne mortu.","Jen la pano, kiu malsupreniris de la ĉielo, por ke oni manĝu el ĝi kaj ne mortu."],[6,51,"Mi estas la viva pano, kiu malsupreniris de la ĉielo; se iu manĝos el ĉi tiu pano, tiu vivos eterne; kaj la pano, kiun mi donos, estas mia karno, por la vivo de la mondo.","Mi estas la viva pano, kiu malsupreniris de la ĉielo; se iu manĝos el ĉi tiu pano, tiu vivos eterne; kaj la pano, kiun mi donos, estas mia karno, por la vivo de la mondo."],[6,52,"La Judoj do disputis inter si, dirante: Kiel ĉi tiu povas doni al ni sian karnon por manĝi?","La Judoj do disputis inter si, dirante: Kiel ĉi tiu povas doni al ni sian karnon por manĝi?"],[6,53,"Jesuo do diris al ili: Vere, vere, mi diras al vi: Se vi ne manĝas la karnon de la Filo de homo kaj ne trinkas lian sangon, vi ne havas en vi vivon.","Jesuo do diris al ili: Vere, vere, mi diras al vi: Se vi ne manĝas la karnon de la Filo de homo kaj ne trinkas lian sangon, vi ne havas en vi vivon."],[6,54,"Kiu manĝas mian karnon kaj trinkas mian sangon, tiu havas eternan vivon; kaj mi levos tiun en la lasta tago.","Kiu manĝas mian karnon kaj trinkas mian sangon, tiu havas eternan vivon; kaj mi levos tiun en la lasta tago."],[6,55,"Ĉar mia karno estas vera manĝaĵo, kaj mia sango estas vera trinkaĵo.","Ĉar mia karno estas vera manĝaĵo, kaj mia sango estas vera trinkaĵo."],[6,56,"Kiu manĝas mian karnon kaj trinkas mian sangon, tiu restas en mi, kaj mi en li.","Kiu manĝas mian karnon kaj trinkas mian sangon, tiu restas en mi, kaj mi en li."],[6,57,"Kiel la vivanta Patro min sendis, kaj mi vivas pro la Patro, tiel, kiu min manĝas, tiu vivos pro mi.","Kiel la vivanta Patro min sendis, kaj mi vivas pro la Patro, tiel, kiu min manĝas, tiu vivos pro mi."],[6,58,"Jen la pano, kiu malsupreniris de la ĉielo; ne kiel la patroj manĝis, kaj mortis; kiu manĝas ĉi tiun panon, tiu vivos eterne.","Jen la pano, kiu malsupreniris de la ĉielo; ne kiel la patroj manĝis, kaj mortis; kiu manĝas ĉi tiun panon, tiu vivos eterne."],[6,59,"Tion li diris en la sinagogo, instruante en Kapernaum.","Tion li diris en la sinagogo, instruante en Kapernaum."],[6,60,"Multaj do el liaj disĉiploj, aŭdinte tion, diris: Malfacila estas tiu parolo; kiu povas lin aŭskulti?","Multaj do el liaj disĉiploj, aŭdinte tion, diris: Malfacila estas tiu parolo; kiu povas lin aŭskulti?"],[6,61,"Sed Jesuo, sciante en si mem, ke liaj disĉiploj pri tio murmuris, diris al ili: Ĉu tio faligas vin?","Sed Jesuo, sciante en si mem, ke liaj disĉiploj pri tio murmuris, diris al ili: Ĉu tio faligas vin?"],[6,62,"Kio do, se vi vidos la Filon de homo supreniranta tien, kie li antaŭe estis?","Kio do, se vi vidos la Filon de homo supreniranta tien, kie li antaŭe estis?"],[6,63,"La spirito estas la viviganto; la karno nenion utilas; la vortoj, kiujn mi diris al vi, estas spirito kaj estas vivo.","La spirito estas la viviganto; la karno nenion utilas; la vortoj, kiujn mi diris al vi, estas spirito kaj estas vivo."],[6,64,"Sed estas iuj el vi, kiuj ne kredas. Ĉar Jesuo sciis de la komenco, kiuj estas la nekredantoj, kaj kiu lin perfidos.","Sed estas iuj el vi, kiuj ne kredas. Ĉar Jesuo sciis de la komenco, kiuj estas la nekredantoj, kaj kiu lin perfidos."],[6,65,"Kaj li diris: Tial mi diris al vi, ke neniu povas veni al mi, se tio ne estas donita al li de mia Patro.","Kaj li diris: Tial mi diris al vi, ke neniu povas veni al mi, se tio ne estas donita al li de mia Patro."],[6,66,"Ĉe tio multaj el liaj disĉiploj iris returne kaj lin ne plu akompanis.","Ĉe tio multaj el liaj disĉiploj iris returne kaj lin ne plu akompanis."],[6,67,"Jesuo do diris al la dek du: Ĉu vi ankaŭ volas foriri?","Jesuo do diris al la dek du: Ĉu vi ankaŭ volas foriri?"],[6,68,"Simon Petro respondis al li: Sinjoro, al kiu ni iru? vi havas la vortojn de eterna vivo.","Simon Petro respondis al li: Sinjoro, al kiu ni iru? vi havas la vortojn de eterna vivo."],[6,69,"Kaj ni ekkredis kaj scias, ke vi estas la Sanktulo de Dio.","Kaj ni ekkredis kaj scias, ke vi estas la Sanktulo de Dio."],[6,70,"Respondis al ili Jesuo: Ĉu mi ne elektis vin la dek du, kaj unu el vi estas diablo?","Respondis al ili Jesuo: Ĉu mi ne elektis vin la dek du, kaj unu el vi estas diablo?"],[6,71,"Li parolis pri Judas Iskariota, filo de Simon; ĉar tiu, unu el la dek du, estis perfidonta lin.","Li parolis pri Judas Iskariota, filo de Simon; ĉar tiu, unu el la dek du, estis perfidonta lin."],[7,1,"Kaj post tio Jesuo iradis en Galileo; ĉar li ne volis iradi en Judujo, ĉar la Judoj celis mortigi lin.","Kaj post tio Jesuo iradis en Galileo; ĉar li ne volis iradi en Judujo, ĉar la Judoj celis mortigi lin."],[7,2,"La festo de la Judoj, nomata la festo de laŭboj, proksimiĝis.","La festo de la Judoj, nomata la festo de laŭboj, proksimiĝis."],[7,3,"Liaj fratoj do diris al li: Transiru de ĉi tie, kaj iru en Judujon, por ke viaj disĉiploj ankaŭ vidu viajn farojn, kiujn vi faras.","Liaj fratoj do diris al li: Transiru de ĉi tie, kaj iru en Judujon, por ke viaj disĉiploj ankaŭ vidu viajn farojn, kiujn vi faras."],[7,4,"Ĉar neniu faras ion sekrete, kaj celas mem esti publike konata. Se vi faras tiajn farojn, montru vin al la mondo.","Ĉar neniu faras ion sekrete, kaj celas mem esti publike konata. Se vi faras tiajn farojn, montru vin al la mondo."],[7,5,"Ĉar liaj fratoj mem ne kredis al li.","Ĉar liaj fratoj mem ne kredis al li."],[7,6,"Jesuo do diris al ili: Mia tempo ankoraŭ ne venis; sed via tempo ĉiam estas preta.","Jesuo do diris al ili: Mia tempo ankoraŭ ne venis; sed via tempo ĉiam estas preta."],[7,7,"La mondo ne povas vin malami; sed min ĝi malamas, ĉar mi atestas pri ĝi, ke ĝiaj faroj estas malbonaj.","La mondo ne povas vin malami; sed min ĝi malamas, ĉar mi atestas pri ĝi, ke ĝiaj faroj estas malbonaj."],[7,8,"Supreniru vi al la festo; mi ankoraŭ ne supreniras al la festo, ĉar mia tempo ankoraŭ ne maturiĝis.","Supreniru vi al la festo; mi ankoraŭ ne supreniras al la festo, ĉar mia tempo ankoraŭ ne maturiĝis."],[7,9,"Dirinte tion al ili, li restis ankoraŭ en Galileo.","Dirinte tion al ili, li restis ankoraŭ en Galileo."],[7,10,"Sed kiam liaj fratoj supreniris al la festo, tiam li ankaŭ supreniris, ne malkaŝe, sed kvazaŭ sekrete.","Sed kiam liaj fratoj supreniris al la festo, tiam li ankaŭ supreniris, ne malkaŝe, sed kvazaŭ sekrete."],[7,11,"La Judoj do serĉis lin ĉe la festo, kaj diris: Kie li estas?","La Judoj do serĉis lin ĉe la festo, kaj diris: Kie li estas?"],[7,12,"Kaj fariĝis multe da murmurado inter la homamasoj pri li. Unuj diris: Li estas bonulo; aliaj diris: Ne, sed li erarigas la amason.","Kaj fariĝis multe da murmurado inter la homamasoj pri li. Unuj diris: Li estas bonulo; aliaj diris: Ne, sed li erarigas la amason."],[7,13,"Tamen neniu parolis malkaŝe pri li, pro timo antaŭ la Judoj.","Tamen neniu parolis malkaŝe pri li, pro timo antaŭ la Judoj."],[7,14,"Sed ĉirkaŭ la mezo de la festo, Jesuo supreniris en la templon kaj instruis.","Sed ĉirkaŭ la mezo de la festo, Jesuo supreniris en la templon kaj instruis."],[7,15,"Kaj la Judoj miris, dirante: Kiel ĉi tiu scias skribojn, neniam lerninte?","Kaj la Judoj miris, dirante: Kiel ĉi tiu scias skribojn, neniam lerninte?"],[7,16,"Jesuo respondis al ili kaj diris: Mia instruado estas ne mia, sed Ties, kiu min sendis.","Jesuo respondis al ili kaj diris: Mia instruado estas ne mia, sed Ties, kiu min sendis."],[7,17,"Se iu volas plenumi Lian volon, tiu scios pri la instruado, ĉu ĝi estas de Dio, aŭ ĉu mi parolas nur el mi mem.","Se iu volas plenumi Lian volon, tiu scios pri la instruado, ĉu ĝi estas de Dio, aŭ ĉu mi parolas nur el mi mem."],[7,18,"Kiu parolas el si mem, tiu celas sian propran gloron; sed kiu celas la gloron de Tiu, kiu lin sendis, tiu estas verema, kaj maljusteco ne estas en li.","Kiu parolas el si mem, tiu celas sian propran gloron; sed kiu celas la gloron de Tiu, kiu lin sendis, tiu estas verema, kaj maljusteco ne estas en li."],[7,19,"Ĉu Moseo ne donis al vi la leĝon? kaj neniu el vi observas la leĝon. Kial vi celas mortigi min?","Ĉu Moseo ne donis al vi la leĝon? kaj neniu el vi observas la leĝon. Kial vi celas mortigi min?"],[7,20,"La homamaso respondis: Vi havas demonon; kiu celas mortigi vin?","La homamaso respondis: Vi havas demonon; kiu celas mortigi vin?"],[7,21,"Jesuo respondis kaj diris al ili: Mi faris unu faron, kaj vi ĉiuj miras pro tio.","Jesuo respondis kaj diris al ili: Mi faris unu faron, kaj vi ĉiuj miras pro tio."],[7,22,"Moseo donis al vi cirkumcidon (tamen ĝi estas ne de Moseo, sed de la patroj); kaj vi en la sabato cirkumcidas viron.","Moseo donis al vi cirkumcidon (tamen ĝi estas ne de Moseo, sed de la patroj); kaj vi en la sabato cirkumcidas viron."],[7,23,"Se viro estas cirkumcidata en la sabato, por ke oni ne malobeu al la Mosea leĝo, ĉu vi koleras kontraŭ mi pro tio, ke mi tute sanigis viron en sabato?","Se viro estas cirkumcidata en la sabato, por ke oni ne malobeu al la Mosea leĝo, ĉu vi koleras kontraŭ mi pro tio, ke mi tute sanigis viron en sabato?"],[7,24,"Ne juĝu laŭ ŝajno, sed juĝu justan juĝon.","Ne juĝu laŭ ŝajno, sed juĝu justan juĝon."],[7,25,"Tiam kelkaj el la Jerusalemanoj diris: Ĉu li ne estas tiu, kiun oni celas mortigi?","Tiam kelkaj el la Jerusalemanoj diris: Ĉu li ne estas tiu, kiun oni celas mortigi?"],[7,26,"Kaj jen li parolas maltime, kaj ili diras al li nenion. Ĉu eble la estraro certe scias, ke ĉi tiu estas la Kristo?","Kaj jen li parolas maltime, kaj ili diras al li nenion. Ĉu eble la estraro certe scias, ke ĉi tiu estas la Kristo?"],[7,27,"Tamen ni scias, de kie ĉi tiu estas; sed kiam la Kristo venos, neniu scios, de kie li estas.","Tamen ni scias, de kie ĉi tiu estas; sed kiam la Kristo venos, neniu scios, de kie li estas."],[7,28,"Jesuo do, instruante en la templo, ekkriis kaj diris: Vi jam min konas, kaj vi ankaŭ scias, de kie mi estas; kaj mi ne venis de mi mem; sed Tiu, kiu min sendis, estas vera, sed Lin vi ne konas.","Jesuo do, instruante en la templo, ekkriis kaj diris: Vi jam min konas, kaj vi ankaŭ scias, de kie mi estas; kaj mi ne venis de mi mem; sed Tiu, kiu min sendis, estas vera, sed Lin vi ne konas."],[7,29,"Mi Lin konas, ĉar mi estas de Li; kaj Li min sendis.","Mi Lin konas, ĉar mi estas de Li; kaj Li min sendis."],[7,30,"Oni do celis kapti lin; sed neniu metis sur lin sian manon, ĉar lia horo ankoraŭ ne venis.","Oni do celis kapti lin; sed neniu metis sur lin sian manon, ĉar lia horo ankoraŭ ne venis."],[7,31,"Kaj multaj el la homamaso kredis al li, kaj diris: Kiam la Kristo venos, ĉu li faros pli multe da signoj, ol ĉi tiu faris?","Kaj multaj el la homamaso kredis al li, kaj diris: Kiam la Kristo venos, ĉu li faros pli multe da signoj, ol ĉi tiu faris?"],[7,32,"La Fariseoj aŭdis la amason murmuranta tion pri li, kaj la ĉefpastroj kaj la Fariseoj sendis oficistojn, por kapti lin.","La Fariseoj aŭdis la amason murmuranta tion pri li, kaj la ĉefpastroj kaj la Fariseoj sendis oficistojn, por kapti lin."],[7,33,"Jesuo do diris al ili: Ankoraŭ iom da tempo mi estas kun vi, kaj mi foriras al Tiu, kiu min sendis.","Jesuo do diris al ili: Ankoraŭ iom da tempo mi estas kun vi, kaj mi foriras al Tiu, kiu min sendis."],[7,34,"Vi min serĉos kaj ne trovos; kaj kie mi estas, vi ne povas tien veni.","Vi min serĉos kaj ne trovos; kaj kie mi estas, vi ne povas tien veni."],[7,35,"Tial la Judoj inter si diris: Kien ĉi tiu iros, ke ni lin ne trovos? ĉu li iros al la disĵetitoj inter la Grekoj kaj instruos la Grekojn?","Tial la Judoj inter si diris: Kien ĉi tiu iros, ke ni lin ne trovos? ĉu li iros al la disĵetitoj inter la Grekoj kaj instruos la Grekojn?"],[7,36,"Kia diro estas tio, kion li diris: Vi min serĉos kaj ne trovos, kaj: Kie mi estas, vi ne povas tien veni?","Kia diro estas tio, kion li diris: Vi min serĉos kaj ne trovos, kaj: Kie mi estas, vi ne povas tien veni?"],[7,37,"En la lasta tago, la granda tago de la festo, Jesuo staris kaj kriis, dirante: Se iu soifas, tiu venu al mi kaj trinku.","En la lasta tago, la granda tago de la festo, Jesuo staris kaj kriis, dirante: Se iu soifas, tiu venu al mi kaj trinku."],[7,38,"Kiu kredas al mi, kiel la Skribo diris, el ties ventro fluos riveroj da viva akvo.","Kiu kredas al mi, kiel la Skribo diris, el ties ventro fluos riveroj da viva akvo."],[7,39,"Sed tion li diris pri la Spirito, kiun estis ricevontaj tiuj, kiuj kredis al li; ĉar la Spirito ankoraŭ ne estis donita, ĉar Jesuo ankoraŭ ne estis glorita.","Sed tion li diris pri la Spirito, kiun estis ricevontaj tiuj, kiuj kredis al li; ĉar la Spirito ankoraŭ ne estis donita, ĉar Jesuo ankoraŭ ne estis glorita."],[7,40,"Iuj do el la homamaso, aŭdinte tiujn vortojn, diris: Vere ĉi tiu estas la Profeto.","Iuj do el la homamaso, aŭdinte tiujn vortojn, diris: Vere ĉi tiu estas la Profeto."],[7,41,"Aliaj diris: Ĉi tiu estas la Kristo. Sed kelkaj diris: Tamen ĉu el Galileo la Kristo venas?","Aliaj diris: Ĉi tiu estas la Kristo. Sed kelkaj diris: Tamen ĉu el Galileo la Kristo venas?"],[7,42,"Ĉu la Skribo ne diris, ke la Kristo venas el la idaro de David kaj el la vilaĝo Bet-Leĥem, kie David estis?","Ĉu la Skribo ne diris, ke la Kristo venas el la idaro de David kaj el la vilaĝo Bet-Leĥem, kie David estis?"],[7,43,"Tiel fariĝis pro li malkonsento inter la homamaso.","Tiel fariĝis pro li malkonsento inter la homamaso."],[7,44,"Kaj iuj el ili volis kapti lin, sed neniu metis sur lin la manojn.","Kaj iuj el ili volis kapti lin, sed neniu metis sur lin la manojn."],[7,45,"Tiam la oficistoj revenis al la ĉefpastroj kaj Fariseoj, kaj ĉi tiuj diris al ili: Kial vi lin ne alkondukis?","Tiam la oficistoj revenis al la ĉefpastroj kaj Fariseoj, kaj ĉi tiuj diris al ili: Kial vi lin ne alkondukis?"],[7,46,"Respondis la oficistoj: Ankoraŭ neniam tiel parolis homo.","Respondis la oficistoj: Ankoraŭ neniam tiel parolis homo."],[7,47,"La Fariseoj do respondis al ili: Ĉu vi ankaŭ estas erarigitaj?","La Fariseoj do respondis al ili: Ĉu vi ankaŭ estas erarigitaj?"],[7,48,"Ĉu kredis al li iu el la regantoj, aŭ el la Fariseoj?","Ĉu kredis al li iu el la regantoj, aŭ el la Fariseoj?"],[7,49,"Sed tiu homamaso, kiu ne scias la leĝon, estas malbenita.","Sed tiu homamaso, kiu ne scias la leĝon, estas malbenita."],[7,50,"Tiam Nikodemo (tiu, kiu venis nokte al Jesuo, estante unu el ili) diris al ili:","Tiam Nikodemo (tiu, kiu venis nokte al Jesuo, estante unu el ili) diris al ili:"],[7,51,"Ĉu nia leĝo juĝas iun, se antaŭe oni ne aŭskultis lin, kaj ne sciiĝis, kion li faras?","Ĉu nia leĝo juĝas iun, se antaŭe oni ne aŭskultis lin, kaj ne sciiĝis, kion li faras?"],[7,52,"Ili respondis kaj diris al li: Ĉu vi ankaŭ estas el Galileo? Esploru, kaj vidu, ke neniam el Galileo venas profeto.","Ili respondis kaj diris al li: Ĉu vi ankaŭ estas el Galileo? Esploru, kaj vidu, ke neniam el Galileo venas profeto."],[7,53,"Kaj ĉiu iris al sia domo;","Kaj ĉiu iris al sia domo;"],[8,1,"[sed Jesuo iris al la monto Olivarba.","[sed Jesuo iris al la monto Olivarba."],[8,2,"Kaj li revenis frumatene en la templon, kaj la tuta popolo venis al li; kaj li sidiĝis, kaj instruadis ilin.","Kaj li revenis frumatene en la templon, kaj la tuta popolo venis al li; kaj li sidiĝis, kaj instruadis ilin."],[8,3,"Kaj la skribistoj kaj Fariseoj alkondukis virinon, kaptitan en adulto; kaj stariginte ŝin en la mezo,","Kaj la skribistoj kaj Fariseoj alkondukis virinon, kaptitan en adulto; kaj stariginte ŝin en la mezo,"],[8,4,"ili diris al li: Majstro, ĉi tiu virino estas kaptita adultante, en la faro mem.","ili diris al li: Majstro, ĉi tiu virino estas kaptita adultante, en la faro mem."],[8,5,"En la leĝo Moseo ordonis al ni tiajn ŝtonmortigi; sed kion vi diras?","En la leĝo Moseo ordonis al ni tiajn ŝtonmortigi; sed kion vi diras?"],[8,6,"Kaj tion ili diris, provante lin, por povi lin akuzi pri io. Sed Jesuo sin klinis, kaj per fingro skribis sur la tero.","Kaj tion ili diris, provante lin, por povi lin akuzi pri io. Sed Jesuo sin klinis, kaj per fingro skribis sur la tero."],[8,7,"Kiam ili ankoraŭ demandis lin, li leviĝis, kaj diris al ili: Kiu el vi estas senpeka, tiu unua ĵetu sur ŝin ŝtonon.","Kiam ili ankoraŭ demandis lin, li leviĝis, kaj diris al ili: Kiu el vi estas senpeka, tiu unua ĵetu sur ŝin ŝtonon."],[8,8,"Kaj denove li sin klinis kaj skribis sur la tero.","Kaj denove li sin klinis kaj skribis sur la tero."],[8,9,"Sed aŭdinte tion, ili eliris unu post alia, komencante de la plej maljunaj kaj ĝis la lastaj; kaj restis Jesuo sola, kaj la virino staranta en la mezo.","Sed aŭdinte tion, ili eliris unu post alia, komencante de la plej maljunaj kaj ĝis la lastaj; kaj restis Jesuo sola, kaj la virino staranta en la mezo."],[8,10,"Kaj Jesuo leviĝis, kaj diris al ŝi: Virino, kie ili estas? ĉu neniu vin kondamnis?","Kaj Jesuo leviĝis, kaj diris al ŝi: Virino, kie ili estas? ĉu neniu vin kondamnis?"],[8,11,"Kaj ŝi diris: Neniu, Sinjoro. Jesuo diris al ŝi: Ankaŭ mi vin ne kondamnas; iru, kaj de nun ne plu peku.]","Kaj ŝi diris: Neniu, Sinjoro. Jesuo diris al ŝi: Ankaŭ mi vin ne kondamnas; iru, kaj de nun ne plu peku.]"],[8,12,"Jesuo denove parolis al ili, dirante: Mi estas la lumo de la mondo; kiu min sekvas, tiu ne iros en mallumo, sed havos la lumon de la vivo.","Jesuo denove parolis al ili, dirante: Mi estas la lumo de la mondo; kiu min sekvas, tiu ne iros en mallumo, sed havos la lumon de la vivo."],[8,13,"La Fariseoj do diris al li: Vi atestas pri vi mem; via atesto ne estas vera.","La Fariseoj do diris al li: Vi atestas pri vi mem; via atesto ne estas vera."],[8,14,"Jesuo respondis kaj diris al ili: Kvankam mi atestas pri mi mem, tamen mia atesto estas vera; ĉar mi scias, de kie mi venis, kaj kien mi iras; sed vi ne scias, de kie mi venis, nek kien mi iras.","Jesuo respondis kaj diris al ili: Kvankam mi atestas pri mi mem, tamen mia atesto estas vera; ĉar mi scias, de kie mi venis, kaj kien mi iras; sed vi ne scias, de kie mi venis, nek kien mi iras."],[8,15,"Vi juĝas laŭ la karno; mi juĝas neniun.","Vi juĝas laŭ la karno; mi juĝas neniun."],[8,16,"Tamen, eĉ se mi juĝas, mia juĝo estas vera; ĉar mi ne estas sola, sed mi kaj la Patro, kiu min sendis.","Tamen, eĉ se mi juĝas, mia juĝo estas vera; ĉar mi ne estas sola, sed mi kaj la Patro, kiu min sendis."],[8,17,"Estas ja skribite en via leĝo, ke la atesto de du homoj estas vera.","Estas ja skribite en via leĝo, ke la atesto de du homoj estas vera."],[8,18,"Mi estas atestanto pri mi mem, kaj la Patro, kiu min sendis, atestas pri mi.","Mi estas atestanto pri mi mem, kaj la Patro, kiu min sendis, atestas pri mi."],[8,19,"Ili do diris al li: Kie estas via Patro? Respondis Jesuo: Vi konas nek min, nek mian Patron; se vi konus min, vi konus ankaŭ mian Patron.","Ili do diris al li: Kie estas via Patro? Respondis Jesuo: Vi konas nek min, nek mian Patron; se vi konus min, vi konus ankaŭ mian Patron."],[8,20,"Tiujn vortojn Jesuo parolis en la trezorejo, dum li instruis en la templo; kaj neniu arestis lin, ĉar lia horo ankoraŭ ne venis.","Tiujn vortojn Jesuo parolis en la trezorejo, dum li instruis en la templo; kaj neniu arestis lin, ĉar lia horo ankoraŭ ne venis."],[8,21,"Jesuo do denove diris al ili: Mi foriras, kaj vi serĉos min, kaj vi mortos en via peko; kien mi iras, tien vi ne povas veni.","Jesuo do denove diris al ili: Mi foriras, kaj vi serĉos min, kaj vi mortos en via peko; kien mi iras, tien vi ne povas veni."],[8,22,"La Judoj do diris: Ĉu li sin mortigos? ĉar li diras: Kien mi iras, tien vi ne povas veni.","La Judoj do diris: Ĉu li sin mortigos? ĉar li diras: Kien mi iras, tien vi ne povas veni."],[8,23,"Kaj li diris al ili: Vi estas de malsupre, mi estas de supre; vi estas de ĉi tiu mondo, mi ne estas de ĉi tiu mondo.","Kaj li diris al ili: Vi estas de malsupre, mi estas de supre; vi estas de ĉi tiu mondo, mi ne estas de ĉi tiu mondo."],[8,24,"Mi tial diris al vi, ke vi mortos en viaj pekoj; ĉar se vi ne kredos, ke mi estas, vi mortos en viaj pekoj.","Mi tial diris al vi, ke vi mortos en viaj pekoj; ĉar se vi ne kredos, ke mi estas, vi mortos en viaj pekoj."],[8,25,"Ili do diris al li: Kiu vi estas? Jesuo diris al ili: Laŭ tio, kion mi diradis al vi de la komenco.","Ili do diris al li: Kiu vi estas? Jesuo diris al ili: Laŭ tio, kion mi diradis al vi de la komenco."],[8,26,"Mi havas multon por diri kaj juĝi pri vi; sed Tiu, kiu min sendis, estas vera; kaj tion, kion mi aŭdis de Li, mi parolas al la mondo.","Mi havas multon por diri kaj juĝi pri vi; sed Tiu, kiu min sendis, estas vera; kaj tion, kion mi aŭdis de Li, mi parolas al la mondo."],[8,27,"Ili ne komprenis, ke li parolas al ili pri la Patro.","Ili ne komprenis, ke li parolas al ili pri la Patro."],[8,28,"Jesuo do diris: Kiam vi levos la Filon de homo, tiam vi scios, ke mi estas, kaj ke mi ne faras ion per mi mem; sed kiel la Patro instruis min, tion mi parolas.","Jesuo do diris: Kiam vi levos la Filon de homo, tiam vi scios, ke mi estas, kaj ke mi ne faras ion per mi mem; sed kiel la Patro instruis min, tion mi parolas."],[8,29,"Kaj Tiu, kiu min sendis, estas kun mi; Li ne lasis min sola; ĉar mi ĉiam faras tion, kio plaĉas al Li.","Kaj Tiu, kiu min sendis, estas kun mi; Li ne lasis min sola; ĉar mi ĉiam faras tion, kio plaĉas al Li."],[8,30,"Dum li parolis tion, multaj kredis al li.","Dum li parolis tion, multaj kredis al li."],[8,31,"Jesuo do diris al la Judoj, kiuj kredis al li: Se vi restos en mia vorto, vi estas vere miaj disĉiploj;","Jesuo do diris al la Judoj, kiuj kredis al li: Se vi restos en mia vorto, vi estas vere miaj disĉiploj;"],[8,32,"kaj vi scios la veron, kaj la vero vin liberigos.","kaj vi scios la veron, kaj la vero vin liberigos."],[8,33,"Ili respondis al li: Ni estas idaro de Abraham, kaj ankoraŭ al neniu ni estis sklavoj; kial vi diras: Vi estos liberigitaj?","Ili respondis al li: Ni estas idaro de Abraham, kaj ankoraŭ al neniu ni estis sklavoj; kial vi diras: Vi estos liberigitaj?"],[8,34,"Jesuo respondis al ili: Vere, vere, mi diras al vi: Ĉiu, kiu faras pekon, estas sklavo de peko.","Jesuo respondis al ili: Vere, vere, mi diras al vi: Ĉiu, kiu faras pekon, estas sklavo de peko."],[8,35,"Kaj la sklavo ne ĉiam restas en la domo, sed la filo ĉiam restas.","Kaj la sklavo ne ĉiam restas en la domo, sed la filo ĉiam restas."],[8,36,"Se do la Filo vin liberigos, vi estos efektive liberaj.","Se do la Filo vin liberigos, vi estos efektive liberaj."],[8,37,"Mi scias, ke vi estas idaro de Abraham; sed vi celas mortigi min, ĉar mia vorto ne progresas en vi.","Mi scias, ke vi estas idaro de Abraham; sed vi celas mortigi min, ĉar mia vorto ne progresas en vi."],[8,38,"Mi parolas tion, kion mi vidis ĉe mia Patro; kaj vi ankaŭ faras tion, kion vi vidis ĉe via patro.","Mi parolas tion, kion mi vidis ĉe mia Patro; kaj vi ankaŭ faras tion, kion vi vidis ĉe via patro."],[8,39,"Ili respondis kaj diris al li: Nia patro estas Abraham. Jesuo diris al ili: Se vi estus Abrahamidoj, vi farus la farojn de Abraham.","Ili respondis kaj diris al li: Nia patro estas Abraham. Jesuo diris al ili: Se vi estus Abrahamidoj, vi farus la farojn de Abraham."],[8,40,"Sed nun vi celas mortigi min, homon, kiu parolis al vi la veron, kiun mi aŭdis de Dio; tion Abraham ne faris.","Sed nun vi celas mortigi min, homon, kiu parolis al vi la veron, kiun mi aŭdis de Dio; tion Abraham ne faris."],[8,41,"Vi faras la farojn de via patro. Tiam ili diris al li: Ni ne naskiĝis per malĉasteco; unu Patron ni havas, Dion.","Vi faras la farojn de via patro. Tiam ili diris al li: Ni ne naskiĝis per malĉasteco; unu Patron ni havas, Dion."],[8,42,"Jesuo diris al ili: Se Dio estus via Patro, vi min amus; ĉar de Dio mi elvenis, kaj estas veninta; ĉar mi ne venis de mi mem, sed Li min sendis.","Jesuo diris al ili: Se Dio estus via Patro, vi min amus; ĉar de Dio mi elvenis, kaj estas veninta; ĉar mi ne venis de mi mem, sed Li min sendis."],[8,43,"Kial vi ne komprenas mian parolon? Tial, ke vi ne povas aŭdi mian vorton.","Kial vi ne komprenas mian parolon? Tial, ke vi ne povas aŭdi mian vorton."],[8,44,"Vi estas de patro, la diablo, kaj vi volas fari la dezirojn de via patro. Li estis hommortiganto de la komenco, kaj ne staras en la vero, ĉar vero ne estas en li. Kiam li parolas mensogon, li parolas sian propraĵon, ĉar li estas mensoganto, kaj la patro de ĝi.","Vi estas de patro, la diablo, kaj vi volas fari la dezirojn de via patro. Li estis hommortiganto de la komenco, kaj ne staras en la vero, ĉar vero ne estas en li. Kiam li parolas mensogon, li parolas sian propraĵon, ĉar li estas mensoganto, kaj la patro de ĝi."],[8,45,"Sed tial, ke mi parolas la veron, vi ne kredas al mi.","Sed tial, ke mi parolas la veron, vi ne kredas al mi."],[8,46,"Kiu el vi pruvas kontraŭ mi pekon? Se mi diras la veron, kial vi ne kredas al mi?","Kiu el vi pruvas kontraŭ mi pekon? Se mi diras la veron, kial vi ne kredas al mi?"],[8,47,"Kiu estas de Dio, tiu aŭskultas la vortojn de Dio; vi ne aŭskultas, ĉar vi ne estas el Dio.","Kiu estas de Dio, tiu aŭskultas la vortojn de Dio; vi ne aŭskultas, ĉar vi ne estas el Dio."],[8,48,"La Judoj respondis kaj diris al li: Ĉu ne prave ni diras, ke vi estas Samariano kaj havas demonon?","La Judoj respondis kaj diris al li: Ĉu ne prave ni diras, ke vi estas Samariano kaj havas demonon?"],[8,49,"Jesuo respondis: Mi ne havas demonon; sed mi honoras mian Patron, kaj vi min malhonoras.","Jesuo respondis: Mi ne havas demonon; sed mi honoras mian Patron, kaj vi min malhonoras."],[8,50,"Sed mi ne serĉas mian gloron: estas Unu, kiu serĉas kaj juĝas.","Sed mi ne serĉas mian gloron: estas Unu, kiu serĉas kaj juĝas."],[8,51,"Vere, vere, mi diras al vi: Se iu observos mian vorton, tiu la morton neniam vidos.","Vere, vere, mi diras al vi: Se iu observos mian vorton, tiu la morton neniam vidos."],[8,52,"La Judoj diris al li: Nun ni scias, ke vi havas demonon. Mortis Abraham, kaj la profetoj; kaj vi diras: Se iu observos mian vorton, tiu la morton neniam gustumos.","La Judoj diris al li: Nun ni scias, ke vi havas demonon. Mortis Abraham, kaj la profetoj; kaj vi diras: Se iu observos mian vorton, tiu la morton neniam gustumos."],[8,53,"Ĉu vi estas pli granda ol nia patro Abraham, kiu mortis? kaj la profetoj mortis; kiu vi pretendas esti?","Ĉu vi estas pli granda ol nia patro Abraham, kiu mortis? kaj la profetoj mortis; kiu vi pretendas esti?"],[8,54,"Jesuo respondis: Se mi gloros min mem, mia gloro estas nenio; Tiu, kiu min gloras, estas mia Patro, pri kiu vi diras, ke Li estas via Dio;","Jesuo respondis: Se mi gloros min mem, mia gloro estas nenio; Tiu, kiu min gloras, estas mia Patro, pri kiu vi diras, ke Li estas via Dio;"],[8,55,"kaj vi Lin ne konis, sed mi Lin konas; kaj se mi diros, ke mi Lin ne konas, mi estos, kiel vi, mensoganto; sed mi Lin konas, kaj observas Lian vorton.","kaj vi Lin ne konis, sed mi Lin konas; kaj se mi diros, ke mi Lin ne konas, mi estos, kiel vi, mensoganto; sed mi Lin konas, kaj observas Lian vorton."],[8,56,"Via patro Abraham ĝojegis vidi mian tagon, kaj li vidis kaj estis ravita.","Via patro Abraham ĝojegis vidi mian tagon, kaj li vidis kaj estis ravita."],[8,57,"Tiam la Judoj diris al li: Vi ankoraŭ ne estas kvindekjara, kaj ĉu vi vidis Abrahamon?","Tiam la Judoj diris al li: Vi ankoraŭ ne estas kvindekjara, kaj ĉu vi vidis Abrahamon?"],[8,58,"Jesuo diris al ili: Vere, vere, mi diras al vi: Antaŭ ol naskiĝis Abraham, mi ekzistas.","Jesuo diris al ili: Vere, vere, mi diras al vi: Antaŭ ol naskiĝis Abraham, mi ekzistas."],[8,59,"Tiam ili prenis ŝtonojn, por ĵeti sur lin; sed Jesuo sin kaŝis, kaj eliris el la templo.","Tiam ili prenis ŝtonojn, por ĵeti sur lin; sed Jesuo sin kaŝis, kaj eliris el la templo."],[9,1,"Kaj preterirante, li vidis viron blindan de post la naskiĝo.","Kaj preterirante, li vidis viron blindan de post la naskiĝo."],[9,2,"Kaj liaj disĉiploj demandis lin, dirante: Rabeno, kiu do pekis, ĉi tiu viro, aŭ liaj gepatroj, ke li naskiĝis blinda?","Kaj liaj disĉiploj demandis lin, dirante: Rabeno, kiu do pekis, ĉi tiu viro, aŭ liaj gepatroj, ke li naskiĝis blinda?"],[9,3,"Jesuo respondis: Nek ĉi tiu viro pekis, nek liaj gepatroj; sed por ke la faroj de Dio aperu en li.","Jesuo respondis: Nek ĉi tiu viro pekis, nek liaj gepatroj; sed por ke la faroj de Dio aperu en li."],[9,4,"Dum estas tago, mi devas prilabori la farojn de Tiu, kiu min sendis; venas la nokto, kiam neniu povas labori.","Dum estas tago, mi devas prilabori la farojn de Tiu, kiu min sendis; venas la nokto, kiam neniu povas labori."],[9,5,"Dum mi estas en la mondo, mi estas la lumo de la mondo.","Dum mi estas en la mondo, mi estas la lumo de la mondo."],[9,6,"Dirinte tion, li kraĉis sur la teron, kaj faris el la kraĉaĵo koton, kaj ŝmiris per la koto la okulojn de la blindulo,","Dirinte tion, li kraĉis sur la teron, kaj faris el la kraĉaĵo koton, kaj ŝmiris per la koto la okulojn de la blindulo,"],[9,7,"kaj diris al li: Iru, lavu vin en la lageto de Ŝiloaĥ (tio estas, Sendito). Li do foriris, kaj sin lavis, kaj revenis vidanta.","kaj diris al li: Iru, lavu vin en la lageto de Ŝiloaĥ (tio estas, Sendito). Li do foriris, kaj sin lavis, kaj revenis vidanta."],[9,8,"La najbaroj do, kaj tiuj, kiuj antaŭe vidis lin, ke li estas almozulo, diris: Ĉu ĉi tiu ne estas tiu, kiu sidis kaj petis almozojn?","La najbaroj do, kaj tiuj, kiuj antaŭe vidis lin, ke li estas almozulo, diris: Ĉu ĉi tiu ne estas tiu, kiu sidis kaj petis almozojn?"],[9,9,"Unuj diris: Li estas; aliaj diris: Ne, sed li estas simila al tiu. Li diris: Tiu mi estas.","Unuj diris: Li estas; aliaj diris: Ne, sed li estas simila al tiu. Li diris: Tiu mi estas."],[9,10,"Ili do diris al li: Kiamaniere viaj okuloj malfermiĝis?","Ili do diris al li: Kiamaniere viaj okuloj malfermiĝis?"],[9,11,"Li respondis kaj diris: La homo, nomata Jesuo, faris koton kaj ŝmiris miajn okulojn, kaj diris al mi: Iru al Ŝiloaĥ, kaj vin lavu; kaj mi iris, kaj lavis min, kaj mi ricevis vidpovon.","Li respondis kaj diris: La homo, nomata Jesuo, faris koton kaj ŝmiris miajn okulojn, kaj diris al mi: Iru al Ŝiloaĥ, kaj vin lavu; kaj mi iris, kaj lavis min, kaj mi ricevis vidpovon."],[9,12,"Tiam ili diris al li: Kie li estas? Li diris: Mi ne scias.","Tiam ili diris al li: Kie li estas? Li diris: Mi ne scias."],[9,13,"Ili kondukis al la Fariseoj la iam blindan viron.","Ili kondukis al la Fariseoj la iam blindan viron."],[9,14,"Sed estis sabato la tago, en kiu Jesuo faris la koton kaj malfermis liajn okulojn.","Sed estis sabato la tago, en kiu Jesuo faris la koton kaj malfermis liajn okulojn."],[9,15,"La Fariseoj do denove demandis lin, kiamaniere li ricevis vidpovon. Kaj li diris al ili: Li metis koton sur miajn okulojn, kaj mi lavis min, kaj mi vidas.","La Fariseoj do denove demandis lin, kiamaniere li ricevis vidpovon. Kaj li diris al ili: Li metis koton sur miajn okulojn, kaj mi lavis min, kaj mi vidas."],[9,16,"Unuj do el la Fariseoj diris: Ĉi tiu homo ne estas de Dio, ĉar li ne observas la sabaton. Aliaj diris: Kiel povas homo pekulo fari tiajn signojn? Kaj malkonsento estis inter ili.","Unuj do el la Fariseoj diris: Ĉi tiu homo ne estas de Dio, ĉar li ne observas la sabaton. Aliaj diris: Kiel povas homo pekulo fari tiajn signojn? Kaj malkonsento estis inter ili."],[9,17,"Denove ili diris al la blindulo: Kion vi diras pri li rilate tion, ke li malfermis viajn okulojn? Li diris: Li estas profeto.","Denove ili diris al la blindulo: Kion vi diras pri li rilate tion, ke li malfermis viajn okulojn? Li diris: Li estas profeto."],[9,18,"La Judoj ne kredis pri li, ke li estis antaŭe blinda, kaj ke li ricevis vidpovon, ĝis ili alvokis la gepatrojn de tiu, kiu ricevis vidpovon,","La Judoj ne kredis pri li, ke li estis antaŭe blinda, kaj ke li ricevis vidpovon, ĝis ili alvokis la gepatrojn de tiu, kiu ricevis vidpovon,"],[9,19,"kaj demandis ilin, dirante: Ĉu ĉi tiu estas via filo, kiu, vi diras, naskiĝis blinda? kiel do li nun vidas?","kaj demandis ilin, dirante: Ĉu ĉi tiu estas via filo, kiu, vi diras, naskiĝis blinda? kiel do li nun vidas?"],[9,20,"Liaj gepatroj respondis kaj diris: Ni scias, ke ĉi tiu estas nia filo, kaj ke li naskiĝis blinda;","Liaj gepatroj respondis kaj diris: Ni scias, ke ĉi tiu estas nia filo, kaj ke li naskiĝis blinda;"],[9,21,"sed kial li nun vidas, ni ne scias; kaj kiu malfermis liajn okulojn, ni ne scias; demandu lin, li havas plenaĝon; li pri si mem parolos.","sed kial li nun vidas, ni ne scias; kaj kiu malfermis liajn okulojn, ni ne scias; demandu lin, li havas plenaĝon; li pri si mem parolos."],[9,22,"Tion diris la gepatroj, ĉar ili timis la Judojn; ĉar la Judoj jam interkonsentis, ke se iu konfesos, ke li estas la Kristo, tiu estu forigita el la sinagogo.","Tion diris la gepatroj, ĉar ili timis la Judojn; ĉar la Judoj jam interkonsentis, ke se iu konfesos, ke li estas la Kristo, tiu estu forigita el la sinagogo."],[9,23,"Tial la gepatroj diris: Li havas plenaĝon, demandu lin.","Tial la gepatroj diris: Li havas plenaĝon, demandu lin."],[9,24,"Ili do denove alvokis la viron, kiu estis blinda, kaj diris al li: Donu gloron al Dio; ni certe scias, ke tiu homo estas pekulo.","Ili do denove alvokis la viron, kiu estis blinda, kaj diris al li: Donu gloron al Dio; ni certe scias, ke tiu homo estas pekulo."],[9,25,"Li do respondis: Ĉu li estas pekulo, mi ne scias; unu aferon mi scias, ke mi estis blinda kaj nun vidas.","Li do respondis: Ĉu li estas pekulo, mi ne scias; unu aferon mi scias, ke mi estis blinda kaj nun vidas."],[9,26,"Tiam ili diris al li denove: Kion li faris al vi? kiamaniere li malfermis viajn okulojn?","Tiam ili diris al li denove: Kion li faris al vi? kiamaniere li malfermis viajn okulojn?"],[9,27,"Li respondis al ili: Mi ĵus diris al vi, kaj vi ne atentis; kial vi volas denove ĝin aŭdi? ĉu vi ankaŭ volas fariĝi liaj disĉiploj?","Li respondis al ili: Mi ĵus diris al vi, kaj vi ne atentis; kial vi volas denove ĝin aŭdi? ĉu vi ankaŭ volas fariĝi liaj disĉiploj?"],[9,28,"Tiam ili insultis lin, kaj diris: Vi estas lia disĉiplo, sed ni estas disĉiploj de Moseo.","Tiam ili insultis lin, kaj diris: Vi estas lia disĉiplo, sed ni estas disĉiploj de Moseo."],[9,29,"Ni scias, ke Dio parolis al Moseo; sed pri ĉi tiu, ni ne scias, de kie li estas.","Ni scias, ke Dio parolis al Moseo; sed pri ĉi tiu, ni ne scias, de kie li estas."],[9,30,"La viro respondis kaj diris al ili: Jen la mirindaĵo, ke vi ne scias, de kie li estas, kaj tamen li malfermis miajn okulojn.","La viro respondis kaj diris al ili: Jen la mirindaĵo, ke vi ne scias, de kie li estas, kaj tamen li malfermis miajn okulojn."],[9,31,"Ni scias, ke Dio ne atentas pekulojn; sed se iu estas adoranto de Dio kaj plenumas Lian volon, tiun Li atentas.","Ni scias, ke Dio ne atentas pekulojn; sed se iu estas adoranto de Dio kaj plenumas Lian volon, tiun Li atentas."],[9,32,"De la komenco de la mondo oni neniam aŭdis, ke iu malfermis la okulojn de homo, kiu naskiĝis blinda.","De la komenco de la mondo oni neniam aŭdis, ke iu malfermis la okulojn de homo, kiu naskiĝis blinda."],[9,33,"Se ĉi tiu homo ne estus de Dio, li nenion povus fari.","Se ĉi tiu homo ne estus de Dio, li nenion povus fari."],[9,34,"Ili respondis kaj diris al li: Vi tute naskiĝis en pekoj, kaj ĉu vi nin instruas? Kaj ili forpelis lin eksteren.","Ili respondis kaj diris al li: Vi tute naskiĝis en pekoj, kaj ĉu vi nin instruas? Kaj ili forpelis lin eksteren."],[9,35,"Jesuo aŭdis, ke ili forpelis lin; kaj trovinte lin, li diris al li: Ĉu vi kredas al la Filo de Dio?","Jesuo aŭdis, ke ili forpelis lin; kaj trovinte lin, li diris al li: Ĉu vi kredas al la Filo de Dio?"],[9,36,"Li respondis kaj diris: Kiu li estas, Sinjoro, por ke mi kredu al li?","Li respondis kaj diris: Kiu li estas, Sinjoro, por ke mi kredu al li?"],[9,37,"Jesuo diris al li: Vi lin vidis; kaj li estas tiu, kiu parolas kun vi.","Jesuo diris al li: Vi lin vidis; kaj li estas tiu, kiu parolas kun vi."],[9,38,"Kaj li diris: Sinjoro, mi kredas. Kaj li adorkliniĝis al li.","Kaj li diris: Sinjoro, mi kredas. Kaj li adorkliniĝis al li."],[9,39,"Kaj Jesuo diris: Por juĝo mi venis en ĉi tiun mondon, por ke la nevidantoj vidu, kaj ke la vidantoj fariĝu blindaj.","Kaj Jesuo diris: Por juĝo mi venis en ĉi tiun mondon, por ke la nevidantoj vidu, kaj ke la vidantoj fariĝu blindaj."],[9,40,"Kaj tion aŭdis tiuj el la Fariseoj, kiuj estis kun li; kaj ili diris al li: Ĉu ni ankaŭ estas blindaj?","Kaj tion aŭdis tiuj el la Fariseoj, kiuj estis kun li; kaj ili diris al li: Ĉu ni ankaŭ estas blindaj?"],[9,41,"Jesuo diris al ili: Se vi estus blindaj, vi ne havus pekon; sed nun vi diras: Ni vidas; via peko do restas.","Jesuo diris al ili: Se vi estus blindaj, vi ne havus pekon; sed nun vi diras: Ni vidas; via peko do restas."],[10,1,"Vere, vere, mi diras al vi: Kiu eniras en la ŝafejon ne tra la pordo, sed aliloke suprengrimpas, tiu estas ŝtelisto kaj rabisto.","Vere, vere, mi diras al vi: Kiu eniras en la ŝafejon ne tra la pordo, sed aliloke suprengrimpas, tiu estas ŝtelisto kaj rabisto."],[10,2,"Sed kiu eniras tra la pordo, tiu estas la paŝtisto de la ŝafoj.","Sed kiu eniras tra la pordo, tiu estas la paŝtisto de la ŝafoj."],[10,3,"Al tiu la pordisto malfermas; kaj la ŝafoj aŭskultas lian voĉon, kaj li alvokas laŭ nomoj siajn proprajn ŝafojn, kaj elkondukas ilin.","Al tiu la pordisto malfermas; kaj la ŝafoj aŭskultas lian voĉon, kaj li alvokas laŭ nomoj siajn proprajn ŝafojn, kaj elkondukas ilin."],[10,4,"Kaj kiam li kondukis eksteren siajn ŝafojn, li iras antaŭ ili, kaj la ŝafoj lin sekvas, ĉar ili konas lian voĉon.","Kaj kiam li kondukis eksteren siajn ŝafojn, li iras antaŭ ili, kaj la ŝafoj lin sekvas, ĉar ili konas lian voĉon."],[10,5,"Kaj fremdulon ili ne sekvos, sed forkuros de li, ĉar ili ne konas la voĉon de fremduloj.","Kaj fremdulon ili ne sekvos, sed forkuros de li, ĉar ili ne konas la voĉon de fremduloj."],[10,6,"Tiun alegorion Jesuo diris al ili; sed ili ne komprenis, kiajn aferojn li parolas al ili.","Tiun alegorion Jesuo diris al ili; sed ili ne komprenis, kiajn aferojn li parolas al ili."],[10,7,"Jesuo do diris denove al ili: Vere, vere, mi diras al vi: Mi estas la pordo de la ŝafoj.","Jesuo do diris denove al ili: Vere, vere, mi diras al vi: Mi estas la pordo de la ŝafoj."],[10,8,"Ĉiuj, kiuj venis pli frue ol mi, estas ŝtelistoj kaj rabistoj; sed la ŝafoj ne aŭskultis ilin.","Ĉiuj, kiuj venis pli frue ol mi, estas ŝtelistoj kaj rabistoj; sed la ŝafoj ne aŭskultis ilin."],[10,9,"Mi estas la pordo; se iu tra mi eniras, tiu estos savita; kaj li eniros kaj eliros, kaj trovos paŝtaĵon.","Mi estas la pordo; se iu tra mi eniras, tiu estos savita; kaj li eniros kaj eliros, kaj trovos paŝtaĵon."],[10,10,"La ŝtelisto ne venas, krom por ŝteli kaj buĉi kaj pereigi; mi venis, por ke ili havu vivon, kaj havu ĝin abunde.","La ŝtelisto ne venas, krom por ŝteli kaj buĉi kaj pereigi; mi venis, por ke ili havu vivon, kaj havu ĝin abunde."],[10,11,"Mi estas la bona paŝtisto; la bona paŝtisto demetas sian vivon por la ŝafoj.","Mi estas la bona paŝtisto; la bona paŝtisto demetas sian vivon por la ŝafoj."],[10,12,"La dungito, kaj tiu, kiu ne estas paŝtisto, kies propraĵo la ŝafoj ne estas, ekvidas la lupon venanta kaj lasas la ŝafojn kaj forkuras; kaj la lupo ilin kaptas kaj dispelas;","La dungito, kaj tiu, kiu ne estas paŝtisto, kies propraĵo la ŝafoj ne estas, ekvidas la lupon venanta kaj lasas la ŝafojn kaj forkuras; kaj la lupo ilin kaptas kaj dispelas;"],[10,13,"li forkuras tial, ke li estas dungito kaj ne zorgas pri la ŝafoj.","li forkuras tial, ke li estas dungito kaj ne zorgas pri la ŝafoj."],[10,14,"Mi estas la bona paŝtisto, kaj mi konas la miajn, kaj la miaj min konas","Mi estas la bona paŝtisto, kaj mi konas la miajn, kaj la miaj min konas"],[10,15,"tiel same, kiel la Patro min konas, kaj mi konas la Patron; kaj mi demetas mian vivon por la ŝafoj.","tiel same, kiel la Patro min konas, kaj mi konas la Patron; kaj mi demetas mian vivon por la ŝafoj."],[10,16,"Kaj aliajn ŝafojn mi havas, kiuj ne estas de ĉi tiu gregejo; ilin ankaŭ mi devas alkonduki, kaj ili aŭskultos mian voĉon; kaj estos unu grego, unu paŝtisto.","Kaj aliajn ŝafojn mi havas, kiuj ne estas de ĉi tiu gregejo; ilin ankaŭ mi devas alkonduki, kaj ili aŭskultos mian voĉon; kaj estos unu grego, unu paŝtisto."],[10,17,"Pro tio la Patro min amas, ke mi demetas mian vivon, por ke mi ĝin reprenu.","Pro tio la Patro min amas, ke mi demetas mian vivon, por ke mi ĝin reprenu."],[10,18,"Neniu ĝin forprenas de mi, sed mi ĝin demetas memvole. Mi havas la rajton ĝin demeti, kaj mi havas la rajton ĝin repreni. Ĉi tiun ordonon mi ricevis de mia Patro.","Neniu ĝin forprenas de mi, sed mi ĝin demetas memvole. Mi havas la rajton ĝin demeti, kaj mi havas la rajton ĝin repreni. Ĉi tiun ordonon mi ricevis de mia Patro."],[10,19,"Denove fariĝis malkonsento inter la Judoj pro tiuj diroj.","Denove fariĝis malkonsento inter la Judoj pro tiuj diroj."],[10,20,"Kaj multaj el ili diris: Li havas demonon kaj estas freneza; kial vi lin aŭskultas?","Kaj multaj el ili diris: Li havas demonon kaj estas freneza; kial vi lin aŭskultas?"],[10,21,"Aliaj diris: Tiuj ne estas diroj de demonhavanto. Ĉu demono povas malfermi la okulojn de blinduloj?","Aliaj diris: Tiuj ne estas diroj de demonhavanto. Ĉu demono povas malfermi la okulojn de blinduloj?"],[10,22,"Okazis la festo de inaŭguro en Jerusalem, kaj estis vintro;","Okazis la festo de inaŭguro en Jerusalem, kaj estis vintro;"],[10,23,"kaj Jesuo promenis en la templo, en la portiko de Salomono.","kaj Jesuo promenis en la templo, en la portiko de Salomono."],[10,24,"La Judoj do ĉirkaŭis lin, kaj diris al li: Ĝis kiam vi tenas en dubo nian animon? Se vi estas la Kristo, diru al ni malkaŝe.","La Judoj do ĉirkaŭis lin, kaj diris al li: Ĝis kiam vi tenas en dubo nian animon? Se vi estas la Kristo, diru al ni malkaŝe."],[10,25,"Jesuo respondis al ili: Mi diris al vi, kaj vi ne kredas; la faroj, kiujn mi faras en la nomo de mia Patro, atestas pri mi.","Jesuo respondis al ili: Mi diris al vi, kaj vi ne kredas; la faroj, kiujn mi faras en la nomo de mia Patro, atestas pri mi."],[10,26,"Sed vi ne kredas, ĉar vi ne estas el miaj ŝafoj.","Sed vi ne kredas, ĉar vi ne estas el miaj ŝafoj."],[10,27,"Miaj ŝafoj aŭskultas mian voĉon, kaj mi ilin konas, kaj ili min sekvas;","Miaj ŝafoj aŭskultas mian voĉon, kaj mi ilin konas, kaj ili min sekvas;"],[10,28,"kaj mi donas al ili eternan vivon; kaj ili neniam pereos, kaj neniu ilin forkaptos el mia mano.","kaj mi donas al ili eternan vivon; kaj ili neniam pereos, kaj neniu ilin forkaptos el mia mano."],[10,29,"Mia Patro, kiu donis ilin al mi, superas ĉion; kaj neniu povas ion forkapti el la mano de mia Patro.","Mia Patro, kiu donis ilin al mi, superas ĉion; kaj neniu povas ion forkapti el la mano de mia Patro."],[10,30,"Mi kaj la Patro estas unu.","Mi kaj la Patro estas unu."],[10,31,"Tiam la Judoj denove prenis ŝtonojn, por ŝtonmortigi lin.","Tiam la Judoj denove prenis ŝtonojn, por ŝtonmortigi lin."],[10,32,"Jesuo respondis al ili: Multajn bonajn farojn mi montris al vi de mia Patro; pro kiu el ili vi volas ŝtonmortigi min?","Jesuo respondis al ili: Multajn bonajn farojn mi montris al vi de mia Patro; pro kiu el ili vi volas ŝtonmortigi min?"],[10,33,"La Judoj respondis: Ne pro bona faro ni volas ŝtonmortigi vin, sed pro blasfemo, kaj ĉar vi, estante homo, pretendas esti Dio.","La Judoj respondis: Ne pro bona faro ni volas ŝtonmortigi vin, sed pro blasfemo, kaj ĉar vi, estante homo, pretendas esti Dio."],[10,34,"Jesuo respondis: Ĉu ne estas skribite en via leĝo: Mi diris: Vi estas dioj?","Jesuo respondis: Ĉu ne estas skribite en via leĝo: Mi diris: Vi estas dioj?"],[10,35,"Se li nomis dioj tiujn, al kiuj venis la vorto de Dio (kaj la Skribo ne povas esti nuligita),","Se li nomis dioj tiujn, al kiuj venis la vorto de Dio (kaj la Skribo ne povas esti nuligita),"],[10,36,"ĉu vi diras pri tiu, kiun la Patro konsekris kaj sendis en la mondon: Vi blasfemas; ĉar mi diris: Mi estas Filo de Dio?","ĉu vi diras pri tiu, kiun la Patro konsekris kaj sendis en la mondon: Vi blasfemas; ĉar mi diris: Mi estas Filo de Dio?"],[10,37,"Se mi ne faras la farojn de mia Patro, ne kredu al mi.","Se mi ne faras la farojn de mia Patro, ne kredu al mi."],[10,38,"Sed se mi faras ilin, kvankam vi ne kredas al mi, kredu la farojn, por ke vi sciu kaj komprenu, ke la Patro estas en mi, kaj mi en la Patro.","Sed se mi faras ilin, kvankam vi ne kredas al mi, kredu la farojn, por ke vi sciu kaj komprenu, ke la Patro estas en mi, kaj mi en la Patro."],[10,39,"Ili denove celis kapti lin, sed li iris for de ilia mano.","Ili denove celis kapti lin, sed li iris for de ilia mano."],[10,40,"Li foriris denove trans Jordanon tien, kie Johano unue baptis, kaj tie li restadis.","Li foriris denove trans Jordanon tien, kie Johano unue baptis, kaj tie li restadis."],[10,41,"Kaj multaj venis al li, kaj diris: Johano ja ne faris signon; sed ĉio, kion Johano diris pri ĉi tiu, estis vera.","Kaj multaj venis al li, kaj diris: Johano ja ne faris signon; sed ĉio, kion Johano diris pri ĉi tiu, estis vera."],[10,42,"Kaj tie multaj kredis al li.","Kaj tie multaj kredis al li."],[11,1,"Kaj estis unu malsanulo, nomata Lazaro, el Betania, la vilaĝo de Maria kaj ŝia fratino Marta.","Kaj estis unu malsanulo, nomata Lazaro, el Betania, la vilaĝo de Maria kaj ŝia fratino Marta."],[11,2,"Tiu Maria, kies frato Lazaro estis malsana, estis tiu sama, kiu ŝmiris la Sinjoron per ŝmiraĵo kaj viŝis liajn piedojn per siaj haroj.","Tiu Maria, kies frato Lazaro estis malsana, estis tiu sama, kiu ŝmiris la Sinjoron per ŝmiraĵo kaj viŝis liajn piedojn per siaj haroj."],[11,3,"La fratinoj do sendis al li, dirante: Sinjoro, jen tiu, kiun vi amas, estas malsana.","La fratinoj do sendis al li, dirante: Sinjoro, jen tiu, kiun vi amas, estas malsana."],[11,4,"Sed Jesuo, aŭdinte tion, diris: Ĉi tiu malsano estas ne por la morto, sed por la gloro de Dio, por ke la Filo de Dio estu per ĝi glorata.","Sed Jesuo, aŭdinte tion, diris: Ĉi tiu malsano estas ne por la morto, sed por la gloro de Dio, por ke la Filo de Dio estu per ĝi glorata."],[11,5,"Kaj Jesuo amis Martan kaj ŝian fratinon kaj Lazaron.","Kaj Jesuo amis Martan kaj ŝian fratinon kaj Lazaron."],[11,6,"Kaj kiam li sciiĝis, ke tiu estas malsana, li restis ankoraŭ du tagojn en la loko, kie li estis.","Kaj kiam li sciiĝis, ke tiu estas malsana, li restis ankoraŭ du tagojn en la loko, kie li estis."],[11,7,"Poste li diris al la disĉiploj: Ni iru returne en Judujon.","Poste li diris al la disĉiploj: Ni iru returne en Judujon."],[11,8,"La disĉiploj diris al li: Rabeno, la Judoj ĵus celis ŝtonmortigi vin; kaj ĉu vi denove iras tien?","La disĉiploj diris al li: Rabeno, la Judoj ĵus celis ŝtonmortigi vin; kaj ĉu vi denove iras tien?"],[11,9,"Jesuo respondis: Ĉu ne estas dek du horoj en la tago? Se iu iras dum la tago, li ne faletas, ĉar li vidas la lumon de ĉi tiu mondo.","Jesuo respondis: Ĉu ne estas dek du horoj en la tago? Se iu iras dum la tago, li ne faletas, ĉar li vidas la lumon de ĉi tiu mondo."],[11,10,"Sed se iu iras dum la nokto, li faletas, ĉar en li ne estas la lumo.","Sed se iu iras dum la nokto, li faletas, ĉar en li ne estas la lumo."],[11,11,"Tion li parolis, kaj poste li diris al ili: Nia amiko Lazaro endormiĝis, sed mi iras, por veki lin el lia dormo.","Tion li parolis, kaj poste li diris al ili: Nia amiko Lazaro endormiĝis, sed mi iras, por veki lin el lia dormo."],[11,12,"La disĉiploj do diris: Sinjoro, se li endormiĝis, li resaniĝos.","La disĉiploj do diris: Sinjoro, se li endormiĝis, li resaniĝos."],[11,13,"Jesuo parolis pri lia morto; sed ili supozis, ke li parolas pri ripozo en dormo.","Jesuo parolis pri lia morto; sed ili supozis, ke li parolas pri ripozo en dormo."],[11,14,"Tiam Jesuo diris al ili klare: Lazaro jam mortis.","Tiam Jesuo diris al ili klare: Lazaro jam mortis."],[11,15,"Kaj pro vi mi ĝojas, ke mi ne ĉeestis tie, por ke vi kredu; tamen ni iru al li.","Kaj pro vi mi ĝojas, ke mi ne ĉeestis tie, por ke vi kredu; tamen ni iru al li."],[11,16,"Tiam Tomaso, nomata Didimo, diris al siaj kundisĉiploj: Ni ankaŭ iru, por ke ni mortu kun li.","Tiam Tomaso, nomata Didimo, diris al siaj kundisĉiploj: Ni ankaŭ iru, por ke ni mortu kun li."],[11,17,"Kiam Jesuo alvenis, li trovis lin jam kvar tagojn entombigita.","Kiam Jesuo alvenis, li trovis lin jam kvar tagojn entombigita."],[11,18,"Kaj Betania estis proksime de Jerusalem, en la distanco de ĉirkaŭ dek kvin stadioj;","Kaj Betania estis proksime de Jerusalem, en la distanco de ĉirkaŭ dek kvin stadioj;"],[11,19,"kaj multaj el la Judoj jam venis al Marta kaj Maria, por konsoli ilin pri ilia frato.","kaj multaj el la Judoj jam venis al Marta kaj Maria, por konsoli ilin pri ilia frato."],[11,20,"Marta do, kiam ŝi eksciis, ke Jesuo alproksimiĝas, iris al li renkonte; sed Maria ankoraŭ sidis en la domo.","Marta do, kiam ŝi eksciis, ke Jesuo alproksimiĝas, iris al li renkonte; sed Maria ankoraŭ sidis en la domo."],[11,21,"Tiam diris Marta al Jesuo: Sinjoro, se vi estus ĉi tie, mia frato ne estus mortinta.","Tiam diris Marta al Jesuo: Sinjoro, se vi estus ĉi tie, mia frato ne estus mortinta."],[11,22,"Sed eĉ nun mi scias, ke kion ajn vi petos de Dio, tion Dio donos al vi.","Sed eĉ nun mi scias, ke kion ajn vi petos de Dio, tion Dio donos al vi."],[11,23,"Jesuo diris al ŝi: Via frato releviĝos.","Jesuo diris al ŝi: Via frato releviĝos."],[11,24,"Marta diris al li: Mi scias, ke li releviĝos ĉe la releviĝo en la lasta tago.","Marta diris al li: Mi scias, ke li releviĝos ĉe la releviĝo en la lasta tago."],[11,25,"Jesuo diris al ŝi: Mi estas la releviĝo kaj la vivo; kiu kredas al mi, eĉ se li estos mortinta, tiu vivos,","Jesuo diris al ŝi: Mi estas la releviĝo kaj la vivo; kiu kredas al mi, eĉ se li estos mortinta, tiu vivos,"],[11,26,"kaj ĉiu, kiu vivas kaj kredas al mi, por ĉiam ne mortos. Ĉu vi tion kredas?","kaj ĉiu, kiu vivas kaj kredas al mi, por ĉiam ne mortos. Ĉu vi tion kredas?"],[11,27,"Ŝi diris al li: Jes, Sinjoro, mi jam kredas, ke vi estas la Kristo, la Filo de Dio, la venanta en la mondon.","Ŝi diris al li: Jes, Sinjoro, mi jam kredas, ke vi estas la Kristo, la Filo de Dio, la venanta en la mondon."],[11,28,"Kaj dirinte tion, ŝi foriris, kaj vokis sekrete sian fratinon Maria, dirante: La Majstro ĉeestas, kaj vokas vin.","Kaj dirinte tion, ŝi foriris, kaj vokis sekrete sian fratinon Maria, dirante: La Majstro ĉeestas, kaj vokas vin."],[11,29,"Kaj ŝi, aŭdinte tion, leviĝis rapide kaj iris al li.","Kaj ŝi, aŭdinte tion, leviĝis rapide kaj iris al li."],[11,30,"(Sed Jesuo ankoraŭ ne eniris en la vilaĝon, sed estis en la loko, kie Marta lin renkontis.)","(Sed Jesuo ankoraŭ ne eniris en la vilaĝon, sed estis en la loko, kie Marta lin renkontis.)"],[11,31,"La Judoj do, kiuj estis kun ŝi en la domo kaj konsolis ŝin, vidinte, ke Maria leviĝis subite kaj eliris, sekvis ŝin, dirante: Ŝi iras al la tombo, por plori tie.","La Judoj do, kiuj estis kun ŝi en la domo kaj konsolis ŝin, vidinte, ke Maria leviĝis subite kaj eliris, sekvis ŝin, dirante: Ŝi iras al la tombo, por plori tie."],[11,32,"Kiam Maria alvenis al la loko, kie Jesuo estis, kaj lin vidis, ŝi falis antaŭ liaj piedoj, dirante: Sinjoro, se vi estus ĉi tie, mia frato ne estus mortinta.","Kiam Maria alvenis al la loko, kie Jesuo estis, kaj lin vidis, ŝi falis antaŭ liaj piedoj, dirante: Sinjoro, se vi estus ĉi tie, mia frato ne estus mortinta."],[11,33,"Kiam do Jesuo vidis ŝin ploranta kaj la Judojn ankaŭ, kiuj venis kun ŝi, plorantaj, li ĝemis en la spirito kaj maltrankviliĝis,","Kiam do Jesuo vidis ŝin ploranta kaj la Judojn ankaŭ, kiuj venis kun ŝi, plorantaj, li ĝemis en la spirito kaj maltrankviliĝis,"],[11,34,"kaj diris: Kie vi lin kuŝigis? Ili diris al li: Sinjoro, venu kaj vidu.","kaj diris: Kie vi lin kuŝigis? Ili diris al li: Sinjoro, venu kaj vidu."],[11,35,"Jesuo larmis.","Jesuo larmis."],[11,36,"La Judoj do diris: Jen kiel li lin amis!","La Judoj do diris: Jen kiel li lin amis!"],[11,37,"Sed kelkaj el ili diris: Ĉu ĉi tiu, kiu malfermis la okulojn de la blindulo, ne povus kaŭzi ankaŭ, ke ĉi tiu homo ne mortu?","Sed kelkaj el ili diris: Ĉu ĉi tiu, kiu malfermis la okulojn de la blindulo, ne povus kaŭzi ankaŭ, ke ĉi tiu homo ne mortu?"],[11,38,"Tiam Jesuo, denove ĝemante en si, venis al la tombo. Ĝi estis kaverno, kaj sur ĝi kuŝis ŝtono.","Tiam Jesuo, denove ĝemante en si, venis al la tombo. Ĝi estis kaverno, kaj sur ĝi kuŝis ŝtono."],[11,39,"Jesuo diris: Forprenu la ŝtonon. Marta, la fratino de la mortinto, diris al li: Sinjoro, li jam malbonodoras, ĉar li estis tie kvar tagojn.","Jesuo diris: Forprenu la ŝtonon. Marta, la fratino de la mortinto, diris al li: Sinjoro, li jam malbonodoras, ĉar li estis tie kvar tagojn."],[11,40,"Jesuo diris al ŝi: Ĉu mi ne diris al vi, ke se vi kredos, vi vidos la gloron de Dio?","Jesuo diris al ŝi: Ĉu mi ne diris al vi, ke se vi kredos, vi vidos la gloron de Dio?"],[11,41,"Oni do forprenis la ŝtonon. Kaj Jesuo levis siajn okulojn, kaj diris: Patro, mi dankas Vin, ke Vi min aŭskultis.","Oni do forprenis la ŝtonon. Kaj Jesuo levis siajn okulojn, kaj diris: Patro, mi dankas Vin, ke Vi min aŭskultis."],[11,42,"Kaj mi sciis, ke Vi ĉiam aŭskultas min; sed pro la ĉirkaŭstaranta homamaso mi tion diris, por ke ili kredu, ke Vi min sendis.","Kaj mi sciis, ke Vi ĉiam aŭskultas min; sed pro la ĉirkaŭstaranta homamaso mi tion diris, por ke ili kredu, ke Vi min sendis."],[11,43,"Kaj dirinte tion, li kriis per laŭta voĉo: Lazaro, elvenu.","Kaj dirinte tion, li kriis per laŭta voĉo: Lazaro, elvenu."],[11,44,"Kaj la mortinto elvenis, kun la manoj kaj piedoj ligitaj per tombotukoj; kaj lia vizaĝo estis ĉirkaŭligita per viŝtuko. Jesuo diris al ili: Malligu lin, kaj lasu lin iri.","Kaj la mortinto elvenis, kun la manoj kaj piedoj ligitaj per tombotukoj; kaj lia vizaĝo estis ĉirkaŭligita per viŝtuko. Jesuo diris al ili: Malligu lin, kaj lasu lin iri."],[11,45,"Tiam multaj el la Judoj, kiuj venis al Maria, kaj vidis, kion li faris, kredis al li.","Tiam multaj el la Judoj, kiuj venis al Maria, kaj vidis, kion li faris, kredis al li."],[11,46,"Sed kelkaj el ili foriris al la Fariseoj, kaj rakontis al ili tion, kion Jesuo faris.","Sed kelkaj el ili foriris al la Fariseoj, kaj rakontis al ili tion, kion Jesuo faris."],[11,47,"Tial la ĉefpastroj kaj la Fariseoj kunvenigis sinedrion, kaj diris: Kion ni faras? ĉar ĉi tiu homo faras multajn signojn;","Tial la ĉefpastroj kaj la Fariseoj kunvenigis sinedrion, kaj diris: Kion ni faras? ĉar ĉi tiu homo faras multajn signojn;"],[11,48,"se ni lasos lin tiel, ĉiuj kredos al li, kaj la Romanoj venos kaj forigos nian lokon kaj nian nacion.","se ni lasos lin tiel, ĉiuj kredos al li, kaj la Romanoj venos kaj forigos nian lokon kaj nian nacion."],[11,49,"Sed unu el ili, Kajafas, ĉefpastro en tiu sama jaro, diris al ili: Vi scias nenion,","Sed unu el ili, Kajafas, ĉefpastro en tiu sama jaro, diris al ili: Vi scias nenion,"],[11,50,"nek konsideras, ke bone estas por vi, ke unu homo mortu por la popolo, kaj ke la tuta nacio ne pereu.","nek konsideras, ke bone estas por vi, ke unu homo mortu por la popolo, kaj ke la tuta nacio ne pereu."],[11,51,"Sed li diris tion ne de si mem; sed estante ĉefpastro en tiu jaro, li profetis, ke Jesuo mortos por la nacio;","Sed li diris tion ne de si mem; sed estante ĉefpastro en tiu jaro, li profetis, ke Jesuo mortos por la nacio;"],[11,52,"kaj ne nur por la nacio, sed ankaŭ por ke li kunvenigu en unu la ĉie disĵetitajn filojn de Dio.","kaj ne nur por la nacio, sed ankaŭ por ke li kunvenigu en unu la ĉie disĵetitajn filojn de Dio."],[11,53,"De post tiu tago do ili konsiliĝis, por lin mortigi.","De post tiu tago do ili konsiliĝis, por lin mortigi."],[11,54,"Tial Jesuo ne plu iris publike inter la Judoj, sed foriris de tie en la kamparon apud la dezerto, en urbon nomatan Efraim; kaj tie li restadis kun la disĉiploj.","Tial Jesuo ne plu iris publike inter la Judoj, sed foriris de tie en la kamparon apud la dezerto, en urbon nomatan Efraim; kaj tie li restadis kun la disĉiploj."],[11,55,"Kaj la Pasko de la Judoj proksimiĝis, kaj multaj supreniris el la kamparo al Jerusalem antaŭ la Pasko, por sin sanktigi.","Kaj la Pasko de la Judoj proksimiĝis, kaj multaj supreniris el la kamparo al Jerusalem antaŭ la Pasko, por sin sanktigi."],[11,56,"Ili do serĉis Jesuon, kaj parolis inter si, starante en la templo: Kion vi pensas? Ĉu ke li ne venos al la festo?","Ili do serĉis Jesuon, kaj parolis inter si, starante en la templo: Kion vi pensas? Ĉu ke li ne venos al la festo?"],[11,57,"Kaj la ĉefpastroj kaj la Fariseoj jam antaŭe ordonis, ke se iu scias, kie li estas, tiu montru tion, por ke oni lin kaptu.","Kaj la ĉefpastroj kaj la Fariseoj jam antaŭe ordonis, ke se iu scias, kie li estas, tiu montru tion, por ke oni lin kaptu."],[12,1,"Jesuo do ses tagojn antaŭ la Pasko venis al Betania, kie estis Lazaro, kiun Jesuo relevis el inter la mortintoj.","Jesuo do ses tagojn antaŭ la Pasko venis al Betania, kie estis Lazaro, kiun Jesuo relevis el inter la mortintoj."],[12,2,"Oni do pretigis por li tie vespermanĝon, kaj Marta servadis; sed Lazaro estis unu el tiuj, kiuj sidis kun li ĉe manĝo.","Oni do pretigis por li tie vespermanĝon, kaj Marta servadis; sed Lazaro estis unu el tiuj, kiuj sidis kun li ĉe manĝo."],[12,3,"Tiam Maria prenis funton da pura narda ŝmiraĵo tre multekosta, ŝmiris la piedojn de Jesuo, kaj viŝis liajn piedojn per siaj haroj; kaj la domo pleniĝis de la odoro de la ŝmiraĵo.","Tiam Maria prenis funton da pura narda ŝmiraĵo tre multekosta, ŝmiris la piedojn de Jesuo, kaj viŝis liajn piedojn per siaj haroj; kaj la domo pleniĝis de la odoro de la ŝmiraĵo."],[12,4,"Sed diris Judas Iskariota, unu el liaj disĉiploj, kiu estis lin perfidonta:","Sed diris Judas Iskariota, unu el liaj disĉiploj, kiu estis lin perfidonta:"],[12,5,"Kial oni ne vendis ĉi tiun ŝmiraĵon por tricent denaroj kaj donis al malriĉuloj?","Kial oni ne vendis ĉi tiun ŝmiraĵon por tricent denaroj kaj donis al malriĉuloj?"],[12,6,"Tion li diris, ne ĉar li zorgis pri la malriĉuloj; sed ĉar li estis ŝtelisto, kaj havis la monujon kaj forprenadis tion, kion oni metis en ĝin.","Tion li diris, ne ĉar li zorgis pri la malriĉuloj; sed ĉar li estis ŝtelisto, kaj havis la monujon kaj forprenadis tion, kion oni metis en ĝin."],[12,7,"Sed Jesuo diris: Lasu ŝin konservi ĝin por la tago de mia entombigo.","Sed Jesuo diris: Lasu ŝin konservi ĝin por la tago de mia entombigo."],[12,8,"Ĉar la malriĉulojn vi ĉiam havas kun vi, sed min vi ne ĉiam havas.","Ĉar la malriĉulojn vi ĉiam havas kun vi, sed min vi ne ĉiam havas."],[12,9,"La amaso de la Judoj do sciiĝis, ke li estas tie; kaj ili venis ne nur pro Jesuo, sed ankaŭ por vidi Lazaron, kiun li levis el la mortintoj.","La amaso de la Judoj do sciiĝis, ke li estas tie; kaj ili venis ne nur pro Jesuo, sed ankaŭ por vidi Lazaron, kiun li levis el la mortintoj."],[12,10,"Sed la ĉefpastroj konsiliĝis, ke ili mortigu ankaŭ Lazaron;","Sed la ĉefpastroj konsiliĝis, ke ili mortigu ankaŭ Lazaron;"],[12,11,"ĉar pro li multaj Judoj foriris, kaj kredis al Jesuo.","ĉar pro li multaj Judoj foriris, kaj kredis al Jesuo."],[12,12,"En la sekvanta tago granda homamaso, veninte al la festo, kaj sciiĝinte, ke Jesuo venas al Jerusalem,","En la sekvanta tago granda homamaso, veninte al la festo, kaj sciiĝinte, ke Jesuo venas al Jerusalem,"],[12,13,"prenis branĉojn de la palmoj, kaj iris al li renkonte, kaj kriis: Hosana! Estu benata la Reĝo de Izrael, kiu venas en la nomo de la Eternulo!","prenis branĉojn de la palmoj, kaj iris al li renkonte, kaj kriis: Hosana! Estu benata la Reĝo de Izrael, kiu venas en la nomo de la Eternulo!"],[12,14,"Kaj Jesuo, trovinte junan azenon, sidis sur ĝi, kiel estas skribite:","Kaj Jesuo, trovinte junan azenon, sidis sur ĝi, kiel estas skribite:"],[12,15,"Ne timu, filino de Cion: jen via Reĝo venas, sidanta sur ido de azeno.","Ne timu, filino de Cion: jen via Reĝo venas, sidanta sur ido de azeno."],[12,16,"Tion la disĉiploj unue ne komprenis; sed post la gloriĝo de Jesuo ili rememoris, ke tio estis skribita pri li kaj ke oni faris al li tion.","Tion la disĉiploj unue ne komprenis; sed post la gloriĝo de Jesuo ili rememoris, ke tio estis skribita pri li kaj ke oni faris al li tion."],[12,17,"La homamaso do, kiu ĉeestis kun li, kiam li elvokis Lazaron el la tombo, kaj levis lin el la mortintoj, atestis pri li.","La homamaso do, kiu ĉeestis kun li, kiam li elvokis Lazaron el la tombo, kaj levis lin el la mortintoj, atestis pri li."],[12,18,"Pro tio ankaŭ la homamaso iris al li renkonte, ĉar ili sciiĝis, ke li faris tiun signon.","Pro tio ankaŭ la homamaso iris al li renkonte, ĉar ili sciiĝis, ke li faris tiun signon."],[12,19,"La Fariseoj do diris inter si: Vidu, kiel nenio prosperis al vi; jen la mondo eliris post li.","La Fariseoj do diris inter si: Vidu, kiel nenio prosperis al vi; jen la mondo eliris post li."],[12,20,"Kaj inter tiuj, kiuj alvojaĝis por adorkliniĝi ĉe la festo, estis iuj Grekoj;","Kaj inter tiuj, kiuj alvojaĝis por adorkliniĝi ĉe la festo, estis iuj Grekoj;"],[12,21,"tiuj do venis al Filipo, kiu estis el Betsaida Galilea, kaj petis lin, dirante: Sinjoro, ni volas vidi Jesuon.","tiuj do venis al Filipo, kiu estis el Betsaida Galilea, kaj petis lin, dirante: Sinjoro, ni volas vidi Jesuon."],[12,22,"Filipo venis kaj sciigis Andreon; kaj poste Andreo kaj Filipo venis kaj sciigis Jesuon.","Filipo venis kaj sciigis Andreon; kaj poste Andreo kaj Filipo venis kaj sciigis Jesuon."],[12,23,"Sed Jesuo respondis al ili, dirante: Venis la horo, por ke la Filo de homo estu glorata.","Sed Jesuo respondis al ili, dirante: Venis la horo, por ke la Filo de homo estu glorata."],[12,24,"Vere, vere, mi diras al vi: Se la tritika grenero ne falas en la teron kaj ne mortas, ĝi restas sola; sed se ĝi mortas, ĝi donas multe da frukto.","Vere, vere, mi diras al vi: Se la tritika grenero ne falas en la teron kaj ne mortas, ĝi restas sola; sed se ĝi mortas, ĝi donas multe da frukto."],[12,25,"Kiu amas sian vivon, tiu ĝin perdas; kaj kiu malamas sian vivon en ĉi tiu mondo, tiu ĝin konservos ĝis eterna vivo.","Kiu amas sian vivon, tiu ĝin perdas; kaj kiu malamas sian vivon en ĉi tiu mondo, tiu ĝin konservos ĝis eterna vivo."],[12,26,"Se iu min servas, tiu sekvu min; kaj kie mi estas, tie ankaŭ estos mia servanto; se iu min servas, tiun la Patro honoros.","Se iu min servas, tiu sekvu min; kaj kie mi estas, tie ankaŭ estos mia servanto; se iu min servas, tiun la Patro honoros."],[12,27,"Nun maltrankviliĝas mia animo; kaj kion mi diru? Patro, savu min el ĉi tiu horo. Sed por tio mi venis ĝis ĉi tiu horo.","Nun maltrankviliĝas mia animo; kaj kion mi diru? Patro, savu min el ĉi tiu horo. Sed por tio mi venis ĝis ĉi tiu horo."],[12,28,"Patro, gloru Vian nomon. Tiam voĉo venis el la ĉielo: Mi jam gloris ĝin kaj denove gloros.","Patro, gloru Vian nomon. Tiam voĉo venis el la ĉielo: Mi jam gloris ĝin kaj denove gloros."],[12,29,"Do la apudstaranta homamaso, aŭdinte, diris, ke tondris; aliaj diris: Anĝelo parolis al li.","Do la apudstaranta homamaso, aŭdinte, diris, ke tondris; aliaj diris: Anĝelo parolis al li."],[12,30,"Jesuo respondis kaj diris: Ne por mi venis tiu voĉo, sed por vi.","Jesuo respondis kaj diris: Ne por mi venis tiu voĉo, sed por vi."],[12,31,"Nun estas la juĝo de ĉi tiu mondo; nun la estro de ĉi tiu mondo estos elpelita.","Nun estas la juĝo de ĉi tiu mondo; nun la estro de ĉi tiu mondo estos elpelita."],[12,32,"Kaj mi, se mi estos suprenlevita de sur la tero, altiros al mi ĉiujn homojn.","Kaj mi, se mi estos suprenlevita de sur la tero, altiros al mi ĉiujn homojn."],[12,33,"Tion li diris, per aludo montrante, per kia morto li mortos.","Tion li diris, per aludo montrante, per kia morto li mortos."],[12,34,"La homamaso respondis al li: Ni aŭdis el la leĝo, ke la Kristo restados por ĉiam; kaj kiel vi diras: La Filo de homo devas esti suprenlevita? Kiu estas ĉi tiu Filo de homo?","La homamaso respondis al li: Ni aŭdis el la leĝo, ke la Kristo restados por ĉiam; kaj kiel vi diras: La Filo de homo devas esti suprenlevita? Kiu estas ĉi tiu Filo de homo?"],[12,35,"Jesuo do diris al ili: Ankoraŭ mallongan tempon estas la lumo kun vi. Iradu, dum vi havas la lumon, por ke la mallumo ne venu sur vin; ĉar tiu, kiu iradas en mallumo, ne scias, kien li iras.","Jesuo do diris al ili: Ankoraŭ mallongan tempon estas la lumo kun vi. Iradu, dum vi havas la lumon, por ke la mallumo ne venu sur vin; ĉar tiu, kiu iradas en mallumo, ne scias, kien li iras."],[12,36,"Dum vi havas lumon, kredu al la lumo, por ke vi fariĝu filoj de lumo. Tion parolis Jesuo, kaj li foriris, kaj sin kaŝis for de ili.","Dum vi havas lumon, kredu al la lumo, por ke vi fariĝu filoj de lumo. Tion parolis Jesuo, kaj li foriris, kaj sin kaŝis for de ili."],[12,37,"Sed kvankam li jam faris tiom da signoj antaŭ ili, tamen ili ne kredis al li;","Sed kvankam li jam faris tiom da signoj antaŭ ili, tamen ili ne kredis al li;"],[12,38,"por ke plenumiĝu la vorto de la profeto Jesaja, kiun li parolis: Ho Eternulo, kiu kredis nian raporton? Kaj super kiu malkaŝiĝis la brako de la Eternulo?","por ke plenumiĝu la vorto de la profeto Jesaja, kiun li parolis: Ho Eternulo, kiu kredis nian raporton? Kaj super kiu malkaŝiĝis la brako de la Eternulo?"],[12,39,"Pro tio ili ne povis kredi, ĉar Jesaja diris plue:","Pro tio ili ne povis kredi, ĉar Jesaja diris plue:"],[12,40,"Li blindigis iliajn okulojn kaj sensentigis ilian koron, Por ke ili ne vidu per siaj okuloj, kaj ke ili ne komprenu per sia koro, Kaj ke ili ne konvertiĝu, Kaj ke Mi ilin ne sanigu.","Li blindigis iliajn okulojn kaj sensentigis ilian koron, Por ke ili ne vidu per siaj okuloj, kaj ke ili ne komprenu per sia koro, Kaj ke ili ne konvertiĝu, Kaj ke Mi ilin ne sanigu."],[12,41,"Tion diris Jesaja, ĉar li vidis lian gloron kaj parolis pri li.","Tion diris Jesaja, ĉar li vidis lian gloron kaj parolis pri li."],[12,42,"Tamen eĉ el la regantoj multaj kredis al li; sed pro la Fariseoj ili ne konfesis lin, por ke ili ne estu elpelitaj el la sinagogo;","Tamen eĉ el la regantoj multaj kredis al li; sed pro la Fariseoj ili ne konfesis lin, por ke ili ne estu elpelitaj el la sinagogo;"],[12,43,"ĉar ili ŝatis la laŭdon de homoj pli, ol la gloron de Dio.","ĉar ili ŝatis la laŭdon de homoj pli, ol la gloron de Dio."],[12,44,"Kaj Jesuo kriis kaj diris: Kiu kredas al mi, tiu kredas ne al mi, sed al Tiu, kiu min sendis.","Kaj Jesuo kriis kaj diris: Kiu kredas al mi, tiu kredas ne al mi, sed al Tiu, kiu min sendis."],[12,45,"Kaj kiu vidas min, tiu vidas ankaŭ Tiun, kiu min sendis.","Kaj kiu vidas min, tiu vidas ankaŭ Tiun, kiu min sendis."],[12,46,"Mi venis lumo en la mondon, por ke ĉiu, kiu kredas al mi, ne restadu en mallumo.","Mi venis lumo en la mondon, por ke ĉiu, kiu kredas al mi, ne restadu en mallumo."],[12,47,"Kaj se iu aŭdas miajn dirojn kaj ne plenumas ilin, mi lin ne juĝas; ĉar mi venis, ne por juĝi la mondon, sed por savi la mondon.","Kaj se iu aŭdas miajn dirojn kaj ne plenumas ilin, mi lin ne juĝas; ĉar mi venis, ne por juĝi la mondon, sed por savi la mondon."],[12,48,"Tiu, kiu forrifuzas min kaj ne akceptas miajn dirojn, havas juĝonton; la vorto, kiun mi parolis, juĝos lin en la lasta tago.","Tiu, kiu forrifuzas min kaj ne akceptas miajn dirojn, havas juĝonton; la vorto, kiun mi parolis, juĝos lin en la lasta tago."],[12,49,"Ĉar mi ne parolis de mi mem; sed la Patro, kiu sendis min, mem ordonis al mi, kion mi parolu, kaj kion mi diru.","Ĉar mi ne parolis de mi mem; sed la Patro, kiu sendis min, mem ordonis al mi, kion mi parolu, kaj kion mi diru."],[12,50,"Kaj mi scias, ke Lia ordono estas eterna vivo; kion do mi parolas, ĝuste kiel la Patro diris al mi, tiel mi parolas.","Kaj mi scias, ke Lia ordono estas eterna vivo; kion do mi parolas, ĝuste kiel la Patro diris al mi, tiel mi parolas."],[13,1,"Kaj antaŭ la Paska festo Jesuo, sciante, ke lia horo venis, por ke li transiru el ĉi tiu mondo al la Patro, aminte siajn proprulojn, kiuj estis en la mondo, amis ilin ĝis la fino.","Kaj antaŭ la Paska festo Jesuo, sciante, ke lia horo venis, por ke li transiru el ĉi tiu mondo al la Patro, aminte siajn proprulojn, kiuj estis en la mondo, amis ilin ĝis la fino."],[13,2,"Kaj dum la vespermanĝo, kiam la diablo jam metis en la koron de Judas Iskariota, filo de Simon, la intencon perfidi lin,","Kaj dum la vespermanĝo, kiam la diablo jam metis en la koron de Judas Iskariota, filo de Simon, la intencon perfidi lin,"],[13,3,"Jesuo, sciante, ke la Patro donis ĉion en liajn manojn, kaj ke li venis de Dio kaj iras al Dio,","Jesuo, sciante, ke la Patro donis ĉion en liajn manojn, kaj ke li venis de Dio kaj iras al Dio,"],[13,4,"leviĝis de la vespermanĝo kaj demetis siajn vestojn; kaj li prenis viŝtukon, kaj sin zonis.","leviĝis de la vespermanĝo kaj demetis siajn vestojn; kaj li prenis viŝtukon, kaj sin zonis."],[13,5,"Poste li verŝis akvon en la pelvon, kaj komencis lavi la piedojn de la disĉiploj kaj viŝi ilin per la tuko, per kiu li estis zonita.","Poste li verŝis akvon en la pelvon, kaj komencis lavi la piedojn de la disĉiploj kaj viŝi ilin per la tuko, per kiu li estis zonita."],[13,6,"Tiam li venis al Simon Petro. Ĉi tiu diris al li: Sinjoro, ĉu vi lavas al mi la piedojn?","Tiam li venis al Simon Petro. Ĉi tiu diris al li: Sinjoro, ĉu vi lavas al mi la piedojn?"],[13,7,"Jesuo respondis kaj diris al li: Kion mi faras, vi nun ne scias, sed poste vi komprenos.","Jesuo respondis kaj diris al li: Kion mi faras, vi nun ne scias, sed poste vi komprenos."],[13,8,"Petro diris al li: Vi ja neniam lavos miajn piedojn. Respondis al li Jesuo: Se mi ne lavas vin, vi ne partoprenas kun mi.","Petro diris al li: Vi ja neniam lavos miajn piedojn. Respondis al li Jesuo: Se mi ne lavas vin, vi ne partoprenas kun mi."],[13,9,"Simon Petro diris al li: Sinjoro, ne nur miajn piedojn, sed ankaŭ la manojn kaj la kapon.","Simon Petro diris al li: Sinjoro, ne nur miajn piedojn, sed ankaŭ la manojn kaj la kapon."],[13,10,"Jesuo diris al li: Kiu sin jam banis, tiu bezonas nur, ke oni lavu la piedojn, kaj li estas tuta pura; kaj vi estas puraj, tamen ne ĉiuj.","Jesuo diris al li: Kiu sin jam banis, tiu bezonas nur, ke oni lavu la piedojn, kaj li estas tuta pura; kaj vi estas puraj, tamen ne ĉiuj."],[13,11,"Ĉar li konis tiun, kiu perfidos lin; tial li diris: Vi ne ĉiuj estas puraj.","Ĉar li konis tiun, kiu perfidos lin; tial li diris: Vi ne ĉiuj estas puraj."],[13,12,"Kiam do li jam lavis iliajn piedojn kaj surmetis siajn vestojn kaj denove sidiĝis, li diris al ili: Ĉu vi scias, kion mi faris al vi?","Kiam do li jam lavis iliajn piedojn kaj surmetis siajn vestojn kaj denove sidiĝis, li diris al ili: Ĉu vi scias, kion mi faris al vi?"],[13,13,"Vi nomas min Majstro kaj Sinjoro; kaj prave vi diras, ĉar tia mi estas.","Vi nomas min Majstro kaj Sinjoro; kaj prave vi diras, ĉar tia mi estas."],[13,14,"Se do mi, la Sinjoro kaj la Majstro, lavis viajn piedojn, vi ankaŭ devas inter vi lavi la piedojn.","Se do mi, la Sinjoro kaj la Majstro, lavis viajn piedojn, vi ankaŭ devas inter vi lavi la piedojn."],[13,15,"Ĉar mi donis al vi ekzemplon, por ke vi ankaŭ faru tion, kion mi faris al vi.","Ĉar mi donis al vi ekzemplon, por ke vi ankaŭ faru tion, kion mi faris al vi."],[13,16,"Vere, vere, mi diras al vi: Sklavo ne estas pli granda ol lia sinjoro; nek estas la sendito pli granda ol la sendinto.","Vere, vere, mi diras al vi: Sklavo ne estas pli granda ol lia sinjoro; nek estas la sendito pli granda ol la sendinto."],[13,17,"Se ĉi tion vi scias, vi estas feliĉaj, se tion vi faras.","Se ĉi tion vi scias, vi estas feliĉaj, se tion vi faras."],[13,18,"Ne pri vi ĉiuj mi parolas; mi scias, kiujn mi elektis; sed por ke plenumiĝu la Skribo: Tiu, kiu manĝas mian panon, levis kontraŭ min la piedon.","Ne pri vi ĉiuj mi parolas; mi scias, kiujn mi elektis; sed por ke plenumiĝu la Skribo: Tiu, kiu manĝas mian panon, levis kontraŭ min la piedon."],[13,19,"De nun mi parolas al vi pri tio, antaŭ ol ĝi okazos, por ke, kiam ĝi okazos, vi kredu, ke mi estas.","De nun mi parolas al vi pri tio, antaŭ ol ĝi okazos, por ke, kiam ĝi okazos, vi kredu, ke mi estas."],[13,20,"Vere, vere, mi diras al vi: Kiu akceptas tiun, kiun mi sendas, tiu akceptas min; kaj kiu min akceptas, tiu akceptas Tiun, kiu min sendis.","Vere, vere, mi diras al vi: Kiu akceptas tiun, kiun mi sendas, tiu akceptas min; kaj kiu min akceptas, tiu akceptas Tiun, kiu min sendis."],[13,21,"Dirinte tion, Jesuo maltrankviliĝis en spirito, kaj ateste parolis, dirante: Vere, vere, mi diras al vi, ke unu el vi min perfidos.","Dirinte tion, Jesuo maltrankviliĝis en spirito, kaj ateste parolis, dirante: Vere, vere, mi diras al vi, ke unu el vi min perfidos."],[13,22,"Tiam la disĉiploj rigardis unu la alian, dubante pri kiu li parolas.","Tiam la disĉiploj rigardis unu la alian, dubante pri kiu li parolas."],[13,23,"Estis apud la sino de Jesuo unu el liaj disĉiploj, kiun Jesuo amis.","Estis apud la sino de Jesuo unu el liaj disĉiploj, kiun Jesuo amis."],[13,24,"Simon Petro do faris signon al li, ke li demandu, pri kiu li parolas.","Simon Petro do faris signon al li, ke li demandu, pri kiu li parolas."],[13,25,"Tiu do, kliniĝante al la brusto de Jesuo, diris al li: Sinjoro, kiu ĝi estas?","Tiu do, kliniĝante al la brusto de Jesuo, diris al li: Sinjoro, kiu ĝi estas?"],[13,26,"Jesuo respondis: Ĝi estas tiu, por kiu mi trempos la pecon kaj donos al li. Kaj trempinte la pecon, li donis ĝin al Judas Iskariota, filo de Simon.","Jesuo respondis: Ĝi estas tiu, por kiu mi trempos la pecon kaj donos al li. Kaj trempinte la pecon, li donis ĝin al Judas Iskariota, filo de Simon."],[13,27,"Kaj post la peco, tiam Satano eniris en lin. Jesuo do diris al li: Kion vi faras, tion faru senprokraste.","Kaj post la peco, tiam Satano eniris en lin. Jesuo do diris al li: Kion vi faras, tion faru senprokraste."],[13,28,"Sed neniu el la kunmanĝantoj sciis, kial li diris al li tion.","Sed neniu el la kunmanĝantoj sciis, kial li diris al li tion."],[13,29,"Iuj pensis, ĉar Judas havis la monujon, ke Jesuo diris al li: Aĉetu tion, kion ni bezonas por la festo; aŭ ke li donu ion al la malriĉuloj.","Iuj pensis, ĉar Judas havis la monujon, ke Jesuo diris al li: Aĉetu tion, kion ni bezonas por la festo; aŭ ke li donu ion al la malriĉuloj."],[13,30,"Li do, ricevinte la pecon, tuj eliris; kaj estis nokto.","Li do, ricevinte la pecon, tuj eliris; kaj estis nokto."],[13,31,"Kiam li eliris, Jesuo diris: Nun la Filo de homo estas glorata, kaj Dio estas glorata en li;","Kiam li eliris, Jesuo diris: Nun la Filo de homo estas glorata, kaj Dio estas glorata en li;"],[13,32,"kaj Dio gloros lin en Si mem, kaj tuj Li gloros lin.","kaj Dio gloros lin en Si mem, kaj tuj Li gloros lin."],[13,33,"Infanoj, ankoraŭ mallongan tempon mi estas kun vi. Vi min serĉos; kaj kiel mi diris al la Judoj: Kien mi iras, tien vi ne povas veni, tiel ankaŭ al vi mi nun diras.","Infanoj, ankoraŭ mallongan tempon mi estas kun vi. Vi min serĉos; kaj kiel mi diris al la Judoj: Kien mi iras, tien vi ne povas veni, tiel ankaŭ al vi mi nun diras."],[13,34,"Novan ordonon mi donas al vi, ke vi amu unu alian; kiel mi amis vin, tiel vi ankaŭ amu unu alian.","Novan ordonon mi donas al vi, ke vi amu unu alian; kiel mi amis vin, tiel vi ankaŭ amu unu alian."],[13,35,"Per tio ĉiuj homoj scios, ke vi estas miaj disĉiploj, se vi havos amon unu al alia.","Per tio ĉiuj homoj scios, ke vi estas miaj disĉiploj, se vi havos amon unu al alia."],[13,36,"Simon Petro diris al li: Sinjoro, kien vi iras? Jesuo respondis: Kien mi iras, vi ne povas min sekvi nun, sed poste vi min sekvos.","Simon Petro diris al li: Sinjoro, kien vi iras? Jesuo respondis: Kien mi iras, vi ne povas min sekvi nun, sed poste vi min sekvos."],[13,37,"Petro diris al li: Sinjoro, kial mi ne povas vin sekvi nun? mi demetos por vi mian vivon.","Petro diris al li: Sinjoro, kial mi ne povas vin sekvi nun? mi demetos por vi mian vivon."],[13,38,"Jesuo respondis al li: Ĉu vi demetos por mi vian vivon? Vere, vere, mi diras al vi: La koko ne krios, antaŭ ol vi min malkonfesos tri fojojn.","Jesuo respondis al li: Ĉu vi demetos por mi vian vivon? Vere, vere, mi diras al vi: La koko ne krios, antaŭ ol vi min malkonfesos tri fojojn."],[14,1,"Ne maltrankviliĝu via koro; vi kredas al Dio, kredu ankaŭ al mi.","Ne maltrankviliĝu via koro; vi kredas al Dio, kredu ankaŭ al mi."],[14,2,"Ĉe la domo de mia Patro estas multe da loĝejoj; se ne tiel estus, mi dirus al vi; mi iras, por pretigi por vi lokon.","Ĉe la domo de mia Patro estas multe da loĝejoj; se ne tiel estus, mi dirus al vi; mi iras, por pretigi por vi lokon."],[14,3,"Kaj se mi iros kaj pretigos por vi lokon, mi revenos kaj ricevos vin al mi mem, por ke vi ankaŭ estu tie, kie mi estas.","Kaj se mi iros kaj pretigos por vi lokon, mi revenos kaj ricevos vin al mi mem, por ke vi ankaŭ estu tie, kie mi estas."],[14,4,"Kaj kien mi iras, vi scias, kaj vi konas la vojon.","Kaj kien mi iras, vi scias, kaj vi konas la vojon."],[14,5,"Tomaso diris al li: Sinjoro, ni ne scias, kien vi iras; kiel ni konas la vojon?","Tomaso diris al li: Sinjoro, ni ne scias, kien vi iras; kiel ni konas la vojon?"],[14,6,"Jesuo diris al li: Mi estas la vojo kaj la vero kaj la vivo; neniu venas al la Patro krom per mi.","Jesuo diris al li: Mi estas la vojo kaj la vero kaj la vivo; neniu venas al la Patro krom per mi."],[14,7,"Se vi min konus, vi konus ankaŭ mian Patron; kaj de nun vi konas Lin kaj Lin vidis.","Se vi min konus, vi konus ankaŭ mian Patron; kaj de nun vi konas Lin kaj Lin vidis."],[14,8,"Filipo diris al li: Sinjoro, montru al ni la Patron, kaj por ni tio sufiĉos.","Filipo diris al li: Sinjoro, montru al ni la Patron, kaj por ni tio sufiĉos."],[14,9,"Jesuo diris al li: Ĉu mi estas kun vi tiel longan tempon, kaj vi min ne konas, Filipo? tiu, kiu vidis min, vidis ankaŭ la Patron; kiel vi diras: Montru al ni la Patron?","Jesuo diris al li: Ĉu mi estas kun vi tiel longan tempon, kaj vi min ne konas, Filipo? tiu, kiu vidis min, vidis ankaŭ la Patron; kiel vi diras: Montru al ni la Patron?"],[14,10,"Ĉu vi ne kredas, ke mi estas en la Patro kaj la Patro en mi? la vortojn, kiujn mi parolas al vi, mi parolas ne de mi mem; sed la Patro, restanta en mi, faras Siajn farojn.","Ĉu vi ne kredas, ke mi estas en la Patro kaj la Patro en mi? la vortojn, kiujn mi parolas al vi, mi parolas ne de mi mem; sed la Patro, restanta en mi, faras Siajn farojn."],[14,11,"Kredu al mi, ke mi estas en la Patro, kaj la Patro en mi; aŭ almenaŭ kredu al mi pro la faroj mem.","Kredu al mi, ke mi estas en la Patro, kaj la Patro en mi; aŭ almenaŭ kredu al mi pro la faroj mem."],[14,12,"Vere, vere, mi diras al vi: Kiu kredas al mi, tiu ankaŭ faros la farojn, kiujn mi faras; kaj li faros pli grandajn ol tiuj, ĉar mi iras al la Patro.","Vere, vere, mi diras al vi: Kiu kredas al mi, tiu ankaŭ faros la farojn, kiujn mi faras; kaj li faros pli grandajn ol tiuj, ĉar mi iras al la Patro."],[14,13,"Kaj kion ajn vi petos en mia nomo, tion mi faros, por ke la Patro estu glorata en la Filo.","Kaj kion ajn vi petos en mia nomo, tion mi faros, por ke la Patro estu glorata en la Filo."],[14,14,"Se vi petos ion de mi en mia nomo, tion mi faros.","Se vi petos ion de mi en mia nomo, tion mi faros."],[14,15,"Se vi min amas, vi observos miajn ordonojn.","Se vi min amas, vi observos miajn ordonojn."],[14,16,"Kaj mi petos la Patron, kaj Li donos al vi alian Parakleton, por ke li restadu kun vi por ĉiam;","Kaj mi petos la Patron, kaj Li donos al vi alian Parakleton, por ke li restadu kun vi por ĉiam;"],[14,17,"tiu estas la Spirito de la vero, kiun la mondo ne povas akcepti, ĉar ĝi lin ne vidas nek konas; vi lin konas, ĉar li restadas kun vi kaj estos en vi.","tiu estas la Spirito de la vero, kiun la mondo ne povas akcepti, ĉar ĝi lin ne vidas nek konas; vi lin konas, ĉar li restadas kun vi kaj estos en vi."],[14,18,"Mi ne lasos vin orfaj; mi venas al vi.","Mi ne lasos vin orfaj; mi venas al vi."],[14,19,"Ankoraŭ iom da tempo, kaj la mondo ne plu vidos min, sed vi vidos min; ĉar mi vivas, tial vi ankaŭ vivos.","Ankoraŭ iom da tempo, kaj la mondo ne plu vidos min, sed vi vidos min; ĉar mi vivas, tial vi ankaŭ vivos."],[14,20,"En tiu tago vi scios, ke mi estas en mia Patro, kaj vi en mi, kaj mi en vi.","En tiu tago vi scios, ke mi estas en mia Patro, kaj vi en mi, kaj mi en vi."],[14,21,"Kiu havas miajn ordonojn kaj observas ilin, tiu estas, kiu min amas; kaj kiu min amas, tiu estos amata de mia Patro, kaj mi amos lin, kaj elmontros min al li.","Kiu havas miajn ordonojn kaj observas ilin, tiu estas, kiu min amas; kaj kiu min amas, tiu estos amata de mia Patro, kaj mi amos lin, kaj elmontros min al li."],[14,22,"Judas (ne la Iskariota) diris al li: Sinjoro, kio okazis, ke vi elmontros vin al ni, kaj ne al la mondo?","Judas (ne la Iskariota) diris al li: Sinjoro, kio okazis, ke vi elmontros vin al ni, kaj ne al la mondo?"],[14,23,"Jesuo respondis kaj diris al li: Se iu min amas, tiu observos mian vorton; kaj mia Patro lin amos; kaj ni venos al li kaj faros loĝon kun li.","Jesuo respondis kaj diris al li: Se iu min amas, tiu observos mian vorton; kaj mia Patro lin amos; kaj ni venos al li kaj faros loĝon kun li."],[14,24,"Kiu min ne amas, tiu ne observas miajn vortojn; kaj la vorto, kiun vi aŭdas, estas ne mia, sed de la Patro, kiu min sendis.","Kiu min ne amas, tiu ne observas miajn vortojn; kaj la vorto, kiun vi aŭdas, estas ne mia, sed de la Patro, kiu min sendis."],[14,25,"Tion mi parolis al vi, dum mi ĉe vi restas.","Tion mi parolis al vi, dum mi ĉe vi restas."],[14,26,"Sed la Parakleto, la Sankta Spirito, kiun la Patro sendos en mia nomo, instruos vin pri ĉio, kaj vin rememorigos pri ĉio, kion mi diris al vi.","Sed la Parakleto, la Sankta Spirito, kiun la Patro sendos en mia nomo, instruos vin pri ĉio, kaj vin rememorigos pri ĉio, kion mi diris al vi."],[14,27,"Pacon mi lasas al vi; mian pacon mi donas al vi; ne kiel la mondo donas, mi donas al vi. Ne maltrankviliĝu via koro, nek senkuraĝiĝu.","Pacon mi lasas al vi; mian pacon mi donas al vi; ne kiel la mondo donas, mi donas al vi. Ne maltrankviliĝu via koro, nek senkuraĝiĝu."],[14,28,"Vi aŭdis, ke mi diris al vi: Mi foriras, kaj mi revenas al vi. Se vi min amus, vi ĝojus pro tio, ke mi iras al la Patro, ĉar la Patro estas pli granda ol mi.","Vi aŭdis, ke mi diris al vi: Mi foriras, kaj mi revenas al vi. Se vi min amus, vi ĝojus pro tio, ke mi iras al la Patro, ĉar la Patro estas pli granda ol mi."],[14,29,"Kaj nun mi diris al vi, antaŭ ol ĝi okazos, por ke vi kredu, kiam ĝi okazos.","Kaj nun mi diris al vi, antaŭ ol ĝi okazos, por ke vi kredu, kiam ĝi okazos."],[14,30,"De nun mi jam ne multe parolos kun vi; ĉar la estro de la mondo venas; kaj li havas nenion en mi;","De nun mi jam ne multe parolos kun vi; ĉar la estro de la mondo venas; kaj li havas nenion en mi;"],[14,31,"sed por ke la mondo sciu, ke mi amas la Patron, kaj kiel la Patro ordonis al mi, tiel mi faras. Leviĝu; ni foriru de ĉi tie.","sed por ke la mondo sciu, ke mi amas la Patron, kaj kiel la Patro ordonis al mi, tiel mi faras. Leviĝu; ni foriru de ĉi tie."],[15,1,"Mi estas la vera vinberarbo, kaj mia Patro estas la kultivisto.","Mi estas la vera vinberarbo, kaj mia Patro estas la kultivisto."],[15,2,"Ĉiun nefruktodonan branĉon en mi Li forprenas; kaj ĉiun fruktodonan branĉon Li purigas, por ke ĝi donu pli da frukto.","Ĉiun nefruktodonan branĉon en mi Li forprenas; kaj ĉiun fruktodonan branĉon Li purigas, por ke ĝi donu pli da frukto."],[15,3,"Jam vi estas puraj pro la vorto, kiun mi parolis al vi.","Jam vi estas puraj pro la vorto, kiun mi parolis al vi."],[15,4,"Restadu en mi, kaj mi en vi. Kiel la branĉo ne povas de si mem doni frukton, se ĝi ne restas en la vinberarbo, tiel ankaŭ vi ne povas, se vi ne restas en mi.","Restadu en mi, kaj mi en vi. Kiel la branĉo ne povas de si mem doni frukton, se ĝi ne restas en la vinberarbo, tiel ankaŭ vi ne povas, se vi ne restas en mi."],[15,5,"Mi estas la vinberarbo; vi estas la branĉoj; kiu restadas en mi, kaj mi en li, tiu donas multe da frukto; ĉar sen mi vi nenion povas fari.","Mi estas la vinberarbo; vi estas la branĉoj; kiu restadas en mi, kaj mi en li, tiu donas multe da frukto; ĉar sen mi vi nenion povas fari."],[15,6,"Se iu ne restas en mi, tiu estas elĵetita, kiel la branĉo, kaj sekiĝas; kaj oni ilin kolektas kaj ĵetas en fajron, kaj ili brulas.","Se iu ne restas en mi, tiu estas elĵetita, kiel la branĉo, kaj sekiĝas; kaj oni ilin kolektas kaj ĵetas en fajron, kaj ili brulas."],[15,7,"Se vi restadas en mi, kaj miaj vortoj restadas en vi, petu kion ajn vi volos, kaj tio estos farita por vi.","Se vi restadas en mi, kaj miaj vortoj restadas en vi, petu kion ajn vi volos, kaj tio estos farita por vi."],[15,8,"En tio mia Patro estas glorata, ke vi donas multe da frukto; kaj vi estos miaj disĉiploj.","En tio mia Patro estas glorata, ke vi donas multe da frukto; kaj vi estos miaj disĉiploj."],[15,9,"Kiel la Patro min amis, tiel mi ankaŭ vin amis; restadu en mia amo.","Kiel la Patro min amis, tiel mi ankaŭ vin amis; restadu en mia amo."],[15,10,"Se vi observos miajn ordonojn, vi restados en mia amo tiel same, kiel mi observis la ordonojn de mia Patro kaj restadas en Lia amo.","Se vi observos miajn ordonojn, vi restados en mia amo tiel same, kiel mi observis la ordonojn de mia Patro kaj restadas en Lia amo."],[15,11,"Tion mi parolis al vi, por ke mia ĝojo en vi restadu, kaj via ĝojo estu plena.","Tion mi parolis al vi, por ke mia ĝojo en vi restadu, kaj via ĝojo estu plena."],[15,12,"Jen estas mia ordono: ke vi amu unu alian tiel same, kiel mi vin amis.","Jen estas mia ordono: ke vi amu unu alian tiel same, kiel mi vin amis."],[15,13,"Neniu havas amon pli grandan ol tio, ke iu demetus sian vivon por siaj amikoj.","Neniu havas amon pli grandan ol tio, ke iu demetus sian vivon por siaj amikoj."],[15,14,"Vi estas miaj amikoj, se vi faras tion, kion mi al vi ordonas.","Vi estas miaj amikoj, se vi faras tion, kion mi al vi ordonas."],[15,15,"Mi jam ne nomas vin sklavoj, ĉar la sklavo ne scias, kion lia sinjoro faras; sed mi nomis vin amikoj, ĉar ĉion, kion mi aŭdis de mia Patro, mi sciigis al vi.","Mi jam ne nomas vin sklavoj, ĉar la sklavo ne scias, kion lia sinjoro faras; sed mi nomis vin amikoj, ĉar ĉion, kion mi aŭdis de mia Patro, mi sciigis al vi."],[15,16,"Vi ne elektis min, sed mi elektis vin, kaj starigis vin, por ke vi iru kaj donu frukton, kaj ke via frukto daŭru; por ke la Patro donu al vi ĉion ajn, kion vi petos de Li en mia nomo.","Vi ne elektis min, sed mi elektis vin, kaj starigis vin, por ke vi iru kaj donu frukton, kaj ke via frukto daŭru; por ke la Patro donu al vi ĉion ajn, kion vi petos de Li en mia nomo."],[15,17,"Tion mi ordonas al vi, por ke vi amu unu la alian.","Tion mi ordonas al vi, por ke vi amu unu la alian."],[15,18,"Se la mondo malamas vin, vi scias, ke ĝi malamis min pli frue, ol vin.","Se la mondo malamas vin, vi scias, ke ĝi malamis min pli frue, ol vin."],[15,19,"Se vi estus el la mondo, la mondo amus siajn proprajn; sed ĉar vi ne estas el la mondo, kaj mi elektis vin for de la mondo, tial la mondo vin malamas.","Se vi estus el la mondo, la mondo amus siajn proprajn; sed ĉar vi ne estas el la mondo, kaj mi elektis vin for de la mondo, tial la mondo vin malamas."],[15,20,"Memoru la vorton, kiun mi diris al vi: Sklavo ne estas pli granda ol lia sinjoro. Se ili min persekutis, vin ankaŭ ili persekutos; se ili observis mian vorton, ankaŭ vian ili observos.","Memoru la vorton, kiun mi diris al vi: Sklavo ne estas pli granda ol lia sinjoro. Se ili min persekutis, vin ankaŭ ili persekutos; se ili observis mian vorton, ankaŭ vian ili observos."],[15,21,"Sed ĉion ĉi tion ili faros al vi pro mia nomo, ĉar ili ne konas Tiun, kiu min sendis.","Sed ĉion ĉi tion ili faros al vi pro mia nomo, ĉar ili ne konas Tiun, kiu min sendis."],[15,22,"Se mi ne estus veninta kaj parolinta al ili, ili ne havus pekon; sed nun ili ne havas pretekston por sia peko.","Se mi ne estus veninta kaj parolinta al ili, ili ne havus pekon; sed nun ili ne havas pretekston por sia peko."],[15,23,"Tiu, kiu min malamas, malamas ankaŭ mian Patron.","Tiu, kiu min malamas, malamas ankaŭ mian Patron."],[15,24,"Se mi ne estus farinta inter ili farojn, kiajn neniu alia faris, ili ne havus pekon; sed nun ili vidis kaj malamis min kaj ankaŭ mian Patron.","Se mi ne estus farinta inter ili farojn, kiajn neniu alia faris, ili ne havus pekon; sed nun ili vidis kaj malamis min kaj ankaŭ mian Patron."],[15,25,"Sed tio okazas, por ke plenumiĝu la vorto skribita en ilia leĝo: Ili malamis min senkaŭze.","Sed tio okazas, por ke plenumiĝu la vorto skribita en ilia leĝo: Ili malamis min senkaŭze."],[15,26,"Sed kiam venos la Parakleto, kiun mi sendos de la Patro al vi, la Spirito de la vero, kiu devenas de la Patro, tiu pri mi atestos;","Sed kiam venos la Parakleto, kiun mi sendos de la Patro al vi, la Spirito de la vero, kiu devenas de la Patro, tiu pri mi atestos;"],[15,27,"kaj vi ankaŭ atestas, ĉar vi estis kun mi de la komenco.","kaj vi ankaŭ atestas, ĉar vi estis kun mi de la komenco."],[16,1,"Tion mi parolis al vi, por ke vi ne falpuŝiĝu.","Tion mi parolis al vi, por ke vi ne falpuŝiĝu."],[16,2,"Ili forpelos vin el la sinagogoj; eĉ venas la horo, kiam iu, kiu mortigos vin, opinios, ke li faras servon al Dio.","Ili forpelos vin el la sinagogoj; eĉ venas la horo, kiam iu, kiu mortigos vin, opinios, ke li faras servon al Dio."],[16,3,"Kaj tion ili faros pro tio, ke ili ne konis la Patron, nek min.","Kaj tion ili faros pro tio, ke ili ne konis la Patron, nek min."],[16,4,"Sed tion mi parolis al vi, por ke vi rememoru, kiam ĝia tempo venos, ke mi ĝin antaŭdiris al vi. Sed en la komenco mi ne diris al vi tion, ĉar mi estis kun vi.","Sed tion mi parolis al vi, por ke vi rememoru, kiam ĝia tempo venos, ke mi ĝin antaŭdiris al vi. Sed en la komenco mi ne diris al vi tion, ĉar mi estis kun vi."],[16,5,"Sed nun mi foriras al Tiu, kiu min sendis; kaj neniu el vi demandas min: Kien vi iras?","Sed nun mi foriras al Tiu, kiu min sendis; kaj neniu el vi demandas min: Kien vi iras?"],[16,6,"Sed ĉar mi tiel parolis al vi, malĝojo plenigis vian koron.","Sed ĉar mi tiel parolis al vi, malĝojo plenigis vian koron."],[16,7,"Tamen mi diras al vi la veron: Estas bone por vi, ke mi foriros; ĉar se mi ne foriros, la Parakleto ne venos al vi; sed se mi foriros, mi sendos lin al vi.","Tamen mi diras al vi la veron: Estas bone por vi, ke mi foriros; ĉar se mi ne foriros, la Parakleto ne venos al vi; sed se mi foriros, mi sendos lin al vi."],[16,8,"Kaj kiam li alvenos, li pruvos la mondon kulpa rilate pekon kaj justecon kaj juĝon:","Kaj kiam li alvenos, li pruvos la mondon kulpa rilate pekon kaj justecon kaj juĝon:"],[16,9,"rilate pekon, ĉar ili ne kredas al mi;","rilate pekon, ĉar ili ne kredas al mi;"],[16,10,"rilate justecon, ĉar mi foriras al la Patro, kaj vi jam ne rigardas min;","rilate justecon, ĉar mi foriras al la Patro, kaj vi jam ne rigardas min;"],[16,11,"rilate juĝon, ĉar la estro de ĉi tiu mondo estas juĝita.","rilate juĝon, ĉar la estro de ĉi tiu mondo estas juĝita."],[16,12,"Mi havas ankoraŭ multon por diri al vi, sed vi ne povas ĝin nun elporti.","Mi havas ankoraŭ multon por diri al vi, sed vi ne povas ĝin nun elporti."],[16,13,"Tamen kiam venos li, la Spirito de la vero, li gvidos vin en ĉian veron; ĉar li parolos ne de si mem; sed kion ajn li aŭdos, tion li parolos; kaj li anoncos al vi venontajn aferojn.","Tamen kiam venos li, la Spirito de la vero, li gvidos vin en ĉian veron; ĉar li parolos ne de si mem; sed kion ajn li aŭdos, tion li parolos; kaj li anoncos al vi venontajn aferojn."],[16,14,"Li gloros min, ĉar li ricevos el miaj kaj anoncos al vi.","Li gloros min, ĉar li ricevos el miaj kaj anoncos al vi."],[16,15,"Ĉio ajn, kion la Patro havas, estas mia; tial mi diris, ke li ricevos el miaj kaj anoncos al vi.","Ĉio ajn, kion la Patro havas, estas mia; tial mi diris, ke li ricevos el miaj kaj anoncos al vi."],[16,16,"Mallongan tempon, kaj vi jam ne rigardas min; kaj denove mallongan tempon, kaj vi min vidos.","Mallongan tempon, kaj vi jam ne rigardas min; kaj denove mallongan tempon, kaj vi min vidos."],[16,17,"Iuj do el liaj disĉiploj diris al aliaj: Kio estas ĉi tio, kion li diras al ni: Mallongan tempon, kaj vi ne rigardas min; kaj denove mallongan tempon, kaj vi min vidos; kaj: Ĉar mi foriras al la Patro?","Iuj do el liaj disĉiploj diris al aliaj: Kio estas ĉi tio, kion li diras al ni: Mallongan tempon, kaj vi ne rigardas min; kaj denove mallongan tempon, kaj vi min vidos; kaj: Ĉar mi foriras al la Patro?"],[16,18,"Ili do diris: Kio estas ĉi tio, kion li diras: Mallongan tempon? Ni ne komprenas lian diron.","Ili do diris: Kio estas ĉi tio, kion li diras: Mallongan tempon? Ni ne komprenas lian diron."],[16,19,"Jesuo ekvidis, ke ili deziras demandi lin, kaj li diris al ili: Ĉu vi serĉas inter vi klarigon pri tio, kion mi diris: Mallongan tempon, kaj vi ne rigardas min; kaj denove mallongan tempon, kaj vi min vidos?","Jesuo ekvidis, ke ili deziras demandi lin, kaj li diris al ili: Ĉu vi serĉas inter vi klarigon pri tio, kion mi diris: Mallongan tempon, kaj vi ne rigardas min; kaj denove mallongan tempon, kaj vi min vidos?"],[16,20,"Vere, vere, mi diras al vi, ke vi ploros kaj lamentos, sed la mondo ĝojos; vi estos malĝojaj, sed via malĝojo fariĝos ĝojo.","Vere, vere, mi diras al vi, ke vi ploros kaj lamentos, sed la mondo ĝojos; vi estos malĝojaj, sed via malĝojo fariĝos ĝojo."],[16,21,"Virino, kiam ŝi akuŝas, havas malĝojon, ĉar ŝia horo venis; sed kiam ŝi naskis la infaneton, ŝi jam ne memoras sian doloregon, pro ĝojo, ĉar homo naskiĝis en la mondon.","Virino, kiam ŝi akuŝas, havas malĝojon, ĉar ŝia horo venis; sed kiam ŝi naskis la infaneton, ŝi jam ne memoras sian doloregon, pro ĝojo, ĉar homo naskiĝis en la mondon."],[16,22,"Vi do ankaŭ havas nun malĝojon; sed mi revidos vin, kaj via koro ĝojos, kaj neniu forprenos de vi vian ĝojon.","Vi do ankaŭ havas nun malĝojon; sed mi revidos vin, kaj via koro ĝojos, kaj neniu forprenos de vi vian ĝojon."],[16,23,"Kaj en tiu tago vi demandos min pri nenio. Vere, vere, mi diras al vi, se vi petos ion de la Patro, Li donos ĝin al vi en mia nomo.","Kaj en tiu tago vi demandos min pri nenio. Vere, vere, mi diras al vi, se vi petos ion de la Patro, Li donos ĝin al vi en mia nomo."],[16,24,"Ĝis nun vi petis nenion en mia nomo; petu, kaj vi ricevos, por ke via ĝojo estu plena.","Ĝis nun vi petis nenion en mia nomo; petu, kaj vi ricevos, por ke via ĝojo estu plena."],[16,25,"Ĉi tion mi parolis al vi alegorie; sed venas la horo, kiam mi jam ne parolos al vi alegorie, sed anoncos al vi malkaŝe pri la Patro.","Ĉi tion mi parolis al vi alegorie; sed venas la horo, kiam mi jam ne parolos al vi alegorie, sed anoncos al vi malkaŝe pri la Patro."],[16,26,"En tiu tago vi petos en mia nomo; kaj mi ne diras, ke mi petos de la Patro pro vi;","En tiu tago vi petos en mia nomo; kaj mi ne diras, ke mi petos de la Patro pro vi;"],[16,27,"ĉar la Patro mem vin amas tial, ke vi min amis, kaj kredis, ke mi elvenis de Dio.","ĉar la Patro mem vin amas tial, ke vi min amis, kaj kredis, ke mi elvenis de Dio."],[16,28,"Mi elvenis de la Patro, kaj alvenis en la mondon; denove mi lasas la mondon, kaj iras al la Patro.","Mi elvenis de la Patro, kaj alvenis en la mondon; denove mi lasas la mondon, kaj iras al la Patro."],[16,29,"Liaj disĉiploj diris: Jen nun vi parolas malkaŝe, kaj nenian alegorion diras.","Liaj disĉiploj diris: Jen nun vi parolas malkaŝe, kaj nenian alegorion diras."],[16,30,"Nun ni scias, ke vi ĉion scias, kaj ne bezonas, ke iu demandu vin; pro tio ni kredas, ke vi elvenis de Dio.","Nun ni scias, ke vi ĉion scias, kaj ne bezonas, ke iu demandu vin; pro tio ni kredas, ke vi elvenis de Dio."],[16,31,"Jesuo respondis al ili: Ĉu vi nun kredas?","Jesuo respondis al ili: Ĉu vi nun kredas?"],[16,32,"Jen venas la horo, kaj eĉ jam venis, kiam vi disiĝos, ĉiu al sia loko, kaj vi lasos min sola; kaj tamen mi ne estas sola, ĉar la Patro estas kun mi.","Jen venas la horo, kaj eĉ jam venis, kiam vi disiĝos, ĉiu al sia loko, kaj vi lasos min sola; kaj tamen mi ne estas sola, ĉar la Patro estas kun mi."],[16,33,"Tion mi parolis al vi, por ke en mi vi havu pacon. En la mondo vi havos suferadon; sed kuraĝu; mi venkis la mondon.","Tion mi parolis al vi, por ke en mi vi havu pacon. En la mondo vi havos suferadon; sed kuraĝu; mi venkis la mondon."],[17,1,"Tion Jesuo parolis; kaj levinte la okulojn al la ĉielo, li diris: Patro, la horo venis; gloru Vian Filon, por ke la Filo Vin gloru;","Tion Jesuo parolis; kaj levinte la okulojn al la ĉielo, li diris: Patro, la horo venis; gloru Vian Filon, por ke la Filo Vin gloru;"],[17,2,"kiel Vi donis al li aŭtoritaton super ĉiu karno, por ke li donu eternan vivon al ĉiuj tiuj, kiujn Vi donis al li.","kiel Vi donis al li aŭtoritaton super ĉiu karno, por ke li donu eternan vivon al ĉiuj tiuj, kiujn Vi donis al li."],[17,3,"Kaj jen estas la eterna vivo, ke ili konu Vin, la sole veran Dion, kaj tiun, kiun Vi sendis, Jesuon Kriston.","Kaj jen estas la eterna vivo, ke ili konu Vin, la sole veran Dion, kaj tiun, kiun Vi sendis, Jesuon Kriston."],[17,4,"Mi gloris Vin sur la tero, plenuminte la faron, kiun Vi donis al mi por fari.","Mi gloris Vin sur la tero, plenuminte la faron, kiun Vi donis al mi por fari."],[17,5,"Kaj nun, ho Patro, gloru min kun Vi, per la gloro, kiun mi havis kun Vi, antaŭ ol la mondo ekzistis.","Kaj nun, ho Patro, gloru min kun Vi, per la gloro, kiun mi havis kun Vi, antaŭ ol la mondo ekzistis."],[17,6,"Mi elmontris Vian nomon al la homoj, kiujn Vi donis al mi el la mondo; Viaj ili estis, kaj al mi Vi ilin donis; kaj ili konservis Vian vorton.","Mi elmontris Vian nomon al la homoj, kiujn Vi donis al mi el la mondo; Viaj ili estis, kaj al mi Vi ilin donis; kaj ili konservis Vian vorton."],[17,7,"Nun ili scias, ke ĉio ajn, kion Vi donis al mi, estas de Vi;","Nun ili scias, ke ĉio ajn, kion Vi donis al mi, estas de Vi;"],[17,8,"ĉar mi donis al ili la vortojn, kiujn Vi donis al mi; kaj ili akceptis ilin, kaj scias vere, ke mi elvenis de Vi; kaj ili kredas, ke Vi min sendis.","ĉar mi donis al ili la vortojn, kiujn Vi donis al mi; kaj ili akceptis ilin, kaj scias vere, ke mi elvenis de Vi; kaj ili kredas, ke Vi min sendis."],[17,9,"Mi preĝas por ili; mi preĝas ne por la mondo, sed por tiuj, kiujn Vi donis al mi, ĉar ili estas Viaj;","Mi preĝas por ili; mi preĝas ne por la mondo, sed por tiuj, kiujn Vi donis al mi, ĉar ili estas Viaj;"],[17,10,"kaj ĉio mia estas Via, kaj Via estas mia; kaj mi estas glorita per ili.","kaj ĉio mia estas Via, kaj Via estas mia; kaj mi estas glorita per ili."],[17,11,"Mi jam ne estas en la mondo, kaj ĉi tiuj estas en la mondo, kaj mi venas al Vi. Patro Sankta, gardu en Via nomo tiujn, kiujn Vi donis al mi, por ke ili estu unu tiel same, kiel ni.","Mi jam ne estas en la mondo, kaj ĉi tiuj estas en la mondo, kaj mi venas al Vi. Patro Sankta, gardu en Via nomo tiujn, kiujn Vi donis al mi, por ke ili estu unu tiel same, kiel ni."],[17,12,"Dum mi estis kun ili, mi konservis en Via nomo tiujn, kiujn Vi donis al mi; kaj mi gardis ilin, kaj neniu el ili pereis, krom la filo de perdiĝo, por ke plenumiĝu la Skribo.","Dum mi estis kun ili, mi konservis en Via nomo tiujn, kiujn Vi donis al mi; kaj mi gardis ilin, kaj neniu el ili pereis, krom la filo de perdiĝo, por ke plenumiĝu la Skribo."],[17,13,"Sed nun mi venas al Vi; kaj tion mi parolas en la mondo, por ke ili havu mian ĝojon ĝis pleneco en si mem.","Sed nun mi venas al Vi; kaj tion mi parolas en la mondo, por ke ili havu mian ĝojon ĝis pleneco en si mem."],[17,14,"Mi donis al ili Vian vorton; kaj la mondo malamis ilin, ĉar ili ne estas el la mondo, kiel mi ne estas el la mondo.","Mi donis al ili Vian vorton; kaj la mondo malamis ilin, ĉar ili ne estas el la mondo, kiel mi ne estas el la mondo."],[17,15,"Mi petas, ne ke Vi forigu ilin el la mondo, sed ke Vi gardu ilin kontraŭ la malbono.","Mi petas, ne ke Vi forigu ilin el la mondo, sed ke Vi gardu ilin kontraŭ la malbono."],[17,16,"Ili ne estas el la mondo, kiel mi ne estas el la mondo.","Ili ne estas el la mondo, kiel mi ne estas el la mondo."],[17,17,"Konsekru ilin en la vero; Via vorto estas vero.","Konsekru ilin en la vero; Via vorto estas vero."],[17,18,"Kiel Vi min sendis en la mondon, tiel ankaŭ mi ilin sendis en la mondon.","Kiel Vi min sendis en la mondon, tiel ankaŭ mi ilin sendis en la mondon."],[17,19,"Kaj por ili mi konsekras min, por ke ili mem ankaŭ estu konsekritaj en la vero.","Kaj por ili mi konsekras min, por ke ili mem ankaŭ estu konsekritaj en la vero."],[17,20,"Kaj mi preĝas ne nur por ili, sed ankaŭ por tiuj, kiuj kredos al mi pro ilia vorto;","Kaj mi preĝas ne nur por ili, sed ankaŭ por tiuj, kiuj kredos al mi pro ilia vorto;"],[17,21,"por ke ili ĉiuj estu unu; kiel Vi, Patro, estas en mi, kaj mi en Vi, tiel ili ankaŭ estu en ni; por ke la mondo kredu, ke Vi min sendis.","por ke ili ĉiuj estu unu; kiel Vi, Patro, estas en mi, kaj mi en Vi, tiel ili ankaŭ estu en ni; por ke la mondo kredu, ke Vi min sendis."],[17,22,"Kaj la gloron, kiun Vi donis al mi, mi donis al ili; por ke ili estu unu tiel same, kiel ni estas unu;","Kaj la gloron, kiun Vi donis al mi, mi donis al ili; por ke ili estu unu tiel same, kiel ni estas unu;"],[17,23,"mi en ili, kaj Vi en mi, por ke ili perfektiĝu en unu; por ke la mondo sciu, ke Vi min sendis, kaj ke Vi ilin amis, kiel Vi min amis.","mi en ili, kaj Vi en mi, por ke ili perfektiĝu en unu; por ke la mondo sciu, ke Vi min sendis, kaj ke Vi ilin amis, kiel Vi min amis."],[17,24,"Patro, pri tiuj, kiujn Vi donis al mi, mi volas, ke ili ankaŭ estu kun mi tie, kie mi estas; por ke ili vidu mian gloron, kiun Vi donis al mi; ĉar Vi amis min antaŭ la fondo de la mondo.","Patro, pri tiuj, kiujn Vi donis al mi, mi volas, ke ili ankaŭ estu kun mi tie, kie mi estas; por ke ili vidu mian gloron, kiun Vi donis al mi; ĉar Vi amis min antaŭ la fondo de la mondo."],[17,25,"Ho Patro justa, la mondo Vin ne konis, tamen mi Vin konis; kaj ĉi tiuj scias, ke Vi min sendis;","Ho Patro justa, la mondo Vin ne konis, tamen mi Vin konis; kaj ĉi tiuj scias, ke Vi min sendis;"],[17,26,"kaj al ili Vian nomon mi konigis kaj ankoraŭ konigos, por ke la amo, per kiu Vi amis min, estu en ili, kaj mi en ili.","kaj al ili Vian nomon mi konigis kaj ankoraŭ konigos, por ke la amo, per kiu Vi amis min, estu en ili, kaj mi en ili."],[18,1,"Parolinte tiujn vortojn, Jesuo foriris kun siaj disĉiploj trans la torenton Kidron, kie estis ĝardeno, en kiun li eniris kune kun siaj disĉiploj.","Parolinte tiujn vortojn, Jesuo foriris kun siaj disĉiploj trans la torenton Kidron, kie estis ĝardeno, en kiun li eniris kune kun siaj disĉiploj."],[18,2,"Kaj Judas, lia perfidanto, konis la lokon; ĉar Jesuo ofte venis tien kun siaj disĉiploj.","Kaj Judas, lia perfidanto, konis la lokon; ĉar Jesuo ofte venis tien kun siaj disĉiploj."],[18,3,"Judas do, ricevinte la kohorton kaj oficistojn, senditajn de la ĉefpastroj kaj Fariseoj, venis tien kun lanternoj kaj torĉoj kaj bataliloj.","Judas do, ricevinte la kohorton kaj oficistojn, senditajn de la ĉefpastroj kaj Fariseoj, venis tien kun lanternoj kaj torĉoj kaj bataliloj."],[18,4,"Jesuo do, sciante ĉion, kio venos al li, paŝis antaŭen, kaj diris al ili: Kiun vi serĉas?","Jesuo do, sciante ĉion, kio venos al li, paŝis antaŭen, kaj diris al ili: Kiun vi serĉas?"],[18,5,"Ili respondis al li: Jesuon Nazaretan. Jesuo respondis: Mi estas tiu. Kaj Judas, lia perfidanto, staris kun ili.","Ili respondis al li: Jesuon Nazaretan. Jesuo respondis: Mi estas tiu. Kaj Judas, lia perfidanto, staris kun ili."],[18,6,"Kiam do li diris al ili: Mi estas tiu, ili malantaŭen ekpaŝis kaj falis sur la teron.","Kiam do li diris al ili: Mi estas tiu, ili malantaŭen ekpaŝis kaj falis sur la teron."],[18,7,"Tiam denove li demandis ilin: Kiun vi serĉas? Ili diris: Jesuon Nazaretan.","Tiam denove li demandis ilin: Kiun vi serĉas? Ili diris: Jesuon Nazaretan."],[18,8,"Jesuo respondis: Mi ĵus diris al vi, ke mi estas tiu; se do vi min serĉas, lasu ĉi tiujn foriri;","Jesuo respondis: Mi ĵus diris al vi, ke mi estas tiu; se do vi min serĉas, lasu ĉi tiujn foriri;"],[18,9,"por ke plenumiĝu la vorto, kiun li diris: El tiuj, kiujn Vi donis al mi, mi perdis neniun.","por ke plenumiĝu la vorto, kiun li diris: El tiuj, kiujn Vi donis al mi, mi perdis neniun."],[18,10,"Simon Petro do, havante glavon, eltiris ĝin, kaj frapis sklavon de la ĉefpastro kaj detranĉis lian dekstran orelon. La nomo de la sklavo estis Malĥo.","Simon Petro do, havante glavon, eltiris ĝin, kaj frapis sklavon de la ĉefpastro kaj detranĉis lian dekstran orelon. La nomo de la sklavo estis Malĥo."],[18,11,"Jesuo do diris al Petro: Metu la glavon en ĝian ingon; la kalikon, kiun la Patro donis al mi, ĉu mi ne trinkos?","Jesuo do diris al Petro: Metu la glavon en ĝian ingon; la kalikon, kiun la Patro donis al mi, ĉu mi ne trinkos?"],[18,12,"La kohorto kaj la milestro kaj la oficistoj de la Judoj kaptis do Jesuon kaj ligis lin,","La kohorto kaj la milestro kaj la oficistoj de la Judoj kaptis do Jesuon kaj ligis lin,"],[18,13,"kaj kondukis lin unue al Anas; ĉar ĉi tiu estis bopatro de Kajafas, kiu estis ĉefpastro en tiu jaro.","kaj kondukis lin unue al Anas; ĉar ĉi tiu estis bopatro de Kajafas, kiu estis ĉefpastro en tiu jaro."],[18,14,"Kajafas estis tiu, kiu donis konsilon al la Judoj, ke estos bone, ke unu homo mortu por la popolo.","Kajafas estis tiu, kiu donis konsilon al la Judoj, ke estos bone, ke unu homo mortu por la popolo."],[18,15,"Kaj Simon Petro sekvis Jesuon, kaj ankaŭ alia disĉiplo. Ĉi tiu disĉiplo estis konata de la ĉefpastro, kaj eniris kun Jesuo en la korton de la ĉefpastro;","Kaj Simon Petro sekvis Jesuon, kaj ankaŭ alia disĉiplo. Ĉi tiu disĉiplo estis konata de la ĉefpastro, kaj eniris kun Jesuo en la korton de la ĉefpastro;"],[18,16,"sed Petro staris ekstere apud la pordo. Kaj la alia disĉiplo, kiu estis konata de la ĉefpastro, eliris kaj parolis kun la pordistino, kaj enirigis Petron.","sed Petro staris ekstere apud la pordo. Kaj la alia disĉiplo, kiu estis konata de la ĉefpastro, eliris kaj parolis kun la pordistino, kaj enirigis Petron."],[18,17,"La sklavino pordistino diris al Petro: Ĉu vi ne estas ankaŭ el la disĉiploj de tiu homo? Li diris: Mi ne estas.","La sklavino pordistino diris al Petro: Ĉu vi ne estas ankaŭ el la disĉiploj de tiu homo? Li diris: Mi ne estas."],[18,18,"La sklavoj kaj la oficistoj, farinte karban fajron (ĉar estis malvarme), staris kaj sin varmigis; Petro ankaŭ estis kun ili, starante kaj sin varmigante.","La sklavoj kaj la oficistoj, farinte karban fajron (ĉar estis malvarme), staris kaj sin varmigis; Petro ankaŭ estis kun ili, starante kaj sin varmigante."],[18,19,"La ĉefpastro demandis Jesuon pri liaj disĉiploj kaj pri lia instruado.","La ĉefpastro demandis Jesuon pri liaj disĉiploj kaj pri lia instruado."],[18,20,"Jesuo respondis al li: Mi parolis malkaŝe al la mondo; mi ĉiam instruis en la sinagogoj kaj en la templo, kie ĉiuj Judoj kunvenas; kaj sekrete mi nenion parolis.","Jesuo respondis al li: Mi parolis malkaŝe al la mondo; mi ĉiam instruis en la sinagogoj kaj en la templo, kie ĉiuj Judoj kunvenas; kaj sekrete mi nenion parolis."],[18,21,"Kial vi min demandas? demandu tiujn, kiuj aŭdis, kion mi parolis al ili; ili ja scias, kion mi diris.","Kial vi min demandas? demandu tiujn, kiuj aŭdis, kion mi parolis al ili; ili ja scias, kion mi diris."],[18,22,"Kaj kiam li parolis tion, unu el la apude starantaj oficistoj per la manplato frapis Jesuon, dirante: Ĉu tiel vi respondas al la ĉefpastro?","Kaj kiam li parolis tion, unu el la apude starantaj oficistoj per la manplato frapis Jesuon, dirante: Ĉu tiel vi respondas al la ĉefpastro?"],[18,23,"Respondis Jesuo al li: Se mi malbone parolis, atestu pri la malbono; sed se bone, kial vi min frapas?","Respondis Jesuo al li: Se mi malbone parolis, atestu pri la malbono; sed se bone, kial vi min frapas?"],[18,24,"Anas sendis lin ligitan al la ĉefpastro Kajafas.","Anas sendis lin ligitan al la ĉefpastro Kajafas."],[18,25,"Simon Petro staris kaj sin varmigis. Oni do diris al li: Ĉu vi estas unu el liaj disĉiploj? Li neis, dirante: Mi ne estas.","Simon Petro staris kaj sin varmigis. Oni do diris al li: Ĉu vi estas unu el liaj disĉiploj? Li neis, dirante: Mi ne estas."],[18,26,"Unu el la sklavoj de la ĉefpastro, estante parenco de tiu, kies orelon Petro detranĉis, diris: Ĉu mi ne vidis vin kun li en la ĝardeno?","Unu el la sklavoj de la ĉefpastro, estante parenco de tiu, kies orelon Petro detranĉis, diris: Ĉu mi ne vidis vin kun li en la ĝardeno?"],[18,27,"Petro do denove neis; kaj tuj la koko ekkriis.","Petro do denove neis; kaj tuj la koko ekkriis."],[18,28,"Kaj oni kondukis Jesuon de Kajafas en la palacon; estis frumatene; kaj ili ne eniris en la palacon, por ke ili ne malpuriĝu, sed povu manĝi la Paskon.","Kaj oni kondukis Jesuon de Kajafas en la palacon; estis frumatene; kaj ili ne eniris en la palacon, por ke ili ne malpuriĝu, sed povu manĝi la Paskon."],[18,29,"Pilato do eliris al ili, kaj diris: Kian akuzon vi prezentas kontraŭ ĉi tiu viro?","Pilato do eliris al ili, kaj diris: Kian akuzon vi prezentas kontraŭ ĉi tiu viro?"],[18,30,"Ili respondis kaj diris al li: Se li ne estus malbonfaranto, ni ne transdonus lin al vi.","Ili respondis kaj diris al li: Se li ne estus malbonfaranto, ni ne transdonus lin al vi."],[18,31,"Pilato do diris al ili: Vi mem prenu lin, kaj juĝu lin laŭ via leĝo. La Judoj diris al li: Ne estas permesate al ni mortigi homon;","Pilato do diris al ili: Vi mem prenu lin, kaj juĝu lin laŭ via leĝo. La Judoj diris al li: Ne estas permesate al ni mortigi homon;"],[18,32,"por ke plenumiĝu la vorto de Jesuo, kiun li parolis, montrante, per kia morto li mortos.","por ke plenumiĝu la vorto de Jesuo, kiun li parolis, montrante, per kia morto li mortos."],[18,33,"Pilato do reeniris en la palacon, kaj alvokis Jesuon, kaj diris al li: Ĉu vi estas la Reĝo de la Judoj?","Pilato do reeniris en la palacon, kaj alvokis Jesuon, kaj diris al li: Ĉu vi estas la Reĝo de la Judoj?"],[18,34,"Jesuo respondis: Ĉu vi tion diras de vi mem, aŭ ĉu aliaj diris ĝin al vi pri mi?","Jesuo respondis: Ĉu vi tion diras de vi mem, aŭ ĉu aliaj diris ĝin al vi pri mi?"],[18,35,"Pilato respondis: Ĉu mi estas Judo? Via propra nacio kaj la ĉefpastroj transdonis vin al mi; kion vi faris?","Pilato respondis: Ĉu mi estas Judo? Via propra nacio kaj la ĉefpastroj transdonis vin al mi; kion vi faris?"],[18,36,"Jesuo respondis: Mia regno ne estas el ĉi tiu mondo; se mia regno estus el ĉi tiu mondo, miaj servantoj bataladus, por ke mi ne transdoniĝu al la Judoj; sed nun mia regno ne estas el ĉi tie.","Jesuo respondis: Mia regno ne estas el ĉi tiu mondo; se mia regno estus el ĉi tiu mondo, miaj servantoj bataladus, por ke mi ne transdoniĝu al la Judoj; sed nun mia regno ne estas el ĉi tie."],[18,37,"Pilato demandis lin: Ĉu vi do estas reĝo? Jesuo respondis: Vi diras, ke mi estas reĝo. Por tio mi naskiĝis kaj venis en la mondon, ke mi atestu pri la vero. Ĉiu, kiu estas el la vero, aŭskultas mian voĉon.","Pilato demandis lin: Ĉu vi do estas reĝo? Jesuo respondis: Vi diras, ke mi estas reĝo. Por tio mi naskiĝis kaj venis en la mondon, ke mi atestu pri la vero. Ĉiu, kiu estas el la vero, aŭskultas mian voĉon."],[18,38,"Pilato diris al li: Kio estas la vero? Kaj dirinte tion, li eliris denove al la Judoj, kaj diris al ili: Mi trovas en li nenian kulpon.","Pilato diris al li: Kio estas la vero? Kaj dirinte tion, li eliris denove al la Judoj, kaj diris al ili: Mi trovas en li nenian kulpon."],[18,39,"Sed estas ĉe vi kutime, ke mi liberigu al vi unu dum la Pasko: ĉu vi do volas, ke mi liberigu al vi la Reĝon de la Judoj?","Sed estas ĉe vi kutime, ke mi liberigu al vi unu dum la Pasko: ĉu vi do volas, ke mi liberigu al vi la Reĝon de la Judoj?"],[18,40,"Kaj ili kriis denove, dirante: Ne ĉi tiun, sed Barabason. Barabas estis rabisto.","Kaj ili kriis denove, dirante: Ne ĉi tiun, sed Barabason. Barabas estis rabisto."],[19,1,"Tiam do Pilato prenis Jesuon kaj lin skurĝigis.","Tiam do Pilato prenis Jesuon kaj lin skurĝigis."],[19,2,"Kaj la soldatoj plektis kronon el dornoj kaj metis ĝin sur lian kapon, kaj vestis lin per purpura mantelo;","Kaj la soldatoj plektis kronon el dornoj kaj metis ĝin sur lian kapon, kaj vestis lin per purpura mantelo;"],[19,3,"kaj venis al li, kaj diris: Saluton, Reĝo de la Judoj! kaj ili frapis lin per la manplatoj.","kaj venis al li, kaj diris: Saluton, Reĝo de la Judoj! kaj ili frapis lin per la manplatoj."],[19,4,"Pilato do denove eliris, kaj diris al ili: Jen mi elkondukas lin al vi, por ke vi sciu, ke mi trovas en li nenian kulpon.","Pilato do denove eliris, kaj diris al ili: Jen mi elkondukas lin al vi, por ke vi sciu, ke mi trovas en li nenian kulpon."],[19,5,"Jesuo do eliris, portante la dornan kronon kaj la purpuran mantelon. Pilato diris al ili: Jen la homo!","Jesuo do eliris, portante la dornan kronon kaj la purpuran mantelon. Pilato diris al ili: Jen la homo!"],[19,6,"Kiam do la ĉefpastroj kaj oficistoj lin vidis, ili kriis: Krucumu, krucumu lin. Pilato diris al ili: Mem prenu lin kaj krucumu lin, ĉar mi trovas en li nenian kulpon.","Kiam do la ĉefpastroj kaj oficistoj lin vidis, ili kriis: Krucumu, krucumu lin. Pilato diris al ili: Mem prenu lin kaj krucumu lin, ĉar mi trovas en li nenian kulpon."],[19,7,"La Judoj respondis al li: Ni havas leĝon, kaj laŭ tiu leĝo li devas morti tial, ke li pretendis esti Filo de Dio.","La Judoj respondis al li: Ni havas leĝon, kaj laŭ tiu leĝo li devas morti tial, ke li pretendis esti Filo de Dio."],[19,8,"Kiam do Pilato aŭdis tiun diron, li des pli timis;","Kiam do Pilato aŭdis tiun diron, li des pli timis;"],[19,9,"kaj reenirinte en la palacon, li diris al Jesuo: De kie vi estas? Sed Jesuo nenion respondis.","kaj reenirinte en la palacon, li diris al Jesuo: De kie vi estas? Sed Jesuo nenion respondis."],[19,10,"Tiam diris Pilato al li: Ĉu vi ne parolas al mi? ĉu vi ne scias, ke mi havas povon krucumi vin, kaj povon liberigi vin?","Tiam diris Pilato al li: Ĉu vi ne parolas al mi? ĉu vi ne scias, ke mi havas povon krucumi vin, kaj povon liberigi vin?"],[19,11,"Jesuo respondis: Vi havus nenian povon kontraŭ mi, se ĝi ne estus donita al vi de supre; tial tiu, kiu transdonis min al vi, havas la pli grandan pekon.","Jesuo respondis: Vi havus nenian povon kontraŭ mi, se ĝi ne estus donita al vi de supre; tial tiu, kiu transdonis min al vi, havas la pli grandan pekon."],[19,12,"Ĉe tio Pilato penis liberigi lin; sed la Judoj kriis, dirante: Se vi liberigos tiun, vi ne estas amiko de Cezaro; ĉiu, kiu pretendas esti reĝo, parolas kontraŭ Cezaro.","Ĉe tio Pilato penis liberigi lin; sed la Judoj kriis, dirante: Se vi liberigos tiun, vi ne estas amiko de Cezaro; ĉiu, kiu pretendas esti reĝo, parolas kontraŭ Cezaro."],[19,13,"Kiam do Pilato aŭdis tiun vorton, li elkondukis Jesuon, kaj sidiĝis sur tribunala seĝo en loko nomata La Pavimo, sed en la Hebrea lingvo Gabata.","Kiam do Pilato aŭdis tiun vorton, li elkondukis Jesuon, kaj sidiĝis sur tribunala seĝo en loko nomata La Pavimo, sed en la Hebrea lingvo Gabata."],[19,14,"Estis la Preparado de la Pasko, ĉirkaŭ la sesa horo. Kaj li diris al la Judoj: Jen via Reĝo!","Estis la Preparado de la Pasko, ĉirkaŭ la sesa horo. Kaj li diris al la Judoj: Jen via Reĝo!"],[19,15,"Ili kriegis: Forigu, forigu, krucumu lin. Pilato diris al ili: Ĉu mi krucumu vian Reĝon? La ĉefpastroj respondis: Ni ne havas reĝon krom Cezaro.","Ili kriegis: Forigu, forigu, krucumu lin. Pilato diris al ili: Ĉu mi krucumu vian Reĝon? La ĉefpastroj respondis: Ni ne havas reĝon krom Cezaro."],[19,16,"Tiam do li transdonis lin al ili, por esti krucumita.","Tiam do li transdonis lin al ili, por esti krucumita."],[19,17,"Kaj ili prenis Jesuon; kaj li eliris, portante sian krucon, al la loko nomata Loko de Kranio, kiu estas en la Hebrea lingvo Golgota;","Kaj ili prenis Jesuon; kaj li eliris, portante sian krucon, al la loko nomata Loko de Kranio, kiu estas en la Hebrea lingvo Golgota;"],[19,18,"tie ili krucumis lin, kaj kun li du aliajn, ĉiuflanke po unu, kaj Jesuon meze.","tie ili krucumis lin, kaj kun li du aliajn, ĉiuflanke po unu, kaj Jesuon meze."],[19,19,"Kaj Pilato ankaŭ skribis titolon, kaj surmetis ĝin sur la krucon. Kaj estis skribite: JESUO NAZARETA, LA REĜO DE LA JUDOJ.","Kaj Pilato ankaŭ skribis titolon, kaj surmetis ĝin sur la krucon. Kaj estis skribite: JESUO NAZARETA, LA REĜO DE LA JUDOJ."],[19,20,"Tiun titolon multaj el la Judoj legis; ĉar la loko, kie Jesuo estis krucumita, estis proksime de la urbo; kaj ĝi estis skribita Hebree kaj Latine kaj Greke.","Tiun titolon multaj el la Judoj legis; ĉar la loko, kie Jesuo estis krucumita, estis proksime de la urbo; kaj ĝi estis skribita Hebree kaj Latine kaj Greke."],[19,21,"Tiam la ĉefpastroj de la Judoj diris al Pilato: Ne skribu: La Reĝo de la Judoj; sed, ke li diris: Mi estas Reĝo de la Judoj.","Tiam la ĉefpastroj de la Judoj diris al Pilato: Ne skribu: La Reĝo de la Judoj; sed, ke li diris: Mi estas Reĝo de la Judoj."],[19,22,"Respondis Pilato: Kion mi skribis, tion mi skribis.","Respondis Pilato: Kion mi skribis, tion mi skribis."],[19,23,"Kaj la soldatoj, kiam ili krucumis Jesuon, prenis liajn vestojn, kaj dividis ilin en kvar partojn, po unu parto por ĉiu soldato; kaj la tunikon; sed la tuniko estis senkudra, desupre teksita tra la tuto.","Kaj la soldatoj, kiam ili krucumis Jesuon, prenis liajn vestojn, kaj dividis ilin en kvar partojn, po unu parto por ĉiu soldato; kaj la tunikon; sed la tuniko estis senkudra, desupre teksita tra la tuto."],[19,24,"Ili do diris unu al alia: Ni ne disŝiru ĝin, sed lotu pri ĝi, kies ĝi estos; por ke plenumiĝu la Skribo, kiu diras: Ili dividis miajn vestojn inter si, Pri mia tuniko ili lotis. Tion la soldatoj faris.","Ili do diris unu al alia: Ni ne disŝiru ĝin, sed lotu pri ĝi, kies ĝi estos; por ke plenumiĝu la Skribo, kiu diras: Ili dividis miajn vestojn inter si, Pri mia tuniko ili lotis. Tion la soldatoj faris."],[19,25,"Sed apud la kruco de Jesuo staris lia patrino, kaj la fratino de lia patrino, Maria, la edzino de Klopas, kaj Maria Magdalena.","Sed apud la kruco de Jesuo staris lia patrino, kaj la fratino de lia patrino, Maria, la edzino de Klopas, kaj Maria Magdalena."],[19,26,"Jesuo, rigardante sian patrinon, kaj la apudstarantan disĉiplon, kiun li amis, diris al sia patrino: Virino, jen via filo!","Jesuo, rigardante sian patrinon, kaj la apudstarantan disĉiplon, kiun li amis, diris al sia patrino: Virino, jen via filo!"],[19,27,"Tiam li diris al la disĉiplo: Jen via patrino! Kaj de post tiu horo la disĉiplo akceptis ŝin en sian domon.","Tiam li diris al la disĉiplo: Jen via patrino! Kaj de post tiu horo la disĉiplo akceptis ŝin en sian domon."],[19,28,"Jesuo, sciante, ke ĉio jam finiĝis, por ke plenumiĝu la Skribo, diris: Mi soifas.","Jesuo, sciante, ke ĉio jam finiĝis, por ke plenumiĝu la Skribo, diris: Mi soifas."],[19,29,"Kuŝis tie vazo plena de vinagro; oni do metis spongon, plenigitan per la vinagro, sur hisopon, kaj levis ĝin al lia buŝo.","Kuŝis tie vazo plena de vinagro; oni do metis spongon, plenigitan per la vinagro, sur hisopon, kaj levis ĝin al lia buŝo."],[19,30,"Kiam do Jesuo ricevis la vinagron, li diris: Estas finite; kaj, klininte sian kapon, li ellasis for la spiriton.","Kiam do Jesuo ricevis la vinagron, li diris: Estas finite; kaj, klininte sian kapon, li ellasis for la spiriton."],[19,31,"La Judoj, ĉar estis la Preparado, por ke la korpoj ne restadu sur la krucoj dum la sabato (ĉar la tago de tiu sabato estis granda tago), petis Pilaton, ke oni rompu iliajn krurojn, kaj forportu ilin.","La Judoj, ĉar estis la Preparado, por ke la korpoj ne restadu sur la krucoj dum la sabato (ĉar la tago de tiu sabato estis granda tago), petis Pilaton, ke oni rompu iliajn krurojn, kaj forportu ilin."],[19,32,"Tiam la soldatoj venis, kaj rompis la krurojn de la unua kaj de la alia krucumita kun li;","Tiam la soldatoj venis, kaj rompis la krurojn de la unua kaj de la alia krucumita kun li;"],[19,33,"sed kiam ili venis al Jesuo, kaj vidis, ke li jam mortis, ili ne rompis liajn krurojn;","sed kiam ili venis al Jesuo, kaj vidis, ke li jam mortis, ili ne rompis liajn krurojn;"],[19,34,"tamen unu el la soldatoj per lanco pikis lian flankon, kaj tuj elvenis sango kaj akvo.","tamen unu el la soldatoj per lanco pikis lian flankon, kaj tuj elvenis sango kaj akvo."],[19,35,"Kaj la vidinto atestis, kaj vera estas lia atesto; kaj li scias, ke li diras la veron, ke vi ankaŭ kredu.","Kaj la vidinto atestis, kaj vera estas lia atesto; kaj li scias, ke li diras la veron, ke vi ankaŭ kredu."],[19,36,"Ĉar tio okazis, por ke plenumiĝu la Skribo: Osto en li ne estos rompita.","Ĉar tio okazis, por ke plenumiĝu la Skribo: Osto en li ne estos rompita."],[19,37,"Kaj ankoraŭ alia Skribo diras: Ili rigardos tiun, kiun ili trapikis.","Kaj ankoraŭ alia Skribo diras: Ili rigardos tiun, kiun ili trapikis."],[19,38,"Post tio, Jozef el Arimateo, kiu estis disĉiplo de Jesuo, sed sekrete pro timo antaŭ la Judoj, petis Pilaton, ke li povu forpreni la korpon de Jesuo; kaj Pilato permesis. Li do venis kaj forprenis lian korpon.","Post tio, Jozef el Arimateo, kiu estis disĉiplo de Jesuo, sed sekrete pro timo antaŭ la Judoj, petis Pilaton, ke li povu forpreni la korpon de Jesuo; kaj Pilato permesis. Li do venis kaj forprenis lian korpon."],[19,39,"Venis ankaŭ Nikodemo (tiu, kiu unue venis al Jesuo nokte), portanta miksaĵon de mirho kaj aloo, ĉirkaŭ cent funtoj.","Venis ankaŭ Nikodemo (tiu, kiu unue venis al Jesuo nokte), portanta miksaĵon de mirho kaj aloo, ĉirkaŭ cent funtoj."],[19,40,"Ili do prenis la korpon de Jesuo, kaj ĉirkaŭvindis ĝin per tolaĵoj kun aromaĵoj, laŭ la kutimo de la Judoj por entombigo.","Ili do prenis la korpon de Jesuo, kaj ĉirkaŭvindis ĝin per tolaĵoj kun aromaĵoj, laŭ la kutimo de la Judoj por entombigo."],[19,41,"Kaj estis ĝardeno en la loko, kie li estis krucumita, kaj en la ĝardeno nova tombo, en kiun ankoraŭ neniu estis metita.","Kaj estis ĝardeno en la loko, kie li estis krucumita, kaj en la ĝardeno nova tombo, en kiun ankoraŭ neniu estis metita."],[19,42,"Tien do, pro la Preparado de la Judoj (ĉar la tombo estis proksima) ili enmetis Jesuon.","Tien do, pro la Preparado de la Judoj (ĉar la tombo estis proksima) ili enmetis Jesuon."],[20,1,"La unuan tagon de la semajno Maria Magdalena venis frue, dum estis ankoraŭ mallume, al la tombo, kaj vidis la ŝtonon prenita for de la tombo.","La unuan tagon de la semajno Maria Magdalena venis frue, dum estis ankoraŭ mallume, al la tombo, kaj vidis la ŝtonon prenita for de la tombo."],[20,2,"Ŝi do kuris kaj venis al Simon Petro kaj al tiu alia disĉiplo, kiun Jesuo amis, kaj ŝi diris al ili: Oni forprenis el la tombo la Sinjoron, kaj ni ne scias, kien oni lin metis.","Ŝi do kuris kaj venis al Simon Petro kaj al tiu alia disĉiplo, kiun Jesuo amis, kaj ŝi diris al ili: Oni forprenis el la tombo la Sinjoron, kaj ni ne scias, kien oni lin metis."],[20,3,"Eliris do Petro kaj la alia disĉiplo, kaj iris al la tombo.","Eliris do Petro kaj la alia disĉiplo, kaj iris al la tombo."],[20,4,"Kaj ambaŭ ekkuris kune; kaj la alia disĉiplo kuris antaŭen pli rapide ol Petro, kaj unua alvenis al la tombo;","Kaj ambaŭ ekkuris kune; kaj la alia disĉiplo kuris antaŭen pli rapide ol Petro, kaj unua alvenis al la tombo;"],[20,5,"kaj kliniĝinte, li enrigardis, kaj vidis la tolaĵojn kuŝantajn; tamen li ne eniris.","kaj kliniĝinte, li enrigardis, kaj vidis la tolaĵojn kuŝantajn; tamen li ne eniris."],[20,6,"Kaj poste venis Simon Petro, sekvante lin, kaj eniris en la tombon; kaj li vidis la tolaĵojn kuŝantajn,","Kaj poste venis Simon Petro, sekvante lin, kaj eniris en la tombon; kaj li vidis la tolaĵojn kuŝantajn,"],[20,7,"kaj la viŝtukon, kiu estis sur lia kapo, ne kuŝantan kun la tolaĵoj, sed kunvolvitan en aparta loko.","kaj la viŝtukon, kiu estis sur lia kapo, ne kuŝantan kun la tolaĵoj, sed kunvolvitan en aparta loko."],[20,8,"Tiam eniris do la alia disĉiplo, kiu unua alvenis al la tombo, kaj li vidis kaj kredis.","Tiam eniris do la alia disĉiplo, kiu unua alvenis al la tombo, kaj li vidis kaj kredis."],[20,9,"Ĉar ili ankoraŭ ne komprenis la Skribon, ke li devas releviĝi el la mortintoj.","Ĉar ili ankoraŭ ne komprenis la Skribon, ke li devas releviĝi el la mortintoj."],[20,10,"Kaj la disĉiploj iris returne hejmen.","Kaj la disĉiploj iris returne hejmen."],[20,11,"Sed Maria staris ekstere apud la tombo, plorante; kaj dum ŝi ploris, ŝi kliniĝis, kaj enrigardis en la tombon;","Sed Maria staris ekstere apud la tombo, plorante; kaj dum ŝi ploris, ŝi kliniĝis, kaj enrigardis en la tombon;"],[20,12,"kaj ŝi vidis du anĝelojn en blankaj vestoj, sidantajn, unu ĉe la kaploko kaj unu ĉe la piedloko, kie la korpo de Jesuo antaŭe kuŝis.","kaj ŝi vidis du anĝelojn en blankaj vestoj, sidantajn, unu ĉe la kaploko kaj unu ĉe la piedloko, kie la korpo de Jesuo antaŭe kuŝis."],[20,13,"Kaj ili diris al ŝi: Virino, kial vi ploras? Ŝi respondis: Ĉar oni forprenis mian Sinjoron, kaj mi ne scias, kien oni lin metis.","Kaj ili diris al ŝi: Virino, kial vi ploras? Ŝi respondis: Ĉar oni forprenis mian Sinjoron, kaj mi ne scias, kien oni lin metis."],[20,14,"Dirinte tion, ŝi sin turnis malantaŭen, kaj vidis Jesuon staranta, kaj ne sciis, ke ĝi estas Jesuo.","Dirinte tion, ŝi sin turnis malantaŭen, kaj vidis Jesuon staranta, kaj ne sciis, ke ĝi estas Jesuo."],[20,15,"Jesuo diris al ŝi: Virino, kial vi ploras? kiun vi serĉas? Ŝi, supozante, ke li estas la ĝardenisto, diris al li: Sinjoro, se vi forportis lin, sciigu min, kien vi metis lin, kaj mi lin forprenos.","Jesuo diris al ŝi: Virino, kial vi ploras? kiun vi serĉas? Ŝi, supozante, ke li estas la ĝardenisto, diris al li: Sinjoro, se vi forportis lin, sciigu min, kien vi metis lin, kaj mi lin forprenos."],[20,16,"Jesuo diris al ŝi: Maria. Ŝi sin turnis, kaj diris al li Hebrelingve: Raboni; tio estas Majstro.","Jesuo diris al ŝi: Maria. Ŝi sin turnis, kaj diris al li Hebrelingve: Raboni; tio estas Majstro."],[20,17,"Jesuo diris al ŝi: Ne tuŝu min; ĉar mi ankoraŭ ne supreniris al la Patro; sed iru al miaj fratoj, kaj diru al ili: Mi supreniras al mia Patro kaj via Patro, kaj al mia Dio kaj via Dio.","Jesuo diris al ŝi: Ne tuŝu min; ĉar mi ankoraŭ ne supreniris al la Patro; sed iru al miaj fratoj, kaj diru al ili: Mi supreniras al mia Patro kaj via Patro, kaj al mia Dio kaj via Dio."],[20,18,"Maria Magdalena venis al la disĉiploj, sciigante: Mi vidis la Sinjoron; kaj ke li tion diris al ŝi.","Maria Magdalena venis al la disĉiploj, sciigante: Mi vidis la Sinjoron; kaj ke li tion diris al ŝi."],[20,19,"Kiam do estis vespero en tiu sama tago, la unua de la semajno, kaj kiam estis fermitaj la pordoj, kie la disĉiploj estis, pro timo antaŭ la Judoj, Jesuo venis kaj staris meze de ili, kaj diris al ili: Paco al vi.","Kiam do estis vespero en tiu sama tago, la unua de la semajno, kaj kiam estis fermitaj la pordoj, kie la disĉiploj estis, pro timo antaŭ la Judoj, Jesuo venis kaj staris meze de ili, kaj diris al ili: Paco al vi."],[20,20,"Kaj dirinte tion, li montris al ili siajn manojn kaj sian flankon. La disĉiploj do ĝojis, vidante la Sinjoron.","Kaj dirinte tion, li montris al ili siajn manojn kaj sian flankon. La disĉiploj do ĝojis, vidante la Sinjoron."],[20,21,"Jesuo denove diris al ili: Paco al vi; kiel la Patro sendis min, tiel ankaŭ mi vin sendas.","Jesuo denove diris al ili: Paco al vi; kiel la Patro sendis min, tiel ankaŭ mi vin sendas."],[20,22,"Kaj dirinte tion, li elspiris sur ilin, kaj diris: Ricevu la Sanktan Spiriton:","Kaj dirinte tion, li elspiris sur ilin, kaj diris: Ricevu la Sanktan Spiriton:"],[20,23,"kies pekojn vi pardonos, al tiuj ili estas pardonitaj; kies vi retenos, ili estas retenitaj.","kies pekojn vi pardonos, al tiuj ili estas pardonitaj; kies vi retenos, ili estas retenitaj."],[20,24,"Sed Tomaso, unu el la dek du, nomata Didimo, ne ĉeestis kun ili, kiam Jesuo venis.","Sed Tomaso, unu el la dek du, nomata Didimo, ne ĉeestis kun ili, kiam Jesuo venis."],[20,25,"La aliaj disĉiploj do diris al li: Ni vidis la Sinjoron. Sed li diris al ili: Se mi ne vidos en liaj manoj la truon de la najloj, kaj se mi ne metos mian fingron en la lokon de la najloj, kaj ne metos mian manon en lian flankon, mi tute ne kredos.","La aliaj disĉiploj do diris al li: Ni vidis la Sinjoron. Sed li diris al ili: Se mi ne vidos en liaj manoj la truon de la najloj, kaj se mi ne metos mian fingron en la lokon de la najloj, kaj ne metos mian manon en lian flankon, mi tute ne kredos."],[20,26,"Kaj post ok tagoj la disĉiploj denove estis interne, kaj Tomaso kun ili. Kaj Jesuo venis, kiam la pordoj estis fermitaj, kaj staris en la mezo, kaj diris: Paco al vi.","Kaj post ok tagoj la disĉiploj denove estis interne, kaj Tomaso kun ili. Kaj Jesuo venis, kiam la pordoj estis fermitaj, kaj staris en la mezo, kaj diris: Paco al vi."],[20,27,"Tiam li diris al Tomaso: Etendu ĉi tien vian fingron kaj vidu miajn manojn; kaj etendu vian manon kaj enmetu ĝin en mian flankon; kaj ne estu nekredema, sed estu kredanta.","Tiam li diris al Tomaso: Etendu ĉi tien vian fingron kaj vidu miajn manojn; kaj etendu vian manon kaj enmetu ĝin en mian flankon; kaj ne estu nekredema, sed estu kredanta."],[20,28,"Tomaso respondis al li kaj diris: Mia Sinjoro kaj mia Dio.","Tomaso respondis al li kaj diris: Mia Sinjoro kaj mia Dio."],[20,29,"Jesuo diris al li: Ĉar vi vidis min, vi kredas; feliĉaj estas tiuj, kiuj ne vidis, kaj tamen kredas.","Jesuo diris al li: Ĉar vi vidis min, vi kredas; feliĉaj estas tiuj, kiuj ne vidis, kaj tamen kredas."],[20,30,"Jesuo faris antaŭ la disĉiploj multajn aliajn signojn, kiuj ne estas skribitaj en ĉi tiu libro;","Jesuo faris antaŭ la disĉiploj multajn aliajn signojn, kiuj ne estas skribitaj en ĉi tiu libro;"],[20,31,"sed ĉi tiuj estas skribitaj, por ke vi kredu, ke Jesuo estas la Kristo, la Filo de Dio, kaj ke kredante, vi havu vivon en lia nomo.","sed ĉi tiuj estas skribitaj, por ke vi kredu, ke Jesuo estas la Kristo, la Filo de Dio, kaj ke kredante, vi havu vivon en lia nomo."],[21,1,"Post tio Jesuo denove sin montris al la disĉiploj apud la maro de Tiberias; kaj li montris sin jene.","Post tio Jesuo denove sin montris al la disĉiploj apud la maro de Tiberias; kaj li montris sin jene."],[21,2,"Estis kune Simon Petro, kaj Tomaso, nomata Didimo, kaj Natanael el Kana Galilea, kaj la filoj de Zebedeo, kaj aliaj du el liaj disĉiploj.","Estis kune Simon Petro, kaj Tomaso, nomata Didimo, kaj Natanael el Kana Galilea, kaj la filoj de Zebedeo, kaj aliaj du el liaj disĉiploj."],[21,3,"Simon Petro diris al ili: Mi iras, por fiŝkapti. Ili diris al li: Ni ankaŭ iras kun vi. Ili do eliris, kaj iris sur la ŝipon; kaj tiun nokton ili nenion kaptis.","Simon Petro diris al ili: Mi iras, por fiŝkapti. Ili diris al li: Ni ankaŭ iras kun vi. Ili do eliris, kaj iris sur la ŝipon; kaj tiun nokton ili nenion kaptis."],[21,4,"Sed ĉe la tagiĝo Jesuo staris sur la marbordo; tamen la disĉiploj ne sciis, ke ĝi estas Jesuo.","Sed ĉe la tagiĝo Jesuo staris sur la marbordo; tamen la disĉiploj ne sciis, ke ĝi estas Jesuo."],[21,5,"Tiam Jesuo diris al ili: Infanoj, ĉu vi havas ian manĝaĵon? Ili respondis al li: Ne.","Tiam Jesuo diris al ili: Infanoj, ĉu vi havas ian manĝaĵon? Ili respondis al li: Ne."],[21,6,"Kaj li diris al ili: Ĵetu la reton ĉe la dekstra flanko de la ŝipo, kaj vi trovos. Ili do ĝin elĵetis; kaj pro la multeco de la fiŝoj ili ne plu povis ĝin treni.","Kaj li diris al ili: Ĵetu la reton ĉe la dekstra flanko de la ŝipo, kaj vi trovos. Ili do ĝin elĵetis; kaj pro la multeco de la fiŝoj ili ne plu povis ĝin treni."],[21,7,"Tiu disĉiplo, kiun Jesuo amis, diris al Petro: Ĝi estas la Sinjoro. Kiam do Simon Petro aŭdis, ke ĝi estas la Sinjoro, li alzonis al si sian kitelon (ĉar li estis nuda) kaj ĵetis sin en la maron.","Tiu disĉiplo, kiun Jesuo amis, diris al Petro: Ĝi estas la Sinjoro. Kiam do Simon Petro aŭdis, ke ĝi estas la Sinjoro, li alzonis al si sian kitelon (ĉar li estis nuda) kaj ĵetis sin en la maron."],[21,8,"Sed la aliaj disĉiploj venis en la ŝipeto (ĉar ili estis ne malproksime de la tero, sed nur ĉirkaŭ ducent ulnoj), trenante la reton plenan de fiŝoj.","Sed la aliaj disĉiploj venis en la ŝipeto (ĉar ili estis ne malproksime de la tero, sed nur ĉirkaŭ ducent ulnoj), trenante la reton plenan de fiŝoj."],[21,9,"Kaj kiam ili eliris sur la teron, ili vidis fajron karban aranĝitan tie, kaj fiŝon kuŝantan sur ĝi, kaj panon.","Kaj kiam ili eliris sur la teron, ili vidis fajron karban aranĝitan tie, kaj fiŝon kuŝantan sur ĝi, kaj panon."],[21,10,"Jesuo diris al ili: Alportu el la fiŝoj, kiujn vi ĵus kaptis.","Jesuo diris al ili: Alportu el la fiŝoj, kiujn vi ĵus kaptis."],[21,11,"Simon Petro iris sur la ŝipon, kaj tiris la reton al la tero, plenan de grandaj fiŝoj, cent kvindek tri; kaj kvankam estis tiel multaj, tamen la reto ne disŝiriĝis.","Simon Petro iris sur la ŝipon, kaj tiris la reton al la tero, plenan de grandaj fiŝoj, cent kvindek tri; kaj kvankam estis tiel multaj, tamen la reto ne disŝiriĝis."],[21,12,"Jesuo diris al ili: Venu, matenmanĝu. Kaj neniu el la disĉiploj kuraĝis lin demandi: Kiu vi estas? sciante, ke ĝi estas la Sinjoro.","Jesuo diris al ili: Venu, matenmanĝu. Kaj neniu el la disĉiploj kuraĝis lin demandi: Kiu vi estas? sciante, ke ĝi estas la Sinjoro."],[21,13,"Jesuo venis kaj prenis la panon kaj donis al ili, kaj tiel same la fiŝon.","Jesuo venis kaj prenis la panon kaj donis al ili, kaj tiel same la fiŝon."],[21,14,"Tiu estas jam la tria fojo, kiam aperis Jesuo al siaj disĉiploj, post sia releviĝo el la mortintoj.","Tiu estas jam la tria fojo, kiam aperis Jesuo al siaj disĉiploj, post sia releviĝo el la mortintoj."],[21,15,"Post la matenmanĝo Jesuo diris al Simon Petro: Simon, filo de Jona, ĉu vi amas min pli, ol tiuj? Li diris al li: Jes, Sinjoro; vi scias, ke mi vin amas. Li diris al li: Paŝtu miajn ŝafidojn.","Post la matenmanĝo Jesuo diris al Simon Petro: Simon, filo de Jona, ĉu vi amas min pli, ol tiuj? Li diris al li: Jes, Sinjoro; vi scias, ke mi vin amas. Li diris al li: Paŝtu miajn ŝafidojn."],[21,16,"Li diris al li ankoraŭ la duan fojon: Simon, filo de Jona, ĉu vi min amas? Li diris al li: Jes, Sinjoro; vi scias, ke mi vin amas. Li diris al li: Zorgu pri miaj ŝafoj.","Li diris al li ankoraŭ la duan fojon: Simon, filo de Jona, ĉu vi min amas? Li diris al li: Jes, Sinjoro; vi scias, ke mi vin amas. Li diris al li: Zorgu pri miaj ŝafoj."],[21,17,"Li diris al li la trian fojon: Simon, filo de Jona, ĉu vi min amas? Petro ĉagreniĝis, ke li diris al li la trian fojon: Ĉu vi min amas? kaj respondis al li: Sinjoro, vi scias ĉion; vi scias, ke mi vin amas. Jesuo diris al li: Paŝtu miajn ŝafojn.","Li diris al li la trian fojon: Simon, filo de Jona, ĉu vi min amas? Petro ĉagreniĝis, ke li diris al li la trian fojon: Ĉu vi min amas? kaj respondis al li: Sinjoro, vi scias ĉion; vi scias, ke mi vin amas. Jesuo diris al li: Paŝtu miajn ŝafojn."],[21,18,"Vere, vere, mi diras al vi: Kiam vi estis juna, vi zonis vin, kaj iris, kien vi volis; sed kiam vi maljuniĝos, vi etendos viajn manojn, kaj alia vin zonos, kaj portos vin, kien vi ne volos.","Vere, vere, mi diras al vi: Kiam vi estis juna, vi zonis vin, kaj iris, kien vi volis; sed kiam vi maljuniĝos, vi etendos viajn manojn, kaj alia vin zonos, kaj portos vin, kien vi ne volos."],[21,19,"Tion li diris, montrante per aludo, per kia morto li gloros Dion. Kaj dirinte tion, li diris al li: Sekvu min.","Tion li diris, montrante per aludo, per kia morto li gloros Dion. Kaj dirinte tion, li diris al li: Sekvu min."],[21,20,"Petro, sin turninte, vidis malantaŭe la disĉiplon, kiun Jesuo amis (kiu ankaŭ klinis sin al lia brusto dum la vespermanĝo, kun la diro: Sinjoro, kiu estas la perfidanta vin?).","Petro, sin turninte, vidis malantaŭe la disĉiplon, kiun Jesuo amis (kiu ankaŭ klinis sin al lia brusto dum la vespermanĝo, kun la diro: Sinjoro, kiu estas la perfidanta vin?)."],[21,21,"Petro do, vidinte lin, diris al Jesuo: Sinjoro, kaj kion pri ĉi tiu?","Petro do, vidinte lin, diris al Jesuo: Sinjoro, kaj kion pri ĉi tiu?"],[21,22,"Jesuo diris al li: Se mi volas, ke li restu, ĝis mi venos, kio estas al vi? vi sekvu min.","Jesuo diris al li: Se mi volas, ke li restu, ĝis mi venos, kio estas al vi? vi sekvu min."],[21,23,"Tial inter la fratoj disiris la famo, ke tiu disĉiplo ne mortos; tamen Jesuo ne diris al li, ke li ne mortos, sed: Se mi volas, ke li restu, ĝis mi venos, kio estas al vi?","Tial inter la fratoj disiris la famo, ke tiu disĉiplo ne mortos; tamen Jesuo ne diris al li, ke li ne mortos, sed: Se mi volas, ke li restu, ĝis mi venos, kio estas al vi?"],[21,24,"Tiu estas la disĉiplo, kiu atestas pri tio kaj skribis tion: kaj ni scias, ke lia atesto estas vera.","Tiu estas la disĉiplo, kiu atestas pri tio kaj skribis tion: kaj ni scias, ke lia atesto estas vera."],[21,25,"Estas ankaŭ multaj aliaj faroj, kiujn Jesuo faris; kaj mi supozas, ke se ĉiu el ili estus skribita detale, la tuta mondo ne havus lokon por la skribotaj libroj.","Estas ankaŭ multaj aliaj faroj, kiujn Jesuo faris; kaj mi supozas, ke se ĉiu el ili estus skribita detale, la tuta mondo ne havus lokon por la skribotaj libroj."]]}};